series":"topic","name":"源码猎人","desc":"读完 6 篇专栏长文"},{"id":"ach-topic-all","icon":"🧠","tier":"金","series":"topic","name":"知其所以然","desc":"读完全部 15 篇专栏长文"},{"id":"ach-allrounder","icon":"🌟","tier":"金","series":"collect","name":"六边形学徒","desc":"六大板块全部破冰（章节/测验/算法/易错/考试/专栏各有动作）"},{"id":"ach-marathon","icon":"🚀","tier":"钻石","series":"collect","name":"全栈修行者","desc":"累计完成 150 个学习动作（打卡+答题+刷题+易错+专栏）"},{"id":"ach-night-owl","icon":"🌙","tier":"银","series":"special","name":"夜猫子工程师","desc":"在凌晨 0 点~5 点之间完成一次答题"},{"id":"ach-comeback","icon":"🔄","tier":"银","series":"special","name":"卷土重来","desc":"答错后重新再来，累计 20 次学习动作"},{"id":"ach-master","icon":"💎","tier":"钻石","series":"special","name":"全栈毕业礼","desc":"集齐其余全部常规勋章（真·全栈毕业，隐藏成就不计入）"}]');
