INSERT INTO json_doc (name, data) VALUES ('examPapers', '[{"id":"exam-basic","icon":"📗","name":"第一套 · Java 基础摸底卷","level":"入门","minutes":30,"passScore":60,"desc":"覆盖 Java 语法、面向对象、集合基础、MySQL 入门。学完第 1~3 章即可挑战。","questions":[{"q":"下列哪个不是 Java 的基本数据类型？","options":["int","boolean","String","char"],"answer":2,"explain":"String 是引用类型（类），8 大基本类型是 byte/short/int/long/float/double/char/boolean。","topic":"Java 基础"},{"q":"10 / 3 的结果是？","options":["3.33","3","4","编译错误"],"answer":1,"explain":"整数除法直接截断小数部分，得 3。","topic":"Java 基础"},{"q":"以下代码输出：int[] arr = {1,2,3}; System.out.println(arr[3]);","options":["3","null","ArrayIndexOutOfBoundsException","0"],"answer":2,"explain":"数组下标从 0 开始，arr[3] 越界（最大 arr[2]），运行时抛数组越界异常。","topic":"数组"},{"q":"面向对象三大特性不包括？","options":["封装","继承","多态","重载"],"answer":3,"explain":"重载（Overload）是方法签名不同的一组同名方法，属于语法特性；三大特性是封装/继承/多态。","topic":"面向对象"},{"q":"关于构造器，正确的是？","options":["构造器必须有返回值","构造器可以被子类继承","类没写构造器时编译器提供无参构造器","构造器不能重载"],"answer":2,"explain":"构造器无返回值声明、不被继承（可 super 调用）、支持重载；默认无参构造器在手写任何构造器后消失。","topic":"面向对象"},{"q":"方法重载（Overload）的条件是？","options":["方法名相同参数列表不同","方法名参数都相同","返回值必须不同","必须在子类中"],"answer":0,"explain":"重载=同名不同参（个数/类型/顺序），与返回值和继承无关；同名同参是重写（Override），发生在父子类间。","topic":"面向对象"},{"q":"String s = \\"hello\\"; s.toUpperCase(); System.out.println(s); 输出？","options":["HELLO","hello","Hello","编译错误"],"answer":1,"explain":"String 不可变，toUpperCase 返回新对象，原 s 不变——返回值被丢弃了。要写 s = s.toUpperCase()。","topic":"String"},{"q":"ArrayList 默认初始容量（首次 add 时分配）是？","options":["8","10","16","0"],"answer":1,"explain":"懒加载：new ArrayList() 底层数组为空，第一次 add 时扩到 10；之后 1.5 倍扩容。","topic":"集合"},{"q":"遍历 ArrayList 时删除元素，会触发？","options":["正常删除","ConcurrentModificationException","NullPointerException","静默失败"],"answer":1,"explain":"fail-fast：modCount 与 expectedModCount 不一致立即抛异常。用 iterator.remove() 或 removeIf。","topic":"集合"},{"q":"HashMap 中 key 重复 put 会？","options":["报错","新增两个条目","覆盖旧 value","忽略新值"],"answer":2,"explain":"相同 key（equals 相等）时新值覆盖旧值并返回旧值——这也是 put 返回值的妙用。","topic":"集合"},{"q":"下列关于接口说法错误的是？","options":["接口可以被多实现","接口中的变量默认 public static final","JDK8 后接口可以有 default 方法","接口可以实例化"],"answer":3,"explain":"接口不能直接 new（匿名内部类实现除外），只能被类实现后通过多态使用。","topic":"面向对象"},{"q":"try 块中 return 5，finally 块中 System.out.println(\\"f\\")，finally 会执行吗？","options":["不执行","执行，在 return 前","执行，在 return 后真正返回前","看 JVM 心情"],"answer":2,"explain":"return 表达式先求值暂存，再执行 finally，最后真正返回——finally 几乎总执行（除非 exit/崩溃）。","topic":"异常"},{"q":"SQL 中过滤分组结果用？","options":["WHERE","HAVING","GROUP","ORDER BY"],"answer":1,"explain":"WHERE 过滤行（聚合前），HAVING 过滤组（聚合后），配合 GROUP BY 使用。","topic":"MySQL"},{"q":"SELECT COUNT(*) 与 COUNT(col) 的区别是？","options":["完全一样","COUNT(col) 不统计 col 为 NULL 的行","COUNT(*) 更慢","COUNT(col) 更慢"],"answer":1,"explain":"COUNT(*) 数行数；COUNT(col) 跳过 NULL 值。有 NULL 时结果不同。","topic":"MySQL"},{"q":"下列哪个命令用于提交本地修改到版本库？","options":["git push","git commit","git add","git clone"],"answer":1,"explain":"add 进暂存区 → commit 进本地仓库 → push 推远程。链路别搞混。","topic":"Git"},{"q":"以下代码结果：Integer a = 127, b = 127; Integer c = 128, d = 128; a == b 和 c == d 分别是？","options":["true true","true false","false false","false true"],"answer":1,"explain":"IntegerCache 缓存 -128~127，127 是同一对象；128 各自新建对象 == 比地址为 false。包装类一律 equals。","topic":"Java 基础"},{"q":"JVM 负责的是？","options":["编译源码为字节码","执行字节码并管理内存","编写代码","打包 jar"],"answer":1,"explain":"javac 编译，JVM 执行字节码 + GC 内存管理。\\"一次编写到处运行\\"靠 JVM。","topic":"JVM"},{"q":"以下哪个不是有效变量名？","options":["_count","$price","2name","userName2"],"answer":2,"explain":"变量名不能以数字开头。_ 和 $ 合法（但不推荐 $）。","topic":"Java 基础"},{"q":"HTTP 状态码 404 表示？","options":["服务器内部错误","资源未找到","请求成功","未授权"],"answer":1,"explain":"404 Not Found 资源不存在；500 服务器错误；200 成功；401 未认证。","topic":"HTTP"},{"q":"抽象类和接口，下列说法正确的是？","options":["都能被实例化","抽象类可含构造器和成员变量，接口变量默认常量","接口必须包含抽象方法","一个类只能实现一个接口"],"answer":1,"explain":"两者都不能实例化；接口可有 default 方法（8+）；接口可多实现。抽象类\\"半成品\\"、接口\\"契约\\"是设计本质区别。","topic":"面向对象"}]},{"id":"exam-mid","icon":"📘","name":"第二套 · 进阶实战卷","level":"进阶","minutes":40,"passScore":60,"desc":"覆盖并发、JVM、索引事务、Spring 原理。学完第 5~7 章后挑战，接近真实校招笔试难度。","questions":[{"q":"线程池参数 core=2, max=4, queue=5。当前 2 核心忙、队列满 5 个，再来任务会？","options":["进队列等待","创建第 3 个线程执行","直接拒绝","丢弃队首"],"answer":1,"explain":"核心满→队列；队列满→扩到 max；再满→拒绝。\\"先排队后扩容\\"是高频考点。","topic":"并发"},{"q":"volatile 关键字不能保证的是？","options":["可见性","禁止指令重排","原子性","内存屏障"],"answer":2,"explain":"volatile 两语义：可见性+有序性。i++ 这类复合操作不原子，需 AtomicInteger 或锁。","topic":"并发"},{"q":"线程安全的 List 实现不包括？","options":["Vector","CopyOnWriteArrayList","Collections.synchronizedList(list)","ArrayList"],"answer":3,"explain":"ArrayList 线程不安全。并发场景用 COW（读多写少）或 synchronized 包装。","topic":"集合"},{"q":"JVM 中线程私有的内存区域是？","options":["堆","方法区/元空间","虚拟机栈","字符串常量池"],"answer":2,"explain":"栈、程序计数器、本地方法栈线程私有；堆和方法区共享。","topic":"JVM"},{"q":"G1 收集器的核心创新是？","options":["标记-复制算法","Region 分区 + 按停顿目标优先回收","只回收新生代","单线程回收"],"answer":1,"explain":"堆切等大 Region，回收价值高的区域优先处理（Garbage First 得名），可设定软停顿目标。","topic":"JVM"},{"q":"双亲委派模型的正确描述是？","options":["子加载器先自己加载再给父","父加载器优先，父无法加载才子加载","随机选择加载器","只允许一个加载器"],"answer":1,"explain":"先委托父→父搞不定子才上。保证核心类安全 + 类唯一不重复。","topic":"JVM"},{"q":"事务隔离级别中，MySQL InnoDB 默认是？","options":["读未提交","读已提交","可重复读","串行化"],"answer":2,"explain":"InnoDB 默认 RR，并通过 MVCC+临键锁基本解决幻读，强于 SQL 标准的 RR 定义。","topic":"MySQL"},{"q":"联合索引 (a, b, c)，以下能用到索引的是？","options":["WHERE b=1","WHERE a=1 AND c=2","WHERE a=1 AND b>5 AND c=2","WHERE c=1"],"answer":2,"explain":"a 等值 + b 范围可用（部分），c 在范围列之后断档用不上；B 中 c 断档（b 缺失）。严格说 C 用到 (a,b)。","topic":"MySQL"},{"q":"EXPLAIN 输出 type=ALL 意味着？","options":["命中唯一索引","全表扫描","覆盖索引","索引下推"],"answer":1,"explain":"type 性能梯度 system>const>eq_ref>ref>range>index>ALL。ALL 全表扫描，大表必须优化。","topic":"MySQL"},{"q":"undo log 的作用不包括？","options":["事务回滚","MVCC 版本链","崩溃恢复数据页","保存修改前镜像"],"answer":2,"explain":"崩溃恢复靠 redo log（重做）；undo 是回滚+一致性读。","topic":"MySQL"},{"q":"Spring IoC 的主要作用是？","options":["提升运行速度","解耦对象创建与依赖管理","减少代码行数","自动修复 Bug"],"answer":1,"explain":"控制反转把对象装配交给容器：依赖接口不依赖实现，换实现零改动，可测性强。","topic":"Spring"},{"q":"@Transactional 默认遇到什么异常回滚？","options":["所有 Exception","Error","RuntimeException 和 Error","受检异常"],"answer":2,"explain":"默认只回滚运行时异常和 Error。抛 IOException 不回滚！惯例 rollbackFor=Exception.class。","topic":"Spring"},{"q":"同类中 methodA() 调 this.methodB()（@Transactional 标注），B 的事务？","options":["生效","不生效（未走代理）","部分生效","编译错误"],"answer":1,"explain":"AOP 靠代理对象织入，this 是原始对象。自调用是事务失效第一大原因。","topic":"Spring"},{"q":"Spring Boot 自动配置从哪里读取配置类列表？","options":["application.yml","META-INF 下的 imports/factories 文件","pom.xml","启动类注解参数"],"answer":1,"explain":"AutoConfigurationImportSelector 读 META-INF/spring/...imports（2.7 前是 spring.factories），配合 @Conditional 过滤。","topic":"Spring"},{"q":"Redis 缓存\\"查询不存在数据导致请求全打 DB\\"的问题是？","options":["击穿","穿透","雪崩","倾斜"],"answer":1,"explain":"穿透=查没有的数据；击穿=热点 key 过期瞬间；雪崩=大面积同时失效。方案：空值缓存/布隆过滤器。","topic":"Redis"},{"q":"Cache Aside 模式的写顺序是？","options":["先删缓存再更新库","先更新库再删缓存","先更新缓存再更新库","只更新缓存"],"answer":1,"explain":"先库后删缓存+过期时间兜底是主流；反过来旧值回填窗口大。强一致需求上 Canal+MQ。","topic":"Redis"},{"q":"Redis 内存达到 maxmemory 后，最常推荐的淘汰策略是？","options":["noeviction","allkeys-lru","volatile-random","volatile-ttl"],"answer":1,"explain":"纯缓存场景 allkeys-lru 最常用：全量 key 中淘汰最久未使用。noeviction 会写报错。","topic":"Redis"},{"q":"保证\\"消息不丢\\"的消费端做法是？","options":["自动 ack","业务处理成功后手动 ack","发消息前备份","队列加倍"],"answer":1,"explain":"自动 ack 在\\"处理中宕机\\"时丢消息。手动 ack 保证至少一次语义（配合幂等防重复）。","topic":"消息队列"},{"q":"解决哈希冲突，JDK8 HashMap 采用？","options":["开放寻址","链表+红黑树（链表长超 8 且数组≥64 树化）","二次哈希","溢出区"],"answer":1,"explain":"冲突挂链，长了转红黑树把最坏 O(n) 降到 O(log n)；树化前提数组 ≥64，否则先扩容。","topic":"集合"},{"q":"HashMap 扩容触发条件是？","options":["size > capacity","size > capacity × 0.75（负载因子）","put 报错时","手动调用"],"answer":1,"explain":"超过\\"容量×0.75\\"翻倍扩容。0.75 是空间与冲突概率的折中。","topic":"集合"}]},{"id":"exam-interview","icon":"📕","name":"第三套 · 综合面试模拟卷","level":"冲刺","minutes":45,"passScore":70,"desc":"模拟真实面试问答的选择题化版本：原理 + 场景 + 方案设计。冲这 70 分及格线，不过就回去背八股。","questions":[{"q":"对象进入老年代的条件不包括？","options":["年龄达到 15","大对象直接进入","动态年龄判断（Survivor 中同龄超一半）","刚 new 出来的小对象"],"answer":3,"explain":"新对象默认进 Eden（例外：大对象直接进老年代、TLAB 分配）。晋升三途径：年龄 15、大对象、动态年龄。","topic":"JVM"},{"q":"CMS 收集器被废弃的根本原因是？","options":["太占内存","标记-清除产生碎片+并发失败退化，G1 更优","只支持老年代——这是事实但不是废因","开源协议问题"],"answer":1,"explain":"CMS 碎片化导致 Full GC 退化成 Serial Old 长停顿，JDK14 移除。G1 用 Region+整理算法接棒。","topic":"JVM"},{"q":"ThreadLocal 内存泄漏的根源是？","options":["ThreadLocal 本身太大","Entry 的 key 被回收成 null 后 value 强引用链无法到达且线程长存","GC 不工作","Map 容量太小"],"answer":1,"explain":"key 弱引用被 GC → (null, value) 残留 → 线程池线程不死就泄漏。解法：finally remove()。","topic":"并发"},{"q":"synchronized 锁升级顺序正确的是？","options":["重量级→轻量级→偏向","偏向→轻量级→重量级","轻量级→偏向→重量级","随机"],"answer":1,"explain":"无锁→偏向（单线程）→轻量级（CAS 自旋）→重量级（monitor 阻塞）。单向不可逆。","topic":"并发"},{"q":"CAS 的 ABA 问题解决方案是？","options":["加锁","版本号机制（如 AtomicStampedReference）","减少线程","换 synchronized"],"answer":1,"explain":"值 A→B→A 过程 CAS 感知不到。加版本戳：每次修改版本+1，比较值+版本。","topic":"并发"},{"q":"InnoDB 为什么选 B+ 树而不是 B 树？","options":["B 树不稳定","B+ 数据全在叶子且叶子成链表，范围查询强、非叶子不存数据树更矮","B 树不能存大对象","历史原因"],"answer":1,"explain":"矮胖=少 IO；叶子链表=范围扫描 O(1) 接力。B 树数据散在各层，范围查询要中序回溯。","topic":"MySQL"},{"q":"RR 隔离级别下，普通 SELECT 防幻读靠？","options":["行锁","表锁","MVCC 快照读","乐观锁"],"answer":2,"explain":"快照读走 MVCC（ReadView 复用第一次的），看不到新提交行；当前读（FOR UPDATE）才靠 Next-Key 锁。","topic":"MySQL"},{"q":"线上一条 SQL 突然变慢，第一步应该？","options":["直接加索引","EXPLAIN 分析执行计划定位原因","重启数据库","升级配置"],"answer":1,"explain":"先定位再动手是工程铁律：EXPLAIN 看扫描方式/索引命中/rows，盲目加索引可能无效甚至更糟。","topic":"MySQL"},{"q":"Spring Bean 生命周期中 AOP 代理对象在哪一步生成？","options":["实例化时","属性填充时","初始化后（BeanPostProcessor 后置处理）","销毁前"],"answer":2,"explain":"初始化完成后由 AbstractAutoProxyCreator 后置处理器判断是否需要代理——所以代理包着的是\\"初始化完\\"的对象。","topic":"Spring"},{"q":"解决循环依赖，Spring 用的是？","options":["直接报错","三级缓存（提前暴露早期引用工厂）","反射强制注入","GC 处理"],"answer":1,"explain":"singletonObjects/earlySingletonObjects/singletonFactories 三级缓存：A 创建中提前暴露工厂，B 注入 A 的早期引用。仅单例+setter 注入可解；构造器循环依赖无解。","topic":"Spring"},{"q":"Redis 单线程为什么快，不包括哪个原因？","options":["纯内存","IO 多路复用 epoll","避免上下文切换","多线程并行计算"],"answer":3,"explain":"Redis 是\\"单线程\\"模型（6.0 后仅网络 IO 多线程），快靠内存+epoll+无锁+高效结构，不是并行计算。","topic":"Redis"},{"q":"Redis 分布式锁未设置过期时间的最大风险是？","options":["性能差","持有者宕机后死锁，无人能解锁","锁不住","数据丢失"],"answer":1,"explain":"必须 SET NX EX 原子设置过期+唯一值+Lua 安全释放；Redisson 看门狗续期是工业级方案。","topic":"Redis"},{"q":"秒杀场景\\"Redis 预扣库存 + MQ 异步下单\\"的核心目的是？","options":["省电","把万级并发削峰成数据库可承受的量级","好看","防止重复下单"],"answer":1,"explain":"Redis 原子扣减挡住无效流量，MQ 把落库节奏与流量洪峰解耦——削峰填谷是秒杀架构灵魂。","topic":"场景设计"},{"q":"缓存与数据库一致性方案中\\"延迟双删\\"针对的问题是？","options":["缓存宕机","读写并发下旧值回填缓存","主从延迟","大 key"],"answer":1,"explain":"删缓存→更库→（读写并发的读请求可能把旧值回填）→延迟再删一次，清理脏缓存。延迟=主从同步+业务耗时。","topic":"Redis"},{"q":"Kafka 比 RabbitMQ 吞吐高的核心原因是？","options":["语言不同","顺序写磁盘+零拷贝+批量+分区并行","没管理界面","消息短"],"answer":1,"explain":"日志分段顺序追加写、sendfile 零拷贝、批量压缩传输、分区水平扩展——工程组合拳。","topic":"消息队列"},{"q":"接口幂等性设计，下列哪个不适合做幂等依据？","options":["数据库唯一索引","请求携带唯一 requestId + 去重表","系统当前时间戳","状态机条件更新"],"answer":2,"explain":"时间戳每次都不同，无法判重。唯一约束/去重表/状态机/setnx 都是可靠幂等手段。","topic":"场景设计"},{"q":"TCP 三次握手中，第三次 ACK 丢失会？","options":["连接建立成功","服务端重发 SYN+ACK 直到超时回收（客户端可先发数据触发）","客户端宕机","进入 TIME_WAIT"],"answer":1,"explain":"服务端停在 SYN_RCVD 状态重传 SYN+ACK；客户端认为已建立，首包数据可携带 ACK 完成。","topic":"网络"},{"q":"JWT 相比 Session 的最大劣势是？","options":["性能差","无法服务端主动作废（无状态双刃剑）","不安全","不能跨域"],"answer":1,"explain":"签发后无法吊销，登出/封号需黑名单或短 TTL+Refresh 兜底。优势是无状态横向扩展友好。","topic":"认证"},{"q":"Nginx 反向代理的作用不包括？","options":["负载均衡","隐藏真实服务","静态资源服务","数据库分库分表"],"answer":3,"explain":"分库分表是数据层的事（ShardingSphere）。Nginx 活在 HTTP 层：转发、均衡、缓存、限流。","topic":"中间件"},{"q":"项目里\\"用户反馈下单接口偶尔 500，日志偶发 Deadlock found\\"，最优解法是？","options":["换 MySQL 为 MongoDB","梳理加锁顺序统一（如按订单 id 升序）+ 缩小事务 + 重试死锁","加大连接池","升级 JDK"],"answer":1,"explain":"死锁根因多为交叉加锁顺序。统一顺序破坏循环等待条件；小事务减少持锁时间；应用层捕获死锁异常重试（InnoDB 自动回滚一方）。","topic":"场景设计"}]},{"id":"exam-network","icon":"📡","name":"第四套 · 计算机网络专项卷","level":"进阶","minutes":30,"passScore":60,"desc":"对标小林 coding《图解网络》：TCP 握手挥手、滑动窗口、HTTP/HTTPS 全覆盖。","questions":[{"q":"TCP 建立连接时，SYN 洪泛攻击的原理是？","options":["发送大量数据撑爆带宽","伪造源 IP 发海量 SYN，占满半连接队列","不断发送 RST","篡改序号"],"answer":1,"explain":"服务端收到 SYN 就分配资源进 SYN_RCVD 等确认，攻击者不回 ACK，半连接队列耗尽。防御：syncookie、调大队列、减少重试。","topic":"TCP"},{"q":"四次挥手中，服务端收到 FIN 后先回 ACK 再发自己的 FIN，原因是？","options":["协议规定必须分开","服务端可能还有未发完的数据，ACK 立即回、FIN 等数据发完","为了重传","降低带宽"],"answer":1,"explain":"全双工两个方向独立关闭。握手时可合并（无积压数据），挥手时通常不能——这就是\\"四次\\"的由来。极端情况（无数据+延迟确认合并）可变三次。","topic":"TCP"},{"q":"流量控制与拥塞控制的区别是？","options":["一个是 TCP 一个是 UDP 的","流控防\\"接收方\\"过载（rwnd），拥塞控制防\\"网络\\"过载（cwnd）","完全相同只是叫法不同","拥塞控制只用于局域网"],"answer":1,"explain":"流控端到端，看接收方通告；拥塞控制全局，看丢包/延迟。实际发送窗口 = min(rwnd, cwnd)。","topic":"TCP"},{"q":"TCP 超时重传后，cwnd 会如何变化？","options":["减半继续","不变","重置为 1 MSS，重新慢启动（ssthresh 设为当前一半）","翻倍"],"answer":2,"explain":"超时意味着严重拥塞，重罚：cwnd=1 从头来。对比快恢复（3 重复 ACK）只是减半。","topic":"TCP"},{"q":"HTTP 状态码 502 与 504 的区别是？","options":["一个是客户端错","502=网关收到无效响应（上游挂了/返回格式错），504=网关等上游超时","都是重定向","502 表示成功"],"answer":1,"explain":"Nginx 场景：上游进程崩了/返回残缺 → 502；上游处理太慢超过 proxy_read_timeout → 504。排错方向不同：502 查进程存活，504 查接口耗时。","topic":"HTTP"},{"q":"HTTPS 证书验证失败的可能原因不包括？","options":["证书过期","域名不匹配","证书链不完整（缺中间证书）","TLS 版本太新"],"answer":3,"explain":"常见失败：过期/域名不符/链不完整/自签名不受信。TLS 版本太新只会导致\\"协商失败\\"，不是证书验证失败。","topic":"HTTPS"},{"q":"TLS 1.3 相比 1.2 的改进不包括？","options":["握手 1-RTT，支持 0-RTT 恢复","废弃 RSA 密钥交换，强制 (EC)DHE 实现前向安全","减少了加密套件数量（去弱留强）","数据传输改用 UDP"],"answer":3,"explain":"TLS1.3 仍跑在 TCP 上；改用 UDP 的是 HTTP/3 的 QUIC。其余都是 1.3 的真实改进。","topic":"HTTPS"},{"q":"关于 HTTP/2 多路复用，正确的说法是？","options":["一个 TCP 连接上并发多个流，解决 HTTP 层队头阻塞","必须配合 HTTPS 之外的新协议","每个请求仍需独立 TCP 连接","彻底解决了所有队头阻塞"],"answer":0,"explain":"HTTP/2 二进制分帧+流实现应用层并发；但 TCP 层丢包仍会阻塞所有流（TCP 层 HOL），需 HTTP/3/QUIC 解决。","topic":"HTTP"},{"q":"TCP 粘包问题的正确处理方式是？","options":["TCP 本身有消息边界，无需处理","应用层定界：定长包、分隔符、长度字段+数据体","改用 UDP 就一定不粘","调大内核缓冲区"],"answer":1,"explain":"TCP 是字节流无边界，\\"粘包\\"是应用层未定界的表现。主流方案是\\"长度字段+body\\"（HTTP 的 Content-Length 即此思路）。","topic":"TCP"},{"q":"强缓存命中时，浏览器的行为是？","options":["发请求，服务器回 304","不发请求，直接读本地缓存（200 from cache）","重新下载全量资源","回源 CDN"],"answer":1,"explain":"强缓存（max-age 未过期）连请求都不发；协商缓存才发请求问服务器（304 表示没变）。","topic":"HTTP"},{"q":"从输入 URL 到页面显示，DNS 解析的正确顺序是？","options":["根域名→顶级域→权威域","浏览器缓存→本地 DNS（递归）→根→顶级域→权威域（迭代）","权威域→顶级域→根","先 TCP 握手再 DNS"],"answer":1,"explain":"主机对本地 DNS 是递归查询（要最终答案），本地 DNS 对外是迭代查询（一级级问）。先有 IP 才有 TCP 握手。","topic":"DNS"},{"q":"ARP 协议的作用是？","options":["把域名解析成 IP","把 IP 地址解析成 MAC 地址（同局域网内）","分配 IP 地址","加密数据"],"answer":1,"explain":"网络层寻址靠 IP，链路层实际帧传输靠 MAC；ARP 广播问\\"谁有这个 IP\\"，对应 MAC 回答。分配 IP 的是 DHCP。","topic":"网络基础"},{"q":"以下哪种情况 TCP 连接会立即进入 CLOSED？","options":["发送 FIN 后","收到 RST 报文","收到 ACK","进入 TIME_WAIT 后"],"answer":1,"explain":"RST 强制复位，立即释放连接资源（这也是\\"给服务端发 RST 探活\\"的原理）。正常关闭要走 FIN→TIME_WAIT 流程。","topic":"TCP"},{"q":"为什么视频通话用 UDP 而不重传丢失的帧？","options":["UDP 更安全","实时性优先：旧帧重传到达已过时，不如丢弃继续直播","UDP 带宽免费","TCP 不能传视频"],"answer":1,"explain":"实时场景\\"最新数据\\"比\\"完整数据\\"重要。TCP 重传反而加剧延迟（队头阻塞），宁可丢帧也要低延迟。","topic":"网络应用"},{"q":"CORS 预检请求使用的 HTTP 方法是？","options":["GET","POST","OPTIONS","HEAD"],"answer":2,"explain":"复杂请求（自定义头/PUT/DELETE 等）先发 OPTIONS 询问服务端允许的源/方法/头，通过后才发真实请求。","topic":"HTTP"},{"q":"HTTP/1.1 的 Keep-Alive 解决了什么？没解决什么？","options":["解决了队头阻塞；没解决连接复用","解决了连接复用（减少握手）；没解决响应队头阻塞（串行处理）","解决了安全性；没解决性能","什么都没解决"],"answer":1,"explain":"Keep-Alive 让一个 TCP 连接处理多个请求（免重复握手），但同一时刻仍一连接一请求，慢响应会堵住后面的——HOL 依旧。","topic":"HTTP"},{"q":"0-RTT 会话恢复存在的安全风险是？","options":["无法加密","重放攻击：攻击者截获 0-RTT 数据可重复发送","证书失效","不能携带数据"],"answer":1,"explain":"0-RTT 数据在握手完成前发送，服务端无法防重放。缓解：只允许幂等请求走 0-RTT、服务端记录去重。","topic":"HTTPS"},{"q":"TIME_WAIT 过多（几万个）最不可能的原因是？","options":["本机作为客户端大量短连接爬取","压测工具高频建连","服务端主动关闭大量长连接","开启了 keep-alive 长连接且复用良好"],"answer":3,"explain":"TIME_WAIT 出现在主动关闭方。长连接复用良好意味着关闭频率低，TIME_WAIT 自然少。前三者都是典型诱因。","topic":"TCP"},{"q":"对称加密 AES 和非对称 RSA 在 HTTPS 中的分工是？","options":["都用 RSA","RSA 交换会话密钥并验签，AES 加密实际数据","都用 AES","AES 验证证书"],"answer":1,"explain":"非对称安全但慢（大数运算），只管密钥协商和签名；对称快，管海量数据。混合加密 = 安全与性能的平衡。","topic":"HTTPS"},{"q":"浏览器输入一个 HTTPS 网址到首屏，哪个环节不涉及 DNS？","options":["获取服务器 IP","CDN 边缘节点调度","建立 TCP 连接后的 TLS 证书域名比对","TLS 密钥计算"],"answer":3,"explain":"TLS 密钥计算用随机数/ECDHE 参数，与 DNS 无关。A/B/C 都依赖域名或 IP 解析链路。","topic":"综合"}]},{"id":"exam-os","icon":"⚙️","name":"第五套 · 操作系统与底层专项卷","level":"进阶","minutes":30,"passScore":60,"desc":"对标小林 coding《图解系统》：进程线程、内存、IO 多路复用全覆盖。","questions":[{"q":"以下哪项是线程\\"私有\\"的资源？","options":["堆","全局变量","栈和寄存器/程序计数器","打开的文件表"],"answer":2,"explain":"线程私有：栈、寄存器、PC、errno；共享：堆、全局变量、文件、信号处理。","topic":"进程线程"},{"q":"进程上下文切换的主要开销来源是？","options":["进程名太长","切换页表导致 TLB 失效 + 内核栈/寄存器切换","磁盘 IO","网络延迟"],"answer":1,"explain":"换地址空间 → TLB 全失效 → 后续内存访问都要重新查页表。线程共享地址空间，切换便宜得多。","topic":"进程线程"},{"q":"协程的核心优势是？","options":["利用多核更彻底","用户态调度、切换纳秒级、单线程可开百万个","不需要内存","自动加锁"],"answer":1,"explain":"协程调度不进内核，只保存少量寄存器。但单个协程线程遇到内核阻塞仍会卡住整线程，要配非阻塞 IO。","topic":"进程线程"},{"q":"管道（匿名 pipe）的使用限制是？","options":["只能传输二进制","只能用于有亲缘关系的进程（父子），且单向","速度最慢","不能跨网络"],"answer":1,"explain":"匿名管道是内存中的环形缓冲，进程退出即消失；命名管道 FIFO 突破亲缘限制；跨主机用 Socket。","topic":"IPC"},{"q":"虚拟内存出现缺页中断后，OS 的动作是？","options":["直接杀死进程","从磁盘调入所需页，内存不足按置换算法淘汰页面","重启系统","扩大磁盘"],"answer":1,"explain":"缺页 → 若有空闲帧直接调入；没有则按 LRU 近似等算法淘汰（脏页先写回）。频繁缺页=颠簸，性能雪崩。","topic":"内存"},{"q":"top 命令中 VIRT 远大于 RES 的原因是？","options":["内存泄漏","VIRT 是虚拟地址空间（含 mmap/保留未用），RES 是实际物理驻留","VIRT 单位不同","RES 不包括堆"],"answer":1,"explain":"malloc 预留的虚拟空间不算物理内存（惰性分配）。JVM 大堆进程 VIRT 很大是正常现象，看 RES 才接近真实占用。","topic":"内存"},{"q":"select 相比 epoll 的劣势不包括？","options":["fd 上限 1024","每次调用全量拷贝 fd 集合进内核","返回后要 O(n) 遍历找就绪","不能监听 UDP socket"],"answer":3,"explain":"select 可以监听任何 fd（含 UDP），这不是它的劣势；ABC 才是 select 三宗罪。","topic":"IO"},{"q":"epoll 的边缘触发（ET）模式要求？","options":["fd 必须阻塞","配合非阻塞 fd，一次性循环读干（直到 EAGAIN）","每次都要重新注册","只能用于监听 socket"],"answer":1,"explain":"ET 只通知一次，漏读就再也不提醒。必须非阻塞+循环读到 EAGAIN。LT（Redis 用的）可读不完下次还通知。","topic":"IO"},{"q":"死锁的四个必要条件中，\\"按固定顺序加锁\\"破坏的是？","options":["互斥","持有并等待","不可剥夺","循环等待"],"answer":3,"explain":"所有线程都按同一顺序申请锁，就不会形成\\"A 等 B、B 等 A\\"的环形等待链。这是生产中最实用的死锁预防手段。","topic":"死锁"},{"q":"共享内存是最快 IPC，但仍需要信号量的原因是？","options":["信号量加快读写","共享内存本身不同步，需要信号量做互斥/同步保护","法律要求","信号量负责加密"],"answer":1,"explain":"共享内存就是同一块物理内存，读写无内核介入——快，但并发读写会竞态。信号量（P/V）负责\\"谁什么时候能用\\"。","topic":"IPC"},{"q":"零拷贝 sendfile 相比传统\\"read+write\\"的优势是？","options":["磁盘更快","数据不经过用户态，减少拷贝次数和上下文切换","加密更安全","自动压缩"],"answer":1,"explain":"传统 4 次拷贝 4 次切换；sendfile 内核侧直接转发（可 DMA 到网卡），CPU 不参与数据拷贝。Kafka/Nginx 静态文件受益。","topic":"IO"},{"q":"LRU 页面置换算法的含义是？","options":["淘汰最先进入的页","淘汰最长时间未被访问的页","淘汰访问频率最低的页","随机淘汰"],"answer":1,"explain":"Least Recently Used=最近最久未使用（看时间）；LFU 看频率。Redis 的 LRU 是随机抽样近似版。","topic":"内存"},{"q":"以下哪种场景最适合多进程而非多线程？","options":["共享大量数据的计算","需要故障隔离的服务（如 Chrome 每个 tab）","频繁小数据交换","单机高并发连接"],"answer":1,"explain":"进程隔离性好：一个崩不影响其他。要隔离用多进程；要共享和轻量用线程/协程。","topic":"进程线程"},{"q":"B+ 树索引与操作系统的关联，正确的说法是？","options":["B+ 树每层对应一次磁盘页 IO，页大小对齐 OS/磁盘的块","B+ 树只存在 CPU 缓存","索引不需要磁盘","页大小无关紧要"],"answer":0,"explain":"InnoDB 16KB 页 ≈ 文件系统块/磁盘扇区的整数倍，一次树节点访问 = 一次页读取。树高决定 IO 次数——这就是\\"矮胖\\"的意义。","topic":"综合"},{"q":"用户态与内核态切换的触发场景不包括？","options":["系统调用","缺页中断","时钟中断引发的调度","两个用户线程间切换（同一进程）"],"answer":3,"explain":"用户级线程切换完全在用户态完成（不进内核），这是协程快的原因。前三者都要陷入内核。","topic":"进程线程"},{"q":"fork 创建子进程后，父子进程对同一变量的修改互相可见吗？","options":["可见，同一内存","不可见，写时复制（COW）后各自持有独立页","父进程可见子进程不可见","取决于编译器"],"answer":1,"explain":"fork 时共享物理页（只读），任一方写入触发 COW 复制出新页各自修改——隔离性由 OS 保证。","topic":"进程线程"},{"q":"Redis 单线程快的理由中，与 OS 相关的是？","options":["算法复杂度低","epoll IO 多路复用 + 内存操作 + 无上下文切换和锁竞争","CPU 核数多","磁盘顺序读写"],"answer":1,"explain":"纯内存操作纳秒级 + epoll 单线程管万级连接 + 单线程免锁免切换。6.0 的多线程只加速网络 IO。","topic":"综合"},{"q":"mmap 相比 read 的优势是？","options":["一定更快无脑用","文件映射进地址空间，减少一次用户态拷贝，适合随机访问大文件","不需要内存","自动持久化"],"answer":1,"explain":"mmap 把文件映射为内存区域，读取不再经过用户缓冲拷贝；但页错误开销和小文件场景可能更慢——不是银弹。","topic":"IO"},{"q":"CPU 利用率高但应用吞吐低的常见原因是？","options":["CPU 太好","频繁上下文切换/自旋锁忙等/GC 抖动等无效消耗","网络太慢","磁盘太满"],"answer":1,"explain":"\\"忙\\"不等于\\"有效\\"。top 看 us/sy/wa，vmstat 看 cs（切换数），jstat 看 GC——定位是算力浪费在何处。","topic":"排查"},{"q":"操作系统提供\\"虚拟内存\\"的最主要目的是？","options":["提高 CPU 主频","进程隔离 + 地址空间统一 + 物理内存超卖（按需加载/交换）","加快网络","替代硬盘"],"answer":1,"explain":"三大收益：隔离安全、编程简单（连续地址）、内存超卖。代价是页表管理和缺页开销。","topic":"内存"}]},{"id":"exam-deep","icon":"🧗","name":"第六套 · MySQL/Redis 深度综合卷","level":"挑战","minutes":35,"passScore":60,"desc":"对标小林 coding《MySQL/Redis》：B+ 树、MVCC、三大缓存问题全真模拟。","questions":[{"q":"InnoDB 中，一棵 3 层 B+ 树约能存 2000 万行的前提估算依据是？","options":["每层 1000 行 × 1000 × 20","非叶子节点约 1170 个指针/页 × 1170 × 叶子每页约 16 行","2 的 24 次方","经验值无依据"],"answer":1,"explain":"16KB 页 ÷ (8B 主键+6B 指针) ≈ 1170；叶子每页约 16 行（1KB/行）。1170×1170×16 ≈ 2190 万。超过后树变 4 层，IO 增加。","topic":"索引"},{"q":"覆盖索引的含义是？","options":["索引覆盖了全表","查询字段全部包含在索引中，无需回表","一个索引覆盖多个表","主键索引的别称"],"answer":1,"explain":"如联合索引 (name, age) 能直接满足 SELECT id, name, age WHERE name=...。EXPLAIN 的 Extra 显示 Using index。高频优化手段。","topic":"索引"},{"q":"MVCC 的版本链存储在？","options":["binlog","undo log（通过 roll_ptr 串起来的历史版本）","redo log","单独的版本表"],"answer":1,"explain":"每行有 DB_TRX_ID 和 DB_ROLL_PTR 指向 undo 旧版本，多次修改形成链；ReadView 决定沿链找哪个可见版本。","topic":"事务"},{"q":"事务里执行 SELECT（RR 级别）用到 ReadView，判断\\"某版本可见\\"的规则是？","options":["trx_id 比 max 小即可见","trx_id < min 可见；≥ max 不可见；中间看是否在活跃列表","全部可见","全部不可见"],"answer":1,"explain":"低于最小活跃 id=早已提交可见；高于等于 max=快照后才开始不可见；中间的看是否还在未提交集合里。","topic":"事务"},{"q":"以下哪种情况 @Transactional 会失效？","options":["方法抛 RuntimeException","同类中 this.xxx() 调用事务方法（绕过代理）","传播级别 REQUIRED","方法为 public"],"answer":1,"explain":"事务由 AOP 代理实现，this 调用不走代理。解决：注入自身/拆类/AopContext.currentProxy()。另：catch 吞掉异常、非 public、引擎非 InnoDB 也失效。","topic":"Spring"},{"q":"redo log 写入流程中，innodb_flush_log_at_trx_commit=1 的含义是？","options":["每秒刷盘，可能丢 1 秒","每次事务提交都 fsync，最安全（配合 sync_binlog=1 双一配置）","不刷盘","只刷内存"],"answer":1,"explain":"双一配置（redo=1 + binlog=1）保证提交后宕机不丢数据，代价是性能；=2 每秒刷、=0 每秒写 OS 缓存，逐级降低安全性换性能。","topic":"日志"},{"q":"间隙锁（Gap Lock）在哪个隔离级别下存在？","options":["RU","RC","RR 的当前读","只在串行化"],"answer":2,"explain":"RR 级别的当前读（FOR UPDATE/UPDATE/DELETE）用 Next-Key（行+间隙）防幻读插入；RC 没有间隙锁，并发更好但可能幻读。","topic":"锁"},{"q":"用 EXPLAIN 分析慢 SQL，type 的性能从好到差排序正确的是？","options":["const > ref > range > index > ALL","ALL > index > range","ref > const","顺序无关"],"answer":0,"explain":"const(主键/唯一等值) > eq_ref > ref > range(范围) > index(扫全索引) > ALL(全表)。目标是消除 ALL 和 index。","topic":"优化"},{"q":"Redis 的 String 用 embstr 编码的条件和优势是？","options":["长度 ≤ 44 字节，redisObject 和 SDS 一次内存分配、连续存储省内存且缓存友好","任意长度","只有整数","仅集群模式"],"answer":0,"explain":"短字符串 embstr 一块内存（robj+SDS），超过 44B 转 raw（两次分配）。44 = 64(分配粒度) - 头部 - 结尾。","topic":"数据结构"},{"q":"Redis 主从复制时，从库首次同步的流程是？","options":["只同步增量命令","master bgsave 生成 RDB 发给从库全量加载，期间新写命令进缓冲区再同步（ replication backlog）","主库停写等从库追上","从库自己读主库磁盘"],"answer":1,"explain":"全量=RDB 快照 + 缓冲增量。断线重连可尝试增量复制（靠 offset 在 backlog 中找差距，backlog 太小则退化为全量）。","topic":"高可用"},{"q":"缓存与数据库双写不一致，最推荐的更新策略是？","options":["先更新缓存再更新库","Cache Aside：先更新数据库，再删除缓存","同时更新","只更新缓存定时刷库"],"answer":1,"explain":"先删缓存并发下旧读回填概率高；先更库再删缓存不一致窗口最小。再配合\\"延迟双删/订阅 binlog 删除\\"兜底。","topic":"缓存"},{"q":"Redis 分布式锁的正确释放姿势是？","options":["直接 DEL","Lua 脚本原子校验\\"锁值是自己\\"再 DEL（或用可续期方案如 Redisson 看门狗）","FLUSHALL","EXPIRE 归零"],"answer":1,"explain":"业务超时锁过期 → 别人拿到锁 → 自己 DEL 误删别人的锁。Lua 保证\\"判断+删除\\"原子；Redisson 看门狗自动续期解决业务超时。","topic":"分布式"},{"q":"布隆过滤器说\\"元素存在\\"，这个结论是？","options":["绝对正确","可能误判（哈希冲突），不存在的不会漏判","绝对错误","随机"],"answer":1,"explain":"位数组 k 个位全 1 → 可能存在（冲突导致误判率 p）；有任一 0 → 一定不存在（无漏）。用于穿透防护时\\"说不存在\\"才可靠。","topic":"缓存"},{"q":"Redis 大 key 删除的正确方式是？","options":["DEL 直接删","UNLINK 异步删（或 SCAN 分批），避免阻塞单线程","改小 value","重启实例"],"answer":1,"explain":"DEL 百万元素集合会卡住主线程数百 ms。4.0+ UNLINK 后台线程释放；老版本用 SCAN + 分批删。预防：限制集合长度、监控 bigkeys。","topic":"运维"},{"q":"Redis Cluster 中 key 的分片路由规则是？","options":["按 key 长度","CRC16(key) % 16384 定位槽，槽分布在各 master","按写入时间","随机"],"answer":1,"explain":"16384 个槽平均分给 master；客户端可重定向（MOVED）。多 key 操作要求同槽：可用 hash tag {user1000}.orders 强制同槽。","topic":"高可用"},{"q":"为什么 Redis 的过期 key 采用\\"惰性+定期\\"而不是到期立即删？","options":["实现者偷懒","到期立即删需要为每个 key 维护精确定时器，CPU 开销大；惰性+定期平衡 CPU 与内存","内存无限","为了兼容集群"],"answer":1,"explain":"海量定时器不可行。惰性（访问时删）+ 定期（每 100ms 随机抽样删）组合，用少量内存残留换 CPU——典型工程折中。","topic":"运维"},{"q":"MySQL 深分页 LIMIT 1000000,10 很慢，正确的优化是？","options":["加大内存","游标/子查询定位：WHERE id > 上次最大id LIMIT 10，或先查 id 再回表（延迟关联）","换 Redis","加 limit 参数"],"answer":1,"explain":"OFFSET 要扫描并丢弃前 100 万行。游标法利用索引有序直接跳转；延迟关联用覆盖索引先定位 id 再回表取 10 行。","topic":"优化"},{"q":"InnoDB count(*) 很慢的原因与方案是？","options":["InnoDB 要扫数据（MVCC 下不同事务看到的行数不同，无法存总数），大表可用二级索引扫/计数表/EXPLAIN 估数","数错了","MyISAM 更好的唯一原因是数据更安全","无解，必须换库"],"answer":0,"explain":"MVCC 决定\\"没有全局精确行数\\"。MyISAM 存总数但它不支持事务。方案：近似值 EXPLAIN、Redis 计数（有误差）、单独计数表（事务维护）。","topic":"优化"},{"q":"Redis 持久化方案\\"混合持久化\\"（4.0+）的含义是？","options":["RDB 和 AOF 同时全量写","AOF 重写时先写入 RDB 格式全量数据，之后追加增量命令——恢复快且丢失少","一半内存一半磁盘","主从各用一种"],"answer":1,"explain":"文件头 = RDB 全量（载入快），尾部 = AOF 增量（丢得少）。兼顾两者优点，生产推荐 aof-use-rdb-preamble yes。","topic":"持久化"},{"q":"热点账户余额频繁更新导致行锁争用严重，架构上合理的解法是？","options":["把字段改 TEXT","缓冲记账：Redis 预扣+异步批量落库/拆分子账户摊平热点行","加大连接池","换 MyISAM"],"answer":1,"explain":"单行热点写是 B+ 树行锁模型的天敌。思路都是\\"把 N 次单行写合并\\"：预扣异步落库、子账户轮转、队列串行批量。","topic":"场景设计"}]},{"id":"exam-jvm-conc","icon":"🧵","name":"第七套 · 并发与 JVM 专项卷","level":"进阶","minutes":30,"passScore":60,"desc":"Java 内存模型、线程池、锁升级、GC 器与调优——中高级面试的深水区专项检验。","questions":[{"q":"Java 内存模型（JMM）中的主内存与工作内存，正确说法是？","options":["就是堆和栈","所有共享变量存主内存，线程操作须先拷贝到自己的工作内存，改完再刷回——可见性问题的根源","工作内存是数据库缓存","JDK8 后废除"],"answer":1,"explain":"JMM 是抽象规范（屏蔽硬件差异）：线程只能操作工作内存副本，变量在主内存与工作内存间交互受 eight operations / happens-before 约束。volatile 就是通过强制刷回+失效副本保证可见。","topic":"JMM"},{"q":"happens-before 规则中\\"解锁先于后续对同一把锁的加锁\\"属于哪条？","options":["程序顺序规则","监视器锁规则","传递规则","线程启动规则"],"answer":1,"explain":"监视器锁规则：unlock 先 happens-before 后续同锁 lock——所以锁内修改对下一个拿锁的线程可见。volatile 规则、线程 start/join 规则同理构成可见性保障体系。","topic":"JMM"},{"q":"线程池中 corePoolSize=2, max=5, 队列容量=10，提交第 13 个任务（当前 2 核心 10 队列满）时？","options":["入队等待","创建第 3 个非核心线程执行","直接拒绝","丢弃队首"],"answer":1,"explain":"提交顺序：核心线程 → 队列 → 非核心线程（直到 max）→ 拒绝策略。队列满且未到 max 时扩线程——这也是\\"队列过大导致 max 失效\\"的原因。","topic":"线程池"},{"q":"ThreadPoolExecutor 的 keepAliveTime 作用于？","options":["所有线程","超过核心数的空闲线程（默认），allowCoreThreadTimeOut(true) 时也作用于核心线程","只作用于队列任务","主线程"],"answer":1,"explain":"非核心线程空闲超过 keepAliveTime 回收。核心线程默认常驻——长期低负载服务可开 allowCoreThreadTimeOut 省资源。","topic":"线程池"},{"q":"synchronized 修饰静态方法锁的是？","options":["实例对象","类的 Class 对象（全局唯一）","方法区","不锁"],"answer":1,"explain":"静态方法属于类：锁 Xxx.class，所有实例共用一把锁；实例方法锁 this。两者不互斥——同类的静态同步方法和实例同步方法可并发进入。","topic":"锁"},{"q":"轻量级锁膨胀为重量级锁的时机是？","options":["第一次加锁","自旋获取锁失败（竞争激烈，达到自适应自旋上限）","线程数超过 CPU 核数","JVM 启动 10 秒后"],"answer":1,"explain":"自旋是\\"赌锁很快释放\\"：失败说明竞争真实存在，继续空转浪费 CPU → 膨胀为重量级锁（OS mutex，线程挂起）。自适应自旋会参考历史成功率调整次数。","topic":"锁"},{"q":"AQS 独占模式获取失败后，线程在队列中的状态变化是？","options":["直接死亡","封装 Node 入队 → 前驱标记 SIGNAL → park 挂起，被前驱 release 时 unpark","自旋抢锁不放","抛异常"],"answer":1,"explain":"addWaiter 入队 → shouldParkAfterFailedAcquire 把前驱 waitStatus 设为 SIGNAL → LockSupport.park 挂起。release 时 unparkSuccessor 唤醒后继。这就是\\"等待-通知\\"的底层实现。","topic":"AQS"},{"q":"Semaphore(3) 初始 3 许可，acquire 4 次后第 4 个线程？","options":["获得许可","阻塞直到有线程 release","抛异常","覆盖别人的许可"],"answer":1,"explain":"Semaphore 许可数可配公平/非公平，acquire 减 release 增。用途：接口并发上限（连接池）、限流闸门。tryAcquire 不阻塞可做快速失败。","topic":"AQS"},{"q":"G1 收集器中 Humongous 区域存放？","options":["永久代","大于 Region 一半的大对象，直接进老年代逻辑区域，可能跨多个连续 Region","元空间数据","线程栈"],"answer":1,"explain":"Region 规格一般 1~32M：对象 ≥ Region/2 判为 Humongous。大量 Humongous 会引发 Mixed GC 压力甚至并发失败——这也是\\"G1 下大对象敏感\\"的原因，调大 Region 或优化代码拆分大对象。","topic":"GC"},{"q":"类加载器收到类加载请求后，正确流程是？","options":["立刻自己加载","逐级委托父加载器，Bootstrap 无法加载才逐级下放，保证核心类唯一与安全","随机选择加载器","并行加载取最快"],"answer":1,"explain":"双亲委派：防止核心 API 被篡改（自定义 java.lang.String 不会被加载）+ 避免重复加载。打破场景：SPI 线程上下文加载器、Tomcat 每应用隔离、热部署。","topic":"类加载"},{"q":"存活对象在 Survivor 区之间每复制一次，年龄？","options":["不变","加 1，达到阈值（默认 15）晋升老年代","减 1","重置为 0"],"answer":1,"explain":"对象头 Mark Word 用 4bit 存 GC 年龄（所以上限 15）。动态年龄判定：同龄对象总大小超 Survivor 一半，该年龄及以上直接晋升——防止 Surviver 装不下。","topic":"GC"},{"q":"jstack 输出中发现两个线程互相 WAITING (on object monitor)，且彼此持有对方需要的锁，这是？","options":["正常现象","死锁，jstack 底部会直接输出 \\"Found one Java-level deadlock\\" 并给出环路","内存泄漏","类加载问题"],"answer":1,"explain":"死锁四条件：互斥/持有等待/不可剥夺/循环等待。jstack 自动检测 Java 层死锁。预防：全局锁排序、tryLock 超时、缩小锁范围。","topic":"排错"},{"q":"JIT 即时编译中\\"方法调用计数器超阈值触发编译\\"对应的概念是？","options":["类加载","热点探测：C1/C2 把热点代码编译成本地机器码，后续调用走编译版本（还可能内联/逃逸分析优化）","GC 触发","反射"],"answer":1,"explain":"分层编译：C1 快速编译（client）、C2 深度优化（server）。热点代码 = 调用计数 + 回边计数超阈值。逃逸分析/锁消除/栈上分配都是 C2 优化产物。","topic":"JIT"},{"q":"读写锁 ReentrantReadWriteLock 中，读锁持有期间另一线程请求写锁会？","options":["立即成功","阻塞：读锁共享、写锁独占，写必须等所有读释放（写锁可降级为读，读不能升级为写）","升级为写锁","抛异常"],"answer":1,"explain":"锁降级（写→读）安全可行（同线程内先放写再拿读）；锁升级（读→写）会死锁（别的读还没放）。读多写少场景用它提升并发，JDK8 StampedLock 再加乐观读优化。","topic":"锁"},{"q":"线程的六种状态中，调用 Object.wait() 后进入？","options":["BLOCKED","WAITING（需 notify 唤醒；带超时的 wait(ms) 是 TIMED_WAITING）","TERMINATED","NEW"],"answer":1,"explain":"区分：BLOCKED 是等 monitor 锁（synchronized 竞争失败）；WAITING 是主动让出（wait/join/park）。sleep 不释放锁、wait 释放锁——经典对比题。","topic":"线程"},{"q":"OOM 后 heap dump 显示 byte[] 占 90%，业务是导出报表，最可能的原因是？","options":["JVM bug","一次性把全量数据载入内存（查询无分页 + POI 全内存模式），应改分页查询 + 流式写出（SXSSFWorkbook）","堆太小必然","数据库问题"],"answer":1,"explain":"大数据导出三板斧：分页拉数据、SXSSF 滑动窗口写 Excel、流式响应下载。任何\\"全量 in-memory\\"模式在数据量增长后必然 OOM。","topic":"排错"},{"q":"volatile 修饰数组引用（volatile int[] arr），对 arr[0]=1 的可见性？","options":["保证可见","不保证：volatile 只管引用本身，数组元素的修改不具 volatile 语义——要用 AtomicIntegerArray","编译报错","自动扩大到元素"],"answer":1,"explain":"volatile 数组是高频误区。元素级原子/可见需求用 AtomicIntegerArray/LongAdder 等，或锁。这题能答对说明真懂\\"volatile 修饰的是引用\\"而非内容。","topic":"JMM"},{"q":"Full GC 后老年代占用几乎没有下降，说明？","options":["GC 正常","老年代里都是活对象——存在内存泄漏或缓存过大，需要 dump 分析引用链","堆太小","CPU 太慢"],"answer":1,"explain":"GC 回收不掉 = 对象仍被 GC Roots 强引用。MAT 查支配树+引用链，常见根因：static 集合、ThreadLocal、连接器缓存。这题是\\"GC 问题转内存问题\\"的分水岭。","topic":"排错"},{"q":" CompletableFuture.allOf(cf1, cf2).join() 的语义是？","options":["任一完成即返回","等待全部完成后继续（thenApply 等在 allOf 之后能拿到两者结果），异常传播给 join","只等第一个","并行执行但不同步"],"answer":1,"explain":"编排利器：allOf 聚合等待、anyOf 竞速。默认线程池是 ForkJoinPool.commonPool（IO 密集慎用，建议自定义池）。异步任务链是 Java8+ 并发面试必考。","topic":"线程"},{"q":"线上频繁 Full GC 的第一优先级排查动作是？","options":["直接调大堆","看 GC 日志定位触发原因（晋升过快/元空间/Humongous/System.gc），再决定调参还是改代码","重启服务器","换 G1"],"answer":1,"explain":"先诊断后治疗：GC 日志能直接看到 Full GC 的 cause（Allocation Failure/Metaspace/System.gccall 等），不同 cause 解法完全不同。盲调 = 玄学运维。","topic":"排错"}]},{"id":"exam-spring","icon":"🌱","name":"第八套 · Spring 全家桶专项卷","level":"进阶","minutes":30,"passScore":60,"desc":"IoC/AOP/事务/Boot 自动装配/MVC 流程——后端框架原理的全真笔试。","questions":[{"q":"IoC 容器初始化的核心两阶段是？","options":["编译+运行","BeanDefinition 的加载注册（解析配置为 BeanDefinition Map）→ Bean 的实例化初始化（refresh 中的 finishBeanFactoryInitialization）","扫描+编译","无阶段"],"answer":1,"explain":"先\\"注册表\\"后\\"实例\\"：所有配置（XML/注解/imports）先转 BeanDefinition；非懒加载单例在容器 refresh 完成阶段统一创建。这种两段式为扩展点（BeanFactoryPostProcessor 改定义）留了缝。","topic":"IoC"},{"q":"BeanFactoryPostProcessor 与 BeanPostProcessor 的执行时机分别是？","options":["都在实例化后","前者在 Bean 实例化前修改 BeanDefinition（如占位符解析）；后者在 Bean 初始化前后加工 Bean 实例（如 AOP 代理）","前者废弃","无区别"],"answer":1,"explain":"记忆：Factory 级管\\"定义\\"，Bean 级管\\"实例\\"。PropertySourcesPlaceholderConfigurer 是前者；AnnotationAwareAspectJAutoProxyCreator 是后者。","topic":"IoC"},{"q":"@ConditionalOnMissingBean 的意义与坑是？","options":["必须有该 Bean","容器没有该类型 Bean 才装配当前配置——实现用户配置覆盖默认配置；但依赖加载顺序，跨模块顺序不当会失效","强制单例","性能优化"],"answer":1,"explain":"自动配置类必须在用户配置之后处理才正确生效——Spring Boot 用 @AutoConfigureAfter/Before 控制顺序。自定义 starter 时漏了这些注解会出现\\"默认配置抢先生效\\"。","topic":"Boot"},{"q":"Spring MVC 中 HandlerInterceptor 与 Servlet Filter 的区别，错误的是？","options":["Interceptor 由 Spring 管理，能注入容器 Bean","Filter 是 Servlet 规范，DispatcherServlet 之前执行","Interceptor 能拿到执行方法信息（HandlerMethod）","Filter 比 Interceptor 执行更晚"],"answer":3,"explain":"顺序：Filter 前置 → DispatcherServlet → Interceptor.preHandle → Controller。Filter 粗粒度（编码/CORS），Interceptor 细粒度（鉴权/日志，能感知目标方法）。","topic":"MVC"},{"q":"@RestController 与 @Controller 的区别是？","options":["完全一样","@RestController = @Controller + @ResponseBody：所有方法返回值直接经 HttpMessageConverter 序列化为 JSON，不再走视图解析","前者不能注入","后者已废弃"],"answer":1,"explain":"返回 String 时注意：有 @ResponseBody 走 StringHttpMessageConverter；前端乱码高发点就是它的默认 charset——理解转换器链才能根治。","topic":"MVC"},{"q":"Spring 事务实现方式是？","options":["JVM 锁","AOP：TransactionInterceptor 拦截方法 → 获取/绑定连接（ThreadLocal）→ 异常按规则回滚，底层最终落到 JDBC/JTA","反射","字节码修改数据库"],"answer":1,"explain":"PlatformTransactionManager 抽象（DataSource/JTA/Hibernate 实现）。同事务内多个 DAO 共享同一连接 = TransactionSynchronizationManager 的 ThreadLocal 绑定——这也是事务内开新线程拿不到事务的原因。","topic":"事务"},{"q":" propagation = SUPPORTED 的语义是？","options":["必须新事务","有事务就加入，没有就非事务执行（适合查询方法）","强制挂起","只读事务"],"answer":1,"explain":"七种传播行为记忆：REQUIRED（默认，有则加入无则新建）、SUPPORTS（可有可无）、MANDATORY（必须有否则异常）、REQUIRES_NEW（挂起新开）、NOT_SUPPORTED（挂起非事务）、NEVER（有则异常）、NESTED（保存点）。","topic":"事务"},{"q":"Spring Boot 的 starter 本质是？","options":["jar 包集合而已","依赖聚合 + 自动配置：引入 starter = 拉齐依赖版本 + 通过 imports 文件注册条件化配置类，开箱即用","Maven 插件","容器镜像"],"answer":1,"explain":"官方命名 spring-boot-starter-*，三方 naming *-spring-boot-starter。自定义 starter 三步：写自动配置类 + 条件注解 + 注册到 AutoConfiguration.imports。","topic":"Boot"},{"q":"application.yml 中配置优先级最高的是？","options":["jar 内 application.yml","命令行参数（--server.port=8081）> 外部配置文件 > jar 内配置文件 > 默认值","默认值","bootstrap.yml"],"answer":1,"explain":"Spring Boot 外化配置有 17 级顺序。运维改配置的常规手段就是命令行参数或外部文件覆盖——理解优先级才能解释\\"为什么我改的配置不生效\\"。","topic":"Boot"},{"q":"SpEL 表达式在 Spring Security @PreAuthorize(\\"hasRole(''ADMIN'')\\") 中的作用是？","options":["加密","运行时对方法参数/返回值/安全上下文求值，实现声明式授权","路由","序列化"],"answer":1,"explain":"SpEL 全家桶：@Value 注入、@Cacheable key、@PreAuthorize 授权、@EventListener condition。\\"注解 + SpEL\\" = Spring 声明式编程的通用范式。","topic":"核心"},{"q":"Bean 的 @PostConstruct、afterPropertiesSet、init-method 执行顺序是？","options":["init-method 最先","@PostConstruct（BeanPostProcessor 阶段）→ afterPropertiesSet（InitializingBean）→ init-method（XML/注解指定）","同时执行","随机"],"answer":1,"explain":"三种初始化入口按\\"注解 → 接口 → 配置\\"顺序。销毁对称：@PreDestroy → destroy() → destroy-method。知道顺序才能在多个初始化逻辑间排依赖。","topic":"IoC"},{"q":"Spring 解决 Request 参数绑定时，@RequestParam 与 @PathVariable 的区别是？","options":["一样","@PathVariable 绑定 URL 路径占位符（/users/{id}）；@RequestParam 绑定 query/form 参数（?id=1）","前者 POST 专用","后者已废弃"],"answer":1,"explain":"RESTful 风格：资源标识放路径（PathVariable），过滤条件放查询串（RequestParam），请求体放对象（RequestBody @RequestBody 需 JSON）。混用错位是 400 常见原因。","topic":"MVC"},{"q":"spring.factories / AutoConfiguration.imports 文件的作用是？","options":["存日志","声明自动配置类清单：Spring Boot 启动时读取并尝试装配，配合条件注解过滤","定义路由","版本号"],"answer":1,"explain":"2.7 前在 META-INF/spring.factories 的 EnableAutoConfiguration 键；2.7+ 新格式 META-INF/spring/...AutoConfiguration.imports（一行一个类全名）。自定义 starter 必备。","topic":"Boot"},{"q":"Spring 事件 @TransactionalEventListener(phase = AFTER_COMMIT) 解决的问题是？","options":["加速事件","确保监听逻辑在事务提交后才执行——避免\\"事务回滚了但通知/缓存已发出\\"的脏动作","异步化","重试"],"answer":1,"explain":"默认 @EventListener 同事务执行：事务回滚，事件副作用（发短信/清缓存）却已发生。AFTER_COMMIT 把监听挂到提交后——分布式\\"事务后动作\\"的标准解。","topic":"事件"},{"q":"Spring AOP 默认使用 JDK 动态代理的条件是？","options":["永远默认","目标类实现了接口（且未强制 proxyTargetClass）——否则 CGLib 子类代理","只有 Boot1","Web 项目"],"answer":1,"explain":"Spring Boot 2.x 默认 proxyTargetClass=true 全走 CGLib（规避\\"无接口注入失败\\"的困惑）。知道默认值怎么来的比背默认值重要。","topic":"AOP"},{"q":"CGLib 无法代理的方法是？","options":["public 方法","final/private/static 方法——子类无法覆写，代理逻辑织入不了","protected","所有方法"],"answer":1,"explain":"CGLib 原理是生成子类覆写方法：final 阻止覆写、private 不可见、static 属于类。这些方法上的 @Transactional 全部失效——排查\\"注解不生效\\"先查方法修饰符。","topic":"AOP"},{"q":"@Async 生效的前提与坑是？","options":["无需条件","需 @EnableAsync + 方法 public + 通过代理调用（自调用失效）+ 默认线程池是 SimpleAsyncTaskExecutor（不复用线程，生产须自定义池）","只能用于 Controller","自动事务"],"answer":1,"explain":"三坑：自调用不生效、默认池不复用线程（每次新建，高并发爆炸）、异常不回传。生产配置：自定义 ThreadPoolTaskExecutor + 拒绝策略 + 异常处理器。","topic":"异步"},{"q":"Spring Boot Actuator 的 /health 与 /metrics 的用途区别是？","options":["完全一样","health 报告应用存活/组件状态（给 liveness/readiness 用）；metrics 暴露指标数据（JVM/HTTP/自定义 Counter，接 Prometheus）","health 只给数据库","metrics 已废弃"],"answer":1,"explain":"可观测三件套接入点：Actuator metrics → Micrometer → Prometheus 抓取 → Grafana 看板。健康探针直接决定 K8s 是否重启/摘流量。","topic":"运维"},{"q":"MyBatis 的 Mapper 接口没有实现类，为什么能 @Autowired 注入？","options":["反射 magic","MapperScan 为每个接口注册 MapperFactoryBean，getObject() 返回 JDK 动态代理对象，代理按\\"接口全名.方法名\\"定位 SQL 执行","MyBatis 改了字节码","Spring 容错"],"answer":1,"explain":"又是 FactoryBean + 动态代理组合：接口 → 代理 Bean。同理还有 Feign Client、Dubbo Reference——\\"远程/无实现的接口注入\\"全是这一招。","topic":"MyBatis"},{"q":"Spring Security 的认证流程中，AuthenticationManager 的职责是？","options":["存密码","协调多个 AuthenticationProvider 逐一尝试认证，返回认证后的 Authentication（含权限）","生成 token","渲染页面"],"answer":1,"explain":"ProviderManager 遍历 providers（DAO/JWT/OAuth 各实现）直到一个 supports 且认证成功。安全过滤器链（15+ Filter）+ 认证管理器 + 权限评估（SpEL）构成三层架构。","topic":"Security"}]},{"id":"exam-distributed","icon":"🌐","name":"第九套 · 分布式与架构专项卷","level":"进阶","minutes":35,"passScore":60,"desc":"CAP/Raft/分布式锁/事务/限流熔断/微服务治理——冲高级岗的架构思维专项。","questions":[{"q":"CAP 中\\"网络分区发生时选 AP\\"的典型系统行为是？","options":["拒绝写入","继续提供服务但可能返回旧数据，分区恢复后数据收敛（最终一致）","立即停机","只读"],"answer":1,"explain":"Eureka/Redis 主从是 AP 代表：可用性优先。工程上 AP 不是\\"不管一致\\"，而是用补偿/对账/版本收敛达到最终一致——BASE 理论就是 AP 的落地方法论。","topic":"理论"},{"q":"Raft 中 Candidate 收到更大 term 的消息时应该？","options":["继续竞选","立刻退回 Follower 并更新 term——任期是逻辑时钟，大 term 一票否决","拒绝消息","重启"],"answer":1,"explain":"Raft 用 term 保证时间线统一：任何 RPC 里见到更大 term 立即转 follower；见到更小 term 拒绝并返回自己的 term。选举安全：只有日志最新的 candidate 能当选。","topic":"共识"},{"q":"2PC（两阶段提交）的主要缺陷是？","options":["太慢无法实现","协调者单点故障 + 阻塞（参与者锁定资源等指令）+ 网络分区下数据不一致风险，所以衍生出 3PC/TCC/Saga","不支持 MySQL","只能读"],"answer":1,"explain":"2PC 是\\"强一致 but 可用性差\\"的典型。工程取舍：本地消息表（可靠+最终一致）、TCC（业务层 Try-Confirm-Cancel）、Saga（长流程+补偿）按场景选。","topic":"分布式事务"},{"q":"TCC 模式中 Cancel 阶段的语义与要求是？","options":["重试 Try","释放 Try 预留的资源（如冻结金额），必须幂等且允许空回滚（Try 未到达也返回成功）","提交业务","回滚数据库"],"answer":1,"explain":"TCC 业务侵入大但性能好（不锁全局）。空回滚：Try 超时未达而 Cancel 先到——不加防空则报\\"回滚不存在的事务\\"。悬挂：Cancel 后迟到的 Try 要拒绝。三大坑：空回滚/悬挂/幂等。","topic":"分布式事务"},{"q":"本地消息表方案的核心思想是？","options":["消息存 Redis","业务与消息记录同库同事务写入，定时任务/MQ 把\\"待发送\\"消息投递出去，成功后标记——用本地事务换最终一致","不发消息","双写数据库"],"answer":1,"explain":"把\\"分布式事务\\"降级为\\"本地事务 + 重试投递\\"。表结构：业务 id、消息体、状态、重试次数。优点可靠简单；缺点有延迟 + 业务库压力。RocketMQ 事务消息是它的无表版。","topic":"分布式事务"},{"q":"分布式 ID 用雪花算法，时钟回拨 2 秒的正确处理是？","options":["无影响","拒绝发号并等待时间追平（小回拨），或切换备用 workerId/报警（大回拨）——绝不能继续用回拨前时间戳生成","重启服务","改用 UUID"],"answer":1,"explain":"时间戳回退继续发号 = 重复 ID。美团 Leaf-snowflake 用 ZK 存 workerId + 启动时校验时钟；小回拨等待策略。UUID 无序不适合 InnoDB 主键。","topic":"分布式 ID"},{"q":"一致性哈希解决的主要问题是？","options":["数据加密","普通 hash 取模在节点增减时全局重映射——一致性哈希把节点与数据映射到环上，数据顺时针归属，增删节点只影响相邻区间","负载均衡算法","路由协议"],"answer":1,"explain":"经典场景：缓存节点宕机只迁移 1/N 数据而非全量。虚拟节点解决数据倾斜（节点少时环分布不均）。Redis Cluster 用槽分片也是同类思路。","topic":"分片"},{"q":"Sentinel 的熔断降级与限流的区别是？","options":["完全一样","限流控制\\"进多少\\"（主动保护）；熔断是\\"发现依赖故障后一段时间内快速失败\\"（被动保护自己不被拖死），半开状态探测恢复","熔断更快所以取代限流","限流已废弃"],"answer":1,"explain":"三态熔断器：Closed（正常）→ 失败率/慢调用超阈值 → Open（快速失败）→ 等待窗口 → Half-Open（放少量探测）→ 成功则 Closed。限流与熔断配合使用构成弹性防护。","topic":"流量治理"},{"q":"网关层限流用 Redis + Lua 而非纯 Java 内存限流的原因是？","options":["Lua 更快","多实例部署下单机限流阈值无法共享——分布式限流需要集中计数，Lua 保证\\"判断+扣减\\"原子","Java 不支持","省内存"],"answer":1,"explain":"集群限流 = 全局计数器 + 原子操作。Lua 脚本在 Redis 单线程执行天然原子，实现令牌桶/滑动窗口。代价：每次请求多一次 Redis 往返——可用本地预扣+批量同步折中。","topic":"流量治理"},{"q":"服务注册中心的\\"推送 + 拉取\\"双机制，Nacos 的实现是？","options":["只有轮询","客户端 UDP/gRPC 推送（准实时）+ 定时拉取兜底（防推送丢失），实例带心跳续约，超时剔除","只有推送","人工刷新"],"answer":1,"explain":"推送解决实时性、拉取解决可靠性——双保险是分布式系统的通用模式。Eureka 是纯客户端拉取（30s 间隔，感知慢但简单）；Consul 用 gossip 协议。","topic":"注册中心"},{"q":"微服务间传递用户上下文的正确方式是？","options":["全局变量","请求头透传（userId/token）+ 接收端放入 ThreadLocal/Reactor Context，跨线程用装饰器/TransmittableThreadLocal","每次重新查库","写死在配置"],"answer":1,"explain":"链路上下文（用户/traceId/灰度标记）都走 header 透传。坑：线程池切换丢上下文（TTL 解决）、异步 Servlet 丢失（context 传播）。这是链路追踪与灰度发布的基础设施。","topic":"微服务"},{"q":"分布式链路追踪中 Span 的核心字段与作用是？","options":["只有时间","spanId + parentSpanId + 起止时间 + 标签：构造调用树，定位\\"慢在哪个节点哪一步\\"","只有 IP","日志级别"],"answer":1,"explain":"Trace 全局唯一，Span 树状展开。采样策略（头部采样/尾部采样）平衡成本与覆盖率。SkyWalking 字节码增强零侵入、OpenTelemetry 是标准化方向。","topic":"可观测"},{"q":"读写分离后\\"写完立即读\\"读不到新数据，业务层正确解法是？","options":["全部读主库","关键读强制走主（hint/动态数据源）或\\"写后 N 秒内该用户读主\\"的会话级路由，其余继续读写分离","加锁","放弃从库"],"answer":1,"explain":"一刀切全走主 = 读写分离白做。精细化路由：按\\"用户最近写时间\\"判断——写后短窗口读主，兼顾一致性与负载。这也是各大厂中间件（如 ShardingSphere）内置能力。","topic":"数据库扩展"},{"q":"分库分表后，跨分片的分页/聚合查询的正确姿势是？","options":["没法做","禁止跨片深分页：查询维度设计进分片键；聚合走异构索引（ES/宽表）或中间件聚合（性能受限）","随机取一个分片","全部分片拉回内存排序"],"answer":1,"explain":"分片后 limitations：跨片 join/事务/分页都难。设计期就要把高频查询维度纳入分片键；管理后台类低频查询走 ES/ClickHouse 异构。选好分片键 = 分库分表 80% 的成败。","topic":"数据库扩展"},{"q":"Redis 分布式锁 RedLock 方案的争议核心是？","options":["性能差","Martin Kleppmann 指出：跨节点锁在 GC 停顿/时钟跳变下仍可能同时被两客户端持有—— fencing token（递增令牌+下游校验）才是完备方案","实现太难","不兼容集群"],"answer":1,"explain":"分布式锁完备性需要\\"下游拒绝过期令牌的操作\\"（fencing token）。实践建议：Redis 锁（Redisson）满足绝大多数效率型场景；正确性关键路径用 DB 乐观锁/版本号兜底。","topic":"分布式锁"},{"q":"API 网关的核心职责不包括？","options":["统一鉴权与限流","业务逻辑实现——网关应该薄，业务下沉到服务，网关只做横切关注点（路由/认证/限流/灰度/日志）","路由转发","协议转换"],"answer":1,"explain":"网关写业务代码 = 全局单点变巨型单体。正确姿势：网关插件化横切能力（鉴权/限流/灰度分流），业务路由到服务。Spring Cloud Gateway/Gloo/Kong 都是这思路。","topic":"微服务"},{"q":"幂等键（Idempotency-Key）放在 HTTP 请求中的标准用法是？","options":["随便放","客户端为每个业务操作生成唯一 key 放请求头，服务端 setnx/唯一索引去重——重试携带同 key 则返回首次结果","放 cookie","放 URL 参数即可"],"answer":1,"explain":"支付/下单等\\"不能重做\\"的接口标配（Stripe 等都这么设计）。服务端处理：key + 响应快照保存（处理中/已完成），重试时直接返回快照——比\\"拒绝重复\\"体验更好。","topic":"接口设计"},{"q":"单体到微服务迁移的合理路径是？","options":["一步到位重写","先模块化单体（清晰边界）→ 按\\"绞杀者模式\\"逐域抽出服务 → 先拆与单体耦合最小的域，边迁移边观察","直接微服务","先买云产品"],"answer":1,"explain":"Martin Fowler 绞杀者模式：新功能在新服务，旧功能逐步迁移，网关按路由分流直至旧单体消亡。\\"大爆炸重写\\"是失败率最高的方式。","topic":"架构演进"},{"q":"多租户 SaaS 的数据隔离方案，隔离度从高到低是？","options":["共享表 > 独立库","独立数据库 > 独立 Schema > 共享表+tenant_id 字段——成本依次降低，按客户付费能力分级","全部共享一张表","用文件"],"answer":1,"explain":"大客户独立库（强隔离+备份恢复粒度）、中小客户共享表 tenant_id（成本最优，靠 Mybatis 拦截器自动加 where）。混合分级是商业 SaaS 的标准打法。","topic":"架构设计"},{"q":"系统设计题\\"设计一个分布式任务调度平台\\"，核心组件不必包括？","options":["任务注册与元数据存储","替代业务代码执行——调度平台只负责\\"何时在哪触发\\"，业务逻辑留在执行器（回调模式）","调度器（时间轮/优先队列）","执行器集群与故障转移"],"answer":1,"explain":"XXL-Job/Elastic-Job 模式：调度中心（分片+触发）与执行器（业务）分离。考点：cron 管理、分片广播、失败重试、幂等防重复触发、日志回捞。","topic":"场景设计"}]}]');
