INSERT INTO json_doc (name, data) VALUES ('alertGroups', '[{"key":"syntax","name":"语法陷阱","color":"#f59e0b"},{"key":"oop","name":"面向对象","color":"#8b5cf6"},{"key":"collections","name":"集合框架","color":"#10b981"},{"key":"concurrency","name":"并发编程","color":"#ef4444"},{"key":"jvm","name":"JVM 内存","color":"#6366f1"},{"key":"spring","name":"Spring","color":"#059669"},{"key":"mysql","name":"MySQL","color":"#2563eb"},{"key":"redis","name":"Redis","color":"#dc2626"},{"key":"network","name":"网络","color":"#0891b2"},{"key":"linux","name":"Linux/工程","color":"#7c3aed"}]');
