INSERT INTO json_doc (name, data) VALUES ('mistakeAlerts', '[{"id":"al-1","icon":"➗","group":"syntax","title":"整数除法截断","wrong":"以为 10 / 3 = 3.33","right":"两个 int 相除结果还是 int，直接丢掉小数 = 3。想要 3.33 至少一方是 double：10 / 3.0","scene":"计算平均值时结果永远是整数"},{"id":"al-2","icon":"🔢","group":"syntax","title":"浮点数比较","wrong":"用 == 比较 0.1 + 0.2 == 0.3","right":"浮点有精度误差，结果 false。用 Math.abs(a - b) < 1e-9 或 BigDecimal（金额必用）","scene":"金额计算出 0.30000000000000004"},{"id":"al-3","icon":"🪤","group":"syntax","title":"自动装箱缓存","wrong":"以为 Integer 永远可以用 == 比较","right":"Integer 缓存 -128~127：127 == 127 为 true，128 == 128 为 false！包装类型比较一律用 equals","scene":"打包后接口数据比对莫名失败"},{"id":"al-4","icon":"🧵","group":"syntax","title":"String 不可变","wrong":"以为 s.replace 之后 s 变了","right":"String 不可变，replace 返回新串：s = s.replace(...) 才生效；频繁拼接用 StringBuilder","scene":"循环里拼字符串性能骤降"},{"id":"al-5","icon":"⚡","group":"syntax","title":"char 运算","wrong":"以为 ''a'' + 1 结果是 \\"b\\"","right":"char 参与运算提升为 int：''a'' + 1 = 98。要得到 ''b'' 需强转 (char)(''a'' + 1)","scene":"字符题目算出数字"},{"id":"al-6","icon":"📦","group":"syntax","title":"三元表达式拆箱 NPE","wrong":"以为三元表达式不会空指针","right":"两臂类型不一致会自动拆箱：condition ? intValue : null 装箱时抛 NPE","scene":"线上偶发 NullPointerException"},{"id":"al-7","icon":"🧬","group":"oop","title":"重载 vs 重写","wrong":"以为参数相同返回值不同是重载","right":"仅返回值不同不能重载（编译错）。重载看参数列表，重写看运行时类型","scene":"面试基础题翻车"},{"id":"al-8","icon":"⚙️","group":"oop","title":"静态方法无法重写","wrong":"以为子类\\"重写\\"了父类静态方法","right":"静态方法属于类不属于实例，子类同名静态方法是\\"隐藏\\"不是重写，调用看编译期类型","scene":"多态调用静态方法结果不符预期"},{"id":"al-9","icon":"🏗️","group":"oop","title":"构造器里的多态陷阱","wrong":"在父类构造器里调用可被重写的方法","right":"此时子类字段还没初始化，重写方法读到的是默认值 null/0——构造器只调 private/final/static 方法","scene":"对象刚 new 完字段\\"莫名\\"为空"},{"id":"al-10","icon":"🧊","group":"oop","title":"equals 与 == 混用","wrong":"重写了 equals 忘了重写 hashCode","right":"两个\\"相等\\"对象进 HashMap 后找不到彼此——equals 相等必须 hashCode 相等（约定）","scene":"对象放进 Set 后 contains 返回 false"},{"id":"al-11","icon":"🔁","group":"oop","title":"接口 default 冲突","wrong":"以为实现两个含同名 default 方法的接口没问题","right":"编译器强制要求重写冲突方法，可用 InterfaceA.super.method() 显式指定","scene":"实现多接口编译报错"},{"id":"al-12","icon":"🚫","group":"collections","title":"foreach 中删元素","wrong":"在 for-each 里直接 list.remove(obj)","right":"触发 ConcurrentModificationException！用 Iterator.remove() 或 removeIf()","scene":"遍历删除时抛异常"},{"id":"al-13","icon":"🔎","group":"collections","title":"Arrays.asList 三坑","wrong":"以为 Arrays.asList 返回的 List 能随便增删改","right":"它是定长视图：add/remove 抛 UnsupportedOperationException；改元素会穿透到原数组；传基本类型数组整个变成一个元素","scene":"运行时 UnsupportedOperationException"},{"id":"al-14","icon":"🫙","group":"collections","title":"HashSet 去重失效","wrong":"以为 HashSet 天生能对自定义对象去重","right":"不重写 equals/hashCode 就是按地址去重——两个内容相同的对象都能放进去","scene":"去重后还有重复数据"},{"id":"al-15","icon":"📏","group":"collections","title":"subList 视图联动","wrong":"以为 subList 返回独立的新列表","right":"它是原列表的视图：改 subList 会同步原列表；原列表结构性修改后再用 subList 抛异常","scene":"截取的数据\\"莫名\\"变了"},{"id":"al-16","icon":"🗺️","group":"collections","title":"HashMap 遍历顺序","wrong":"以为 HashMap 遍历按插入顺序","right":"无序！要插入序用 LinkedHashMap，要排序用 TreeMap。每次扩容顺序都可能变","scene":"依赖顺序输出时快时慢"},{"id":"al-17","icon":"⚠️","group":"collections","title":"ConcurrentModification 本质","wrong":"以为只有多线程才抛 CME","right":"单线程也可能：遍历时用集合自己的 remove（modCount 变了）。规则：遍历用迭代器删，或用 removeIf","scene":"单机也出现 CME"},{"id":"al-18","icon":"💜","group":"concurrency","title":"volatile 原子性错觉","wrong":"以为 volatile int count; count++ 是线程安全的","right":"volatile 只保证可见性和有序性，不保证原子性。count++ 是读-改-写三步，要用 AtomicInteger 或锁","scene":"多线程计数结果偏小"},{"id":"al-19","icon":"🏊","group":"concurrency","title":"Executors 创建线程池","wrong":"Executors.newFixedThreadPool 随手就用","right":"队列无界 → 任务堆积 OOM；newCachedThreadPool 线程数无界 → 资源耗尽。阿里规范：手动 new ThreadPoolExecutor","scene":"大促时服务内存暴涨"},{"id":"al-20","icon":"🧵","group":"concurrency","title":"ThreadLocal 不清理","wrong":"ThreadLocal 用完不管","right":"线程池线程复用：下个请求读到上个请求的数据（串号！）+ value 泄漏。必须 finally { remove() }","scene":"用户 A 看到用户 B 的信息"},{"id":"al-21","icon":"🔒","group":"concurrency","title":"锁对象选错","wrong":"给 String/Integer/包装缓存对象加 synchronized","right":"字符串常量池共享、Integer 缓存 -128~127 共享，不同业务可能锁到同一个对象——用专用锁对象","scene":"毫不相关的代码互相阻塞"},{"id":"al-22","icon":"📖","group":"concurrency","title":"双重检查锁单例","wrong":"DCL 单例不写 volatile","right":"new 不是原子操作（分配→初始化→赋引用），重排后别的线程拿到半初始化对象。必须 volatile","scene":"单例偶发字段为空"},{"id":"al-23","icon":"🛌","group":"concurrency","title":"wait 用 if 不用 while","wrong":"if (条件不满足) wait(); 之后直接干活","right":"虚假唤醒会跳过条件判断！wait 必须包在 while (条件不满足) 里，唤醒后重新检查","scene":"生产者消费者偶发逻辑错乱"},{"id":"al-24","icon":"🏔️","group":"jvm","title":"StackOverflow vs OOM","wrong":"把 StackOverflowError 和 OutOfMemoryError 混为一谈","right":"SOE：栈深度超限（递归没出口/死递归）；OOM：堆内存耗尽（对象撑爆）。排查方向完全不同","scene":"递归没写出口"},{"id":"al-25","icon":"🧊","group":"jvm","title":"静态集合当缓存","wrong":"static Map 当全局缓存只用不删","right":"静态集合是 GC Roots，永远可达 → 经典内存泄漏。要用弱引用或带淘汰策略的缓存（Caffeine）","scene":"服务跑了几天内存只涨不跌"},{"id":"al-26","icon":"🪞","group":"jvm","title":"字符串常量池误判","wrong":"以为 new String(\\"a\\") 在堆里就不占常量池","right":"字面量 \\"a\\" 已进常量池，new 又在堆建一份——同一字符串两个对象。intern() 才指向常量池","scene":"== 比较 String 结果不稳定"},{"id":"al-27","icon":"♻️","group":"jvm","title":"finalize 的错觉","wrong":"以为 finalize() 能可靠释放资源","right":"执行时机不确定甚至不执行（JDK9 已废弃）。资源释放用 try-with-resources / finally","scene":"资源没释放导致的连接泄漏"},{"id":"al-28","icon":"🌀","group":"spring","title":"事务自调用失效","wrong":"同类中 A 方法调 B 方法（B 上有 @Transactional）","right":"事务靠代理对象实现，this.b() 绕过了代理 → 事务失效！注入自身代理或拆到另一个类","scene":"加了注解事务却不回滚"},{"id":"al-29","icon":"🤐","group":"spring","title":"异常被吞不回滚","wrong":"以为只要抛异常事务就回滚","right":"默认只回滚 RuntimeException/Error；被 try-catch 吞掉不回滚；受检异常要 rollbackFor = Exception.class","scene":"catch 之后数据还是写进去了"},{"id":"al-30","icon":"🔓","group":"spring","title":"private/final 方法事务失效","wrong":"以为 @Transactional 写在哪都行","right":"代理不能重写 private/final/static 方法 → 事务失效。事务方法必须 public 且能被代理","scene":"事务注解静默不生效"},{"id":"al-31","icon":"💉","group":"spring","title":"循环依赖想当然","wrong":"以为构造器注入能解决循环依赖","right":"Spring 三级缓存只救字段/Setter 注入的单例；构造器循环依赖直接启动失败——设计上应消除循环","scene":"改构造器注入后启动报 BeanCurrentlyInCreationException"},{"id":"al-32","icon":"🎭","group":"spring","title":"@Async 自调用失效","wrong":"同类里调用 @Async 方法以为会异步","right":"和事务同理，this 调用不走代理。异步方法放到别的 Bean 或注入代理对象","scene":"加了 @Async 还是同步执行"},{"id":"al-33","icon":"🌳","group":"mysql","title":"隐式类型转换","wrong":"varchar 索引列用数字查：WHERE phone = 13800000000","right":"MySQL 会把列转成数字比 → 索引失效全表扫。字符串列查询必须带引号","scene":"慢查询日志里全表扫描"},{"id":"al-34","icon":"🔍","group":"mysql","title":"LIKE 前导 %","wrong":"LIKE ''%关键字'' 以为能走索引","right":"前导 % 无法使用 B+ 树有序性 → 全表扫。后缀 ''关键字%'' 才可以；搜索场景用 ES 或覆盖索引","scene":"搜索接口越用越慢"},{"id":"al-35","icon":"⏱️","group":"mysql","title":"大事务长事务","wrong":"一个事务里又发 RPC 又批量写几千行","right":"长事务持有锁+undo 日志膨胀+主从延迟。拆小事务，事务内不做 RPC/慢操作","scene":"偶发锁等待超时"},{"id":"al-36","icon":"🔑","group":"mysql","title":"NULL 值三连坑","wrong":"用 = NULL 判断或 NOT IN 里混入 NULL","right":"NULL 与任何值比较都是 UNKNOWN：判空必须 IS NULL；NOT IN 遇到 NULL 整个返回空集","scene":"NOT IN 查询结果为空"},{"id":"al-37","icon":"📄","group":"mysql","title":"count(*) vs count(列)","wrong":"以为 count(列) 比 count(*) 快","right":"count(*) 是官方优化过的行数统计；count(列) 要逐行取值且排除 NULL 反而更慢","scene":"面试必考+统计接口慢"},{"id":"al-38","icon":"🎚️","group":"mysql","title":"深分页性能陷阱","wrong":"LIMIT 1000000, 10 直接上生产","right":"偏移量全扫描后丢弃。游标分页 WHERE id > last_id LIMIT 10，或延迟关联先查 id","scene":"翻到后面页接口超时"},{"id":"al-39","icon":"🗑️","group":"redis","title":"大 key 悄悄上线","wrong":"把几 MB 的对象直接塞 Redis","right":"大 key 删除阻塞主线程（redis 6 前）、迁移/过期都卡。拆分 + 用 UNLINK 异步删 + 定期扫描","scene":"Redis 偶发卡顿"},{"id":"al-40","icon":"⌨️","group":"redis","title":"KEYS 命令上生产","wrong":"KEYS * 找 key","right":"O(N) 阻塞主线程，百万 key 直接卡死。生产用 SCAN 游标增量遍历","scene":"运维查 key 时服务抖动"},{"id":"al-41","icon":"💥","group":"redis","title":"缓存与 DB 双写不一致","wrong":"先更新库再删缓存就万无一失","right":"并发下仍有小窗口不一致（读旧值回填）。要求高一致：延迟双删/订阅 binlog 异步删/分布式锁串行化","scene":"改了数据页面还是旧值"},{"id":"al-42","icon":"🔓","group":"redis","title":"分布式锁误删","wrong":"A 的锁超时释放后，A 回来把 B 的锁删了","right":"锁值存唯一标识（UUID），删除前 Lua 校验是自己的才删——否则锁互斥形同虚设","scene":"锁失效导致的重复扣款"},{"id":"al-43","icon":"🌊","group":"redis","title":"过期时间一刀切","wrong":"批量 key 统一 30 分钟过期","right":"同一时刻集体失效 → 瞬时 DB 压力雪崩。过期时间加随机抖动（如 25~35 分钟）","scene":"定时任务后 DB 瞬间被打爆"},{"id":"al-44","icon":"🔌","group":"network","title":"CLOSE_WAIT 堆积","wrong":"服务端大量 CLOSE_WAIT 以为是网络问题","right":"是应用收到 FIN 后没调 close()——代码泄漏连接！查流未关闭/连接池耗尽","scene":"线上连接数只增不减"},{"id":"al-45","icon":"🧱","group":"network","title":"TCP 粘包想当然","wrong":"以为 send 三次对面就收三条消息","right":"TCP 是字节流没有消息边界。应用层定长/分隔符/长度头协议自行拆包","scene":"Netty 解析数据错乱"},{"id":"al-46","icon":"🌐","group":"network","title":"CORS 只怪后端","wrong":"跨域报错先怀疑前端写错","right":"CORS 是浏览器安全策略，响应头缺 Access-Control-Allow-Origin。后端配置或网关处理，JSONP/CORS 预检要看清","scene":"控制台一堆 CORS 报错"},{"id":"al-47","icon":"💀","group":"linux","title":"rm -rf 变量空值","wrong":"rm -rf $DIR/script，DIR 为空时变成删根","right":"变量必须判空+引号：rm -rf \\"$DIR/script\\"。生产删除前 echo 出完整路径确认","scene":"经典删库事故的源头"},{"id":"al-48","icon":"🌪️","group":"linux","title":"日志文件删了空间不释放","wrong":"以为 rm 大日志文件磁盘立刻释放","right":"进程还握着文件句柄，空间不释放！用 > file 截断，或重启进程；lsof | grep deleted 查看","scene":"rm 之后 df 看空间没变"}]');
INSERT INTO json_doc (name, data) VALUES ('pitfallDays', '[{"day":1,"stage":"Java 入门","title":"类型与运算陷阱","points":["<code>10 / 3 = 3</code>：两个整数相除结果还是整数，直接截断小数，不是四舍五入。想要 3.33 得转成 double：<code>10 / 3.0</code>。","<code>10 % -3 = 1</code>（不是 -1）：Java 取余符号跟<b>被除数</b>走。","整型默认 int：写 <code>long a = 10000000000;</code> 编译报错，因为右边的字面量先按 int 处理已溢出，要写 <code>10000000000L</code>。","char 能参与运算：<code>''a'' + 1 = 98</code>（ASCII 码 97+1），想得 \\"b\\" 要强转 (char)。"],"questions":[{"q":"System.out.println(7 / 2 + 7 % 2); 输出什么？","options":["4","4.5","5","3.5"],"answer":0,"explain":"7/2 整数除法=3，7%2=1，3+1=4。两步都是整数运算，不存在小数。"},{"q":"byte b = 127; b = b + 1; 会怎样？","options":["b = -128","b = 128","编译报错","运行时异常"],"answer":2,"explain":"b+1 中 b 自动提升为 int，结果 128 是 int，不能自动赋回 byte，编译报错。即使 b += 1 可以（隐式强转），结果也会溢出成 -128。"}]},{"day":2,"stage":"Java 入门","title":"String 与相等性","points":["<code>\\"abc\\" == \\"abc\\"</code> 为 true（常量池同一对象），但 <code>new String(\\"abc\\") == \\"abc\\"</code> 为 false——new 一定创建堆里的新对象。","比较字符串内容永远用 <code>equals()</code>，且把常量放前面防 NPE：<code>\\"admin\\".equals(input)</code>。","String 拼接循环场景性能灾难：每次 + 都 new 新对象，循环 1 万次 = 1 万个对象，必须用 StringBuilder。","<code>s.length() == 0</code> 与 <code>s == null</code> 是两回事：null 连 length() 都调不了直接 NPE。"],"questions":[{"q":"String s = new String(\\"ab\\") + new String(\\"cd\\"); 创建了几个对象？（常量池初始无 \\"ab\\" \\"cd\\"）","options":["2 个","3 个","5 个","6 个"],"answer":2,"explain":"常量池 \\"ab\\"、堆 new \\"ab\\"、常量池 \\"cd\\"、堆 new \\"cd\\"、StringBuilder、最终 toString 的 \\"abcd\\"——共 6 个（若算上 StringBuilder）。经典刁难题，重点是理解 new 必建新对象。"},{"q":"下列哪项是正确的空安全比较写法？","options":["s.equals(\\"x\\")","\\"x\\".equals(s)","s == \\"x\\"","s.compare(\\"x\\")"],"answer":1,"explain":"把确定的常量放前面，s 为 null 时返回 false 而不是抛 NPE。"}]},{"day":3,"stage":"面向对象","title":"构造器与初始化顺序","points":["类一写上<b>有参构造器</b>，默认无参构造器立刻消失，<code>new User()</code> 直接编译报错——手写有参必顺手补无参。","初始化顺序（面试必背）：父类静态 → 子类静态 → 父类实例变量/代码块 → 父类构造器 → 子类实例变量/代码块 → 子类构造器。","<code>this(...)</code> 构造器调用必须放第一行，且一个构造器只能调一个 this 或 super。","构造器里调用可被重写的方法是危险行为：子类重写方法会在\\"子类字段还没赋值\\"时被父类构造器调到，读到零值。"],"questions":[{"q":"new 子类对象时，最先执行的是？","options":["子类构造器","父类构造器","父类静态代码块","子类静态代码块"],"answer":2,"explain":"静态先于实例、父类先于子类。完整顺序：父静态→子静态→父实例→父构造→子实例→子构造。"},{"q":"class A { A() { print(); } void print(){} } class B extends A { int x = 5; void print(){ System.out.println(x); } }，new B() 输出？","options":["5","0","null","编译报错"],"answer":1,"explain":"父类构造器调用的是被重写的 print()（多态），此时子类 x 尚未赋值（还是默认值 0），输出 0。这就是\\"构造器里不要调可重写方法\\"的原因。"}]},{"day":4,"stage":"集合","title":"集合使用陷阱","points":["Arrays.asList(...) 返回的列表<b>不支持 add/remove</b>（长度固定），硬调会 UnsupportedOperationException。","foreach / 迭代中直接 list.remove() 抛 ConcurrentModificationException，要用 iterator.remove() 或 removeIf。","<code>int[] arr</code> 直接 Arrays.asList(arr) 得到的是\\"一个元素的列表\\"（数组本身成为元素），基本类型数组要用 Stream.boxed()。","HashSet 存自定义对象不去重：忘了重写 equals + hashCode，两个\\"相同\\"对象 hashCode 不同被分到不同桶。"],"questions":[{"q":"在 foreach 遍历 ArrayList 时删除元素，正确做法是？","options":["直接 list.remove(o)","用 Iterator 的 remove()","先把 list 变 null","加个 try-catch"],"answer":1,"explain":"iterator.remove() 会同步 expectedModCount；直接 list.remove 只改 modCount，下一次 next() 就 fail-fast 抛异常。"},{"q":"把两个内容相同的 User 对象放入 HashSet，size() = 2，最可能的原因是？","options":["HashSet 有 bug","没重写 equals 和 hashCode","应该用 ArrayList","对象内存地址不同没办法"],"answer":1,"explain":"不重写就沿用 Object 默认实现：equals 比地址、hashCode 返回对象标识哈希，\\"内容相同\\"的两个对象自然各占一个桶。"}]},{"day":5,"stage":"集合","title":"Map 深水区","points":["HashMap 遍历顺序不确定；要插入序用 LinkedHashMap，要键排序用 TreeMap。","get 不存在的 key 返回 null——但 value 类型是 int 等基本类型包装时，自动拆箱 <b>NPE</b>！用 getOrDefault。","JDK7 HashMap 头插法并发扩容会链表成环 → CPU 100%；JDK8 改尾插但并发仍会丢数据，它依然不是线程安全的。","computeIfAbsent / merge 是初始化嵌套集合的优雅写法，比 if-contains-else-put 少一次哈希查找。"],"questions":[{"q":"Map<String, Integer> map = new HashMap<>(); map.get(\\"x\\") 的结果是？","options":["0","null","NPE 异常","\\"null\\""],"answer":1,"explain":"get 返回 null 本身没问题。危险的是赋给 int：int v = map.get(\\"x\\") 会触发拆箱 null.intValue() 抛 NPE。"},{"q":"统计单词次数，JDK8+ 最推荐写法是？","options":["if(map.containsKey(w)) map.put(w, map.get(w)+1); else map.put(w,1);","map.merge(w, 1, Integer::sum);","map.put(w, 1);","map.putIfAbsent(w, 1);"],"answer":1,"explain":"merge 一行搞定：不存在放 1，存在按函数累加。A 功能对但查两次哈希；D 只在不存在时放 1，统计不了次数。"}]},{"day":6,"stage":"并发","title":"多线程入门坑","points":["调用 run() 不是开线程！只有 start() 才创建新线程，run() 只是普通方法调用。","i++ 不是原子操作（读-改-写三步），volatile 也救不了，要用 AtomicInteger 或锁。","sleep(1000) 不释放锁；wait() 必须在 synchronized 块里且会释放锁——两者最经典辨析。","子线程抛出的异常主线程 try-catch 接不到：线程是独立执行栈，要用 UncaughtExceptionHandler 或 Future.get() 获取。"],"questions":[{"q":"两个线程同时执行 count++（volatile int count）1000 次，最终 count 可能是？","options":["一定是 2000","一定小于 2000 且随机","2000 或 1999","报并发异常"],"answer":1,"explain":"volatile 只保证可见性不保证原子性，读-改-写交错会丢更新，结果 ≤ 2000 的随机值。"},{"q":"关于 sleep 和 wait，正确的是？","options":["都在 Object 类里","sleep 会释放锁","wait 必须在 synchronized 中且释放锁","效果一样"],"answer":2,"explain":"wait 是 Object 方法、必须持锁调用且释放锁；sleep 是 Thread 静态方法、抱着锁睡。"}]},{"day":7,"stage":"并发","title":"线程池误用","points":["禁止 Executors.newFixedThreadPool：无界队列堆积任务导致 OOM——阿里规约明令，手动 new ThreadPoolExecutor。","核心线程未满时来了任务先开核心线程（不是先排队）；队列满了才开非核心线程——顺序和直觉相反。","CallerRunsPolicy 是最友好的拒绝策略：让提交线程自己执行，天然起到反压限流作用。","线程池里慎用 ThreadLocal：线程复用导致\\"上个任务的脏数据\\"串到下个任务，用完必须 remove。"],"questions":[{"q":"corePoolSize=2, maxPoolSize=5, queue=10。已有 2 核心线程忙，再来第 3 个任务会？","options":["创建第 3 个线程","进队列排队","触发拒绝","丢弃任务"],"answer":1,"explain":"核心满 → 先入队；队列(10)也满了才会开非核心线程到 5；全满才拒绝。先排队后扩容是考点。"},{"q":"线程池用 ThreadLocal 存用户信息，第二个任务读到了第一个任务的用户——原因是？","options":["ThreadLocal 线程不安全","线程复用且没 remove，残留了旧值","内存溢出","ThreadLocal 是单例"],"answer":1,"explain":"线程池的线程用完不销毁，ThreadLocalMap 跟着线程存活。必须在 finally 中 remove()。"}]},{"day":8,"stage":"JVM","title":"内存与 GC 误区","points":["GC Roots 可达性分析：不是\\"有引用就不回收\\"，而是\\"从 Roots 不可达才回收\\"——对象间互相引用但都不可达，照样回收。","静态集合类是内存泄漏重灾区：往 static Map 里塞对象永不清理 = 永不回收。","System.gc() 只是\\"建议\\"，GC 时机不受程序员控制——不要在代码里指望它释放内存。","堆 OOM ≠ 内存泄漏，也可能是堆太小（-Xms -Xmx）或一次性加载超大文件/大查询。"],"questions":[{"q":"ObjA.obj = objB; ObjB.obj = objA; 除此之外无任何引用，这两个对象会被回收吗？","options":["不会，互相引用着","会，可达性分析判定不可达","不会，引用计数为 2","随机回收"],"answer":1,"explain":"JVM 用可达性分析不用引用计数，循环引用从 GC Roots 不可达照样回收——这是引用计数法的缺陷而 JVM 规避了它。"},{"q":"线上服务慢慢变卡最终 OOM，最可能的原因是？","options":["CPU 太慢","内存泄漏（对象只进不出）","磁盘满","网络延迟"],"answer":1,"explain":"渐进式卡顿到 OOM 是内存泄漏典型症状：静态集合、未关闭资源、ThreadLocal 残留都是常见源头。"}]},{"day":9,"stage":"MySQL","title":"SQL 基础易错","points":["<code>WHERE COUNT(*) > 1</code> 直接报错：聚合结果过滤要用 <b>HAVING</b>——WHERE 过滤行，HAVING 过滤组。","NULL 参与比较全是 UNKNOWN：<code>WHERE col != ''x''</code> <b>查不出 col 为 NULL 的行</b>，要 IS NULL 显式处理。","<code>COUNT(col)</code> 不统计该列 NULL 的行，<code>COUNT(*)</code> 统计所有行——结果可能不一样。","SELECT 非聚合列必须出现在 GROUP BY 里（MySQL 宽松模式下不报错但结果不确定，是坑不是特性）。"],"questions":[{"q":"SELECT dept, COUNT(*) FROM emp WHERE salary > 5000 GROUP BY dept HAVING COUNT(*) > 10; 执行顺序是？","options":["WHERE→GROUP→HAVING→SELECT","SELECT→WHERE→GROUP→HAVING","GROUP→WHERE→HAVING→SELECT","HAVING→WHERE→GROUP→SELECT"],"answer":0,"explain":"标准顺序：FROM→WHERE(过滤行)→GROUP BY(分组)→HAVING(过滤组)→SELECT(投影)→ORDER BY→LIMIT。"},{"q":"表里有 NULL 的 phone 行，SELECT COUNT(*), COUNT(phone) 的关系是？","options":["一定相等","COUNT(*) ≥ COUNT(phone)","COUNT(*) ≤ COUNT(phone)","都为 0"],"answer":1,"explain":"COUNT(*) 数行数（含 NULL 行），COUNT(phone) 跳过 NULL——所以 COUNT(*) ≥ COUNT(phone)。"}]},{"day":10,"stage":"MySQL","title":"索引与性能","points":["联合索引 (a,b,c)：查询必须从 a 开始连续命中，<code>WHERE b=1</code> 完全用不上索引（最左前缀）。","范围查询会\\"断档\\"：<code>WHERE a=1 AND b>10 AND c=2</code>，c 用不上索引（b 是范围后 c 无序）。","LIKE 前导 % 索引失效：<code>LIKE ''%关键字''</code> 用不上索引；后缀形式 <code>LIKE ''关键字%''</code> 不失效。","索引列上做函数/运算必失效：<code>WHERE YEAR(dt)=2024</code> 改写成范围条件 <code>dt >= ''2024-01-01'' AND dt < ''2025-01-01''</code>。"],"questions":[{"q":"联合索引 (city, age)，以下哪个查询能完整用到索引？","options":["WHERE age=20","WHERE city=''北京'' AND age=20","WHERE age=20 AND city LIKE ''%京''","WHERE city LIKE ''%京%''"],"answer":1,"explain":"最左前缀 + 等值连续匹配才能完整利用 (city, age)。A 缺最左列；C 的 LIKE 前导 % 失效；D 同理。"},{"q":"WHERE user_id + 0 = 100 没走索引，怎么改？","options":["加 /+INDEX/ 提示","改写为 WHERE user_id = 100","换成 OR 条件","重建表"],"answer":1,"explain":"对索引列做运算导致失效，把运算移出列：user_id = 100 直接命中。核心原则：运算留右边，列保持\\"干净\\"。"}]},{"day":11,"stage":"MySQL","title":"事务与锁","points":["MySQL InnoDB 默认隔离级别是 RR（可重复读），不是 SQL 标准默认的 RC。","RR 下快照读（普通 SELECT）靠 MVCC 防幻读；当前读（SELECT ... FOR UPDATE）靠临键锁防幻读。","@Transactional 默认只回滚 RuntimeException——抛 IOException 不会回滚！务必 rollbackFor = Exception.class。","同类自调用 @Transactional 方法不走代理、事务失效——拆到另一个 Bean 或注入自身代理。"],"questions":[{"q":"事务方法 A 内部 catch 了 RuntimeException 没 rethrow，结果是？","options":["回滚","不回滚，正常提交","编译报错","抛出新异常"],"answer":1,"explain":"Spring 事务靠\\"异常穿过代理\\"触发回滚，异常被吃掉=事务无感知=照常提交。要回滚就 rethrow 或 TransactionAspectSupport 回滚标记。"},{"q":"UserService.update() 调用同类的 this.save()（@Transactional），save 的事务生效吗？","options":["生效","不生效，this 绕过了代理对象","部分生效","编译失败"],"answer":1,"explain":"AOP 事务的本质是代理对象包裹，this 调用是原始对象方法调用，切面根本不在场。解法：拆类 / 注入自身代理 / AopContext。"}]},{"day":12,"stage":"Spring","title":"IoC 与注入","points":["@Autowired 按<b>类型</b>注入，同类型多个 Bean 启动报错 NoUniqueBeanDefinitionException——配合 @Qualifier(\\"名字\\") 或 @Primary。","@Resource 是 JDK 注解，按<b>名称</b>注入（先名字后类型）。","构造器注入是官方推荐：依赖不可变、防止 NPE、便于测试；字段注入的坑：无法在构造时校验、隐藏依赖。","单例 Bean 里放可变成员变量 = 并发灾难：Bean 无状态才线程安全。"],"questions":[{"q":"接口 PayService 有 wxPay 和 aliPay 两个实现，@Autowired PayService 会？","options":["随机注入一个","注入第一个扫描的","启动报错（除非加 @Primary/@Qualifier）","注入代理集合"],"answer":2,"explain":"按类型找到 2 个候选，无法决策直接启动失败。解法：@Primary 标默认、@Qualifier 指名、或注入 List<PayService> 做策略模式。"},{"q":"以下哪种注入方式被 Spring 官方最推荐？","options":["字段注入 @Autowired","setter 注入","构造器注入","静态变量持有"],"answer":2,"explain":"构造器注入保证依赖不可变且非空、利于单元测试、暴露循环依赖。Spring 官方文档与阿里规约一致推荐。"}]},{"day":13,"stage":"前端/接口","title":"HTTP 与接口易错","points":["POST 不是\\"绝对安全\\"也不幂等；PUT 幂等、POST 不幂等——重复提交风险在 POST 上，要幂等设计。","GET 参数有长度限制（浏览器 URL 约 2KB~8KB），大参数用 POST body。","401 是\\"未认证\\"（没登录/Token 失效），403 是\\"已认证但无权限\\"——混用是接口设计常见错误。","跨域是<b>浏览器行为</b>：Postman 不跨域，浏览器才管 CORS；解决靠后端响应 Access-Control-Allow-Origin 或网关代理。"],"questions":[{"q":"用户已登录但访问无权限的资源，应返回？","options":["401","403","404","500"],"answer":1,"explain":"401 Unauthorized=没登录或凭证失效；403 Forbidden=身份已知但权限不够。语义分清，前端才能正确引导（跳登录 vs 提示无权限）。"},{"q":"前端 fetch 报 CORS 错误，但 Postman 请求同一接口正常，说明？","options":["后端挂了","跨域是浏览器同源策略行为，需后端配 CORS 头","Postman 破解了接口","前端代码有 bug"],"answer":1,"explain":"同源策略只在浏览器生效。解法：后端加 Access-Control-Allow-Origin / 网关统一处理 / dev 代理。"}]},{"day":14,"stage":"Redis","title":"缓存易错","points":["Redis 事务不回滚：MULTI/EXEC 中途出错已执行的命令不撤销——强一致回滚需求别指望 Redis。","setnx 分布式锁必须带<b>唯一值 + Lua 原子解锁</b>：否则 A 超时误删 B 的锁是经典事故。","大 key（10MB 的 value）删除会阻塞单线程：用 UNLINK 异步删、SCAN 代替 KEYS。","缓存空值防穿透必须设<b>短过期时间</b>，否则脏数据永生。"],"questions":[{"q":"锁 set(lockKey, clientId, NX, EX 10)，释放锁正确姿势是？","options":["直接 DEL lockKey","Lua 脚本：GET 比对 clientId 相同才 DEL","EXPIRE 0","等 10 秒自然过期"],"answer":1,"explain":"直接 DEL 可能删掉别人的锁（A 执行慢锁已过期被 B 拿到）。GET+比对+DEL 必须原子，用 Lua。"},{"q":"以下哪个场景最该给缓存 value 加\\"逻辑过期\\"？","options":["全部商品缓存","秒杀热点商品","配置字典表","用户 Session"],"answer":1,"explain":"热点 key 物理过期瞬间的并发重建就是击穿。逻辑过期（不设 TTL，value 内带过期时间+异步刷新）专治热点。"}]},{"day":15,"stage":"工程化","title":"Git 与 Linux 坑","points":["<code>git pull</code> 默认 merge，冲突解决后要先 add 再 commit——rebase 方式则要 git rebase --continue。","<code>git reset --hard</code> 会<b>永久丢弃</b>未提交修改，执行前先 stash 或确认。","<code>rm -rf /</code> 级别事故：rm 命令没有回收站，路径先 pwd 确认再删；变量为空的 <code>rm -rf $dir/</code> 是删库根源。","chmod 777 不是解决方案是埋雷；日志排查三板斧：tail -f、grep、less +F。"],"questions":[{"q":"发现 git reset --hard 丢弃了未提交的代码，还有救吗？","options":["彻底没了","git fsck --lost-found 捞 dangling blob 有机会找回","重启电脑","只能重写"],"answer":1,"explain":"Git 对象仍在 .git/objects 里成为悬空对象，git fsck --lost-found 或 IDE 的 Local History 能救回一部分——这也是\\"勤 commit\\"的理由。"},{"q":"排查\\"服务占用 8080 端口\\"，命令组合是？","options":["ls -l /var/log","lsof -i:8080 或 ss -tlnp | grep 8080","ps aux | grep java 即可","top"],"answer":1,"explain":"按端口找进程：lsof -i:8080（mac）或 ss -tlnp | grep 8080（Linux），拿到 PID 再 kill。ps aux 按进程名搜不适合定位端口。"}]},{"day":16,"stage":"Java 进阶","title":"泛型与类型","points":["泛型是<b>编译期</b>检查，运行时擦除：<code>List&lt;String&gt;</code> 和 <code>List&lt;Integer&gt;</code> 的 Class 是同一个。","<code>List&lt;Object&gt;</code> 不是 <code>List&lt;String&gt;</code> 的父类！泛型不协变，要用 <code>? extends</code> 通配。","不能 new T()：泛型类型运行时不存在，需要 Class&lt;T&gt; 反射或传入工厂。","包装类比较永远 equals：Integer 缓存 -128~127 的 == true 是陷阱不是福利。"],"questions":[{"q":"List<String> a = new ArrayList<>(); List<Integer> b = new ArrayList<>(); a.getClass() == b.getClass() 结果是？","options":["true","false","编译报错","运行异常"],"answer":0,"explain":"类型擦除：运行时都是 ArrayList.class，泛型参数只存在于编译期。这也是为什么反射能绕过泛型检查塞入异构元素。"},{"q":"Integer a = 100, b = 100; a == b 与 Integer c = 200, d = 200; c == d 的结果分别是？","options":["true, true","true, false","false, false","true, 编译错误"],"answer":1,"explain":"IntegerCache 缓存 -128~127：100 在范围内是同一缓存对象 == 为 true；200 超范围各自 new，== 为 false。包装类永远用 equals。"}]},{"day":17,"stage":"MyBatis","title":"MyBatis 易错","points":["<code>#{}</code> 预编译防注入，<code>${}</code> 字符串替换有注入风险——表名/排序字段必须白名单校验后再 ${}。","模糊查询写法：<code>LIKE CONCAT(''%'', #{kw}, ''%'')</code>，不要 <code>LIKE ''%${kw}%''</code>。","resultType 对不上字段名就静默为 null：开驼峰映射 mapUnderscoreToCamelCase 或用 resultMap。","insert 后要拿自增 id：加 <code>useGeneratedKeys=\\"true\\" keyProperty=\\"id\\"</code>，否则对象里 id 一直是 null。"],"questions":[{"q":"防止 SQL 注入，动态排序字段应如何处理？","options":["直接 #{orderBy}","${orderBy} 前加白名单校验","前端传什么就排什么","禁止排序"],"answer":1,"explain":"#{} 会被加引号变成字符串导致 ORDER BY 失效，所以只能 ${}，但必须后端白名单限定可选列名，杜绝注入。"},{"q":"查询结果某字段总是 null，数据库里明明有值，最可能原因是？","options":["数据库坏了","Java 属性名与列名不匹配且未开驼峰映射","SQL 写错了","事务未提交"],"answer":1,"explain":"user_name 列默认映射不到 userName 属性。开 map-underscore-to-camel-case=true 或写 resultMap 显式映射。"}]},{"day":18,"stage":"并发进阶","title":"锁的进阶坑","points":["可重入：同一线程可重复获取自己持有的锁，否则递归/嵌套调用直接死锁。","死锁四条件：互斥、持有等待、不可剥夺、循环等待——破坏任一即可预防（统一加锁顺序最常用）。","synchronized 锁的对象换引用 = 换锁：<code>lock = new Object()</code> 后旧锁作废，两拨人两把锁。","双重检查单例必须 volatile：防 new 的\\"分配-初始化-赋值\\"重排，别的线程拿到半成品。"],"questions":[{"q":"线程 1 锁 A 再锁 B；线程 2 锁 B 再锁 A。会发生？","options":["正常执行","死锁（循环等待）","自动回滚","活锁"],"answer":1,"explain":"互相持有对方要的锁并循环等待=死锁四条件齐活。预防：全局统一\\"先 A 后 B\\"的加锁顺序破坏循环等待。"},{"q":"DCL 单例中 instance 不加 volatile 的隐患是？","options":["性能下降","其他线程可能拿到未初始化完成的对象","不能实例化","内存泄漏"],"answer":1,"explain":"new 的三步可能重排为\\"先赋引用再初始化\\"，判空通过的线程拿到半成品对象开始用，诡异 NPE。volatile 禁止相关重排。"}]},{"day":19,"stage":"JVM","title":"调参与排查","points":["-Xms 和 -Xmx 设成一样：避免堆动态伸缩抖动。","OOM 时堆转储：<code>-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=...</code>，事后用 MAT 分析支配树找泄漏源。","CPU 100% 排查五步：top 找进程 → top -Hp 找线程 → printf %x 转十六进制 → jstack 抓栈 → 按 nid 定位代码行。","频繁 Full GC 常见原因：内存泄漏、元空间不够、大对象直接进老年代、System.gc 被调用。"],"questions":[{"q":"jstack 输出中怎么定位目标线程？","options":["按线程名搜索","把 top -Hp 的线程 PID 转 16 进制比对 nid","看最后 10 行","按时间排序"],"answer":1,"explain":"jstack 的 nid=0x... 是十六进制线程 ID。top 找到吃 CPU 的十进制 PID → printf \\"%x\\" 转换 → 在栈里搜 0x...。"},{"q":"-Xms4g -Xmx4g 的主要目的是？","options":["加快 GC","避免堆动态扩缩带来的抖动","省内存","规范写法好看"],"answer":1,"explain":"初始=最大避免运行时向 OS 申请/归还内存，消除抖动让延迟平稳，生产标准配置。"}]},{"day":20,"stage":"MySQL","title":"日志与主从","points":["redo log 循环写（物理、InnoDB 层、崩溃恢复），binlog 追加写（逻辑、Server 层、复制/归档）——别搞混。","两阶段提交（redo prepare → binlog → redo commit）保证两日志一致，否则主从数据分叉。","主从延迟原因：从库单线程回放、大事务、从库机器差。缓解：并行复制、拆大事务、半同步。","删库不用怕 binlog：用全量备份 + binlog 重放到误操作前一刻（前提：binlog 开着且格式 row）。"],"questions":[{"q":"只写 redo log 不写 binlog 会导致？","options":["无法崩溃恢复","主从复制数据不一致","查询变慢","索引失效"],"answer":1,"explain":"redo 保证本机崩溃恢复，binlog 是复制与归档的载体，没有它从库就收不到变更。"},{"q":"主从延迟过大，以下哪个不是有效缓解手段？","options":["开启并行复制","大事务拆小","从库硬件升级","把 binlog 格式改回 statement"],"answer":3,"explain":"statement 格式省日志但可能主从不一致（函数/now() 执行结果不同），row 才是可靠格式，改回去治标不治本还有害。"}]},{"day":21,"stage":"Spring","title":"Bean 与自动配置","points":["自动配置的开关是 @Conditional 系：classpath 没有驱动类就不装配——所以引了 starter 不配 URL 会启动失败。","自定义 Bean 会覆盖自动配置：@ConditionalOnMissingBean 是\\"你有我就让位\\"的机关。","Bean 默认单例：注入 List&lt;X&gt; 拿到全部实现是策略模式标配，配合 Map&lt;String, X&gt; 按名取。","@Value 拿不到配置的排查：配置文件位置、前缀拼写、@ConfigurationProperties 未加 @EnableConfigurationProperties。"],"questions":[{"q":"自动配置类里 @Bean 方法常带 @ConditionalOnMissingBean，作用是？","options":["防止重复启动","用户自己定义了同类型 Bean 时让位，保证可定制","加速启动","循环依赖检测"],"answer":1,"explain":"这是\\"默认配置可被覆盖\\"的机关：容器已有该类型 Bean 就跳过默认装配，实现约定优于配置又留足定制空间。"},{"q":"同类接口多实现，最优的注入姿势是？","options":["@Qualifier 硬编码","注入 List<X> 或 Map<String, X> 遍历/按名取","写 if-else new","加 static"],"answer":1,"explain":"注入集合天然收集所有实现，新增实现零改动；Map 的 key 是 Bean 名。这就是 Spring 里的策略模式落地。"}]},{"day":22,"stage":"前端","title":"JS 与 Vue 易错","points":["js 的 == 隐式转换天坑：''1'' == 1 为 true、null == undefined 为 true——永远用 ===。","深拷贝别用 JSON.parse(JSON.stringify(obj))：丢函数、丢 undefined、Date 变字符串；用 structuredClone 或库。","Vue3 里 ref 在 script 要 .value，template 里自动解包——script 中忘 .value 是最高频 bug。","props 是单向数据流：子组件直接改 props 不报错但不生效（对象内部属性改除外），要 emit 事件回传。"],"questions":[{"q":"console.log(0 == '''', 0 === '''') 输出？","options":["true, true","true, false","false, false","false, true"],"answer":1,"explain":"== 会把 '''' 转成 0；=== 类型不同直接 false。规则：一律 ===，除 null 判断（x == null 可同时匹配 null/undefined）外。"},{"q":"const user = ref({name:''a''}); 想改名字，正确的是？","options":["user.name = ''b''","user.value.name = ''b''","user = ref({name:''b''})","refUser(user)"],"answer":1,"explain":"script 中 ref 要 .value 拿到内部对象再改属性。整个替换也可以 user.value = {...}。A 少了 .value；C 丢响应性引用。"}]},{"day":23,"stage":"MQ","title":"消息队列易错","points":["消费失败别无限重试：设重试次数 + 死信队列，否则毒丸消息阻塞整个队列。","顺序消息只能在\\"单队列单消费者\\"内保证，多分区并行天生无序——按业务 key 路由到同队列。","消息幂等必须做：至少一次投递语义下重复不可避免，唯一索引/状态机/setnx 三选一。","发送端本地消息表：业务与消息记录同事务落库，定时补偿扫描——防\\"业务成功但消息没发出去\\"。"],"questions":[{"q":"某条消息格式非法导致消费永远失败，正确处理是？","options":["无限重试直到成功","重试 N 次后进死信队列人工处理","直接丢弃不记录","重启消费者"],"answer":1,"explain":"\\"毒丸\\"消息无限重试会阻塞后续消息。有限重试 + 死信/人工干预是标准方案，丢弃要有日志与告警。"},{"q":"订单状态流转消息要求同订单严格有序，怎么设计？","options":["全局单队列单消费者","按 orderId 哈希路由到固定分区，同分区单消费者","消息里加时间戳排序","发三遍取第一个"],"answer":1,"explain":"按业务 key 路由同队列/分区，保证局部有序且保留并行度（不同订单互不阻塞）。全局串行性能太差。"}]},{"day":24,"stage":"网络","title":"TCP/HTTP 深坑","points":["TCP 三次握手缺一不可：防\\"历史重复连接请求\\"造成的资源浪费（两次握手即可建成失效连接）。","TIME_WAIT 是主动关闭方 2MSL 等待：大量 TIME_WAIT 不是服务端 bug，是它主动关连接多（短连接架构病）。","HTTP 1.1 的队头阻塞在 HTTP/2 用多路复用解决（TCP 层的还在，HTTP/3 换 QUIC/UDP）。","HTTPS = HTTP + TLS：非对称交换密钥 → 对称加密通信；证书链验证防中间人。"],"questions":[{"q":"服务端出现数万 TIME_WAIT，最合适的优化方向是？","options":["调大文件描述符","改长连接/连接复用（Keep-Alive、连接池）","关闭防火墙","升级 CPU"],"answer":1,"explain":"TIME_WAIT 堆积根因是频繁建断短连接。上连接池/Keep-Alive 从架构上减少握手次数才是治本。"},{"q":"HTTPS 握手后传输数据用的是？","options":["非对称加密","对称加密","不加密","Base64"],"answer":1,"explain":"非对称只用于交换会话密钥（慢），之后用对称密钥加密通信（快）。兼具安全与性能。"}]},{"day":25,"stage":"算法","title":"编码习惯坑","points":["整型溢出：mid = (l + r) / 2 在 r 很大时溢出，写 <code>mid = l + (r - l) / 2</code>。","字符串比较用 equals；字符判断 charAt 返回 char，用 == 比较 char 是对的（基本类型）。","递归没写终止条件 = StackOverflowError；写对条件但没收敛（每层规模不减）同样爆栈。"," HashMap 的 key 用可变对象（如数组）= 取不回来：hashCode 随内容变化，永远匹配不上。"],"questions":[{"q":"二分查找中 mid = (left + right) / 2 的隐患是？","options":["精度丢失","left+right 溢出为负","死循环","越界异常"],"answer":1,"explain":"大数组 right 接近 Integer.MAX_VALUE 时相加溢出成负数。l + (r-l)/2 数学等价且不溢出，是面试手写规范。"},{"q":"用 HashMap<int[], Integer> 以数组为 key 存\\"前缀和\\"，为什么取不到值？","options":["HashMap 不支持数组 key","数组 hashCode 随内容变，存取时哈希不一致","数组太大","自动装箱失败"],"answer":1,"explain":"Java 数组没有按内容重写 hashCode/equals，且内容一旦被改，查找时的哈希与放入时不同——用 String 或不可变对象做 key。"}]},{"day":26,"stage":"安全","title":"安全防线坑","points":["SQL 注入唯一正解：参数化查询/预编译（MyBatis #{}），拼接 SQL 一律死刑。","XSS 防御：输出转义 + CSP；富文本用白名单过滤（Jsoup sanitize）。","密码存储：BCrypt（自带盐+慢哈希），禁止 MD5 裸存——彩虹表秒破。","JWT 无法主动作废：登出/封号要让 Token 失效，需配合 Redis 黑名单或短过期+刷新 Token。"],"questions":[{"q":"用户登录密码的正确存储方式是？","options":["明文存库","MD5 加密存","BCrypt 加盐哈希存","Base64 编码存"],"answer":2,"explain":"MD5 速度太快可被彩虹表/ GPU 爆破。BCrypt/PBKDF2/Argon2 设计上就慢+自带盐，是密码哈希标准。"},{"q":"用户点击\\"退出登录\\"后 JWT 仍可用一段时间，原因是？","options":["JWT 有 bug","JWT 无状态自包含，服务端不存储无法直接作废","浏览器缓存","HTTPS 问题"],"answer":1,"explain":"JWT 的优点（无状态）正是痛点：签发后无法吊销。方案：短 TTL + refresh token、Redis 黑名单、改用 Session。"}]},{"day":27,"stage":"接口设计","title":"RESTful 与工程规约","points":["URL 用名词复数：/users/1/orders，动词靠 HTTP 方法表达——/getUserById 是反模式。","统一响应体 { code, message, data }：业务错误也返回 HTTP 200 + 业务码，是国内外主流实践（或严格 RESTful 用状态码，团队统一即可）。","分页参数pageNum/pageSize，返回 total——不返回 total 的分页是残废。","接口版本化：/api/v1/...，大改不破坏旧客户端。"],"questions":[{"q":"RESTful 风格下\\"给 ID 为 5 的订单取消\\"，最合理的是？","options":["GET /cancelOrder?id=5","POST /orders/5/cancel","PUT /orders/5 status=cancelled","DELETE /orders/5"],"answer":2,"explain":"取消本质是把订单状态改为 cancelled，PUT 更新资源语义最准；B 的 /cancel 是动词路径；D 会误删订单。"},{"q":"分页接口响应里为什么必须返回 total？","options":["好看","前端计算总页数与\\"是否有下一页\\"，否则无法渲染分页控件","协议要求","性能优化"],"answer":1,"explain":"没有 total 前端只能\\"盲翻页\\"。性能敏感场景可退化返回 hasNext 布尔（游标分页）——但这是权衡，不是省略理由。"}]},{"day":28,"stage":"分布式","title":"分布式入门坑","points":["CAP 只能三选二：P 必选（网络分区必然存在），实际是 CP（ZK/etcd）与 AP（Eureka/Nacos AP 模式）的取舍。","分布式 ID 别用自增：分库分表冲突 + 暴露业务量；用雪花算法（时钟回拨是坑）或号段模式。","幂等是分布式的第一公民：超时重试无处不在，接口不幂等 = 数据灾难。","分布式锁必须考虑：过期时间与业务时长的匹配、看门狗续期、锁的可重入性。"],"questions":[{"q":"注册中心 Nacos（AP 模式）在分区时允许节点数据短暂不一致，符合 CAP 的？","options":["CP","AP","CA","CAP 全满足"],"answer":1,"explain":"注册中心要的是可用性（服务发现不能全挂），接受最终一致。ZK 选 CP：分区时拒绝写保证一致，选举期间不可用。"},{"q":"Redisson 看门狗（watchdog）解决什么问题？","options":["锁竞争","业务未执行完但锁过期被别人抢走——自动续期","网络抖动","内存回收"],"answer":1,"explain":"固定 TTL 骑虎难下：设短了业务没完锁没了，设长了宕机等太久。看门狗后台定时续期，兼顾安全与活性。"}]},{"day":29,"stage":"数据库进阶","title":"优化实战坑","points":["深分页 LIMIT 1000000,10 慢在\\"扫过前 100 万行再丢弃\\"：改游标 WHERE id > lastId LIMIT 10 或延迟关联。","select * 三宗罪：回表取多余列、无法覆盖索引、网络传输大——明确列出需要的字段。","大批量 insert：单条循环 10 万次 vs 批量 values 500 一批，差百倍性能；还要关自动提交。","ONLINE DDL 注意：大表加字段也可能锁表（视算法与版本），生产变更用 gh-ost/pt-osc。"],"questions":[{"q":"SELECT * FROM orders ORDER BY id LIMIT 5000000, 10 优化，正确的是？","options":["加内存","先查 id：SELECT id ... LIMIT 5000000,10，再按 id IN 回查整行","改用 OR 条件","删索引"],"answer":1,"explain":"延迟关联/覆盖索引：先在二级索引（或主键）上完成翻页拿到 id，再回表 10 行——把\\"扫 500 万行回表\\"变成\\"索引上滑过+回表 10 行\\"。"},{"q":"为什么生产环境禁止 SELECT *？（不正确的理由是？）","options":["无法利用覆盖索引","传输多余数据","可能触发回表代价","会导致表锁"],"answer":3,"explain":"SELECT * 与表锁无关（InnoDB 行锁为主）。前三条都是真实代价：覆盖索引失效、IO/带宽浪费、回表成本。"}]},{"day":30,"stage":"面试冲刺","title":"面试表达坑","points":["简历写\\"精通\\"必被往死里问：写\\"熟悉/掌握\\"，留活口。","不会的题别硬编：说\\"这块我了解程度有限，但我理解原理是 X，可以往 Y 方向查证\\"——诚实+思路比编造强一百倍。","项目介绍 STAR 法则：背景(S)→任务(T)→行动(A)→结果(R)带数字：\\"QPS 从 200 优化到 3000\\"。","反问环节别问\\"加不加班\\"先问\\"团队技术栈/导师制/业务方向\\"——展示技术热情。"],"questions":[{"q":"面试官问到一个你完全不会的问题，最佳策略是？","options":["瞎编蒙混","沉默摇头","坦诚不熟 + 给出基于已知知识的推理思路","反问面试官"],"answer":2,"explain":"面试考察的是解决问题的思维方式。坦诚边界+现场推理展示潜力，比一个错误答案有价值得多。"},{"q":"介绍项目时最有说服力的是？","options":["罗列用过的技术名词","强调代码量与加班","STAR 结构：业务背景→技术挑战→你的方案→量化结果","只讲架构图"],"answer":2,"explain":"\\"QPS 3000、RT 50ms、事故率降 80%\\"这类量化结果 + 你个人的决策过程，才能证明这是\\"你的\\"项目。"}]},{"day":31,"stage":"计算机网络","title":"TCP 握手挥手坑","points":["三次握手不是\\"三次通话\\"而是\\"三次报文\\"；SYN 消耗一个序号，SYN+ACK 也消耗——所以 ack=x+1。","TIME_WAIT 一定在<b>主动关闭方</b>。压测机上几万 TIME_WAIT 是\\"你是客户端在大量短连接\\"，不是服务端问题。","服务端大量 CLOSE_WAIT ≠ 网络问题，是<b>你的代码收到 FIN 后没调 close()</b>——九成是连接泄漏（没关流/连接池耗尽）。"],"questions":[{"q":"服务端出现大量 CLOSE_WAIT，最可能的原因是？","options":["被 SYN 攻击","应用代码没有及时关闭连接（收到对方的 FIN 后未 close）","带宽不足","TCP 版本太旧"],"answer":1,"explain":"CLOSE_WAIT 是\\"被动关闭方收到 FIN、自己还没 close\\"的状态。大量堆积=应用层泄漏，查代码里的资源关闭/连接池配置。"},{"q":"syncookie 的核心思想是？","options":["加密 SYN 包","不分配资源存连接，把连接信息编码进 ISN 返回，收到合法 ACK 再建","提高队列长度","直接拒绝所有连接"],"answer":1,"explain":"把\\"半连接该记的信息\\"算进序号里发回客户端，服务端零存储——ACK 回来重新计算校验即可重建，队列打不满。"}]},{"day":32,"stage":"计算机网络","title":"TCP 可靠性机制混淆点","points":["滑动窗口是<b>流量控制</b>（管接收方），慢启动是<b>拥塞控制</b>（管网络），别混。","快重传的触发条件是 <b>3 个重复 ACK</b>，不是 1 个——1 个可能只是乱序。","RTO 超时比 3 个重复 ACK 严重得多：前者 cwnd 归 1 慢启动，后者减半快恢复。"],"questions":[{"q":"收到 3 个重复 ACK 后，TCP 执行的是？","options":["cwnd=1 重新慢启动","快速重传丢失报文，ssthresh/cwnd 减半继续（快恢复）","关闭连接","窗口清零"],"answer":1,"explain":"3 个重复 ACK=轻度丢包，温和处理。超时（RTO）才是重度：cwnd 归 1。"},{"q":"接收方通告 rwnd=0 且窗口更新包丢失，靠什么机制避免死锁？","options":["三次握手重来","发送方的坚持定时器定期发零窗口探测报文","直接断开","RST 复位"],"answer":1,"explain":"零窗口后发送方启动 persist 定时器，周期性探测对方窗口是否恢复——打破\\"互相等待\\"的死锁。"}]},{"day":33,"stage":"计算机网络","title":"HTTP 协议细节坑","points":["301 是<b>永久</b>重定向（SEO 权重转移），302 临时（权重保留）——换域名要用 301。","401 = 未认证（没登录），403 = 已认证但无权限——别答反。","PUT 是幂等的（替换），POST 不幂等；DELETE 幂等但可能返回 404（第二次删没有了）。"],"questions":[{"q":"接口返回 403，含义是？","options":["没登录","登录了但没有访问权限","资源不存在","服务器内部错误"],"answer":1,"explain":"401 Unauthorized 实际是\\"未认证\\"，403 Forbidden 是\\"身份已知但拒绝\\"。语义别搞反，这是常见送分/送命题。"},{"q":"RESTful 设计中，把 POST /users/1/logout 改成更标准的写法是？","options":["GET /logout?user=1","DELETE /sessions/1（删除会话，幂等语义）","POST /deleteLogout","PUT /users/1"],"answer":1,"explain":"REST 用资源思维：登出=删除会话资源。动词藏在 HTTP 方法里，URI 只放名词。"}]},{"day":34,"stage":"计算机网络","title":"HTTPS/HTTP2 坑","points":["HTTPS 证书验证的是\\"公钥属于该域名\\"，验证链是 网站证书→中间 CA→根 CA（浏览器内置）。","TLS 1.2 握手 2-RTT、1.3 只要 1-RTT 且强制 ECDHE（前向安全）。","HTTP/2 多路复用只解决 <b>HTTP 层</b>队头阻塞；TCP 丢包仍会卡所有流——所以有 HTTP/3。"],"questions":[{"q":"TLS 1.3 废弃 RSA 密钥交换的原因是？","options":["RSA 太慢","RSA 不具备前向安全：私钥泄露后历史流量可被解密","RSA 不安全签名","兼容问题"],"answer":1,"explain":"RSA 交换的会话密钥由公钥加密传输，私钥一泄，录下的历史流量全能解。ECDHE 的临时密钥每次独立，历史安全。"},{"q":"HTTP/2 服务端推送（Server Push）的正确理解是？","options":["服务器可以主动给用户发消息","在客户端请求 HTML 时，服务器预推其依赖资源（CSS/JS）减少往返","实时聊天用","推送通知"],"answer":1,"explain":"Push 是资源级别的预推，不是消息推送。实践效果不佳（浪费带宽），很多实现已移除——消息推送用 WebSocket/SSE。"}]},{"day":35,"stage":"计算机网络","title":"DNS/CDN/URL 全流程坑","points":["DNS 记录类型：A(IPv4)、AAAA(IPv6)、CNAME(别名)、MX(邮件)、NS(权威服务器)。","CDN 调度发生在 <b>DNS 阶段</b>：CNAME 指向 CDN 的智能调度系统，按地理位置/负载返回边缘节点 IP。","浏览器同源策略拦的是\\"响应\\"不是\\"请求\\"——请求发出去了，只是 JS 读不到响应。"],"questions":[{"q":"CNAME 记录的作用是？","options":["把域名指向 IPv6","把域名指向另一个域名（别名）","设置邮件服务器","反向解析"],"answer":1,"explain":"www.example.com CNAME → cdn.example.com → CDN 调度。IP 变动只改一处，所有别名生效。"},{"q":"为什么服务器间的 HTTP 调用没有\\"跨域问题\\"？","options":["服务器性能强","同源策略是浏览器的安全机制，服务器间通信不经过浏览器","服务器有特殊证书","跨域只存在于 GET"],"answer":1,"explain":"CORS 拦截发生在浏览器。服务端互调（微服务 RPC/HTTP）不受此限——所以\\"用后端代理转发\\"也能绕过跨域。"}]},{"day":36,"stage":"操作系统","title":"进程线程通信坑","points":["线程 crash（如空指针导致的段错误）会让<b>整个进程</b>挂掉——线程没有独立地址空间可逃。","共享内存最快但<b>不同步</b>；消息队列自带格式但两次拷贝；管道 4MB 缓冲写满会阻塞。","kill -9(SIGKILL) 不可被捕获，进程无法优雅退出；kill -15(SIGTERM) 才是优雅停机信号。"],"questions":[{"q":"生产环境优雅停机应该用哪个信号？","options":["kill -9","kill -15（SIGTERM），让进程执行 shutdown hook 释放资源","kill -1","直接拔电源"],"answer":1,"explain":"SIGTERM 可捕获，应用可以处理完存量请求、刷缓冲、注销注册中心再退出。kill -9 跳过一切清理，可能丢数据/留下僵尸注册。"},{"q":"两个进程通过共享内存交换数据，还需要什么配套机制？","options":["什么都不需要","信号量或互斥锁做同步互斥","必须加 TLS","必须每次重新 attach"],"answer":1,"explain":"共享内存就是同一块物理内存，无内核介入保护。并发读写必须自己用信号量（P/V）或互斥锁协调。"}]},{"day":37,"stage":"操作系统","title":"内存管理坑","points":["malloc 只分配<b>虚拟内存</b>；首次写入才缺页分配物理页——VIRT 大不等于真用了。","TLB 是页表的缓存；进程切换换页表 → TLB 失效 → 这是进程切换贵的主因。","free 后内存不一定归还 OS（glibc 的 ptmalloc 保留在进程堆里）——RSS 不降不是泄漏。"],"questions":[{"q":"程序 malloc 了 4GB 但只写了 100MB，RES（物理驻留）大约是？","options":["4GB","约 100MB + 程序自身开销","0","2GB"],"answer":1,"explain":"惰性分配：只写过的地方有物理页。RES≈实际触碰的页 + 代码/栈等。看内存泄漏要盯 RES 增长趋势。"},{"q":"Linux 查看某进程各线程 CPU 占用的命令是？","options":["top（直接能看到）","top -Hp <pid> 或 ps -T -p <pid>","free -m","df -h"],"answer":1,"explain":"-H 显示线程。找到高 CPU 线程后 printf \\"%x\\" 转十六进制，去 jstack dump 里搜 nid=0x... 定位代码。"}]},{"day":38,"stage":"操作系统","title":"IO 多路复用坑","points":["select 每次调用都要把 fd 集合<b>从用户态拷贝到内核态</b>并全量遍历——连接多时 O(n) 就是灾难。","epoll 不是\\"一定比 select 快\\"：连接少且都活跃时差别不大；连接多活跃少时碾压。","ET 模式必须配<b>非阻塞 fd + 循环读到 EAGAIN</b>；阻塞 fd 用 ET 会漏读。"],"questions":[{"q":"epoll 高效的根本原因是？","options":["用了多线程","红黑树注册免重复拷贝 + 事件回调就绪链表，只处理活跃 fd","fd 上限更大","加密更快"],"answer":1,"explain":"处理成本从\\"与总连接数成正比\\"降到\\"与活跃连接数成正比\\"——10 万连接 100 活跃只处理 100 个。"},{"q":"Redis 6.0 引入 IO 多线程后，命令执行是？","options":["也多线程并行了","仍然单线程串行执行（保住原子性），只把网络读写多线程化","每个 key 一个线程","变成协程"],"answer":1,"explain":"瓶颈在网络包读写不在命令计算。IO Threads 并行收发包，执行仍串行——Redis 的原子性语义不变。"}]},{"day":39,"stage":"操作系统","title":"文件系统与零拷贝坑","points":["PageCache 是内核的文件页缓存：读文件先查它，\\"写文件\\"默认也先写它（异步刷盘）——突然断电可能丢。","sendfile 适合\\"文件→网卡\\"（Kafka/Nginx）；mmap 适合随机读写；两者都不适合所有场景。","fsync 才是强制落盘；Java 的 FileChannel.force() 对应它——重要日志要显式调用。"],"questions":[{"q":"Kafka 消费消息快的原因组合是？","options":["随机读+多线程","顺序读 + sendfile 零拷贝 + PageCache 命中","数据在内存数据库","压缩算法"],"answer":1,"explain":"日志段文件顺序追加+消费者顺序读，PageCache 命中率极高；sendfile 免用户态拷贝——单机百万级 TPS 的物理基础。"},{"q":"write() 返回成功，数据一定落盘了吗？","options":["一定","不一定，可能只在 PageCache，需 fsync 才强制落盘","取决于文件名","磁盘写永不缓存"],"answer":1,"explain":"write 到 PageCache 即返回（快但断电可能丢）。金融级日志/消息持久化必须 fsync（或依赖组件如 RocketMQ 的 SyncFlush）。"}]},{"day":40,"stage":"MySQL 索引","title":"索引设计实战坑","points":["区分度低的列（如性别）单独建索引意义不大——优化器可能弃用，回表比全表扫还慢。","联合索引顺序原则：<b>最常用+区分度最高的放左边</b>；(a,b) 和 (b,a) 是两个不同索引。","索引不是越多越好：每个索引都是一棵 B+ 树，写入要同步维护所有树，且占空间。"],"questions":[{"q":"查询 WHERE gender=1 AND name=..., 最合理的联合索引是？","options":["(gender, name)","(name, gender)","分别建两个单列","(gender) 就够"],"answer":1,"explain":"gender 区分度极低放前面会先圈出一半数据；name 放左边先精确定位。若 (name, gender) 且只需 name 查询，还能兼做最左前缀。"},{"q":"以下最不适合建索引的列是？","options":["订单号（唯一）","用户手机号","性别字段","创建时间"],"answer":2,"explain":"性别只有两三个值，走索引过滤后仍剩近一半行，回表成本高于全表扫。低区分度列适合放进联合索引凑覆盖，不适合单建。"}]},{"day":41,"stage":"MySQL 事务","title":"事务与锁实战坑","points":["<b>死锁排查第一现场</b>：SHOW ENGINE INNODB STATUS 的 LATEST DETECTED DEADLOCK 段。","UPDATE/DELETE 即使没 WHERE 命中行也会加锁范围放大（RR 下可能锁全表扫描路径）——条件必须走索引。","SELECT ... FOR UPDATE 是当前读会加锁；普通 SELECT 是快照读不加锁——搞混就会\\"为什么我锁不住\\"。"],"questions":[{"q":"RR 级别下 UPDATE ... WHERE name=...（name 无索引），锁的范围是？","options":["只锁命中的行","几乎全表的所有行+间隙（扫过都锁）","不锁任何行","只锁表结构"],"answer":1,"explain":"无索引条件走全表扫，RR 当前读会把扫过的记录和间隙都加上 Next-Key 锁。给条件列加索引能把锁缩到目标行——这就是\\"行锁升级表锁感\\"的真相。"},{"q":"想防止\\"查不到就插入\\"的并发重复插入，可靠方案是？","options":["先 SELECT 再 INSERT","唯一索引 + 捕获 DuplicateKey 异常处理","加长事务","用 RC 隔离级别"],"answer":1,"explain":"\\"查了再插\\"存在时间窗口，并发必出问题。数据库唯一约束是最后一道防线，冲突后走更新/返回已有记录逻辑。"}]},{"day":42,"stage":"MySQL 日志","title":"三大日志坑","points":["redo log 是<b>物理日志</b>（某页改了什么）、循环写；binlog 是<b>逻辑日志</b>（语句/行变更）、追加写。","undo log 不只回滚：还是 MVCC 的版本链载体——别答\\"只用于回滚\\"。","两阶段提交顺序：redo prepare → 写 binlog → redo commit。少了它崩溃后主从可能不一致。"],"questions":[{"q":"崩溃恢复时使用的主要日志是？","options":["binlog","redo log（重放物理修改恢复到崩溃前状态）","slow log","error log"],"answer":1,"explain":"重启时 redo 重放保证已提交事务的修改不丢（D）；未提交的用 undo 回滚（A）。binlog 负责复制和按时间点恢复。"},{"q":"binlog 格式选 ROW 的最大好处是？","options":["日志量最小","主从数据一致性最可靠（记录行级前后镜像，不含不确定函数）","可读性最好","速度最快"],"answer":1,"explain":"STATEMENT 格式下 NOW()/UUID()/LIMIT 等在主从可能执行结果不同；ROW 记录实际变更行，安全但量大（配 binlog_row_image=MINIMAL 省空间）。"}]},{"day":43,"stage":"MySQL 优化","title":"慢 SQL 排查坑","points":["EXPLAIN 重点看四列：type（至少 range）、key（实际用的索引）、rows（预估扫描行数）、Extra（Using filesort/temporary 要警惕）。","深分页 LIMIT 1000000,10 的优化：游标法 WHERE id > last_id LIMIT 10，或延迟关联。","count(*) 大表慢是 MVCC 决定的（没有全局精确计数），别答\\"加索引\\"就完事。"],"questions":[{"q":"EXPLAIN 的 Extra 出现 Using filesort 表示？","options":["磁盘坏了","排序无法用索引完成，需要额外的排序步骤（内存/磁盘）","文件被锁定","用了全文索引"],"answer":1,"explain":"ORDER BY 列与索引顺序不一致时出现。优化：建符合排序的联合索引，或减少排序数据量。"},{"q":"延迟关联优化深分页的核心思路是？","options":["把表拆小","先用覆盖索引只查主键 id 分页，再用 id 回表取整行数据","加缓存","调大 OFFSET"],"answer":1,"explain":"SELECT * FROM t JOIN (SELECT id FROM t WHERE ... LIMIT 100000,10) tmp USING(id)——子查询走覆盖索引不回表，最后只回表 10 行。"}]},{"day":44,"stage":"MySQL 实战","title":"主从与高可用坑","points":["主从延迟的常见根因：从库单线程回放（5.7 前）/大事务/从库机器差/从库在跑重查询。","读写分离下\\"写后立即读\\"要读主库——框架方案：ShardingSphere 的强制路由/动态切换数据源。","半同步复制（semi-sync）：至少一个从库收到 binlog 才返回成功——可用性换一致性。"],"questions":[{"q":"用户改完头像刷新页面却显示旧头像（读写分离架构），最可能的原因与解法是？","options":["浏览器坏了；换浏览器","主从延迟：写后读走了从库；写后短窗口强制读主库","缓存永远无法解决","数据库坏了"],"answer":1,"explain":"复制异步有延迟。方案：关键读走主库、延迟双删缓存、或更新后前端短时间读主。"},{"q":"大事务对主从延迟的影响是？","options":["没有影响","主库执行 10 分钟的事务，binlog 传到从库还要再执行 10 分钟——延迟线性放大","只会影响内存","只影响磁盘"],"answer":1,"explain":"从库回放同样耗时。拆小事务（批量改分批提交）是治理主从延迟的第一刀。"}]},{"day":45,"stage":"Redis 数据结构","title":"Redis 数据类型实战坑","points":["存对象别用 JSON 大 String 覆盖写——用 Hash 做字段级更新，省带宽且避免并发覆盖。","Set 的 SDIFF/SINTER/SUNION 直接支持\\"共同关注/推荐差集\\"运算——别拉到 Java 里算。","INCR 是原子计数；想\\"计数+过期\\"要 EXPIRE 配合（注意 key 已存在时 EXPIRE 才生效）。"],"questions":[{"q":"实现\\"点赞用户列表 + 判断是否点过 + 点赞总数\\"，最合适的类型组合是？","options":["String 存 JSON","Set：SADD/SISMEMBER/SCARD 一套搞定","List 遍历判断","ZSet"],"answer":1,"explain":"Set 天然去重，SISMEMBER O(1) 判断，SCARD 计数，SINTER 还能求\\"共同点赞\\"。需求四连全兼容。"},{"q":"用 Redis 统计\\"今日独立访客 UV\\"（亿级），最省内存的方案是？","options":["Set 存全部 userId","HyperLogLog（PFADD/PFCOUNT，固定 12KB，误差 0.81%）","String 拼接","List"],"answer":1,"explain":"亿级 userId 用 Set 要几 GB，HLL 只要 12KB。允许 1% 内误差的统计场景（UV/PV）它就是标准答案。精确去重才用 Set/BitMap。"}]},{"day":46,"stage":"Redis 缓存","title":"缓存模式实战坑","points":["Cache Aside 标准姿势：<b>先更新库，再删缓存</b>（不是更新缓存）——删是懒加载语义，避免写多读少白算。","缓存空值防穿透要设<b>短过期</b>（如 60s），否则造过假数据后真数据也进不来。","布隆过滤器只能\\"一定不存在/可能存在\\"，<b>误判率与位数组大小和哈希函数个数相关</b>，不能删除元素（计数布隆可以）。"],"questions":[{"q":"为什么 Cache Aside 推荐\\"删除缓存\\"而不是\\"更新缓存\\"？","options":["更新更快","避免并发写导致缓存脏数据 + 写多读少场景白算成本","删除更安全不会失败","框架规定"],"answer":1,"explain":"两个并发写按不同顺序到缓存会产生永久脏数据；删除让下次读时按库的最新值重建——把一致性交给懒加载。"},{"q":"先删缓存再更新数据库的方案，并发下的漏洞是？","options":["没有漏洞","删除后、库更新前，读请求把旧值回填缓存——脏数据驻留到过期","数据库会崩溃","缓存会膨胀"],"answer":1,"explain":"经典时序：删缓存→读 miss→读库旧值→回填→更新库→缓存永远是旧值。所以推荐\\"先更库再删缓存\\"+延迟双删兜底。"}]},{"day":47,"stage":"Redis 高可用","title":"持久化与复制坑","points":["RDB 的 fork 在<b>大实例（10GB+）</b>上会卡主线程（页表复制）——这就是大实例偏用 AOF/混合的原因之一。","AOF everysec 不是\\"一秒必落盘\\"而是\\"最多丢一秒\\"；always 最安全但吞吐骤降。","主从复制 backlog（环形缓冲）太小，从库断线稍久就退化为全量重同步——调大 repl-backlog-size。"],"questions":[{"q":"生产 Redis 推荐的持久化配置是？","options":["只用 RDB","混合持久化：AOF 重写时先写 RDB 全量再追加增量（恢复快+丢失少）","只用 AOF always","关闭持久化"],"answer":1,"explain":"aof-use-rdb-preamble yes：文件头 RDB（载入快）+ 尾部增量 AOF（丢失少）。纯缓存场景可只 RDB。"},{"q":"从库重连后执行了全量重同步（而不是增量），最可能的原因是？","options":["从库磁盘坏了","断线期间写入太多，replication offset 已被 backlog 环形覆盖","主库重启过","网络太慢"],"answer":1,"explain":"增量复制要求从库的 offset 还在主库 backlog 里；写风暴会把旧 offset 冲掉。调大 backlog + 稳定网络避免全量风暴。"}]},{"day":48,"stage":"Redis 实战","title":"Redis 使用陷阱","points":["KEYS * 会阻塞单线程——生产用 <b>SCAN</b> 游标分批遍历。","大 key 删除用 <b>UNLINK</b>（异步）而不是 DEL；排查用 redis-cli --bigkeys。","SETNX 锁必须配<b>过期时间+唯一值</b>：无 TTL 死锁，无唯一值会误删别人的锁。"],"questions":[{"q":"Redis 分布式锁\\"误删\\"场景的正确修复是？","options":["加长过期时间到 1 小时","锁值存唯一标识，释放时 Lua 脚本\\"判断是自己的才删\\"","删除前 sleep 一秒","用 DELEX 命令"],"answer":1,"explain":"业务超时→锁过期→B 拿到锁→A 执行完 DEL 掉 B 的锁。Lua 原子\\"比对+删除\\"；根治用 Redisson 看门狗自动续期。"},{"q":"需要遍历上千万个 key 统计特征，正确的命令选择是？","options":["KEYS *","SCAN cursor MATCH ... COUNT 1000 循环游标","SMEMBERS 全部集合","反复 RANDOMKEY"],"answer":1,"explain":"SCAN 分批+不阻塞，返回新游标直到 0。KEYS 会卡住整个实例——生产事故经典来源。"}]},{"day":49,"stage":"并发深入","title":"AQS 与并发工具坑","points":["AQS 核心就是一个 <b>volatile state + CLH 等待队列</b>：获取失败的线程入队挂起，释放时唤醒后继。","CountDownLatch 是\\"等 N 件事完成\\"（一次性）；CyclicBarrier 是\\"N 个线程互相等\\"（可重用）。","Semaphore 控制并发数（限流）；Exchanger 两线程交换数据——场景别混。"],"questions":[{"q":"10 个线程各自算完子任务后，主线程汇总结果——用哪个最合适？","options":["Semaphore(1)","CountDownLatch(10)，主线程 await 等 countDown 到 0","CyclicBarrier(10)","synchronized"],"answer":1,"explain":"\\"一等多\\"用 CountDownLatch；\\"多互等\\"（每批都等齐再继续）才用 CyclicBarrier。"},{"q":"限制数据库连接池最多 20 个并发访问，最贴切的工具是？","options":["CountDownLatch(20)","Semaphore(20)：acquire/release 控制同时访问数","volatile","ThreadLocal"],"answer":1,"explain":"Semaphore 是\\"令牌桶\\"语义：拿不到令牌就阻塞，用完归还——连接池/限流的标准实现。"}]},{"day":50,"stage":"并发深入","title":"线程池调优坑","points":["线程数不是越大越快：CPU 密集 ≈ 核数+1；IO 密集 ≈ 核数 × (1 + 等待时间/计算时间)。","线程池参数要<b>有界队列+拒绝策略</b>：无界队列（如默认 LinkedBlockingQueue）会在堆积时 OOM。","禁止用 Executors.newFixedThreadPool——队列无界；newCachedThreadPool——线程数无界。要手动 new ThreadPoolExecutor。"],"questions":[{"q":"《阿里巴巴 Java 开发手册》禁止 Executors 创建线程池的根本原因是？","options":["语法过时","FixedThreadPool 队列无界会 OOM，CachedThreadPool 线程无界会耗尽资源","性能太差","不支持 lambda"],"answer":1,"explain":"手动 new ThreadPoolExecutor 显式指定核心数/队列上限/拒绝策略——把资源边界写死在代码里。"},{"q":"IO 密集型任务（接口调用平均等待 90ms，计算 10ms），8 核机器线程数建议约？","options":["8","约 8 × (1 + 90/10) = 80 左右，压测定参","1000","1"],"answer":1,"explain":"等待占 90% 时 CPU 大量空闲，多开线程填满等待期。公式只是起点，最终以压测吞吐/RT 曲线为准。"}]},{"day":51,"stage":"JVM 深入","title":"GC 实战坑","points":["GC 日志里的 \\"Full GC (Ergonomics)\\" / \\"Allocation Failure\\" 要能读懂来源：晋升过快/大对象/元空间不足。","停顿和吞吐不可兼得：Parallel 吞吐优先，CMS/G1/ZGC 停顿优先——选型看业务（批处理 vs 在线服务）。","OOM 不一定是堆：元空间（类加载器泄漏）、直接内存（NIO）、栈（无限递归）都会 OOM，报错信息不同。"],"questions":[{"q":"java.lang.OutOfMemoryError: Metaspace 的最常见原因是？","options":["堆太小","动态生成类过多且无法卸载（CGLIB 代理/热部署/反射滥用）","线程太多","缓存太大"],"answer":1,"explain":"Metaspace 存类元数据。每次代理都 new ClassLoader 或无缓存反射，类爆炸撑爆元空间——加参数治标，改代码才是治本。"},{"q":"线上 JVM 排查\\"GC 频繁但回收效果差\\"（Full GC 后老年代仍 90%+），优先怀疑？","options":["堆太小直接扩容","内存泄漏：老年代被活对象占满，dump 分析大对象来源","CPU 不足","磁盘慢"],"answer":1,"explain":"回收不掉=对象还活着=泄漏（缓存无界/ThreadLocal 未清理/连接未关）。jmap dump + MAT 看支配树定位持有链。"}]},{"day":52,"stage":"JVM 深入","title":"JVM 参数实战坑","points":["-Xms 和 -Xmx 设成一样：避免运行期堆动态伸缩带来的抖动。","OOM 时自动 dump：-XX:+HeapDumpOnOutOfMemoryError -XX:HeapDumpPath=...——线上排查救命参数。","-Xss 控制栈大小；递归过深的 StackOverflowError 调它治标，改算法治本。"],"questions":[{"q":"生产 JVM 推荐把 -Xms 与 -Xmx 设为相同值的原因是？","options":["显得专业","避免堆扩容/缩容时的 GC 抖动和内存 recommit 开销","节省磁盘","提高 CPU 主频"],"answer":1,"explain":"堆伸缩伴随 Full GC 与页分配。固定大小让行为可预测——容量规划做在发布前。"},{"q":"以下哪个参数组合是线上服务\\"必备三件套\\"？","options":["-Xmx、HeapDumpOnOutOfMemoryError、GC 日志","-verbose、-Dfile.encoding、-Xss","-agentlib、-Xshare、-Xverify","随意配置"],"answer":0,"explain":"容量上限 + 事故现场自动留证 + GC 行为可观测——出问题时有数据可查，而不是靠猜。"}]},{"day":53,"stage":"Spring 深入","title":"Spring 原理坑","points":["Bean 生命周期口诀：实例化 → 属性注入 → Aware 回调 → BeanPostProcessor 前置 → <b>初始化方法</b> → 后置 → 使用 → 销毁。","AOP 失效场景同事务：this 调用、方法非 public、final 方法（CGLIB 无法重写）。","循环依赖三级缓存只解决<b>单例 + setter/字段注入</b>；构造器注入无法解决（对象还没造出来就互相要）。"],"questions":[{"q":"@PostConstruct 注解方法的执行时机是？","options":["类加载时","属性注入完成后、Bean 对外可用前的初始化阶段","容器关闭时","每次调用时"],"answer":1,"explain":"位于初始化阶段：依赖注入完毕 → @PostConstruct → afterPropertiesSet → init-method。做\\"依赖就绪后的检查/预热\\"正合适。"},{"q":"Spring Boot 2.6+ 默认禁止循环依赖的原因是？","options":["性能问题","循环依赖通常是设计缺陷的信号（职责不清），强制你重构而不是靠容器兜底","内存问题","兼容 JDK17"],"answer":1,"explain":"官方立场：循环依赖是坏味道。开启 spring.main.allow-circular-references=true 只是逃生门，正解是拆分职责/引入中间层。"}]},{"day":54,"stage":"Spring 深入","title":"Spring Boot 自动配置坑","points":["自动配置原理链：@EnableAutoConfiguration → 读取 META-INF/spring/...AutoConfiguration.imports → @Conditional 系列按条件装配。","starter 的意义：依赖聚合 + 自动配置，让\\"引入即用\\"；自定义 starter 也是这两件套。","配置优先级：命令行 > 环境变量 > application-{profile} > application.yml——排配置问题先想优先级。"],"questions":[{"q":"@ConditionalOnClass 的作用是？","options":["类存在才装配该自动配置（classpath 检测）","方法存在才执行","配置了才生效","永远生效"],"answer":1,"explain":"这是 starter\\"引了 jar 就自动生效、没引就不报错\\"的关键——按 classpath 有无某类决定装配。"},{"q":"同一配置项在 application.yml 和命令行 --key=val 同时存在，生效的是？","options":["yml","命令行（优先级最高）","随机","报错"],"answer":1,"explain":"优先级链的顶端是命令行参数，常用于不改文件临时覆盖配置（如 --server.port=8081）。"}]},{"day":55,"stage":"分布式","title":"分布式 ID 与锁坑","points":["UUID 做主键的问题：无序页分裂 + 长；雪花算法 = 时间戳+机器id+序列，趋势递增但<b>依赖时钟</b>（回拨要处理）。","ZK 锁：临时顺序节点 + 监听前驱——公平锁语义，CP 代价是性能低于 Redis。","Redis 锁是 AP（主从切换可能丢锁）；RedLock 争议大；金融场景用 DB 唯一约束+乐观锁兜底。"],"questions":[{"q":"雪花算法时钟回拨的处理思路不包括？","options":["等待追上后再发号","用上次时间戳兜底/报警拒发","记录回拨区间跳过","把机器时间改快"],"answer":3,"explain":"改时间只会更乱。主流方案：检测回拨→小回拨等待/大回拨告警拒绝服务/备用位扩展。"},{"q":"Redis 主从切换导致锁丢失（客户端 A 在旧主加的锁没同步到新主），业界讨论的方案是？","options":["RedLock 多实例多数派加锁（有争议，代价高）","删掉所有锁","把过期时间调大","换 MySQL"],"answer":0,"explain":"RedLock 向 N 个独立实例同时加锁、半数以上成功才算持有——但 Martin Kleppmann 质疑其时钟假设，实践中常改用\\"fencing token + 资源端幂等\\"。"}]},{"day":56,"stage":"分布式","title":"限流算法坑","points":["固定窗口计数器的缺陷：<b>窗口边界双倍突刺</b>（前窗末+后窗初合计可达 2 倍阈值）。","滑动窗口把窗口切小格解决突刺；漏桶恒定速率\\"整流\\"；令牌桶允许突发（预存令牌）。","单机限流用 Guava RateLimiter；分布式限流用 Redis+Lua（原子校验扣减）或 Sentinel 集群流控。"],"questions":[{"q":"允许\\"突发流量、空闲攒额度\\"的限流算法是？","options":["固定窗口","漏桶","令牌桶","计数器"],"answer":2,"explain":"令牌桶按速率放令牌、桶有容量：闲时攒、忙时批量消费。漏桶则是恒定流出，把突发整形成平滑流。"},{"q":"分布式限流用 Redis 实现\\"每秒 100 次\\"，为什么要用 Lua？","options":["Lua 更快","GET+判断+INCR+EXPIRE 多步操作需要原子执行，否则并发下计数错乱","Redis 只支持 Lua","省内存"],"answer":1,"explain":"多命令间会被其他客户端插入导致竞态。Lua 脚本在 Redis 单线程内原子执行——判断与扣减不可分割。"}]},{"day":57,"stage":"消息队列","title":"MQ 进阶坑","points":["消息堆积百万级的处理：先扩消费者（要能水平扩）→ 临时\\"搬运\\"转储 → 修复消费逻辑 → 追平后清理。","顺序消息：Kafka 靠同 key 进同分区（分区内有序）；RocketMQ 靠 MessageQueueSelector + 单线程消费。","延迟消息：RocketMQ 自带延迟级别/定时精度；Kafka 要自己造（时间轮+暂停分区）或用延迟主题。"],"questions":[{"q":"Kafka 保证\\"同一订单的消息被顺序消费\\"的正确做法是？","options":["全局一个分区","按订单 id 作为消息 key（同 key 进同分区，分区内 FIFO）","消费者加锁","提高 acks 参数"],"answer":1,"explain":"Kafka 只保证分区内有序。把相关消息路由到同一分区是标准做法——注意分区数扩容会打乱 key 映射，要提前规划。"},{"q":"消费端处理逻辑有 bug 导致持续堆积，第一个动作是？","options":["重启 MQ","止血：修复或回滚消费逻辑；扩容消费者加速消化，必要时临时转储降级","清空队列","换 MQ"],"answer":1,"explain":"先止损再治理。消费者组扩容受分区数上限约束（消费者数≤分区数），不够就临时搬家到新主题多分区并行处理。"}]},{"day":58,"stage":"系统设计","title":"短链/点赞/排行榜设计套路","points":["短链生成：发号器（自增/雪花）+ 62 进制编码最稳；哈希+冲突重试也可；跳转 302（可统计）vs 301（缓存住）。","排行榜 = ZSet：ZINCRBY 加分、ZREVRANGE 取榜、ZREVRANK 查名次——O(log n) 全搞定。","点赞 = Set/HLL；计数 = INCR；防刷 = 限流 + 唯一约束。基础类型组合拳要熟。"],"questions":[{"q":"短链服务选 302 而不是 301 重定向的主要原因是？","options":["302 更快","302 每次都经过服务端，可以统计点击、支持随时改目标地址","301 不安全","浏览器只支持 302"],"answer":1,"explain":"301 会被浏览器永久缓存，改指向失效、统计丢失。短链平台要数据就要 302（牺牲一点跳转性能）。"},{"q":"游戏积分榜要求\\"实时查我排第几 + 前 100 名\\"，最适合的 Redis 方案是？","options":["List 定时排序","ZSet：分数做 score，ZREVRANK/ZREVRANGE 毫秒级返回","Hash 扫描计算","MySQL ORDER BY"],"answer":1,"explain":"ZSet 的排名查询是内置能力：ZREVRANGE top100、ZREVRANK 个人名次，更新用 ZINCRBY。百万级用户依然 O(log n)。"}]},{"day":59,"stage":"系统设计","title":"缓存/DB 一致性进阶","points":["强一致做不到就<b>收敛</b>：延迟双删、binlog 订阅（Canal）异步删、过期时间兜底——三层防线。","读多写少用 Cache Aside；写多读少考虑\\"写后短 TTL\\"或直接读库；一致性敏感的（余额）直接读主库。","分布式事务日常首选：<b>本地消息表/MQ 事务消息</b>（最终一致）；TCC/Seata AT 留给强一致刚需。"],"questions":[{"q":"Canal 订阅 binlog 删缓存的方案优势是？","options":["速度最快","与业务代码解耦：数据变更由 binlog 驱动统一失效，不侵入业务","省数据库","免部署"],"answer":1,"explain":"业务只管写库，缓存失效由独立的 binlog 消费端处理——漏删率低、新增表零成本接入。代价是多一个组件要运维。"},{"q":"订单超时未支付自动取消，最适合的实现是？","options":["定时任务每秒扫全表","RocketMQ 延迟消息/时间轮：支付创建时发 30 分钟延迟消息，到期检查状态","用户手动取消","数据库触发器"],"answer":1,"explain":"扫表在订单量大时是灾难。延迟消息精确到单订单、无需扫表；到期待检查时用状态机防并发误取消（已支付就忽略）。"}]},{"day":60,"stage":"综合冲刺","title":"面试临场综合坑","points":["场景题万能框架：<b>澄清需求 → 估算量级 → 分层设计（接入/服务/数据）→ 关键点深挖 → 权衡取舍</b>。","答不上来时的降级话术：\\"这个具体数字我记不准，但思路是……\\"——展示推理路径永远比硬编强。","反问环节问\\"这个岗位当前最大的技术挑战\\"——既是信息收集也是展示态度。"],"questions":[{"q":"面试官出\\"设计一个日活千万的签到系统\\"，第一步应该做什么？","options":["直接写 Redis 方案","澄清需求边界：签到粒度/要不要补签/统计什么/实时性要求，再估算存储量级","问面试官答案","从数据库建表开始"],"answer":1,"explain":"不澄清就设计=闭卷乱写。日活千万×BitMap 也就 MB 级，需求不同方案天差地别——先对齐再动手是工程师素养。"},{"q":"签到场景\\"记录某用户一年 365 天是否签到\\"最省内存的存储是？","options":["365 行记录表","BitMap/BitSet：1 个 int 存 31 天，一年 12 个 int","JSON 数组","文本拼接"],"answer":1,"explain":"一天一位：365 bit ≈ 46 字节。Redis BITCOUNT 直接算连续签到，BITOP 做交集（都签过的天）——位运算的降维打击。"}]},{"day":61,"stage":"并发深入","title":"volatile 与 JMM 坑","points":["volatile 只保证可见性与有序性，<b>不保证原子性</b>——volatile int count + count++ 照样丢更新。","DCL 单例必须配 volatile：防止\\"分配→初始化→赋引用\\"重排，别的线程拿到半初始化对象。","happens-before 的\\"程序顺序规则\\"不是\\"指令不重排\\"，而是\\"单线程语义下结果一致\\"——别背反了。","ThreadLocal 用完不 remove：线程池线程复用 → 下一个请求读到上个请求的值（串号事故）+ value 泄漏。"],"questions":[{"q":"volatile int count = 0，10 个线程各执行 1000 次 count++，最终结果？","options":["一定是 10000","一定小于等于 10000 且不确定","一定大于 10000","编译错误"],"answer":1,"explain":"count++ 是读-加-写三步，volatile 只保证读到最新值，不保证三步连续执行。并发丢失更新，结果 ≤ 期望值。要原子用 AtomicInteger。"},{"q":"DCL 单例中 instance 声明为 volatile 的原因是？","options":["提高读取速度","禁止 new 对象的指令重排，避免其他线程拿到未初始化完的对象","保证线程互斥","可以不加"],"answer":1,"explain":"new 不是原子操作：①分配内存 ②初始化 ③instance=引用。②③可能重排——线程 A 执行到③未②时，线程 B 判非空直接返回半成品。volatile 禁止该重排。"}]},{"day":62,"stage":"并发深入","title":"线程池参数坑","points":["<b>Executors 直接创建是生产红线</b>：newFixedThreadPool/newSingleThreadExecutor 无界队列 OOM；newCachedThreadPool 线程数上限 Integer.MAX_VALUE 线程爆炸。","线程池异常默认吞掉：任务抛异常后 worker 静默死亡重建，日志什么都看不见——必须 try-catch 包任务或用 Future.get() 收割。","核心线程默认不回收（除非 allowCoreThreadTimeOut(true)）；池在 shutdown 前一直占着资源。","ThreadLocal + 线程池 = 复用陷阱：每次任务开头 set、结尾 remove，或用阿里 TransmittableThreadLocal。"],"questions":[{"q":"为什么生产环境禁止使用 Executors.newFixedThreadPool？","options":["性能差","LinkedBlockingQueue 无界，任务堆积会 OOM","创建太慢","不支持超时"],"answer":1,"explain":"队列无界 = 任务只进不出，堆积到内存耗尽。规范做法：ThreadPoolExecutor 手动建，队列给有界（如 1000）+ 拒绝策略明确。"},{"q":"线程池里 submit 的任务抛了 NPE，最可能的现象是？","options":["JVM 崩溃","异常被 Future 吞着，没有任何日志，任务\\"静默失败\\"","线程池自动重启任务","其他任务失败"],"answer":1,"explain":"submit 包装成 Future，异常存进 Future 等人来 get——没人 get 就永远没人知道。解决方案：execute + try-catch、统一包装任务类记日志、或 afterExecute 钩子。"}]},{"day":63,"stage":"并发深入","title":"锁使用坑","points":["锁的对象选错：<code>synchronized(this)</code> 在多实例 Bean 下锁不住；锁 String/int 常量（字符串字面量、Integer 缓存对象）会锁到全局共享对象，引发无关代码互斥。","可重入锁忘记释放：ReentrantLock 必须 try/finally 里 unlock()——synchronized 自动释放，手写锁没有这个保险。","锁粒度太粗（整个方法）→ 并发度骤降；事务里加锁 → 锁在事务提交前就释放，别的线程读到旧数据（锁范围与事务范围不一致）。","读多写少用读写锁/StampedLock 优化；只读对象用不可变类（record/String）天然线程安全。"],"questions":[{"q":"synchronized(new Object()) 锁住代码块，效果是？","options":["正常互斥","等于没锁：每次 new 的对象都不同，锁对象不唯一","编译错误","锁全局"],"answer":1,"explain":"锁的本质是\\"多个线程抢同一把锁对象\\"。每次 new 新对象，各线程锁各自的对象，互不冲突——锁形同虚设。锁对象必须是共享唯一实例。"},{"q":"事务方法里 synchronized 锁住核心段，为什么仍可能超卖？","options":["synchronized 不安全","锁释放发生在事务提交之前：另一个线程拿到锁时读到的还是未提交前的旧库存","数据库问题","CPU 太快"],"answer":1,"explain":"顺序是：加锁 → 读库存 → 扣减 → 方法结束释放锁 → 事务才提交。第二个线程拿锁时读到的是\\"未提交的旧值\\"。方案：锁范围包住事务（外层加锁调内层事务方法）、或 DB 条件更新/乐观锁兜底。"}]},{"day":64,"stage":"JVM 实战坑","title":"OOM 与内存泄漏坑","points":["堆 dump 时机：OOM 后再抓可能晚了大对象已被回收——启动加 <code>-XX:+HeapDumpOnOutOfMemoryError</code> 让 JVM 在崩溃瞬间留证据。","静态集合只增不减是泄漏之王：static Map 当缓存不设上限 → Full GC 越来越频繁直到 OOM。","连接池/流/HttpClient 不 close：连接对象不回收 → 既是资源泄漏也是内存泄漏。","Metaspace OOM：CGLib/反射大量动态生成类不卸载（常见于频繁重启 Spring 上下文的测试代码）。"],"questions":[{"q":"线上系统 Full GC 频率从每天 1 次涨到每 5 分钟 1 次，最该先看什么？","options":["直接调大堆","dump 分析老年代里占比最大的对象是谁、被谁引用（MAT 支配树）","升级 JDK","换 GC 器"],"answer":1,"explain":"频率变化说明有东西在缓慢堆积（泄漏）或流量变化。盲目调大堆只是延缓。MAT 看支配树定位\\"谁持有\\"——常见嫌疑：静态缓存、ThreadLocal、监听器未注销。"},{"q":"CPU 100% 但 jstack 里最忙的线程是 \\"GC task thread\\"，说明？","options":["CPU 被业务计算占满","GC 在疯狂工作——大概率是内存问题（频繁 Full GC）","线程死锁","网络 IO 问题"],"answer":1,"explain":"GC 线程吃满 CPU = 老年代反复回收不下来 = 堆里塞满活对象或泄漏。排查方向立刻转向内存：jstat -gcutil 看 Old 区占比与回收后是否下降（不降 = 泄漏）。"}]},{"day":65,"stage":"JVM 实战坑","title":"GC 调优误区","points":["误区：堆越大越好 → 大堆 = Full GC 停顿更长 + 容器内存超限 OOMKilled；8G 堆的 Full GC 可能秒级。","误区：MaxGCPauseMillis 设得越小越好 → G1 为达标会缩小年轻代、提高 GC 频率，吞吐反而崩。","System.gc() 会触发 Full GC：用 -XX:+DisableExplicitGC 关掉（但 DirectByteBuffer 的堆外回收依赖它，需配 -XX:+ExplicitGCInvokesConcurrent 并发触发）。","没看 GC 日志就调参 = 算命。先 -Xlog:gc* / gceasy.io 分析，再动手。"],"questions":[{"q":"容器限制 4G 内存，JVM 设 -Xmx4g，结果被 OOMKilled，原因是？","options":["Xmx 设小了","堆外还有元空间、线程栈、DirectMemory——堆吃满 4G 后其他区域直接超容器配额","K8s 配置错误","GC 器问题"],"answer":1,"explain":"容器只认 cgroup 总量：堆 + Metaspace + 线程数×Xss + 堆外 ≈ 4G 必超。规范：堆 ≈ 容器内存 70%（或 MaxRAMPercentage=75），其余留给非堆。"},{"q":"-XX:MaxGCPauseMillis=10 这种激进目标通常导致？","options":["停顿真的变 10ms 且无副作用","GC 频率暴增、吞吐下降，甚至 young 区被压得过小","JVM 报错","没有影响"],"answer":1,"explain":"G1 的停顿目标是通过调节年轻代大小实现的——目标太苛刻 → 年轻代被缩到很小 → Minor GC 秒触发。一般 200ms 是合理值。"}]},{"day":66,"stage":"Spring 实战坑","title":"依赖注入与 Bean 坑","points":["字段注入的坑：无法 final、隐藏依赖（构造器看不出需要什么）、脱离容器无法单测——改构造器注入。","循环依赖：Spring Boot 2.6+ 默认直接启动报错——别再依赖三级缓存\\"救你\\"，出现循环依赖先反思设计。","@Configuration 类里的 @Bean 方法互调走 CGLib 代理保证单例；改成 @Component + @Lazy 后互调就不再保证。","@Value 读不到值：占位符拼错 / 配置文件没加载 / 用在 static 字段上（Spring 不注入 static）。"],"questions":[{"q":"@Autowired 标在 static 字段上会怎样？","options":["正常注入","注入的是 null：Spring 注入发生在 Bean 实例上，static 字段属于类不归容器管","启动报错","自动转构造注入"],"answer":1,"explain":"Spring 依赖注入基于 Bean 实例，static 属性先于实例存在且被所有实例共享，容器不注入（不报错但值为 null，最阴险）。需要时用 @PostConstruct 里从实例字段转存。"},{"q":"构造器注入相对字段注入的最大优势是？","options":["代码更短","依赖不可变（final）+ 依赖显式化 + 容器外可 new 出来直接单测，且启动期即暴露循环依赖","性能更好","支持更多注解"],"answer":1,"explain":"字段注入的类离开 Spring 容器无法构造（字段全是 null），单测只能靠反射。构造器注入 final 保证状态安全、new 出来即完整。Spring 官方也推荐构造器注入。"}]},{"day":67,"stage":"Spring 实战坑","title":"事务与 AOP 生效坑","points":["事务失效全家桶：自调用（this 绕过代理）、方法非 public、异常被 catch 吞、抛 checked 异常（默认只回滚 RuntimeException）、多线程（事务绑定 ThreadLocal）、MyISAM 不支持事务。","@Transactional 标在 private 方法上不生效——CGLib 无法覆写 private，代理拦不到。","AOP 切面在 this 调用时同样失效——同根因：绕过代理对象。","@Async 方法里抛异常，调用方感知不到——异常进了 AsyncUncaughtExceptionHandler。"],"questions":[{"q":"同类中方法 A（无事务）调用方法 B（@Transactional），B 的事务？","options":["正常生效","不生效：this 调用走原始对象绕过了事务代理","部分生效","编译错误"],"answer":1,"explain":"事务是 AOP 代理实现的。A 里 this.b() 用的是原始对象引用。解法：①注入自身代理（ObjectProvider）②AopContext.currentProxy()（开 exposeProxy）③把 B 挪到别的 Bean。"},{"q":"@Transactional(rollbackFor = Exception.class) 的存在意义是？","options":["加快事务","默认只对 RuntimeException/Error 回滚，checked 异常默认提交——显式声明让 IOException 等也回滚","开启只读","改变隔离级别"],"answer":1,"explain":"Spring 默认回滚策略继承自 EJB：受检异常被视为\\"业务可预期\\"默认提交。大多数业务希望任何异常都回滚——所以规范模板里总带 rollbackFor = Exception.class。"}]},{"day":68,"stage":"MySQL 实战坑","title":"索引与执行计划坑","points":["联合索引 (a,b) 查 WHERE b = 1 完全走不到索引——最左前缀是硬约束，不是\\"可能走\\"。","隐式类型转换使索引失效：phone 是 varchar，WHERE phone = 13800000000（数字）→ MySQL 给列加函数转换 → 索引废。","区分度太低的列（如性别）建索引无意义：优化器算出回表成本超过全表扫描，直接不走。","EXPLAIN 必看四列：type（至少 range，ALL 最差）、key（实际用的索引）、rows（预估扫描行数）、Extra（Using filesort/temporary 是坏信号）。"],"questions":[{"q":"status 是 tinyint，索引建好了，但 WHERE status = 1 仍全表扫描，最可能因为？","options":["索引损坏","status 只有几个值（如 0/1/2），90% 数据都是 1，优化器判断全表扫描更快","MySQL 版本太低","需要重启"],"answer":1,"explain":"索引的价值在缩小范围。区分度低（基数/总行数极小）时，回表成本 > 全表扫描。这类\\"状态列\\"正确做法是联合进复合索引或改表设计。"},{"q":"EXPLAIN 输出 Extra 出现 \\"Using filesort\\"，含义是？","options":["磁盘坏了","排序无法利用索引完成，需要额外排序步骤（内存或磁盘）","正在备份","SQL 写错"],"answer":1,"explain":"filesort 不是\\"文件排序失败\\"，是\\"排序没吃到索引红利\\"。优化方向：让 ORDER BY 列与 WHERE 列组合成联合索引对齐排序顺序。"}]},{"day":69,"stage":"MySQL 实战坑","title":"事务与锁坑","points":["RR 隔离级别的幻读只\\"半防\\"：快照读靠 MVCC 防幻读，当前读（for update）靠间隙锁——混用时照样出幻读。","update 没走索引 = 锁全表（所有行+间隙）：WHERE 条件里的列必须有索引，否则行锁升级为事实上的表锁。","死锁高发姿势：批量更新顺序不一致（A 先更 1 后更 2，B 先更 2 后更 1）→ 统一按主键排序更新。","innodb_lock_wait_timeout 默认 50 秒：锁等待超时报错但不自动重试——应用层要有重试/熔断。"],"questions":[{"q":"update user set name=''x'' where phone = ''138xxx'' 导致大量行锁，最可能的原因是？","options":["行数太多必然锁全表","phone 列没有索引，InnoDB 无法定位具体行，锁住所有扫描过的行（全表）","隔离级别太高","字段太长"],"answer":1,"explain":"InnoDB 行锁锁的是索引项。无索引 → 全表扫描 → 每行都锁。线上规范：update/delete 的 WHERE 条件列必须走索引，CodeReview 必查。"},{"q":"RR 级别下，事务 A 两次普通 select（快照读）结果一致，期间 B 插入并提交了新行。A 第三次执行 select ... for update 会？","options":["结果仍一致","读到 B 插入的新行（幻读出现）：for update 是当前读，读最新已提交数据","报错","死锁"],"answer":1,"explain":"MVCC 只保护快照读。当前读绕过版本链读最新版本——若 B 的插入发生在间隙锁未覆盖的时间窗，幻读就出现了。这就是\\"RR 半防幻读\\"的含义。"}]},{"day":70,"stage":"Redis 实战坑","title":"缓存一致性坑","points":["先删缓存再更新库：删除后、更新前有读请求把<b>旧值</b>填回缓存 → 长期脏。标准姿势是\\"先更新库，再删缓存\\"。","\\"先更新库再删缓存\\"也有极小脏窗口（读比写慢的罕见场景），配合过期时间兜底。","删除缓存失败：重试队列 + binlog 订阅（Canal）异步删除双保险。","延迟双删：更新库 → 删缓存 → 睡 N 毫秒 → 再删一次，覆盖\\"读旧值回填\\"窗口。"],"questions":[{"q":"为什么推荐\\"先更新数据库，再删除缓存\\"而不是反向？","options":["顺序无所谓","反向（先删缓存）在删除与更新之间，读请求会把旧值重新写入缓存，脏数据长期存在；正向的脏读窗口极小且有超时兜底","缓存更新更慢","反向会报错"],"answer":1,"explain":"反向的脏窗口 = 写库耗时（几十 ms，期间任何读都回填旧值且不过期）；正向的脏窗口 = 一次读比一次写慢的罕见场景。概率差几个数量级。"},{"q":"删除缓存操作在 Redis 网络闪断时失败了，可靠的补救方案是？","options":["不管它，等过期","将失败的 key 写入消息队列异步重试；或用 Canal 订阅 binlog 统一驱动删除（彻底解耦）","重启应用","全量刷新缓存"],"answer":1,"explain":"同步重试可能继续失败且阻塞主流程。MQ 异步重试有界重试；Canal 方案业务零侵入，是中大型系统标配。"}]},{"day":71,"stage":"Redis 实战坑","title":"Redis 使用姿势坑","points":["禁用 KEYS *（O(N) 阻塞主线程）→ 用 SCAN 游标分批；同理避免超大集合的 HGETALL/SMEMBERS。","大 key（value > 10KB 或集合百万级）：删除时阻塞主线程 → 用 UNLINK（异步删除）替代 DEL。","SETNX 分布式锁没设过期时间：持锁进程崩溃 → 锁永久存在 → 全系统卡死。SET key val NX EX 30 必须原子一步。","缓存 value 存整个对象 JSON：字段变更后反序列化不兼容 → 版本化 schema 或只存必要字段。"],"questions":[{"q":"线上 Redis 单线程 CPU 突然打满，QPS 不高，最可能的原因是？","options":["内存不足","执行了 KEYS * / 删除大 key / 全量 HGETALL 等 O(N) 慢命令阻塞主线程","网络抖动","持久化损坏"],"answer":1,"explain":"Redis 单线程执行命令，一条慢命令拖住所有请求（其他命令排队）。排查：SLOWLOG GET 看慢命令记录；治理：SCAN 替代 KEYS、UNLINK 替代 DEL、大 key 拆分。"},{"q":"分布式锁还没执行完锁就过期了，另一个进程拿到锁——正确的姿势是？","options":["过期时间设长到 1 小时","看门狗自动续期（Redisson 默认 30s 每 10s 续）+ value 存唯一 id，释放用 Lua 校验后再删","不用过期时间","加数据库锁"],"answer":1,"explain":"过期时间设长只是降低概率、死锁风险上升。正确组合：自动续期保证\\"干活期间锁不过期\\"，唯一 id + Lua 原子释放保证\\"不删别人的锁\\"。"}]},{"day":72,"stage":"网络实战坑","title":"HTTP 与接口联调坑","points":["GET 带 body 部分网关/客户端会丢弃或报错——查询参数放 query string；POST 的 body 才是标准位置。","Content-Type 不匹配：后端 @RequestBody 要 JSON，前端发 form-data → 415；POST 表单没设 multipart → 文件变二进制乱码。","cookie 跨域：fetch/axios 跨域默认不带 cookie，需 withCredentials + 服务端 CORS 回显具体 origin + Allow-Credentials（此时不能用 *）。","PUT/DELETE 被老网关/WAF 拦截 → RESTful 落地前先确认链路支持。"],"questions":[{"q":"CORS 配置 Access-Control-Allow-Origin: * 且 allowCredentials=true，浏览器行为是？","options":["正常跨域","报错拒绝：credentials 模式下 origin 不能是通配符，必须回显具体域名","只拦截 POST","自动转换域名"],"answer":1,"explain":"带 cookie 的跨域是高敏场景，规范强制精确 origin。这是联调期最高频的报错之一。"},{"q":"前端 axios post JSON，后端 400 且参数全 null，先检查什么？","options":["数据库","请求头 Content-Type 是否为 application/json，后端是否用 @RequestBody","JVM 内存","URL 长度"],"answer":1,"explain":"@RequestBody 只解析 JSON 且要求 Content-Type 匹配；form 提交要用 @RequestParam/表单对象。前后端\\"各说各话\\"是联调第一坑。"}]},{"day":73,"stage":"Linux 运维坑","title":"命令与权限坑","points":["rm -rf 变量为空等于核弹：<code>rm -rf $DIR/</code> 当 DIR 未定义时变成 <code>rm -rf /</code>——脚本必须判空 + 绝对路径 + 禁 root 直接跑。","kill -9 慎用：进程没有机会做清理（刷缓冲/释放锁/优雅下线）——先 kill -15（SIGTERM）等几秒再考虑强杀。","chown/chmod -R 误伤系统目录 → 权限错乱到连 ssh 都进不去，只能重装。","df 看磁盘满了但 du 找不到大文件：进程还握着已删除文件的句柄 → lsof | grep deleted 找到进程重启释放。"],"questions":[{"q":"df -h 显示磁盘 100%，但 du 加起来远小于磁盘容量，最可能因为？","options":["du 统计错误","有进程持有已删除文件（deleted 句柄），空间未真正释放，重启对应进程即可","磁盘坏了","文件系统只读"],"answer":1,"explain":"文件删除只是断开目录项，inode 与数据在引用归零时才释放。日志被 rm 但应用还在写 → 空间一直占用。这也是\\"清日志用 truncate 而不是 rm\\"的原因。"},{"q":"为什么线上服务优雅停机要用 kill -15 而不是 kill -9？","options":["-9 权限不够","-15 发送 SIGTERM 让进程有机会：停止接新请求 → 处理完存量 → 释放资源；-9 直接终止连注册中心注销都做不了","速度一样","-9 更安全"],"answer":1,"explain":"-9 = SIGKILL 内核直接回收，进程无感知。后果：注册中心残留死实例、MQ 消息处理一半、文件锁未释放。先 -15 等 grace period，再 -9 兜底。"}]},{"day":74,"stage":"分布式实战坑","title":"分布式锁与幂等坑","points":["分布式锁 value 不放唯一标识：A 超时后 B 拿到锁，A 醒来直接 DEL → 删掉了 B 的锁。value=UUID，释放用 Lua\\"比对+删除\\"。","锁粒度错：锁整个方法 vs 锁业务键（如 orderId）——前者吞吐悬崖，后者才是正确姿势。","幂等只做前端防抖不做后端兜底 = 等事故：网络重试永远存在，后端唯一索引/状态机才是最终防线。","MQ 幂等消费：消费成功但 ack 丢失 → broker 重发；消费前查去重表必须做。"],"questions":[{"q":"分布式锁的 value 为什么要放唯一标识？","options":["性能更好","防止误删他人的锁：A 锁超时被 B 抢走，A 恢复后只能删\\"还是自己 uuid 的锁\\"","方便日志","加密要求"],"answer":1,"explain":"释放锁必须是 Lua 原子操作：GET 比对 value 是自己的才 DEL。否则出现\\"删掉别人的锁 → 第三个进程又拿到锁\\"的连环事故。"},{"q":"MQ 消费者处理完消息后 ack 网络失败，broker 重发同一条消息，业务侧的正确姿势是？","options":["禁止 broker 重发","消费逻辑天然幂等：业务唯一键约束/去重表先查后做，重复消息无副作用","换一个 MQ","关掉网络"],"answer":1,"explain":"至少一次投递是 MQ 的默认承诺，重复不可避免。幂等三板斧：唯一索引（最硬）、去重表（Redis setnx+DB 兜底）、状态机更新。"}]},{"day":75,"stage":"设计题坑","title":"秒杀场景设计坑","points":["只在 DB 扣库存：秒杀瞬间全打 DB → 挂。正确分层：前端防抖 → 网关限流 → Redis 预扣（Lua 原子）→ MQ 异步落库。","Redis 预扣与 DB 扣减不一致：预扣成功但落库失败要回补库存（本地消息表/事务消息保证最终一致）。","超卖兜底：DB 层 <code>UPDATE stock SET n=n-1 WHERE id=? AND n>0</code> 条件更新——无论上层怎么漏，DB 是最后防线。","黄牛刷子：设备指纹+限流+风控名单；URL 提前暴露 → 动态 URL/加密 token。"],"questions":[{"q":"秒杀系统中 Redis 预扣库存的 Lua 脚本解决的核心问题是？","options":["加密","原子性：查询库存与扣减在并发下必须不可分割，否则仍超卖","持久化","限流"],"answer":1,"explain":"GET 再 SET 两步之间有并发窗口（都读到 1 都扣成功）。Lua 在 Redis 单线程内原子执行\\"判断+扣减\\"，这是防超卖的第一道墙。"},{"q":"秒杀前把商品详情页静态化放 CDN，目的是？","options":["好看","把 99% 的浏览流量挡在源站之外，只有下单请求进入业务系统——削减入口流量","利于 SEO","省 CDN 费"],"answer":1,"explain":"秒杀流量模型：浏览:下单 ≈ 100:1。静态化 + 按钮置灰防重复点击，是\\"漏斗最上层\\"的削峰。"}]},{"day":76,"stage":"设计题坑","title":"订单与支付坑","points":["订单号不能用自增（暴露量级+可遍历）——时间戳+机器+序列或雪花，且趋势递增利于 InnoDB 写入。","支付回调必做：验签（防伪造）→ 幂等（同笔多次回调只处理一次）→ 状态机流转（只允许合法状态迁移）→ 主动查单兜底（回调会丢）。","金额用分存 int：浮点 double 存金额有精度灾难（0.1+0.2≠0.3），BigDecimal 也要指定 scale 与 RoundingMode。","退款与支付解耦：退款单独立建表走异步流程，失败重试+人工介入队列。"],"questions":[{"q":"支付接口返回成功但回调通知丢失，订单永远停在\\"待支付\\"，兜底机制是？","options":["等用户重付","主动查单：定时任务对超时未回调的订单调用支付平台查单接口对账修正","数据库手动改","让用户截图"],"answer":1,"explain":"网络通知不承诺必达，正规支付平台都提供查单 API。生产标配：回调（实时）+ 查单（兜底）+ 对账（T+1 终极兜底）三层。"},{"q":"订单金额字段为什么禁止使用 float/double？","options":["占用空间大","IEEE754 二进制无法精确表示 0.1 等十进制小数，累加产生舍入误差，对账差一分钱就是事故","运算慢","MySQL 不支持"],"answer":1,"explain":"0.1+0.2=0.30000000000000004。方案：整数分（bigint）、DECIMAL(10,2)、Java 层 BigDecimal（字符串构造，不用 double 构造）。"}]},{"day":77,"stage":"算法应试坑","title":"刷题方法论坑","points":["只看不写 = 不会：看题解\\"懂了\\"和 20 分钟内白板写对是两回事——每题必须独立敲一遍跑通。","刷题不复盘 = 白刷：错题按\\"套路\\"归档（双指针/滑窗/二分/DP…），三天后重写，写对才移出错题本。","死磕 hard 两小时不如先把 medium 刷透：面试 80% 是 medium，hard 优先刷高频（LRU/K组翻转/接雨水/编辑距离）。","写完不分析复杂度 = 半成品：面试官必追问时间/空间复杂度与优化空间。"],"questions":[{"q":"面试手撕算法时最优先要做的是？","options":["直接写代码抢时间","先确认题意与边界（输入范围/特殊情况）+ 说清思路获面试官认可后再动手","选最难解法炫技","沉默思考"],"answer":1,"explain":"面试考察\\"工程师协作\\"不只是答案：沟通澄清、确认边界、讲述思路再编码——写错方向 20 分钟就没了，方向确认只要 2 分钟。"},{"q":"刷题巩固记忆最有效的节奏是？","options":["一遍过永远不回头","艾宾浩斯复习：当天 → 3 天 → 7 天 → 21 天重写错题，按套路归档","一天刷 50 题只看题解","只刷简单题攒信心"],"answer":1,"explain":"刷题的本质是\\"套路的肌肉记忆\\"。100 题按模板吃透 > 500 题走马观花。每题给自己讲一遍\\"为什么用这个套路\\"。"}]},{"day":78,"stage":"面试表达坑","title":"自我介绍与项目介绍坑","points":["自我介绍流水账 → 应该是\\"技术名片\\"：30 秒定位你 = 方向 + 亮点技术 + 量化成果。","项目介绍讲需求不讲设计：\\"我用 SpringBoot 写了个商城\\"毫无信息量——讲\\"并发量/难点/你的方案/结果数据\\"。","\\"精通\\"二字是靶子：写精通 = 邀请面试官往死里问；用\\"熟悉/掌握\\"并准备好被问穿的深度。","简历项目被人问倒（说不清架构图/为什么选型）= 直接 pass——简历上每一行都要能撑 3 层追问。"],"questions":[{"q":"项目介绍的最优结构是？","options":["按代码模块逐个讲","STAR：业务背景（什么问题）→ 技术挑战（难在哪）→ 你的方案（为什么这么选）→ 量化结果（QPS/耗时/稳定性）","罗列所有技术名词","只讲亮点不讲过程"],"answer":1,"explain":"面试官要听的是\\"你解决了什么难题\\"而不是\\"你用了什么技术\\"。量化结果（RT 从 800ms 降到 50ms）是最有力的语言。"},{"q":"简历写\\"精通 Java 并发\\"，被追问 AQS 源码答不上，最好的补救是？","options":["硬编到底","坦诚边界：\\"AQS 我掌握到 CLH 队列层面，更深的实现我需要回去再深入\\"——诚实+展示已知深度","转移话题","反问面试官"],"answer":1,"explain":"面试官对\\"背题\\"高度敏感，对\\"诚实+方法论\\"宽容。答不上时展示\\"我知道什么、不知道什么、怎么补\\"反而是加分项。"}]},{"day":79,"stage":"Git 与协作坑","title":"版本管理坑","points":["commit 信息写 \\"fix\\" \\"update\\" = 三个月后自己都看不懂 → 规范：feat/fix/refactor + 一句话说清\\"改了什么为什么\\"。","在 master/main 直接开发 = 事故温床：feature 分支开发 → Code Review → 合并，是协作底线。",".env/密码/密钥一旦 commit 就永久在历史里：换密码没用，历史还在——用 git-secrets 预防，泄露了要重写历史（BFG）。","merge 冲突乱解决：只顾编译通过不管语义 → 逻辑静默损坏。冲突要理解双方意图再合并。"],"questions":[{"q":"敏感配置误 commit 并 push 到远程，正确处理是？","options":["删掉文件再 commit 一次就安全了","立即改密码使其失效 + 从历史中清除（BFG/filter-repo）+ 团队通报——历史里的密码任何人都看得到","不管它","把仓库设为私有"],"answer":1,"explain":"Git 历史不可变：后续删除只影响最新版本，历史版本仍可 checkout 出密码。所以\\"改密码\\"永远是最急的第一步，然后才是历史清理。"},{"q":"解决 merge 冲突时，最危险的做法是？","options":["逐行理解双方改动后合并","直接选择\\"使用我的版本\\"（--ours）一键解决所有冲突","和同事讨论","借助 IDE 三方对比工具"],"answer":1,"explain":"一键 ours/theirs 会把对方的改动全部静默丢弃，编译照样通过但功能丢失——这是最难发现的事故类型。冲突必须逐个语义级确认。"}]},{"day":80,"stage":"MyBatis 实战坑","title":"ORM 使用坑","points":["#{} 与 ${} 用混：ORDER BY ${column} 是注入重灾区——动态列名必须白名单映射。","resultType 对象字段与查询列别名不匹配 → 悄悄返回 null 而不是报错（mapUnderscoreToCamelCase 要开）。","批量插入用 for 循环单条 insert = N 次网络往返；用 <foreach> 拼批量 insert（注意单批数量防 SQL 超长）。","PageHelper.startPage 忘了紧跟查询 → ThreadLocal 残留污染下一条 SQL（页码错乱）。"],"questions":[{"q":"PageHelper.startPage(1,10) 与查询之间插入了另一个查询，会发生什么？","options":["报错","分页参数作用到了插入的那条查询上（ThreadLocal 消费后清除），目标查询不分页","两条都分页","数据错乱无法预测"],"answer":1,"explain":"PageHelper 把分页参数放 ThreadLocal，被下一个 SQL 消费。中间插了别的查询 → 分页错位。规范：startPage 与目标查询紧贴。"},{"q":"MyBatis 查询返回的字段全为 null 但 SQL 有数据，最可能因为？","options":["数据库坏了","列名与实体属性不匹配（下划线 vs 驼峰）且没开驼峰映射或没起别名","网络问题","事务未提交"],"answer":1,"explain":"create_time → createTime 需要 map-underscore-to-camel-case=true 或 SQL 别名。MyBatis 匹配不到就静默 null，不报错。"}]},{"day":81,"stage":"消息队列实战坑","title":"MQ 使用姿势坑","points":["生产端不带业务 key 发消息 → 消费端无法幂等/无法保证同实体有序（Kafka 按 key 分区）。","消费逻辑里做重活（调外部接口超时 30s）→ 消费堆积。MQ 只做\\"通知\\"，重活再异步化。","死信队列不监控 = 消息黑洞：失败进死信没人看 → 业务悄悄丢数据。死信必须告警+人工处理台。","顺序消息的消费端并发也会乱序：同 key 路由同分区后，消费端还要单线程/内存队列保序。"],"questions":[{"q":"Kafka 生产端发送订单消息时不指定 key，会导致？","options":["发不出去","消息轮询进各分区：同一订单的状态变更可能落不同分区，消费端无法保证该订单的顺序","消息丢失","消费变慢"],"answer":1,"explain":"Kafka 只保证分区内有序。需要\\"同一订单事件有序\\"就必须 key=orderId，让同订单消息进同一分区。"},{"q":"死信队列（DLQ）的正确用法是？","options":["直接删除死信","监控告警 + 人工/定时任务介入处理：死信是\\"自动重试均失败\\"的信号，背后通常是需要人看的异常","回原队列无限重试","忽略"],"answer":1,"explain":"死信 = 系统在喊救命。无限重试会把队列堵死；静默丢弃则丢业务数据。规范：有限重试 → 死信 → 告警 → 处理后重新投递。"}]},{"day":82,"stage":"微服务实战坑","title":"服务拆分与调用坑","points":["拆分过细（一个接口一个服务）→ 链路长、排查难、分布式事务满天飞：按业务能力拆，够用就好。","同步调用链路过长 → RT 相加、可用性相乘（每层 99.9% 四层就是 99.6%）：能用异步事件解耦就别串行同步。","超时不设置或全局统一：下游恶化上游傻等 → 线程池打满雪崩。超时逐层递减 + 熔断降级。","重试不加退避 = 重试风暴：下游抖动所有上游同时重试 → 雪上加霜。指数退避+抖动+熔断组合。"],"questions":[{"q":"四个服务串行调用，每个可用性 99.9%，整条链路可用性约是？","options":["99.9%","99.6%（0.999⁴）——链路越长可用性越差","100%","90%"],"answer":1,"explain":"可用性是相乘不是相加：0.999⁴ ≈ 0.996 = 年故障 35 分钟变 2.3 小时。这就是\\"能异步就异步\\"的数学依据。"},{"q":"服务 B 偶发超时，服务 A 对 B 的调用重试策略应该是？","options":["无限重试直到成功","有限次数 + 指数退避 + 随机抖动，配合熔断器（连续失败达阈值后快速失败一段时间）","加大线程池","重试 100 次"],"answer":1,"explain":"无脑重试 = DDoS 自己。退避（1s→2s→4s）+ 抖动避免同步踩踏；熔断让 A 在 B 恢复期间快速失败释放资源。"}]},{"day":83,"stage":"监控与告警坑","title":"可观测性建设坑","points":["只看平均响应时间：平均数掩盖长尾——P99/P999 才是用户真实体验。","告警风暴：阈值拍脑袋 → 半夜 50 条告警 → 麻木没人看。告警必须：有行动指南、分级、去重聚合。","日志/指标/链路三件套缺一不可：指标发现\\"有问题\\"，链路定位\\"在哪一步\\"，日志分析\\"为什么\\"。","没有基线 = 没有异常：先记录正常水位再谈告警。"],"questions":[{"q":"接口平均 RT 50ms 但用户反馈\\"偶尔很卡\\"，该看什么指标？","options":["平均值没问题就是快","P99/P999 分位数：可能 1% 请求 2s+（GC 停顿/慢 SQL/锁竞争），平均完全看不出来","CPU 使用率","流量曲线"],"answer":1,"explain":"长尾分布下平均无意义：99 个 10ms + 1 个 4s，平均才 49ms 但那个用户已经爆炸。分位数 + 直方图是接口监控标配。"},{"q":"告警设计的核心原则是？","options":["越敏感越好","每条告警都必须可行动（收到知道该做什么）+ 分级 + 聚合去重，避免狼来了效应","只发邮件","全部打到群里"],"answer":1,"explain":"告警疲劳是生产事故的温床：无效告警让团队麻木，真事故被淹没。按\\"用户影响面\\"分级：P0 电话、P1 群通知、P2 日报。"}]},{"day":84,"stage":"综合冲刺","title":"Offer 谈判与选择坑","points":["只看薪资不看成长：3 年后差距 = 平台业务复杂度 × 技术挑战 × 团队水平，首年薪资差 20% 远不值。","加班文化不问清楚：面试反问\\"团队日常节奏/上线频率\\"——入职后发现 996 再跑成本极高。","口头 offer 不算 offer：薪资/职级/期权/入职时间全部落到书面（邮件确认）再提离职。","小公司 title 大 vs 大厂螺丝钉：0-3 年优先选\\"能学到体系化东西\\"的平台。"],"questions":[{"q":"两个 offer：A 大厂规范但螺丝钉，B 创业公司高 30% 但技术栈老旧一人多岗，0-3 年更建议？","options":["一定选钱多的 B","看成长密度：若 A 有规范工程实践与 mentor 优先 A；技术老+无人带 = 用青春换钱，谨慎评估","一定选大厂 A","掷硬币"],"answer":1,"explain":"0-3 年的核心资产是\\"正确工程习惯与技术视野\\"——在烂环境养成坏习惯，纠正成本极高。"},{"q":"拿到口头 offer 后正确的做法是？","options":["立即提离职","确认关键条款书面化（薪资结构/职级/期权/绩效/入职时间），等背调与审批全部走完再提离职","告诉所有人","拒绝其他面试"],"answer":1,"explain":"口头 offer 在审批/背调环节都可能变卦。铁律：书面确认 + 入职材料齐备后才提离职。"}]},{"day":85,"stage":"综合冲刺","title":"简历工程细节坑","points":["技术栈罗列不写场景：\\"熟悉 Redis\\" → 改成\\"用 Redis 实现分布式锁与热点缓存，解决 XX 场景超卖问题\\"。","项目描述没有量级：加数字——日活/QPS/数据量/团队规模。","格式花哨 → 技术简历黑白 PDF、单栏、关键词清晰（机筛友好），一页为佳。","投递前跑一遍 JD 关键词：机筛靠关键词匹配，JD 里的技术词简历里没有直接被过滤。"],"questions":[{"q":"简历中项目经验最有说服力的写法是？","options":["负责全部开发工作","动词开头 + 技术手段 + 量化结果：\\"主导订单服务重构，引入分库分表与缓存，支撑 QPS 从 500 提升至 5000\\"","粘贴源码链接","写需求列表"],"answer":1,"explain":"\\"动词+手段+量化结果\\"三要素让面试官 10 秒抓住你的价值。每个项目准备 3 条这样的 bullet，每条都能展开讲 5 分钟。"},{"q":"大厂简历机筛（ATS）主要过滤什么？","options":["照片颜值","JD 关键词命中率与基本硬条件（学历/年限/城市）——技术关键词不全会直接漏掉","字体大小","GitHub 链接"],"answer":1,"explain":"海投阶段先过机筛再到人眼。对策：针对性改简历（不是造假），把真实做过但没写出来的技术点按 JD 语言补齐。"}]},{"day":86,"stage":"综合冲刺","title":"背调与入职坑","points":["离职原因说前司坏话 = 红灯：\\"追求更大平台/技术挑战\\"是安全答案。","背调查社保记录：履历时间造假必穿帮（社保连续性对不上），诚信问题直接 cancel offer。","入职材料提前备：离职证明/体检/银行卡，离职证明丢了提前和前司 HR 沟通补开。","试用期主动对齐预期（30/60/90 天目标），定期和 mentor 同步，别闷头干。"],"questions":[{"q":"背调环节最致命的行为是？","options":["薪资期望高","履历时间造假或虚报职级——社保与银行流水可直接验证，属诚信红线","话少","离职原因一般"],"answer":1,"explain":"能力不足可培养，诚信问题零容忍。正规公司背调必查社保连续性，\\"编造经历填补空窗\\"是最高频翻车点。空窗期如实说明即可。"},{"q":"入职后 30/60/90 天计划的意义是？","options":["形式主义","主动与上级对齐预期：什么算做好、优先级是什么、何时 review——试用期通过率的最大保障","给 HR 看的","限制自己"],"answer":1,"explain":"试用期挂人的主因是\\"预期错位\\"。主动定期对齐 = 把不确定性消灭在过程中。"}]},{"day":87,"stage":"综合冲刺","title":"持续成长坑","points":["收藏 ≠ 学会：输入要有输出（博客/分享/开源 PR），输出倒逼理解。","只追新框架不学原理：框架三年一换，原理（OS/网络/DB/分布式）十年不变——原理是\\"慢变量\\"。","不写技术文档：写文档 = 强迫自己把模糊认知变清晰，团队里\\"能写清楚\\"的人晋升最快。","每天 1 小时刻意学习（原理/英语/算法），复利三年 = 完全不同的职业曲线。"],"questions":[{"q":"技术学习最高效的闭环是？","options":["看视频收藏","输入（文档/源码）→ 实践（项目/DEMO）→ 输出（博客/分享）→ 反馈修正","报班被动学","只看书不动手"],"answer":1,"explain":"费曼学习法：能把概念讲给外行听懂 = 真正掌握。输出暴露理解漏洞，是最高效的查漏手段。"},{"q":"技术选型学习上，更值得长期投入的是？","options":["最新最热的框架","慢变量：操作系统/网络/数据库原理/分布式理论——框架会过时，原理可迁移","UI 框架","所有新语言都学一遍"],"answer":1,"explain":"框架是原理的投影：懂 epoll 才真懂 Nginx/Redis/Netty 的差异；懂 B+ 树才能在任何数据库做优化。"}]},{"day":88,"stage":"综合冲刺","title":"高频遗忘点速记（考前一天）","points":["Integer 缓存 -128~127（valueOf/自动装箱）；new Integer 永远新对象。","String 不可变、常量池；StringBuilder 线程不安全快，StringBuffer 安全慢。","HashMap：数组+链表+红黑树（链表长 8 且数组 ≥64 树化）；默认容量 16，负载 0.75，扩容 2n；线程不安全。","ConcurrentHashMap 1.8：CAS+synchronized 锁桶头节点，size 用 CounterCell 分段计数。","MySQL 默认隔离级别 RR（Oracle/PG 是 RC）；InnoDB 行锁+MVCC；MyISAM 表锁无事务。","Redis 单线程（网络 IO 6.0 多线程）+ 内存操作所以快；过期策略惰性+定期，内存淘汰默认 noeviction。"],"questions":[{"q":"链表长度达到 8 且数组长度 ≥ 64 时 HashMap 会？","options":["直接扩容","链表转红黑树，查询从 O(n) 到 O(logn)；节点数降到 6 退化回链表","删除链表","抛异常"],"answer":1,"explain":"两个条件缺一不可：数组 <64 时优先扩容。树化阈值 8 是泊松分布下冲突概率极低的工程取舍。"},{"q":"Redis 6.0 引入多线程是为了？","options":["命令执行并行化","网络 IO（读写/协议解析）多线程——命令执行仍是单线程，保证原子性语义不变","支持事务","替代持久化"],"answer":1,"explain":"瓶颈从 CPU 变网络 IO 后，6.0 把\\"读请求解析/写响应\\"交给多线程，执行器保持单线程——既提速又不破坏\\"单命令原子\\"。"}]},{"day":89,"stage":"综合冲刺","title":"面试时间线与心态","points":["金三银四/金九银十：提前 1-2 个月刷题+背八股+打磨项目；应届生秋招比春招名额多一倍以上。","面试顺序策略：先面 2-3 家不想去的练手攒经验，再面心仪公司——面试也是熟练度活。","一面挂≠你菜：匹配度/HC/面试官偏好都影响结果，复盘\\"答不好的题\\"比沮丧有用。","连续被拒的心态：把每次面试当\\"免费模拟考+行业情报收集\\"，问到的不会题记下来就是复习清单。"],"questions":[{"q":"秋招投递的最优节奏是？","options":["全部攒到最后一天投","分梯队：提前批（免笔试直通）→ 第一批 → 补录；先练手后心仪，每场面试后立即复盘","只投一家押注","等春招"],"answer":1,"explain":"提前批/早批次 HC 最充足、竞争比最低。面试状态需要热身：dream 公司放在第 3-5 场之后。"},{"q":"面试被问倒时，下列哪种回应最减分？","options":["\\"这块我了解不深，但我的理解思路是……\\"","沉默或直接说\\"不知道\\"然后不再尝试","请求提示","关联到相近的知识点"],"answer":1,"explain":"\\"直接躺平\\"暴露的是态度问题而非知识问题。正确姿势：承认边界 + 给出推理尝试 + 表达学习意愿。"}]},{"day":90,"stage":"综合冲刺","title":"毕业总结：全栈工程师的完整知识地图","points":["<b>语言层：</b>Java 语法 → OOP → 集合 → 并发（JMM/线程池/锁/AQS）→ JVM（内存/GC/调优）。","<b>框架层：</b>Spring（IoC/AOP/事务/MVC/Boot 自动装配）→ MyBatis → Spring Cloud（注册/配置/网关/熔断）。","<b>数据层：</b>MySQL（索引/事务/MVCC/锁/日志/主从/分库分表）→ Redis（结构/持久化/缓存三问/集群/分布式锁）→ ES/MQ。","<b>系统层：</b>网络（TCP/HTTP/HTTPS）→ OS（进程/内存/IO/epoll）→ Linux/Docker/K8s → 分布式理论（CAP/Raft）。","<b>工程层：</b>Git → 单测 → CI/CD → 监控告警（Metrics/Tracing/Logging）→ 线上排错方法论。","<b>软实力：</b>需求沟通 → 方案设计文档 → 复盘表达 → 面试谈判。以上 90 天全部覆盖，回到首页按章节查漏补缺。"],"questions":[{"q":"这套课程的学习闭环顺序，最合理的是？","options":["直接背八股文","按\\"语言→框架→数据→中间件→系统→工程\\"主线推进，每章配测验/易错点/模拟考自测，最后图解原理收口","先学分布式","只做项目不学理论"],"answer":1,"explain":"八股是\\"压缩包\\"需要解压：没有语言与系统层的地基，背了也撑不住追问。主线学习 + 测验自检 + 长文收口，才是正确打开方式。"},{"q":"检验自己是否达到\\"全栈入门\\"的标准是？","options":["能背出所有八股","独立完成一个含登录/CRUD/缓存/消息/部署的完整项目，并能解释每个技术选型的\\"为什么\\"","看过所有视频","刷完所有题"],"answer":1,"explain":"全栈的本质是\\"能对结果负责的完整交付能力\\"：从需求到上线到排错。项目是试金石，八股只是入场券。"}]}]');
INSERT INTO json_doc (name, data) VALUES ('pitfallStats', '{"days":90,"questions":180,"points":334}');
INSERT INTO json_doc (name, data) VALUES ('quizSections', '[{"id":"q-ch1","chapter":"第 1 章 · 编程世界入门","questions":[{"id":"q1-1","type":"single","q":"Java 属于哪种类型的语言？","options":["纯编译型语言，直接编译成机器码","纯解释型语言，边解释边执行","先编译成字节码，再由 JVM 执行的混合型语言","标记语言，和 HTML 同类"],"answer":[2],"explain":"Java 源码先由 javac 编译成 .class 字节码（中间码），再由不同平台的 JVM 执行，实现\\"一次编写，到处运行\\"。"},{"id":"q1-2","type":"multi","q":"关于前端 / 后端 / 数据库的分工，下列说法正确的有？","options":["前端负责用户看得见的界面和交互","后端负责业务逻辑处理","数据库负责长期存储数据","后端代码运行在用户的浏览器里"],"answer":[0,1,2],"explain":"后端运行在服务器上，不是浏览器里。前端（浏览器端）、后端（服务器端）、数据库（数据存储）三者各司其职。"},{"id":"q1-3","type":"judge","q":"HTTP 请求-响应是\\"前端发请求 → 后端处理 → 后端返回响应\\"的单向同步过程。","options":["正确","错误"],"answer":[0],"explain":"HTTP 是\\"请求-响应\\"模型：前端主动发起，后端被动应答。后端无法主动推送（除非用 WebSocket/SSE 技术）。"}]},{"id":"q-ch2","chapter":"第 2 章 · 计算机基础","questions":[{"id":"q2-1","type":"single","q":"关于进程和线程，下列说法正确的是？","options":["线程是资源分配的最小单位","一个进程内的多个线程共享该进程的内存空间","一个线程崩溃必定不影响同进程的其他线程","进程间通信比线程间通信更简单"],"answer":[1],"explain":"进程是资源分配的最小单位，线程是 CPU 调度的最小单位。同进程线程共享内存——这既是高效通信的便利，也是线程安全问题的根源。"},{"id":"q2-2","type":"single","q":"浏览器访问 HTTPS 网站时，默认使用的服务器端口是？","options":["80","8080","443","3306"],"answer":[2],"explain":"HTTP 默认 80，HTTPS 默认 443，8080 是常见的应用备用端口，3306 是 MySQL 默认端口。"},{"id":"q2-3","type":"single","q":"HTTP 状态码 404 表示？","options":["服务器内部错误","请求的资源不存在","未认证需要登录","请求成功"],"answer":[1],"explain":"404 Not Found = 资源不存在；401 未认证；403 已认证但无权限；500 服务器内部错误；502/504 网关错误或超时。"},{"id":"q2-4","type":"judge","q":"TCP 建立连接需要\\"三次握手\\"，目的是确保通信双方的收发能力都正常。","options":["正确","错误"],"answer":[0],"explain":"三次握手让双方都确认：我能发你能收，你也能发我也能收。少了任何一次，都无法完整确认双向链路。"}]},{"id":"q-ch3","chapter":"第 3 章 · Java SE 核心","questions":[{"id":"q3-1","type":"single","q":"以下代码的输出是？System.out.println(10 / 3);","options":["3.33","3","4","编译错误"],"answer":[1],"explain":"两个 int 相除结果还是 int，直接舍弃小数部分（不是四舍五入），所以 10/3 = 3。想要 3.33 需要先转 double。"},{"id":"q3-2","type":"single","q":"关于 == 和 equals，说法正确的是？","options":["== 比较对象的内容是否相同","String a = \\"hi\\"; String b = new String(\\"hi\\"); 则 a == b 为 true","equals 默认比较地址，String 重写后比较内容","基本类型 int 只能用 equals 比较"],"answer":[2],"explain":"== 比较引用类型时比较的是内存地址（new 出来的对象地址必不同，故 a == b 是 false）；equals 在 Object 中默认比地址，String 重写为比内容。"},{"id":"q3-3","type":"single","q":"Integer a = 127, b = 127; Integer c = 128, d = 128; 则 a == b 和 c == d 的结果分别是？","options":["true, true","true, false","false, true","false, false"],"answer":[1],"explain":"Integer 对 -128~127 有缓存池，a 和 b 是同一个缓存对象所以 == 为 true；128 超出缓存范围各自 new 新对象，== 为 false。这也是\\"包装类比较必须用 equals\\"的原因。"},{"id":"q3-4","type":"single","q":"面向对象三大特性不包括？","options":["封装","继承","多态","重载"],"answer":[3],"explain":"三大特性是封装、继承、多态。重载（Overload）是方法签名的复用技巧，不属于三大特性。"},{"id":"q3-5","type":"single","q":"关于 HashMap，下列说法错误的是？","options":["JDK8 中底层结构是数组 + 链表 + 红黑树","允许一个 null key","线程安全，适合多线程环境直接使用","默认初始容量 16，负载因子 0.75"],"answer":[2],"explain":"HashMap 线程不安全！多线程环境应该用 ConcurrentHashMap。HashMap 允许一个 null key，链表长度超 8 且数组长度 ≥64 转红黑树。"},{"id":"q3-6","type":"multi","q":"下列哪些是运行时异常（RuntimeException）？","options":["NullPointerException","数组越界异常","IOException（编译时强制处理的异常）","ArithmeticException（除零）"],"answer":[0,1,3],"explain":"空指针、越界、除零都是运行时异常，编译器不强制处理；IOException 是受检异常（编译时异常），必须 try-catch 或 throws。"},{"id":"q3-7","type":"single","q":"频繁进行字符串拼接（如循环 1 万次），应该使用？","options":["String 的 + 运算符","StringBuilder","StringBuffer","char 数组"],"answer":[1],"explain":"String 不可变，+ 拼接每次都创建新对象。StringBuilder 可变且高效；StringBuffer 功能相同但线程安全、性能略低，单线程场景用 StringBuilder 即可。"},{"id":"q3-8","type":"judge","q":"垃圾回收（GC）会回收所有\\"引用计数为零\\"的对象。","options":["正确","错误"],"answer":[1],"explain":"主流 JVM（HotSpot）不用引用计数法（无法解决循环引用），而是用可达性分析：从 GC Roots 出发，沿引用链不可达的对象才是垃圾。"},{"id":"q3-9","type":"single","q":"线程池的核心价值不包括？","options":["复用线程，降低创建销毁开销","控制并发数量，防止资源耗尽","提供任务队列削峰","保证任务执行结果一定正确"],"answer":[3],"explain":"线程池管理线程的生命周期和并发度，但业务逻辑对错与线程池无关。"},{"id":"q3-10","type":"single","q":"启动一个线程应该调用哪个方法？","options":["run()","start()","init()","execute()"],"answer":[1],"explain":"start() 才会向操作系统申请新线程并执行 run()；直接调 run() 只是普通方法调用，在当前线程同步执行，没有多线程效果。"}]},{"id":"q-ch4","chapter":"第 4 章 · 前端开发","questions":[{"id":"q4-1","type":"single","q":"CSS 中让子元素在父容器内水平垂直都居中，最简洁的现代写法是？","options":["父元素 display:flex; justify-content:center; align-items:center;","子元素 margin: 0 auto;","子元素 position:absolute; top:50%;","父元素 text-align:center;"],"answer":[0],"explain":"Flex 两属性组合是标准答案。margin:0 auto 只能水平居中；top:50% 只垂直定位了一半还需要 translate 修正。"},{"id":"q4-2","type":"single","q":"Vue 中实现表单输入与数据双向绑定的指令是？","options":["v-bind","v-model","v-for","v-if"],"answer":[1],"explain":"v-model 是表单双向绑定语法糖（本质是 value 属性 + input 事件的结合）；v-bind 单向绑定数据到属性。"},{"id":"q4-3","type":"single","q":"前端请求后端接口时浏览器控制台报 CORS 错误，原因是？","options":["后端代码有语法错误","浏览器同源策略限制了跨域请求，且后端未配置允许跨域","网络断开了","JSON 格式错误"],"answer":[1],"explain":"CORS 是浏览器安全机制：跨域请求需要后端返回 Access-Control-Allow-Origin 等响应头放行。注意这是浏览器行为，Postman 不受此限制。"},{"id":"q4-4","type":"judge","q":"JavaScript 中 const 声明的对象，其属性值完全不能修改。","options":["正确","错误"],"answer":[1],"explain":"const 锁定的是\\"变量指向的引用\\"，对象的引用不能重新赋值，但对象内部的属性可以修改。想让属性也不可变需要 Object.freeze。"}]},{"id":"q-ch5","chapter":"第 5 章 · MySQL 数据库","questions":[{"id":"q5-1","type":"single","q":"存储用户账户余额，最合适的字段类型是？","options":["FLOAT","DOUBLE","DECIMAL(10,2)","INT"],"answer":[2],"explain":"FLOAT/DOUBLE 是二进制浮点数，存在精度丢失，金额必须用 DECIMAL 精确小数。Java 对应 BigDecimal。"},{"id":"q5-2","type":"single","q":"LEFT JOIN 的结果是？","options":["只返回两表都匹配的行","左表全部行 + 右表匹配不上的填 NULL","右表全部行 + 左表匹配不上的填 NULL","两表的笛卡尔积"],"answer":[1],"explain":"LEFT JOIN 保留左表全部行，右表没有匹配的列补 NULL；INNER JOIN 才是只取交集。"},{"id":"q5-3","type":"single","q":"WHERE name LIKE ''%三'' 会导致？","options":["正常走索引","索引失效，全表扫描","语法错误","结果不完整"],"answer":[1],"explain":"前置 % 使 B+ 树无法按前缀定位，索引失效。''张%''（后置通配）可以走索引。这是 SQL 优化的高频考点。"},{"id":"q5-4","type":"single","q":"事务的 ACID 特性中，\\"原子性\\"指的是？","options":["事务提交后数据永久保存","并发事务互不干扰","事务内操作要么全部成功，要么全部回滚","数据完整性约束不被破坏"],"answer":[2],"explain":"原子性 = 不可分割，全成或全不做；持久性对应 A、隔离性对应 B、一致性对应 D。"},{"id":"q5-5","type":"multi","q":"防止 SQL 注入的正确做法有哪些？","options":["使用 PreparedStatement 占位符传参","对用户输入做参数化校验（类型、长度、格式）","把用户输入直接拼接到 SQL 字符串里","数据库账号遵循最小权限原则"],"answer":[0,1,3],"explain":"拼接用户输入正是 SQL 注入的根源。核心防御是预编译占位符，辅以输入校验和最小权限账号。"},{"id":"q5-6","type":"judge","q":"索引建得越多，查询和写入都会越快。","options":["正确","错误"],"answer":[1],"explain":"索引提升查询（读）速度，但每个索引都是一棵需要维护的 B+ 树，INSERT/UPDATE/DELETE 时要同步更新，写入反而变慢，还占磁盘空间。"}]},{"id":"q-ch6","chapter":"第 6 章 · Spring 后端框架","questions":[{"id":"q6-1","type":"single","q":"Spring IoC 容器的作用是？","options":["管理对象（Bean）的创建和依赖注入","编译 Java 代码","渲染前端页面","管理数据库事务日志"],"answer":[0],"explain":"IoC（控制反转）把对象的创建、装配、生命周期管理权从程序员手里交给 Spring 容器，实现解耦。"},{"id":"q6-2","type":"single","q":"三层架构中，\\"接收 HTTP 请求并返回 JSON\\"的层是？","options":["Service 层","Mapper/DAO 层","Controller 层","Entity 层"],"answer":[2],"explain":"Controller 负责接收请求、参数校验、调用 Service、返回结果；Service 写业务逻辑；DAO 只管数据库读写。"},{"id":"q6-3","type":"single","q":"RESTful 风格中，\\"删除 id 为 5 的用户\\"的接口设计应该是？","options":["GET /api/users/delete/5","POST /api/users/5/delete","DELETE /api/users/5","GET /api/users?action=delete&id=5"],"answer":[2],"explain":"RESTful 用 URL 表示资源（/api/users/5），HTTP 方法表示操作（DELETE 删除）。"},{"id":"q6-4","type":"multi","q":"关于 @Transactional 注解，正确的说法有？","options":["加在 Service 方法上，方法内所有数据库操作具有原子性","默认只对 RuntimeException 回滚，建议配置 rollbackFor = Exception.class","加在 private 方法上也能生效","方法内 try-catch 吞掉异常可能导致事务不回滚"],"answer":[0,1,3],"explain":"@Transactional 基于 AOP 代理实现，private 方法无法被代理增强所以失效；catch 吞异常后代理感知不到异常就不会回滚。这是两个经典的事务失效场景。"},{"id":"q6-5","type":"single","q":"JWT 登录方案中，前端每次请求应该把 Token 放在哪里？","options":["URL 查询参数里","请求头（通常是 Authorization）里","Cookie 里且不设置任何标志","请求体里，每个接口都要"],"answer":[1],"explain":"标准做法是放请求头 Authorization: Bearer <token>，由前端 HTTP 库（axios 拦截器）统一注入，后端拦截器统一校验。"},{"id":"q6-6","type":"judge","q":"用户密码在数据库中必须加密存储（如 BCrypt），不能存明文。","options":["正确","错误"],"answer":[0],"explain":"数据库一旦泄露，明文密码直接暴露。BCrypt 是单向哈希（带盐），登录时对输入密码做同样哈希后比对即可。这是安全底线。"}]},{"id":"q-ch7","chapter":"第 7 章 · 中间件","questions":[{"id":"q7-1","type":"single","q":"Redis 相比 MySQL 快的核心原因是？","options":["代码写得好","数据存储在内存中","没有 SQL 解析","单线程没有锁竞争"],"answer":[1],"explain":"内存读写比磁盘快几个数量级，这是根本原因；高效数据结构、单线程避免切换、IO 多路复用是锦上添花。"},{"id":"q7-2","type":"single","q":"\\"热点缓存 key 过期的瞬间，大量请求直接打到数据库\\"描述的是？","options":["缓存穿透","缓存击穿","缓存雪崩","缓存污染"],"answer":[1],"explain":"击穿 = 一个热 key 失效瞬间被打穿（解法：互斥锁/不过期）；穿透 = 查不存在的数据（解法：空值缓存/布隆过滤器）；雪崩 = 大批 key 同时失效（解法：过期时间加随机）。"},{"id":"q7-3","type":"single","q":"Cache Aside 模式下，更新数据时的正确顺序是？","options":["先删缓存，再更新数据库","先更新数据库，再删除缓存","先更新缓存，再更新数据库","只更新缓存"],"answer":[1],"explain":"先更新库再删缓存（下次查询重新加载新数据），是兼顾简单性和一致性的主流方案。"},{"id":"q7-4","type":"multi","q":"消息队列（MQ）的核心价值包括？","options":["异步提速：主流程不必等耗时操作","削峰填谷：保护数据库不被瞬时洪峰压垮","系统解耦：生产者和消费者互不依赖","保证消息 100% 只消费一次绝不重复"],"answer":[0,1,2],"explain":"MQ 不承诺\\"只一次\\"，网络重试会导致重复消费——所以消费者必须做幂等（如按唯一业务号判重），这是 MQ 使用的关键配套。"},{"id":"q7-5","type":"single","q":"Nginx 负载均衡默认的分发策略是？","options":["随机","轮询（依次分发）","最少连接数优先","IP 哈希"],"answer":[1],"explain":"默认轮询；可配置 weight 权重、ip_hash（同一 IP 固定到同一实例）、least_conn。"},{"id":"q7-6","type":"judge","q":"ES（Elasticsearch）适合替代 MySQL 存储订单交易主数据。","options":["正确","错误"],"answer":[1],"explain":"ES 擅长全文检索和分析，但不保证强事务，主数据（订单、余额）仍应存 MySQL，把需要搜索的字段同步到 ES 做检索层。"}]},{"id":"q-ch8","chapter":"第 8 章 · 工程化必备","questions":[{"id":"q8-1","type":"single","q":"把 feature 分支的提交\\"摘下来接到目标分支末尾、历史变成一条直线\\"的操作是？","options":["git merge","git rebase","git revert","git reset"],"answer":[1],"explain":"rebase 重放提交、历史线性；merge 保留分叉和合并提交。已推送到公共分支的提交禁止 rebase（会改写他人依赖的历史）。"},{"id":"q8-2","type":"single","q":"实时观察服务器上 Java 应用日志的新增内容（排查线上问题），应该用？","options":["cat app.log","tail -f app.log","ls -la","ps -ef"],"answer":[1],"explain":"tail -f 持续滚动输出文件新增内容，配合复现操作实时看报错，是线上排查第一命令。"},{"id":"q8-3","type":"single","q":"Docker 镜像与容器的关系是？","options":["容器是镜像的运行实例，镜像类是模板","镜像是容器运行后的快照","两者完全独立没有关系","一个镜像只能创建一个容器"],"answer":[0],"explain":"镜像（Image）是只读模板（类），容器（Container）是镜像的运行实例（对象），一个镜像可以起任意多个容器。"},{"id":"q8-4","type":"judge","q":"CI（持续集成）的典型行为是：每次 push 代码自动运行测试和构建，失败立即通知。","options":["正确","错误"],"answer":[0],"explain":"CI 让问题在合并早期暴露，避免\\"集成地狱\\"；CD 则更进一步把构建产物自动部署。GitHub Actions/Jenkins/GitLab CI 都是常见工具。"}]},{"id":"q-ch9","chapter":"第 9 章 · 全栈实战与职业","questions":[{"id":"q9-1","type":"single","q":"简历项目描述中，最有说服力的写法是？","options":["\\"精通各种主流技术，能力全面\\"","\\"负责项目开发，完成了大量功能模块\\"","\\"通过 Redis 缓存 + 索引优化，将列表接口 P95 响应从 180ms 降至 15ms\\"","\\"使用了 Spring Boot、Redis、MySQL 等先进技术栈\\""],"answer":[2],"explain":"STAR 法则 + 量化结果（做了什么优化、为什么、效果多少）远胜罗列技术名词，这是技术面试官筛选简历的核心标准。"},{"id":"q9-2","type":"multi","q":"技术面试回答\\"项目难点\\"时，好的策略包括？","options":["讲清问题背景和影响","给出多个候选方案并对比权衡","说明最终方案的效果和数据","把难点说得越玄乎越好，显得高深"],"answer":[0,1,2],"explain":"面试官考察的是\\"解决问题的能力\\"而非词汇量。背景 → 方案权衡 → 结果验证的完整闭环，是工程师成熟度的标志。"},{"id":"q9-3","type":"single","q":"关于系统设计题\\"设计一个秒杀系统\\"，以下哪个思路方向是对的？","options":["直接把所有请求透传给 MySQL，加个大内存就行","前端限流 + 网关限流 + Redis 预扣库存 + MQ 异步下单，层层削峰","全部逻辑塞进一个 Controller 方法里处理","不用设计，买更大的服务器"],"answer":[1],"explain":"秒杀的本质是\\"用有限的库存对抗无限的流量\\"——核心思路是层层过滤削峰：越早拦掉无效请求越好，数据库只承受最终少量成功请求。"},{"id":"q9-4","type":"judge","q":"学习编程应该把所有框架都学完再开始做项目。","options":["正确","错误"],"answer":[1],"explain":"项目驱动学习效率最高：用一个真实项目牵引，需要什么学什么，遇到问题查文档解决——这本身就是工程师的日常工作方式。"}]},{"id":"q-ch10","chapter":"第 10 组 · 计算机网络（小林重点）","questions":[{"id":"q10-1","type":"single","q":"TCP 三次握手中，第二次握手报文的标志位是？","options":["SYN=1","SYN=1, ACK=1","ACK=1, FIN=1","只有 ACK=1"],"answer":[1],"explain":"第二次握手是服务端\\"确认客户端的 SYN + 发起自己的 SYN\\"，两件事合并成一个报文，所以 SYN 和 ACK 同时置 1。"},{"id":"q10-2","type":"single","q":"TIME_WAIT 状态出现在谁身上？等待多长时间？","options":["被动关闭方，1MSL","主动关闭方，2MSL","双方都要等 2MSL","服务端固定 60 秒"],"answer":[1],"explain":"谁主动关闭谁 TIME_WAIT。等 2MSL 的两个原因：①保证最后一个 ACK 丢了还能重传响应；②让旧连接报文在网络中自然消亡，不污染新连接。"},{"id":"q10-3","type":"multi","q":"下列哪些属于 TCP 保证可靠性的机制？","options":["序列号与确认应答","超时重传和快速重传","滑动窗口流量控制","校验和"],"answer":[0,1,2,3],"explain":"全选。TCP 可靠性 = 校验和（查错）+ seq/ack（排序确认）+ 重传（补丢）+ 滑动窗口（流控）+ 拥塞控制（护网）+ 连接管理（状态一致）。"},{"id":"q10-4","type":"single","q":"HTTPS 中，非对称加密主要用在哪个阶段？","options":["传输所有业务数据","仅用于交换对称会话密钥（证书验证与密钥协商）","压缩数据","验证 DNS"],"answer":[1],"explain":"非对称太慢，只负责\\"安全地商量出对称密钥\\"；真正的海量数据传输用对称加密（AES 等）。各取所长。"},{"id":"q10-5","type":"single","q":"浏览器再次请求资源时\\"不发任何请求直接用本地副本\\"，这是？","options":["协商缓存（304）","强缓存（Cache-Control 未过期）","DNS 缓存","CDN 缓存"],"answer":[1],"explain":"强缓存 = 过期前连请求都不发；协商缓存 = 过期后带 If-None-Match/If-Modified-Since 问服务器，没变返回 304。"},{"id":"q10-6","type":"single","q":"拥塞控制中，收到 3 个重复 ACK 会触发什么？","options":["cwnd 重置为 1，重新慢启动","快速重传 + 快恢复（cwnd 减半）","直接断开连接","窗口归零"],"answer":[1],"explain":"3 个重复 ACK 判定轻度丢包 → 立即重传（快重传）→ ssthresh 和 cwnd 减半继续（快恢复）。超时才是最严重情况，cwnd 归 1 重新慢启动。"},{"id":"q10-7","type":"judge","q":"HTTP/2 彻底解决了队头阻塞问题。","options":["正确","错误"],"answer":[1],"explain":"HTTP/2 解决了 HTTP 层的队头阻塞（多路复用），但底层 TCP 丢包时所有流一起等重传——TCP 层队头阻塞仍在，所以才有 HTTP/3 换 QUIC(UDP)。"},{"id":"q10-8","type":"single","q":"为什么 DNS 查询主要用 UDP？","options":["UDP 更安全","查询报文小、一问一答，UDP 无连接开销低延迟低","UDP 支持加密","TCP 不能传输域名"],"answer":[1],"explain":"DNS 查询是\\"小报文+低延迟+高并发\\"场景，UDP 免握手开销。响应超 512B 或区域传送才用 TCP；现代还有 DoH/DoT 加密方案。"}]},{"id":"q-ch11","chapter":"第 11 组 · 操作系统（小林重点）","questions":[{"id":"q11-1","type":"single","q":"进程切换比线程切换开销大的根本原因是？","options":["进程代码更长","进程要切换页表（虚拟地址空间），TLB 大量失效","进程优先级更低","进程没有线程"],"answer":[1],"explain":"换地址空间 → 页表基址寄存器更换 → TLB（翻译缓存）失效 → 之后内存访问要重新查表，这是最大开销来源。线程共享地址空间没这个问题。"},{"id":"q11-2","type":"multi","q":"线程之间共享进程的哪些资源？","options":["堆内存和全局变量","打开的文件描述符","每个线程自己的栈","信号处理函数"],"answer":[0,1,3],"explain":"栈、寄存器、程序计数器是线程私有的；堆、全局变量、文件、信号处理是共享的。C 选项是\\"私有\\"不是共享。"},{"id":"q11-3","type":"single","q":"epoll 相比 select/poll 的核心优势是？","options":["支持的 fd 数量固定更大","注册一次 + 事件回调就绪链表，wait 只返回就绪 fd","不占用任何内核资源","只能用于 TCP"],"answer":[1],"explain":"epoll 三板斧：红黑树管 fd（免重复拷贝）、内核回调（免轮询）、就绪链表（处理量只与活跃连接相关）。10 万连接 100 活跃时优势碾压。"},{"id":"q11-4","type":"single","q":"malloc 成功返回后，物理内存立即分配了吗？","options":["是，同时清零","否，只分配虚拟地址空间，首次写入触发缺页中断才分配物理页","取决于 CPU 型号","只有数组才分配"],"answer":[1],"explain":"惰性分配：malloc 只登记虚拟区域，写时缺页中断才给物理页——所以 malloc 4GB 能成功。这就是 VIRT 和 RES 的差别来源。"},{"id":"q11-5","type":"judge","q":"破坏死锁四个必要条件中的任意一个，就能预防死锁。","options":["正确","错误"],"answer":[0],"explain":"四条件（互斥/持有并等待/不可剥夺/循环等待）必须同时成立才死锁，破坏任一即可。工程最常用：按固定顺序加锁破坏循环等待。"},{"id":"q11-6","type":"single","q":"最快的进程间通信方式是？","options":["管道","消息队列","共享内存（配合信号量同步）","Socket"],"answer":[2],"explain":"共享内存零拷贝，读写直接发生在同一块物理内存；其他方式都要\\"用户→内核→用户\\"两次拷贝。代价是同步要自己管（配信号量）。"},{"id":"q11-7","type":"single","q":"Kafka 发送静态日志文件快的原因之一是用了零拷贝，其核心系统调用是？","options":["mmap 只能用于写文件","sendfile：数据不经过用户态直接内核侧转发","printf 缓冲","fork 加快复制"],"answer":[1],"explain":"传统\\"读文件发网络\\"要 4 次拷贝；sendfile 让数据在内核缓冲直接到（或 DMA 到）网卡，不进用户态，CPU 零参与拷贝。"}]},{"id":"q-ch12","chapter":"第 12 组 · MySQL 深入（小林重点）","questions":[{"id":"q12-1","type":"single","q":"InnoDB 的 B+ 树索引，非叶子节点存放的是什么？","options":["整行数据","键值 + 子节点指针","只有主键","页的校验和"],"answer":[1],"explain":"非叶子只放键+指针（所以一页能放上千个指针，树矮）；数据全在叶子层。B 树的非叶子才放数据。"},{"id":"q12-2","type":"single","q":"通过二级索引 name 查询 SELECT * FROM t WHERE name=... 会发生？","options":["直接返回整行","先查 name 索引得到主键，再回聚簇索引查整行（回表）","全表扫描","报错"],"answer":[1],"explain":"二级索引叶子存的是\\"索引列+主键\\"，拿主键回聚簇索引再查一次叫回表。若查询字段全在索引里则免回表，叫覆盖索引。"},{"id":"q12-3","type":"single","q":"RR（可重复读）与 RC（读已提交）在 MVCC 实现上的本质区别是？","options":["RR 没有 undo log","ReadView 生成时机：RR 事务内第一次查询生成并复用，RC 每条查询都重新生成","RC 不加锁","RR 不支持索引"],"answer":[1],"explain":"就这一个时机差异：RC 每次读都建新快照（别人一提交就能看见→不可重复读）；RR 复用第一次快照（整事务视图一致）。"},{"id":"q12-4","type":"multi","q":"下列哪些 SQL 写法会导致索引失效？","options":["WHERE YEAR(create_time) = 2024","LIKE ''%关键字''","WHERE name = ''张三''（name 有索引）","联合索引 (a,b) 下 WHERE b = 1"],"answer":[0,1,3],"explain":"函数运算、前导模糊、违反最左前缀都会失效。C 是标准等值查询，正常走索引。"},{"id":"q12-5","type":"single","q":"保障事务\\"持久性 D\\"的机制是？","options":["undo log","redo log（WAL，先写日志再刷数据页）","binlog","双写缓冲"],"answer":[1],"explain":"A=undo（回滚）、D=redo（崩溃恢复）、I=锁+MVCC、C=三者共同结果。binlog 是 Server 层日志，用于复制和归档。"},{"id":"q12-6","type":"single","q":"为什么建议用自增主键而不是 UUID？","options":["UUID 更占内存但无所谓","自增顺序插入避免页分裂和碎片，且所有二级索引叶子都存主键，主键越小索引越瘦","UUID 不能做主键","自增主键更安全"],"answer":[1],"explain":"UUID 无序 → 随机插入已有页 → 页分裂+碎片；且 36B 的 UUID 会让每个二级索引都变肥。分布式要全局 id 用雪花算法（趋势递增）。"},{"id":"q12-7","type":"judge","q":"RR 隔离级别下，快照读靠 MVCC、当前读靠临键锁（Next-Key Lock）来避免幻读。","options":["正确","错误"],"answer":[0],"explain":"普通 SELECT 走 MVCC 快照；SELECT...FOR UPDATE/UPDATE/DELETE 是当前读，靠 Next-Key Lock（行锁+间隙锁）阻止插入。但\\"先快照读后当前读\\"混用仍可能看到幻影行。"},{"id":"q12-8","type":"single","q":"redolog 与 binlog 之间用\\"两阶段提交\\"是为了？","options":["提高写入速度","保证两份日志逻辑一致，防止崩溃恢复后主从数据不一致","节省磁盘","兼容旧版本"],"answer":[1],"explain":"redo prepare → 写 binlog → redo commit。任一时刻崩溃都能通过两份日志的状态推导出一致结果——否则可能出现主库有、从库没有的数据分叉。"}]},{"id":"q-ch13","chapter":"第 13 组 · Redis 深入（小林重点）","questions":[{"id":"q13-1","type":"single","q":"缓存穿透、击穿、雪崩的对应解决方案，正确的一组是？","options":["穿透→互斥锁；击穿→布隆过滤器；雪崩→缓存空值","穿透→布隆过滤器/缓存空值；击穿→互斥锁或逻辑过期；雪崩→过期时间加随机+高可用","三者都用\\"加大内存\\"解决","穿透→加随机过期；击穿→限流；雪崩→布隆过滤器"],"answer":[1],"explain":"穿透=查不存在的数据（布隆/空值）；击穿=单个热点 key 过期瞬间（互斥锁/逻辑过期）；雪崩=大量 key 同时失效或 Redis 宕机（随机抖动+集群高可用+限流兜底）。"},{"id":"q13-2","type":"single","q":"ZSet 底层用跳表而不是红黑树的主要理由是？","options":["跳表查询更快（复杂度更低）","实现简单、范围查询沿链表直接走、无需旋转再平衡，性能相当","红黑树不支持排序","跳表占内存一定更小"],"answer":[1],"explain":"两者查询都是 O(log n)，胜负在工程性：跳表范围查询顺链表扫、插入删除只改指针、代码简单好调试。Redis 作者原话就是这个。"},{"id":"q13-3","type":"single","q":"RDB 的 bgsave 期间 Redis 还能处理写命令吗？如何保证快照一致？","options":["不能写，阻塞中","能写，靠 fork + 写时复制（COW），子进程读旧页、主进程改新页","能写，但不保证一致性","取决于客户端数量"],"answer":[1],"explain":"fork 后子进程看到 fork 瞬间的内存；主进程修改数据时内核复制对应页（COW），快照一致性自然成立。代价：写入越多内存消耗越大。"},{"id":"q13-4","type":"multi","q":"关于 Redis 过期删除与内存淘汰，说法正确的有？","options":["过期删除 = 惰性删除 + 定期删除组合","内存满时按 maxmemory 策略淘汰（如 allkeys-lru）","Redis 的 LRU 是维护完整链表的精确 LRU","noeviction 是默认策略，内存满后写入报错"],"answer":[0,1,3],"explain":"Redis 的 LRU 是\\"随机抽样近似 LRU\\"（省链表维护成本），C 错。其余正确：到期 key 靠惰性+定期删除，内存不够才触发淘汰策略。"},{"id":"q13-5","type":"single","q":"哨兵判定主库\\"客观下线\\"需要？","options":["任意 1 个哨兵 ping 不通即可","多数（quorum 及以上）哨兵都报告主库不可达","所有从库确认","客户端超时反馈"],"answer":[1],"explain":"单个哨兵判的是\\"主观下线\\"（可能它自己网络抖）；达到 quorum 多数派才升级为\\"客观下线\\"，触发选举和故障转移——防误判。"},{"id":"q13-6","type":"single","q":"Redis 6.0 引入多线程是为了？","options":["让命令执行并行化","加速网络 IO 读写（命令执行仍是单线程，保住原子性）","替代持久化","支持更多数据类型"],"answer":[1],"explain":"瓶颈在网络 IO 不在计算。IO Threads 只负责读请求/写回包；命令执行依旧单线程串行——原子性语义完全不变。"},{"id":"q13-7","type":"judge","q":"Redis 渐进式 rehash 会同时持有新旧两张哈希表，把搬迁成本分摊到每次操作中。","options":["正确","错误"],"answer":[0],"explain":"扩容时保留旧表，之后每次增删改查顺带搬一个桶，后台任务也帮忙搬；查找查两张表，新增只进新表——避免一次性卡住单线程。"},{"id":"q13-8","type":"single","q":"热点 key 问题（单 key QPS 极高）的合理治理方案是？","options":["把 key 的 value 拆成 100 份","本地缓存多级缓存 / key 加随机后缀分散到多分片","直接删除该 key","把过期时间设长一点"],"answer":[1],"explain":"热 key 的痛是\\"单分片被打满\\"：①多级缓存让请求不落到 Redis；②后缀打散把读压力摊到多个分片。A 是拆大 key 的方法，别混。"}]},{"id":"q-ch14","chapter":"第 14 组 · Java 并发编程（深入）","questions":[{"id":"q14-1","type":"single","q":"volatile 关键字能解决下列哪类问题？","options":["保证 i++ 的原子性","保证可见性和禁止指令重排","替代 synchronized 加锁","让线程休眠"],"answer":[1],"explain":"volatile 两个语义：①写立即刷主存、读走主存（可见性）；②内存屏障禁止重排序。但 i++ 是\\"读-改-写\\"三步复合操作，volatile 不保证原子性——要用 AtomicInteger 或锁。"},{"id":"q14-2","type":"single","q":"synchronized 锁升级的正确顺序是？","options":["重量级 → 轻量级 → 偏向锁","偏向锁 → 轻量级 → 重量级","轻量级 → 偏向锁 → 重量级","直接就是重量级"],"answer":[1],"explain":"JDK 6 引入锁升级（不可逆）：无锁 → 偏向锁（只有一个线程访问，对象头记线程 id，几乎零成本）→ 轻量级锁（交替竞争，CAS 自旋）→ 重量级锁（激烈竞争，操作系统 mutex，线程挂起）。注意 JDK 15 已默认废弃偏向锁。"},{"id":"q14-3","type":"single","q":"CAS 的 ABA 问题指的是？","options":["值从 A 改到 B 再改回 A，CAS 感知不到中间变化","CAS 执行三次失败","三个线程同时 CAS","比较和交换顺序颠倒"],"answer":[0],"explain":"线程 1 读到 A，期间别人把它改成 B 又改回 A，线程 1 的 CAS 仍成功——但状态可能已变（如链表头被换过）。解决：AtomicStampedReference 加版本号，类似乐观锁的 version 字段。"},{"id":"q14-4","type":"multi","q":"关于 ThreadLocal，下列说法正确的有？","options":["每个 Thread 内部有一个 ThreadLocalMap","key 是 ThreadLocal 对象（弱引用），value 是线程隔离的值","线程池场景用完不 remove 可能导致内存泄漏和数据串用","ThreadLocal 值可以跨线程安全传递"],"answer":[0,1,2],"explain":"ThreadLocalMap 的 Entry 的 key 是弱引用，GC 后 key 变 null 但 value 还在（泄漏），用完必须 remove()；线程池线程复用，不清理会把上一个请求的值带给下一个请求（串数据事故）。跨线程传递要用 InheritableThreadLocal 或阿里 TransmittableThreadLocal。"},{"id":"q14-5","type":"single","q":"ReentrantLock 公平锁与非公平锁的本质区别是？","options":["公平锁性能更好","非公平锁允许插队：新线程直接抢锁，抢不到才进队列","公平锁不能重入","没有区别"],"answer":[1],"explain":"非公平锁加锁时先 CAS 直接抢一次，失败才入 AQS 队列排队——减少线程切换，吞吐高但可能\\"饥饿\\"；公平锁严格按队列顺序（先检查队列有没有人在等）。默认非公平。"},{"id":"q14-6","type":"single","q":"CountDownLatch 与 CyclicBarrier 的区别，正确的是？","options":["完全一样可以互换","CountDownLatch 一次性、等待\\"事件发生\\"；CyclicBarrier 可重置复用、等待\\"人齐再一起走\\"","前者性能差","后者只能用于单线程"],"answer":[1],"explain":"CountDownLatch：N 个线程各 countDown()，主线程 await() 等计数归零（如\\"10 个数据源都加载完\\"），不可重用。CyclicBarrier：N 个线程互相 await() 等彼此到齐再一起执行（如\\"分片算完合并\\"），可复用且支持回调。"},{"id":"q14-7","type":"single","q":"AQS 的核心数据结构是？","options":["红黑树","volatile int state + CLH 变体的双向等待队列","哈希表","跳表"],"answer":[1],"explain":"AQS = 一个 volatile 的 state（语义由子类定义：重入次数/许可数/闸门状态）+ CAS 改 state + 获取失败的线程封装成 Node 入双向 FIFO 队列挂起。ReentrantLock/Semaphore/CountDownLatch 都基于它。"},{"id":"q14-8","type":"single","q":"以下代码的输出是：volatile int i = 0; 两个线程各执行 1000 次 i++（无锁），结果？","options":["一定是 2000","一定小于 2000","小于等于 2000，且不确定（丢失更新）","编译错误"],"answer":[2],"explain":"i++ 三步（读/加/写）非原子，两个线程可能同时读到旧值各自 +1 后写回，丢失一次更新。volatile 只保证读到最新值，不保证复合操作原子。结果 ≤ 2000 且每次运行可能不同。"}]},{"id":"q-ch15","chapter":"第 15 组 · JVM 深入（面试区分题）","questions":[{"id":"q15-1","type":"single","q":"对象一定分配在堆上吗？","options":["一定","不一定：JIT 逃逸分析后，未逃逸对象可能栈上分配或标量替换","一定在方法区","一定在虚拟机栈"],"answer":[1],"explain":"逃逸分析（-XX:+DoEscapeAnalysis，默认开）：对象不被方法外引用时，可栈上分配（随栈帧销毁，GC 压力归零）或标量替换（拆成基本量放寄存器）。同步锁消除也基于它——这是\\"Java 对象不慢\\"的底气。"},{"id":"q15-2","type":"single","q":"对象在内存中的布局顺序是？","options":["实例数据 → 对象头 → 对齐填充","对象头（Mark Word+类型指针）→ 实例数据 → 对齐填充","对齐填充 → 对象头 → 实例数据","只有实例数据"],"answer":[1],"explain":"对象头（Mark Word 存 hash/GC 年龄/锁标志 8 字节 + 类型指针 4/8 字节）→ 实例数据 → 对齐到 8 字节整数倍。锁升级就靠改 Mark Word 的标志位——这就是为什么面试把\\"对象布局\\"和\\"锁\\"连着问。"},{"id":"q15-3","type":"single","q":"CMS 与 G1 最本质的区别是？","options":["CMS 更快所以更好","CMS 关注最短停顿但会产生碎片；G1 把堆分成 Region，可预测停顿、整体标记整理局部复制、无碎片","G1 是串行的","没有区别"],"answer":[1],"explain":"CMS 标记-清除 → 内存碎片 → 大对象分配提前 Full GC。G1 将堆划分为 ~2048 个 Region，按停顿目标（-XX:MaxGCPauseMillis）优先回收\\"垃圾最多的区域\\"（这就是名字 Garbage First 的由来），JDK 9+ 默认。"},{"id":"q15-4","type":"single","q":" 强引用、软引用、弱引用、虚引用，按强度排序并对应典型用途，正确的是？","options":["强 > 软 > 弱 > 虚；软引用做缓存，弱引用做 ThreadLocal key","强 > 弱 > 软 > 虚","软 > 强 > 弱 > 虚","四种强度一样"],"answer":[0],"explain":"强引用永不回收；软引用内存不足才回收（适合缓存）；弱引用下次 GC 必回收（ThreadLocalMap 的 key、WeakHashMap）；虚引用仅用于跟踪对象被回收的通知（堆外内存回收）。"},{"id":"q15-5","type":"single","q":"类加载的五个阶段顺序是？","options":["加载 → 验证 → 准备 → 解析 → 初始化","加载 → 准备 → 验证 → 初始化 → 解析","验证 → 加载 → 准备 → 解析 → 初始化","加载 → 初始化 → 验证 → 准备 → 解析"],"answer":[0],"explain":"Loading（读字节码）→ Verification（格式/语义校验）→ Preparation（静态变量分配并设零值，final 常量直接赋值）→ Resolution（符号引用转直接引用）→ Initialization（执行 <clinit> 静态赋值与静态块）。"},{"id":"q15-6","type":"single","q":"什么时候会触发类的初始化（主动引用）？","options":["定义了类的数组","访问静态 final 常量","new 对象、调静态方法、反射 Class.forName","子类初始化时父类先加载就算子类主动初始化的全部"],"answer":[2],"explain":"主动引用：new / 读写静态字段（非 final 常量）/ 调静态方法 / 反射 / main 所在类 / 子类初始化连带父类。被动引用不触发：数组定义、访问编译期常量（已放入常量池）、通过子类访问父类静态字段只初始化父类。"},{"id":"q15-7","type":"single","q":"双亲委派机制的工作方式与作用是？","options":["子加载器先自己加载","先委托父加载器（Application→Platform→Bootstrap），父加载不了才自己加载；防止核心类被篡改和重复加载","父加载器委托子加载器","随机选择加载器"],"answer":[1],"explain":"收到加载请求逐级上抛，Bootstrap 能加载就加载（如 java.lang.String 永远是核心库那份，防止自定义 String 伪造 API）；父级无法加载再逐级下放。打破它：SPI（线程上下文类加载器）、Tomcat 隔离应用、热部署。"},{"id":"q15-8","type":"single","q":"以下哪种 OOM 不属于堆内存不足？","options":["Java heap space","GC overhead limit exceeded","Metaspace（元空间溢出）","unable to create new native thread（无法创建线程）"],"answer":[3],"explain":"unable to create new native thread 是操作系统层面线程数/内存限制，不是堆问题——疯狂创建线程或 ulimit 配置小会触发。Metaspace 溢出是动态生成类过多（CGLib 大量代理）。排查第一步永远是看异常关键字+堆 dump。"}]},{"id":"q-ch16","chapter":"第 16 组 · Spring 深入（源码级考点）","questions":[{"id":"q16-1","type":"single","q":"Bean 的生命周期完整顺序是？","options":["实例化 → 属性注入 → Aware → BeanPostProcessor 前置 → 初始化（@PostConstruct/InitializingBean/init-method）→ 后置处理(AOP 代理在此) → 使用 → 销毁","属性注入 → 实例化 → 初始化","初始化 → 实例化 → 注入","实例化 → 初始化 → 属性注入"],"answer":[0],"explain":"核心记忆点：先构造再注入；@PostConstruct 先于 afterPropertiesSet 先于 init-method；AOP 代理对象由 AnnotationAwareAspectJAutoProxyCreator（一个 BeanPostProcessor）在后置处理阶段生成。"},{"id":"q16-2","type":"single","q":"Spring 三级缓存解决循环依赖，第三级缓存放的是？","options":["成品 Bean","半成品 Bean（已实例化未注入属性）","ObjectFactory（工厂，提前生成或返回代理对象）","BeanDefinition"],"answer":[2],"explain":"一级 singletonObjects 成品；二级 earlySingletonObjects 半成品；三级 singletonFactories 工厂——为什么需要三级：AOP 场景下要保证\\"提前暴露的引用\\"和最终代理一致，工厂保证代理只生成一次。注意：构造器注入/prototype 无法靠三级缓存解决循环依赖。"},{"id":"q16-3","type":"single","q":"@Autowired 与 @Resource 的区别是？","options":["完全相同","@Autowired 是 Spring 的，默认按类型（byType），配 @Qualifier 按名；@Resource 是 JDK 标准的，默认按名称（byName）","@Autowired 按名称","@Resource 是 Spring 特有"],"answer":[1],"explain":"@Autowired 找到多个同类型候选时退化为字段名匹配，仍冲突报 NoUniqueBeanDefinitionException；@Resource 先按 name 找再按 type 兜底。面试常追问：构造器注入优于字段注入（不可变、依赖明确、便于单测）。"},{"id":"q16-4","type":"single","q":"Spring 事务的传播行为 REQUIRES_NEW 与 NESTED 的区别是？","options":["完全一样","REQUIRES_NEW 挂起外层事务开独立新事务（互不影响回滚）；NESTED 在外层事务内建保存点（内层回滚不影响外层，外层回滚则内层跟着回滚）","NESTED 是新连接","REQUIRES_NEW 更快"],"answer":[1],"explain":"REQUIRES_NEW = 两个独立事务（两个连接，外层失败不影响内层已提交）；NESTED = 同一物理事务 + JDBC Savepoint（一个连接，真父子关系）。典型场景：批量处理时单条失败只回滚该条用 NESTED；审计日志必须独立提交用 REQUIRES_NEW。"},{"id":"q16-5","type":"single","q":"以下哪种方式无法解决 @Transactional 场景中\\"方法内部自调用\\"失效？","options":["注入自身代理对象（ObjectProvider<自身>）后调用","拆到另一个 Bean","AopContext.currentProxy()（需 exposeProxy=true）","把方法改成 private"],"answer":[3],"explain":"自调用走的是 this（原始对象）而非代理，事务不生效。改 private 更不行——AOP 代理无法拦截 private 方法。另两个经典失效：异常被 catch 吞掉、抛 checked 异常默认不回滚（rollbackFor 未设置）。"},{"id":"q16-6","type":"single","q":"Spring Boot 自动配置的核心机制是？","options":["扫描所有类","@EnableAutoConfiguration → 读取各 starter 的 META-INF/spring/...AutoConfiguration.imports 文件 → 按条件注解（@ConditionalOnClass 等）筛选生效的配置类","JVM 参数注入","启动时联网下载配置"],"answer":[1],"explain":"约定优于配置的实现：starter 带依赖+配置类，Spring Boot 启动时加载 imports 清单，@ConditionalOnClass/MissingBean/Property 判断该不该装配。自定义 starter 就是\\"写配置类+条件注解+注册到 imports 文件\\"。"},{"id":"q16-7","type":"single","q":"@Component 与 @Bean 的使用场景区别是？","options":["完全等价","@Component 标注自己的类靠包扫描；@Bean 写在配置类方法里，用于第三方库对象（改不了源码）或需要复杂装配逻辑","@Bean 只能注入字符串","@Component 不能用"],"answer":[1],"explain":"别人的类你没法加 @Component，只能 @Bean 方法手动 new+装配（如 ObjectMapper、RestTemplate、连接池）。@Bean 默认方法名是 Bean 名；同配置类内 @Bean 方法互调走代理不会重复创建。"},{"id":"q16-8","type":"single","q":"Spring MVC 一个请求的处理流程正确顺序是？","options":["DispatcherServlet → HandlerMapping 找处理器 → HandlerAdapter 执行 → HandlerAdapter 返回 ModelAndView → ViewResolver 解析视图 → 渲染响应（前后端分离则直接 @ResponseBody 序列化）","先渲染再路由","Filter 在 DispatcherServlet 之后","ViewResolver 先于 HandlerMapping"],"answer":[0],"explain":"Filter 在 Servlet 之前（粗粒度，如 CORS/编码）；DispatcherServlet 是统一入口；@ResponseBody 时经 HttpMessageConverter 直接写 JSON，不走视图解析。异常处理链：Controller→@ExceptionHandler→@ControllerAdvice→HandlerExceptionResolver。"}]},{"id":"q-ch17","chapter":"第 17 组 · 消息队列（MQ 专项）","questions":[{"id":"q17-1","type":"single","q":"MQ 消息丢失的三个环节与对策，正确的是？","options":["只在消费端可能丢失","生产端（confirm/事务）、Broker（持久化+刷盘+副本）、消费端（手动 ack，处理完再确认）","只发生在网络断开时","无法避免"],"answer":[1],"explain":"生产端：RabbitMQ confirm / Kafka acks=all；Broker：durable 队列+持久化消息、刷盘策略、多副本；消费端：关自动 ack，业务成功后手动 basicAck，失败重试+死信队列。三环缺一都可能丢。"},{"id":"q17-2","type":"single","q":"Kafka 如何保证同一分区消息有序？","options":["全局天然有序","同一分区有序；需要有序的业务按 key 路由到同一分区（如同一订单 id）","设置 acks 即可","开启事务"],"answer":[1],"explain":"Kafka 只保证分区内有序（追加写+偏移量）。全局有序 = 单分区（牺牲并行度，一般不干）；业务有序 = 按 key（订单 id）哈希分区，同 key 必落同分区。追问：重试可能导致乱序，需 max.in.flight=1 或开启幂等生产者。"},{"id":"q17-3","type":"single","q":"消息重复消费的根本原因与通用解法是？","options":["MQ 有 bug","网络重试机制导致\\"至少一次\\"投递；消费端必须做幂等（唯一键/去重表/Redis setnx/版本号）","升级 MQ 版本","改用同步调用"],"answer":[1],"explain":"消费完成但 ack 丢失 → Broker 重发；生产端超时重试 → Broker 存了两条。分布式系统里\\"恰好一次\\"极难，工程上都是\\"至少一次 + 幂等\\"：业务唯一键约束、消费前查 Redis 去重表、数据库唯一索引兜底。"},{"id":"q17-4","type":"single","q":"消息积压百万条，紧急处理思路是？","options":["重启 MQ","定位消费速度瓶颈 → 扩消费者/批量消费 → 极端情况新起临时 topic 分摊 + 专门程序搬运 → 事后根治消费逻辑慢 SQL","等它自己消化","直接丢弃"],"answer":[2],"explain":"先看监控定位：是消费端慢（DB 慢查询）还是生产突增。修复消费逻辑后扩容；Kafka 扩分区+消费者同数量扩容；RabbitMQ 换预取参数。预案：消费限流、告警阈值（积压量监控）。"},{"id":"q17-5","type":"single","q":"RocketMQ 事务消息的两阶段流程是？","options":["直接发送即可","先发半消息（对消费者不可见）→ 执行本地事务 → 提交/回滚半消息；Broker 定时回查未决事务","先提交本地事务再发消息","依赖数据库 XA"],"answer":[1],"explain":"解决\\"本地事务与发消息的原子性\\"：①发 half 消息 ②执行本地事务 ③commit（消息可见）/rollback（删除）④超时未决则回查本地事务状态。相比\\"本地消息表\\"省一张表，但要实现回查接口。"}]},{"id":"q-ch18","chapter":"第 18 组 · 分布式系统（架构考点）","questions":[{"id":"q18-1","type":"single","q":"CAP 理论中，P 指的是什么？工程上的取舍通常是？","options":["性能 Performance；追求极致性能","分区容错性（网络分区仍可用）；网络分区无法避免，实际是在 CP（如 ZooKeeper/etcd）与 AP（如 Eureka/Redis 主从）之间取舍","协议 Protocol","并发 Concurrency"],"answer":[1],"explain":"分布式系统网络分区（节点间断联）不可避免，P 必选。分区发生时二选一：拒绝写入保一致（CP，选主期间不可用）或继续服务但数据可能旧（AP）。BASE（基本可用+软状态+最终一致）是 AP 的工程化延伸。"},{"id":"q18-2","type":"single","q":"分布式锁用数据库/Redis/ZooKeeper 实现，正确对比是？","options":["数据库性能最好","Redis（SET NX PX + 唯一值 + Lua 释放或 Redisson 看门狗）性能高，RedLock 有争议；ZK 临时顺序节点可靠性高但吞吐低；DB 乐观锁 version 简单适合低并发","三种完全等价","ZK 性能最高"],"answer":[1],"explain":"Redis 锁要点：原子 SET NX EX、value 放唯一 id 防误删他人锁、释放用 Lua（判断+删除原子）；Redisson 看门狗自动续期。ZK 客户端断连会话消失锁自动释放（无死锁）但性能低。DB 锁靠唯一索引插入或乐观锁。"},{"id":"q18-3","type":"single","q":"Raft 与 Paxos 的关系，及 Raft 三种角色是？","options":["完全不同","Raft 是 Paxos 的可理解化工程实现（拆分 Leader 选举/日志复制/安全性）；角色 Leader/Follower/Candidate","Raft 更难懂","只有 Leader 一种"],"answer":[1],"explain":"Raft 把共识拆成三个子问题：选主（任期 term + 随机超时 + 多数投票）、日志复制（Leader 收写请求 → 复制给 Follower → 多数确认后提交）、安全性（只有日志最新的才能当选）。etcd/Consul/Nacos(Raft) 都用它。"},{"id":"q18-4","type":"single","q":"分布式 ID 生成方案中，雪花算法的结构是？时钟回拨怎么办？","options":["纯随机数，无回拨问题","64 位 = 1 符号 + 41 时间戳 + 10 机器 id + 12 序列号；回拨可等待/用备用位/拒发并告警","自增数字","UUID 最优"],"answer":[1],"explain":"41 位时间戳约 69 年，12 位序列单机每毫秒 4096 个。回拨（NTP 校时）会导致重复 ID：小回拨等上次时间追平，大回拨报警拒绝服务或切换 workerId。UUID 无序不适合做聚簇索引主键（页分裂）。"},{"id":"q18-5","type":"single","q":"限流算法中，令牌桶与漏桶的核心区别是？","options":["没有区别","漏桶恒定速率流出（削峰整形）；令牌桶按速率放令牌、桶内可积攒，允许一定突发流量","令牌桶不能限流","漏桶只用于单机"],"answer":[1],"explain":"漏桶：请求进桶，以固定速率流出，超桶拒绝——输出绝对平滑。令牌桶：恒速生成令牌入桶（有容量上限），请求拿到令牌才通过——允许突发（桶里攒了 N 个令牌就能瞬间放行 N 个）。Guava RateLimiter、Sentinel 都是令牌桶系。"},{"id":"q18-6","type":"single","q":"分布式链路追踪中，一次请求的 TraceId 与 SpanId 关系是？","options":["两者相同","全链路一个 TraceId 贯穿；每个环节（服务/方法）有自己的 SpanId 和父 SpanId，形成调用树","每个服务换新 TraceId","没有关系"],"answer":[1],"explain":"TraceId 在入口网关生成，通过 HTTP header/MQ 消息头透传全链路（日志都带上它，grep 一把看全程）；SpanId 标识调用节点，parentId 串出树状拓扑。SkyWalking/Zipkin 据此可视化耗时热点与故障定位。"}]},{"id":"q-ch19","chapter":"第 19 组 · Linux 与部署运维","questions":[{"id":"q19-1","type":"single","q":"排查\\"服务器 CPU 100%\\"的第一套命令组合是？","options":["top → 找到进程 → top -Hp 进程找线程 → printf 转十六进制 → jstack 按线程 id 定位代码","重启服务器","free -m","df -h"],"answer":[0],"explain":"标准五连：top 找 pid → top -Hp pid 找最耗 CPU 的线程 tid → printf \\"%x\\" tid 转十六进制 → jstack pid | grep 十六进制 -A 20 定位栈 → 看 CPU 型（业务死循环/GC 线程疯狂跑=内存问题转移）。"},{"id":"q19-2","type":"single","q":"查看 8080 端口被哪个进程占用，最常用的命令是？","options":["ls -l","lsof -i:8080 或 ss -tlnp | grep 8080","top","pwd"],"answer":[1],"explain":"lsof -i:8080（列文件句柄含网络）；ss -tlnp（netstat 现代替代，更快）；找到 pid 后 ps -ef | grep pid 看详情，kill -9 pid 强杀。找文件被谁占用则用 lsof 文件路径。"},{"id":"q19-3","type":"single","q":"grep 在当前目录递归搜索包含 \\"OutOfMemory\\" 的日志文件，正确写法是？","options":["grep OutOfMemory *","grep -r \\"OutOfMemory\\" . ","find OutOfMemory","cat | OutOfMemory"],"answer":[1],"explain":"grep -r 递归 + -n 显示行号 + -i 忽略大小写 + -C 3 显示上下文。大日志常用组合：grep \\"ERROR\\" app.log | tail -100；实时追踪 tail -f app.log | grep --color error。"},{"id":"q19-4","type":"single","q":"chmod 754 file 的权限含义是？","options":["所有者读写执行、组读、其他只读","所有人全部权限","所有者只读","组可写"],"answer":[0],"explain":"754 = rwxr-xr--：7=4+2+1（所有者读写执行），5=4+1（组读执行），4（其他只读）。常用：755 脚本可执行、644 配置文件、600 私钥。chown 改属主，-R 递归。"},{"id":"q19-5","type":"single","q":"Docker 中 -v /data:/app/data 参数的作用是？","options":["复制文件","数据卷挂载：把宿主机 /data 目录映射到容器 /app/data，容器删除数据仍在宿主机","设置环境变量","端口映射"],"answer":[1],"explain":"数据卷解决\\"容器可丢弃、数据要长存\\"。-p 8080:80 才是端口映射，-e 设环境变量，--name 命名。部署 MySQL/Redis 必配卷，否则容器重建数据全丢（跟平台部署规范一个道理）。"}]},{"id":"q-ch20","chapter":"第 20 组 · MyBatis 与接口设计","questions":[{"id":"q20-1","type":"single","q":"MyBatis 中 #{} 与 ${} 的本质区别是？","options":["完全等价","#{} 预编译占位符（防 SQL 注入）；${} 字符串拼接（有注入风险，仅用于动态表名/列名且需白名单校验）","${} 更安全","#{} 会拼接字符串"],"answer":[1],"explain":"#{} 生成 PreparedStatement 的 ? 参数——值不参与 SQL 解析，天然防注入；${} 直接文本替换进 SQL。排序字段 ORDER BY ${column} 必须后端白名单映射，绝不能透传用户输入。"},{"id":"q20-2","type":"single","q":"MyBatis 一级缓存与二级缓存的正确说法是？","options":["都是跨会话共享","一级缓存 SqlSession 级默认开启（同会话相同查询走缓存，增删改或 commit 清空）；二级 namespace 级需手动开启，跨会话共享但多表关联易脏读，生产慎用","二级默认开启","一级默认关闭"],"answer":[1],"explain":"一级缓存天然存在且安全；二级缓存以 namespace 为单位，A 表的 namespace 缓存感知不到 B 表的更新 → 脏数据。生产更常用 Redis 自定义缓存（实现 Cache 接口）或干脆交给应用层缓存。"},{"id":"q20-3","type":"single","q":"RESTful 设计中，\\"更新用户\\"最规范的接口是？","options":["GET /user/update?id=1","PUT /users/1（部分更新用 PATCH /users/1），请求体携带变更字段","POST /getUser","DELETE /users"],"answer":[1],"explain":"RESTful 核心：URL 是名词复数（/users），HTTP 方法表达动作（GET 查/POST 建/PUT 全量改/PATCH 局部改/DELETE 删），状态码表达结果（200/201/204/400/404/409）。幂等性：GET/PUT/DELETE 幂等，POST 不幂等。"},{"id":"q20-4","type":"single","q":"接口幂等性设计，下列哪种方案不适合\\"防重复下单\\"？","options":["前端按钮防抖（辅助手段）","唯一业务键（订单号）+ 数据库唯一索引兜底","Redis setnx 预检查","GET 请求发三遍看结果"],"answer":[3],"explain":"幂等 = 同一操作执行多次效果与一次相同。分层防护：前端防抖（体验层）→ 网关/Redis 去重（拦截层）→ DB 唯一索引（最终兜底，绝不能省）。GET 三遍是测试手段不是方案。"}]},{"id":"q-ch21","chapter":"第 21 组 · 高频场景设计题","questions":[{"id":"q21-1","type":"single","q":"秒杀系统最核心要解决的问题是？","options":["页面好看","超卖与瞬时流量：Redis 预扣库存（Lua 原子）削峰 + MQ 异步下单 + 多层限流兜底","数据库字段设计","前端动画"],"answer":[1],"explain":"标准链路：CDN/按钮置灰挡量 → 网关限流（令牌桶）→ Redis Lua 原子预扣库存（防超卖）→ 发 MQ → 消费端落库下单 → 超时未付回补库存。库存校验和扣减必须原子（Lua），DB 层 stock > 0 条件更新兜底。"},{"id":"q21-2","type":"single","q":"\\"如何设计一个短链系统\\"中，短码生成的合理方案是？","options":["随机拼字符串不查重","发号器自增 id + Base62 编码（或哈希+布隆查重），302 跳转 + Redis 缓存热点映射","存全文映射表","用 UUID 全长"],"answer":[1],"explain":"自增 id 经 Base62 压成 6 位（620 亿+）天然不冲突；哈希方案需处理冲突（布隆过滤器预查）。跳转用 302（临时，可统计）不是 301（浏览器缓存，统计不到）。高频短链进 Redis，读多写少经典场景。"},{"id":"q21-3","type":"single","q":"微信朋友圈/微博 Feed 流的\\"推拉结合\\"是指？","options":["一半推一半猜","大 V 写入时推给粉丝太贵 → 普通用户写扩散（推模式，写时进粉丝收件箱）；大 V 用读扩散（拉模式，读时聚合），两者结合","先推后拉所有","只拉不推"],"answer":[1],"explain":"推模式写时扇出到每个粉丝收件箱（读快、写贵、僵尸粉浪费）；拉模式读时去关注列表逐个拉最新（写省、读慢）。工程：粉丝少的走推、百万粉大 V 走拉+推混合，收件箱用 Redis ZSet（时间戳排序）。"},{"id":"q21-4","type":"single","q":"对账系统发现\\"支付成功但订单未更新\\"，最稳妥的自动修复机制是？","options":["人工改库","定时对账任务比对两端状态 + 自动补偿（重试/反向冲正）+ 告警，配合死信队列处理失败补偿","删除该订单","重启支付服务"],"answer":[1],"explain":"跨系统一致性没有银弹，靠\\"对账+补偿\\"兜底：T+1 或准实时对账拉平差异；补偿遵循幂等；连续 N 次补偿失败转人工工单。这体现了分布式思维：允许短暂不一致，但要有发现与修复机制。"}]}]');
INSERT INTO json_doc (name, data) VALUES ('syllabusModules', '[{"id":"mod-java","icon":"☕","name":"Java SE 语言核心","weight":30,"desc":"所有后续内容的地基。面试笔试 70% 的题出自这里，必须学到\\"能默写原理\\"的程度。","units":[{"name":"开发环境：JDK 安装、环境变量、IDEA 使用、第一个 HelloWorld","why":"工具是起点，环境搭不好后面全卡住","days":2,"level":"必修"},{"name":"基础语法：变量、数据类型（8 大基本类型）、运算符、类型转换","why":"一切代码的最小单元","days":3,"level":"必修"},{"name":"流程控制：if/else、switch、for、while、break/continue","why":"程序的\\"岔路口\\"，逻辑思维能力训练","days":2,"level":"必修"},{"name":"方法（函数）：定义、参数传递、重载、递归","why":"代码复用的第一步，面试常考\\"值传递\\"","days":2,"level":"必修"},{"name":"数组：一维/二维数组、遍历、排序、Arrays 工具类","why":"最基础的数据结构，算法题的载体","days":3,"level":"必修"},{"name":"面向对象：类与对象、构造器、this、封装/继承/多态","why":"Java 的灵魂，面试必问三大特性","days":6,"level":"必修"},{"name":"修饰符与关键字：static、final、访问权限、代码块、内部类","why":"面试高频：static 加载时机、final 语义","days":3,"level":"必修"},{"name":"抽象类与接口：abstract、interface、default 方法、设计意义","why":"面试必问\\"抽象类和接口的区别\\"","days":2,"level":"必修"},{"name":"常用 API：String/StringBuilder、包装类与缓存池、Object 方法、日期时间","why":"String 不可变与 127 缓存是顶级高频面试题","days":4,"level":"必修"},{"name":"集合框架：ArrayList/LinkedList、HashMap/LinkedHashMap/TreeMap、HashSet、迭代器、Collections","why":"面试出场率第一的知识点，HashMap 原理必须背熟","days":6,"level":"必修"},{"name":"异常处理：try/catch/finally、受检与非受检异常、自定义异常","why":"finally 执行顺序、异常体系分类是笔试常客","days":2,"level":"必修"},{"name":"泛型：泛型类/接口/方法、通配符 ? extends/super、类型擦除","why":"类型擦除原理是区分度很高的面试题","days":2,"level":"必修"},{"name":"IO 流：字节流/字符流、缓冲流、序列化、Try-with-resources","why":"文件读写、网络编程的基础","days":3,"level":"必修"},{"name":"多线程与并发：Thread、Runnable、线程状态、synchronized、volatile、Lock、线程池、ThreadLocal、CAS","why":"大厂面试必考，线程池参数要能默写","days":8,"level":"必修"},{"name":"JVM 虚拟机：内存区域、类加载机制、双亲委派、GC 算法与垃圾回收器、JVM 调优入门","why":"区分初级和中级的分水岭","days":6,"level":"必修"},{"name":"Java 8+ 新特性：Lambda、Stream API、Optional、新日期 API","why":"工作代码天天在用，面试也爱问","days":3,"level":"必修"},{"name":"网络编程：Socket、BIO/NIO 概念","why":"理解 HTTP 底层与 Netty 的前置","days":2,"level":"进阶"},{"name":"反射与注解：Class 对象、动态代理、自定义注解","why":"Spring 框架原理的基石","days":3,"level":"进阶"},{"name":"设计模式：单例（5 种写法）、工厂、建造者、模板方法、策略、观察者、代理","why":"面试手写单例、Spring 里全是模式","days":5,"level":"进阶"}]},{"id":"mod-db","icon":"🗄️","name":"MySQL 数据库","weight":18,"desc":"后端工程师吃饭的家伙。CRUD 是底线，索引和事务原理是面试分水岭。","units":[{"name":"数据库概念与安装：库/表/行/列、MySQL 安装、客户端连接（Navicat/DataGrip）","why":"先会用工具再谈原理","days":2,"level":"必修"},{"name":"SQL 基础：DDL 建库建表、DML 增删改、DQL 查询、WHERE/ORDER/LIMIT","why":"每天都要写的看家本领","days":4,"level":"必修"},{"name":"多表查询：内连接、左/右外连接、子查询、UNION","why":"业务查询 90% 涉及多表","days":3,"level":"必修"},{"name":"聚合与分组：COUNT/SUM/AVG、GROUP BY、HAVING、执行顺序","why":"SQL 笔试题的核心考点","days":2,"level":"必修"},{"name":"数据库设计：三大范式、主外键、ER 图、常见业务表设计（用户/订单/商品）","why":"面试会问\\"给你一个业务你怎么建表\\"","days":2,"level":"必修"},{"name":"索引：B+ 树结构、聚簇/二级索引、回表、最左前缀、覆盖索引、索引失效场景、EXPLAIN","why":"面试出场率第二的知识点","days":4,"level":"必修"},{"name":"事务：ACID、隔离级别与脏读/不可重复读/幻读、MVCC 原理、锁机制（行锁/间隙锁）","why":"原理八股必考题","days":4,"level":"必修"},{"name":"SQL 优化：慢查询定位、优化思路、大表分页优化、深分页","why":"实际工作和面试都高频","days":2,"level":"必修"},{"name":"连接池：Druid/HikariCP 配置与原理","why":"为什么不能每次请求都建连接","days":1,"level":"必修"},{"name":"其他数据库视野：PostgreSQL、MongoDB、分库分表概念（ShardingSphere）","why":"技术选型视野，大厂数据量大必问","days":3,"level":"加分"}]},{"id":"mod-web","icon":"🎨","name":"前端开发（全栈必备）","weight":12,"desc":"后端向前端的目标：能看懂、能改、能联调、能排错。不用像素级还原设计稿。","units":[{"name":"HTML：常用标签、表单、语义化","why":"网页骨架","days":2,"level":"必修"},{"name":"CSS：选择器、盒模型、Flex 布局、定位、响应式入门","why":"Flex 是现代布局标准答案","days":4,"level":"必修"},{"name":"JavaScript 基础：变量、数据类型、函数、对象、数组方法、DOM 操作、事件","why":"前端唯一编程语言","days":5,"level":"必修"},{"name":"ES6+：let/const、箭头函数、解构、模板字符串、Promise、async/await、模块化","why":"现代前端代码全部是 ES6 语法","days":3,"level":"必修"},{"name":"网络请求：fetch/Axios、JSON、RESTful 调用、跨域 CORS","why":"前后端联调的桥梁，跨域报错必会解决","days":2,"level":"必修"},{"name":"Vue 3：组合式 API、响应式原理（ref/reactive）、组件通信、Vue Router、Pinia","why":"国内市场占有率最高，教程生态最好","days":7,"level":"必修"},{"name":"工程化视野：Vite/Webpack、Node.js 基本概念","why":"知道前端项目怎么跑起来的","days":2,"level":"进阶"},{"name":"React 基础视野：组件、JSX、Hooks 概念","why":"多一门手艺，简历加分","days":3,"level":"加分"}]},{"id":"mod-spring","icon":"🍃","name":"后端框架（Spring 全家桶）","weight":20,"desc":"从\\"会写 Java\\"到\\"会做后端\\"的惊险一跃。学完这章才能独立开发完整接口。","units":[{"name":"Maven：坐标、依赖管理、依赖传递与冲突、生命周期、多模块","why":"不会 Maven 寸步难行","days":2,"level":"必修"},{"name":"Spring 核心概念：IoC 容器、DI 依赖注入、Bean 作用域与生命周期","why":"面试必问 IoC/AOP，要用自己的话讲清","days":3,"level":"必修"},{"name":"AOP：切面、通知类型、切点表达式、应用场景（日志/事务/权限）","why":"Spring 声明式事务的原理","days":2,"level":"必修"},{"name":"Spring MVC / Spring Boot：自动配置原理、starter、配置文件、DispatcherServlet 流程","why":"自动配置原理是 Spring Boot 最高频面试题","days":4,"level":"必修"},{"name":"Web 开发三大件：Controller、Service、Mapper 三层架构与职责","why":"所有公司项目的标准结构","days":2,"level":"必修"},{"name":"MyBatis / MyBatis-Plus：CRUD、resultMap、动态 SQL、#{} 与 ${} 区别、分页","why":"#{} 防注入原理是必考点","days":3,"level":"必修"},{"name":"RESTful API 设计：资源命名、HTTP 方法语义、状态码、接口文档（Swagger/Knife4j）","why":"前后端协作的契约","days":2,"level":"必修"},{"name":"参数校验与全局异常：@Validated、@ControllerAdvice、统一返回结果","why":"工程规范，面试项目深挖必问","days":1,"level":"必修"},{"name":"登录认证：Session vs JWT、Token 设计、拦截器/过滤器、Spring Security 视野","why":"几乎每个项目都要登录","days":3,"level":"必修"},{"name":"Spring 事务：@Transactional、传播行为、失效场景","why":"\\"事务失效的 N 种场景\\"是经典八股","days":2,"level":"必修"},{"name":"定时任务与异步：@Scheduled、@Async、线程池整合","why":"常见业务需求","days":1,"level":"必修"},{"name":"日志体系：SlF4J + Logback、日志级别、排查问题的正确姿势","why":"线上排错靠日志","days":1,"level":"必修"},{"name":"单元测试：JUnit 5、Mockito、测试金字塔","why":"大厂工程素养考察点","days":2,"level":"进阶"},{"name":"微服务视野：Spring Cloud（注册中心/网关/Feign/熔断限流）","why":"大厂标配，校招加分项","days":7,"level":"进阶"}]},{"id":"mod-mid","icon":"⚡","name":"中间件与分布式","weight":12,"desc":"高并发系统的武器库，也是大厂面试区分度最大的部分。","units":[{"name":"Redis 五大类型与应用场景：String/Hash/List/Set/ZSet","why":"每种类型配一个业务场景是标准答法","days":2,"level":"必修"},{"name":"Redis 缓存三大问题：穿透/击穿/雪崩 的原因与方案（布隆过滤器/互斥锁/过期打散）","why":"缓存八股铁三角，必背","days":2,"level":"必修"},{"name":"Redis 进阶：持久化 RDB/AOF、过期淘汰策略、分布式锁 SETNX、缓存一致性","why":"缓存与数据库一致性是高频场景题","days":3,"level":"必修"},{"name":"消息队列价值与选型：解耦/异步/削峰、RabbitMQ/Kafka/RocketMQ 对比","why":"\\"为什么用 MQ\\"要能讲出三大价值","days":2,"level":"必修"},{"name":"MQ 进阶：消息丢失/重复消费/顺序消息、死信队列、幂等性设计","why":"消息可靠性三连问是面试套路","days":3,"level":"必修"},{"name":"Nginx：反向代理、负载均衡策略、动静分离、限流","why":"部署必会，\\"Nginx 干什么的\\"必问","days":2,"level":"必修"},{"name":"Elasticsearch：倒排索引、分词、DSL 查询、与 MySQL 数据同步","why":"搜索场景标配，中高级岗位常问","days":3,"level":"进阶"},{"name":"分布式理论视野：CAP/BASE、分布式 ID、分布式事务（Seata）概念","why":"高级岗位敲门砖","days":3,"level":"加分"}]},{"id":"mod-eng","icon":"🛠️","name":"工程化与运维基础","weight":8,"desc":"让代码\\"能协作、能上线、能排查\\"。入职第一天就要用的东西。","units":[{"name":"Git：add/commit/push/pull、分支与合并、解决冲突、rebase 与 merge 区别、团队协作流","why":"不会 Git 无法参与任何团队项目","days":2,"level":"必修"},{"name":"Linux 常用命令：文件操作、vim、进程管理、端口/日志排查（ps/top/netstat/grep/tail）","why":"服务器都是 Linux","days":3,"level":"必修"},{"name":"Docker：镜像/容器、Dockerfile、docker-compose、部署 Spring Boot + MySQL","why":"环境一致性神器，面试常问\\"docker 干什么用\\"","days":3,"level":"必修"},{"name":"CI/CD 概念：流水线、自动化构建部署（Jenkins/GitLab CI 视野）","why":"知道代码从提交到上线的全流程","days":1,"level":"进阶"},{"name":"接口调试工具：Postman/Apifox、抓包（F12/Charles）","why":"联调排错日频率工具","days":1,"level":"必修"}]},{"id":"mod-algo","icon":"⚔️","name":"算法与数据结构","weight":15,"desc":"笔试硬门槛。校招简历关之后的笔试挂人最多的一关，必须每天保持手感。","units":[{"name":"复杂度分析：时间/空间复杂度、最好最坏平均","why":"所有题都要先分析复杂度","days":1,"level":"必修"},{"name":"数组与双指针：两数之和、三数之和、移动零、盛水容器","why":"最高频入门题型","days":4,"level":"必修"},{"name":"哈希表：字母异位词、交集、两数之和进阶","why":"空间换时间的标准套路","days":2,"level":"必修"},{"name":"链表：反转链表、合并有序链表、环检测（快慢指针）、删除倒数第 N 个","why":"指针操作是手撕代码高频","days":4,"level":"必修"},{"name":"栈与队列：有效括号、最小栈、用栈实现队列","why":"括号匹配是入门必会","days":2,"level":"必修"},{"name":"字符串：最长无重复子串（滑动窗口）、回文判断","why":"滑动窗口模板题","days":2,"level":"必修"},{"name":"二叉树：前中后序遍历、层序遍历（BFS）、最大深度、翻转、最近公共祖先","why":"递归思维的主战场","days":5,"level":"必修"},{"name":"排序算法：冒泡/快排/归并原理、TopK 问题","why":"手撕快排是经典面试题","days":3,"level":"必修"},{"name":"二分查找：标准二分、旋转数组、边界处理","why":"细节多易出错，考细心","days":2,"level":"必修"},{"name":"动态规划入门：爬楼梯、House Robber、最大子数组和","why":"DP 是中等题分水岭","days":4,"level":"必修"},{"name":"回溯算法：全排列、子集、组合总和","why":"面试中等题常客","days":3,"level":"进阶"},{"name":"海量数据题视野：TopK（堆）、布隆过滤器、LRU 缓存设计","why":"大厂特色题","days":3,"level":"加分"}]},{"id":"mod-soft","icon":"🧭","name":"软技能与求职","weight":5,"desc":"决定 offer 上限的隐形分。技术再好，讲不出来也白搭。","units":[{"name":"做项目：独立完成 2 个完整项目（博客系统 + 商城/秒杀），吃透每一个技术选型","why":"项目是面试 60% 的谈资","days":30,"level":"必修"},{"name":"写简历：STAR 法则写项目、突出量化结果、避坑\\"精通\\"字眼","why":"简历关是一切的门票","days":2,"level":"必修"},{"name":"八股文系统背诵：Java/集合/并发/JVM/MySQL/Redis/Spring 分模块过","why":"国内面试绕不开的规则","days":21,"level":"必修"},{"name":"模拟面试：自我介绍、项目介绍 3 分钟版、反问环节","why":"表达力需要刻意练习","days":3,"level":"必修"},{"name":"技术视野：技术博客/GitHub、看源码的方法论、新技术敏感度","why":"长期竞争力","days":7,"level":"加分"}]},{"id":"mod-jvm-adv","icon":"🧠","name":"JVM 与性能工程（进阶）","weight":8,"desc":"从\\"会用 Java\\"到\\"懂 Java 运行时\\"的分水岭，中高级面试的深水区。","units":[{"name":"JMM 内存模型：主内存/工作内存、happens-before 八大规则、volatile/内存屏障","why":"并发正确性的理论根基","days":4,"level":"进阶"},{"name":"对象探秘：对象创建流程、内存布局（对象头/实例数据/对齐）、逃逸分析与栈上分配","why":"理解锁升级与 JIT 优化的前提","days":3,"level":"进阶"},{"name":"GC 器全景：CMS 四阶段、G1 Region/Humongous/Mixed GC、ZGC 染色指针，三色标记与漏标修复","why":"选型与调优的地图","days":5,"level":"进阶"},{"name":"GC 日志分析与调优闭环：gceasy/gcviewer、jstat、常见调优参数与调参方法论","why":"线上 JVM 问题的主战场","days":4,"level":"进阶"},{"name":"排错工具链：jmap/jstack/jstat/arthas/MAT 内存分析，OOM 与 CPU 100% 标准排查流程","why":"生产事故急救包","days":4,"level":"必修"},{"name":"类加载机制：双亲委派、打破场景（SPI/Tomcat/热部署）、自定义类加载器","why":"框架理解与面试高频","days":3,"level":"进阶"},{"name":"字节码与 JIT：javap 读字节码、分层编译 C1/C2、方法内联、JMH 基准测试","why":"理解\\"Java 慢在哪快在哪\\"","days":4,"level":"加分"},{"name":"容器化 JVM：cgroup 感知、MaxRAMPercentage、堆外内存（DirectMemory/Metaspace）与 OOMKilled","why":"云原生时代必备","days":2,"level":"进阶"},{"name":"性能优化实战：慢接口定位方法论、池化/缓存/异步/批量化四大优化手段","why":"性能是综合工程不是玄学","days":5,"level":"进阶"}]},{"id":"mod-spring-adv","icon":"🍃","name":"Spring 深度与云原生（进阶）","weight":8,"desc":"源码级理解 Spring 的\\"为什么\\"，并向微服务/云原生延伸。","units":[{"name":"IoC 源码主线：BeanDefinition → BeanFactoryPostProcessor → 实例化 → BeanPostProcessor → 事件","why":"理解扩展点才能玩转框架","days":5,"level":"进阶"},{"name":"循环依赖与三级缓存、@Lazy 原理、Boot 2.6 禁用循环依赖的启示","why":"高频面试题+设计反思","days":2,"level":"进阶"},{"name":"事务源码与传播行为实战：TransactionInterceptor、挂起/嵌套/独立事务场景落地","why":"事务问题排错的能力来源","days":3,"level":"进阶"},{"name":"AOP 深入：代理创建时机、拦截器链责任链执行、注解驱动切面（自定义 @LogRecord）","why":"横切关注点的工程化","days":3,"level":"进阶"},{"name":"Boot 启动流程与自动装配源码：refresh 主线、@Conditional 体系、自定义 starter","why":"从使用者到造轮子者","days":4,"level":"进阶"},{"name":"Spring Security：过滤器链、认证/授权模型、JWT 集成、RBAC 落地","why":"所有后端都绕不开安全","days":4,"level":"必修"},{"name":"Spring Cloud 核心件：Nacos 注册配置、Gateway 网关、OpenFeign 声明调用、Sentinel 熔断限流","why":"微服务落地四件套","days":6,"level":"进阶"},{"name":"可观测性：Actuator + Micrometer + Prometheus + Grafana、SkyWalking 链路追踪","why":"没有度量就没有优化","days":4,"level":"进阶"},{"name":"K8s 部署 Java 应用：Dockerfile 多阶段、探针、优雅停机、HPA 弹性伸缩","why":"云原生基本功","days":5,"level":"加分"}]},{"id":"mod-distributed","icon":"🌐","name":"分布式系统与架构设计（进阶）","weight":7,"desc":"面向高级岗与系统设计面试的思维体操。","units":[{"name":"分布式理论：CAP/BASE、Paxos/Raft 推导、一致性与可用性的工程取舍","why":"架构决策的理论依据","days":4,"level":"进阶"},{"name":"分布式 ID：UUID 的坑、雪花算法与时钟回拨、号段模式（Leaf）","why":"每个系统都要发 ID","days":2,"level":"进阶"},{"name":"分布式锁三实现：DB/Redis（Redisson 看门狗）/ZK，fencing token 争议","why":"高频面试与真实需求","days":3,"level":"进阶"},{"name":"分布式事务全家桶：2PC/3PC、TCC（空回滚/悬挂）、Saga、本地消息表、MQ 事务消息","why":"跨服务数据一致的武器库","days":5,"level":"进阶"},{"name":"限流熔断降级：计数器/漏桶/令牌桶/滑动窗口、Sentinel 规则、集群限流","why":"过载保护的组合拳","days":3,"level":"进阶"},{"name":"一致性哈希与数据分片：哈希槽/虚拟节点、分库分表中间件（ShardingSphere）","why":"数据量增长必答题","days":4,"level":"进阶"},{"name":"高并发场景设计：秒杀/Feed 流/短链/签到/计数，需求澄清与容量估算方法论","why":"大厂系统设计面试核心","days":6,"level":"进阶"},{"name":"API 设计进阶：幂等键、版本管理、契约测试、防重放签名","why":"开放接口的工程素养","days":2,"level":"必修"}]}]');
INSERT INTO json_doc (name, data) VALUES ('syllabusStats', '{"totalPoints":107,"mustDays":248,"allDays":384,"moduleCount":11}');
INSERT INTO json_doc (name, data) VALUES ('topicsCollections', '[{"id":"top-arraylist","icon":"📦","tag":"集合源码","title":"ArrayList 源码级剖析：扩容机制与 fail-fast","desc":"为什么查询快增删慢？扩容为什么是 1.5 倍？RandomAccess 接口有什么用？remove 遍历为什么踩坑？源码级答案全在这。","blocks":[{"t":"h","html":"一、核心字段：一个数组 + 一个 size，仅此而已"},{"t":"code","lang":"java","title":"ArrayList 核心字段（JDK8+）","code":"public class ArrayList<E> extends AbstractList<E>\\n        implements List<E>, RandomAccess, Cloneable, java.io.Serializable {\\n\\n    private static final int DEFAULT_CAPACITY = 10;      // 默认初始容量\\n    private static final Object[] EMPTY_ELEMENTDATA = {}; // 空数组（有参构造且 size=0 时用）\\n    private static final Object[] DEFAULTCAPACITY_EMPTY_ELEMENTDATA = {}; // 无参构造用\\n\\n    transient Object[] elementData;  // 真正存数据的地方（transient：序列化时跳过，自定义 writeObject 按 size 序列化，省空间）\\n    private int size;                // 实际元素个数（注意：不是数组容量！）\\n}"},{"t":"warn","html":"<b>面试重灾区：</b>无参构造 <code>new ArrayList&lt;&gt;()</code> 在 JDK8 之后<b>并不会立刻创建长度 10 的数组</b>，而是指向空数组 <code>DEFAULTCAPACITY_EMPTY_ELEMENTDATA</code>，第一次 add 时才扩到 10——这就是著名的「懒初始化」优化（JDK6 是构造时就分配 10）。"},{"t":"h","html":"二、add 与 grow：1.5 倍扩容的完整链路"},{"t":"code","lang":"java","title":"add → ensureCapacityInternal → grow（源码精简版）","code":"public boolean add(E e) {\\n    ensureCapacityInternal(size + 1);  // 先确保装得下\\n    elementData[size++] = e;           // 再赋值，size 后移\\n    return true;\\n}\\n\\nprivate void grow(int minCapacity) {\\n    int oldCapacity = elementData.length;\\n    int newCapacity = oldCapacity + (oldCapacity >> 1);  // ★ 1.5 倍：old + old/2（位运算）\\n    if (newCapacity - minCapacity < 0)\\n        newCapacity = minCapacity;                        // 1.5 倍还不够就直接用所需值\\n    if (newCapacity - MAX_ARRAY_SIZE > 0)\\n        newCapacity = hugeCapacity(minCapacity);          // 溢出保护\\n    elementData = Arrays.copyOf(elementData, newCapacity); // ★ 底层 System.arraycopy 整体搬移\\n}"},{"t":"steps","html":"第一次 add(1) 的完整时间线：","items":["elementData 是空数组（长度 0）→ minCapacity = max(10, 0+1) = 10（DEFAULTCAPACITY_EMPTY_ELEMENTDATA 才有这个 max(…, 10) 逻辑）","grow：oldCapacity = 0，newCapacity = 0 + 0 = 0 < 10 → 取 10，Arrays.copyOf 分配新数组","elementData[0] = 1，size 变为 1","第 11 次 add：minCapacity = 11 > 10 → grow：10 + (10>>1) = 15 → 之后 22、33、49…（每次 ×1.5）"]},{"t":"qa","q":"为什么是 1.5 倍而不是 2 倍或固定增量？","a":"① <b>1.5 倍的空间换时间平衡点</b>：增长太慢（如固定 +10）扩容频繁均摊成本高；增长太快（如 2 倍、4 倍）浪费内存且老数组 copyOf 一次性开销大。② <b>oldCapacity + (oldCapacity >> 1)</b> 位运算比乘法快，且 1.5 倍已能保证均摊 O(1)。③ 对照记忆：HashMap 扩容是 2 倍——因为它要求容量是 2 的幂（hash & (n-1) 取模优化），两者约束不同，别混。"},{"t":"h","html":"三、get/set 与 remove：随机访问 O(1)、删除 O(n) 的根源"},{"t":"code","lang":"java","title":"get 与 remove 源码","code":"public E get(int index) {\\n    rangeCheck(index);\\n    return elementData(index);        // ★ 就是数组下标寻址：内存地址 = 首地址 + index × 元素大小\\n}                                     //    这就是「查询快」的全部秘密——O(1)\\n\\npublic E remove(int index) {\\n    rangeCheck(index);\\n    modCount++;\\n    E oldValue = elementData(index);\\n    int numMoved = size - index - 1;\\n    if (numMoved > 0)\\n        System.arraycopy(elementData, index + 1, elementData, index, numMoved); // ★ 后面的元素整体前移\\n    elementData[--size] = null;       // ★ 置 null 让 GC 回收（防止内存泄漏，细节！）\\n    return oldValue;\\n}"},{"t":"p","html":"<b>删除慢的真相：</b>不是「找得慢」而是「挪得慢」——删除中间元素要把后面所有元素整体前移一位，O(n)。同理尾部 add 均摊 O(1)，但中间/头部插入也是 O(n)。"},{"t":"h","html":"四、modCount 与 fail-fast：并发修改异常的源码机制"},{"t":"code","lang":"java","title":"iterator 里的 fail-fast 检查","code":"protected transient int modCount = 0;   // 结构性修改次数（add/remove 都会 ++）\\n\\nprivate class Itr implements Iterator<E> {\\n    int expectedModCount = modCount;    // 创建迭代器时快照\\n\\n    public E next() {\\n        checkForComodification();       // 每次取元素前校验\\n        ...\\n    }\\n    final void checkForComodification() {\\n        if (modCount != expectedModCount)\\n            throw new ConcurrentModificationException(); // ★ fail-fast：立刻抛异常，宁可出错也不带病运行\\n    }\\n}"},{"t":"qa","q":"遍历时删除元素的正确姿势？","a":"三种安全方式：① <b>iterator.remove()</b>（它会同步 expectedModCount = modCount，所以不炸）；② <b>removeIf</b>：list.removeIf(x -> x &lt; 3)（JDK8，底层也是标记+批量删，还更快）；③ <b>倒序 for 循环按下标删</b>（删后面不影响前面未遍历的下标）。<b>错误方式：</b>foreach（底层就是 iterator）里直接 list.remove()——抛 ConcurrentModificationException；正序按下标删——会漏元素（删掉 i 后，后面的元素顶上来，i++ 跳过了下一个）。"},{"t":"h","html":"五、速记总结"},{"t":"list","items":["底层 Object[] 数组；无参构造 JDK8+ 懒初始化，首次 add 才分配 10","扩容 1.5 倍（old + old >> 1），copyOf 整体搬移，均摊 O(1)","get O(1)；中间增删 O(n)（arraycopy 挪移）；实现 RandomAccess 标记接口","modCount + expectedModCount 实现 fail-fast；安全删除用 iterator.remove / removeIf / 倒序下标","transient + 自定义 writeObject：只序列化实际元素，不序列化预留空位","线程不安全。替代：Collections.synchronizedList（全表锁）或 CopyOnWriteArrayList（读多写少）"]}]},{"id":"top-linkedlist","icon":"🔗","tag":"集合源码","title":"LinkedList 源码级剖析：双向链表、双端队列与「伪随机访问」","desc":"JDK 里 LinkedList 同时实现了 List 和 Deque——源码里 first/last 双指针、node(int) 的「二分走位」小聪明，以及它为什么被 Algorithm 教科书除名。","blocks":[{"t":"h","html":"一、结构：双向链表 + first/last 双指针"},{"t":"code","lang":"java","title":"LinkedList 核心结构","code":"public class LinkedList<E>\\n    extends AbstractSequentialList<E>\\n    implements List<E>, Deque<E>, Cloneable, java.io.Serializable {\\n\\n    transient int size = 0;\\n    transient Node<E> first;   // 头指针\\n    transient Node<E> last;    // 尾指针（★ 头尾操作都是 O(1) 的关键）\\n\\n    private static class Node<E> {\\n        E item;            // 数据\\n        Node<E> next;      // 后继\\n        Node<E> prev;      // 前驱\\n        Node(Node<E> prev, E element, Node<E> next) { ... }\\n    }\\n}"},{"t":"code","lang":"text","title":"内存形态","code":"null ← [A] ⇄ [B] ⇄ [C] → null\\n first↑            ↑last\\n\\n每个元素都要额外维护 prev/next 两个引用：\\n64 位 JVM 压缩指针下，一个 Node 额外开销 ≈ 16 字节\\n—— 这就是 LinkedList 内存不友好的根源（ArrayList 每个槽位只是一个引用 4B）"},{"t":"h","html":"二、node(int index)：源码里的「二分走位」优化"},{"t":"code","lang":"java","title":"按 index 找节点——官方源码原味","code":"Node<E> node(int index) {\\n    // assert isElementIndex(index);\\n    if (index < (size >> 1)) {          // ★ 前半段：从头走\\n        Node<E> x = first;\\n        for (int i = 0; i < index; i++)\\n            x = x.next;\\n        return x;\\n    } else {                            // ★ 后半段：从尾走\\n        Node<E> x = last;\\n        for (int i = size - 1; i > index; i--)\\n            x = x.prev;\\n        return x;\\n    }\\n}"},{"t":"qa","q":"既然 LinkedList 声称「增删快」，为什么 get(i) 是 O(n)？「二分走位」把它变成 O(log n) 了吗？","a":"① get(i) 必须从 first/last 一步步 next/prev 走过去，平均 O(n)——所谓「查询慢」。② size >> 1 判断只是把<b>最坏</b>情况减半（走 n/4~n/2 步），仍是 O(n)，<b>不是二分查找</b>（二分要求随机访问，链表恰恰没有）。③ 「增删快」也是<b>限定条件</b>的：拿到节点后改指针 O(1)；但「按值/按下标找到再删」整体还是 O(n)。面试要说全：O(1) 只发生在你<b>已经持有节点引用</b>时。"},{"t":"h","html":"三、Deque 门面：它其实是「双端队列 + 栈」三合一"},{"t":"table","headers":["API 风格","方法","对应语义"],"rows":[["List","add/get/remove(index)","线性表（性能差，不推荐）"],["队列 Queue","offer / poll / peek","尾进头出（FIFO）"],["双端 Deque","offerFirst/offerLast、pollFirst/pollLast","两端进出（滑动窗口题常用）"],["栈 Stack","push / pop / peek","Deque 接口的默认实现（官方推荐代替 Stack 类）"]]},{"t":"info","html":"📚 <b>冷知识（面试加分）：</b>JDK 老类 <code>Stack</code> 继承自 Vector，全表 synchronized 且允许在底部插元素破坏栈语义——官方 Javadoc 明确建议用 <code>Deque&lt;Integer&gt; stack = new ArrayDeque&lt;&gt;()</code> 代替。而 ArrayDeque 用循环数组实现，性能优于 LinkedList 的链式 Deque——所以「用 LinkedList 当队列」在性能上也通常不是最优解。"},{"t":"h","html":"四、ArrayList vs LinkedList 决胜局（面试标准答案）"},{"t":"table","headers":["维度","ArrayList","LinkedList"],"rows":[["底层","动态数组","双向链表"],["随机访问 get(i)","O(1) 下标寻址","O(n) 顺链走位"],["尾部增删","均摊 O(1)","O(1)"],["中间增删","O(n)（arraycopy 挪移）","O(n)（遍历找位置）+ O(1)（改指针）"],["内存","连续 + 预留空位（扩容浪费）","每节点多 2 个引用，碎片化，缓存不友好"],["CPU 缓存友好度","★ 极高（顺序内存预取）","差（指针跳转 cache miss 多）"],["实际选型","★ 默认之选（实测几乎全场景更快）","仅头尾频繁进出（且不如 ArrayDeque）"]]},{"t":"warn","html":"<b>颠覆认知的结论：</b>由于 CPU 缓存预取 + 数组内存连续性，实测中 <b>ArrayList 在绝大多数场景（含中间插入）都跑赢 LinkedList</b>。Joshua Bloch（《Effective Java》作者、Java 集合框架之父）自己都说「LinkedList 只有 1% 的场景有意义」。面试敢说这句，直接和其他候选人拉开差距。"}]},{"id":"top-hashmap","icon":"🗺️","tag":"集合源码","title":"HashMap 源码级剖析：从 put 一行行读到红黑树","desc":"面试出现率第一的类。capacity 为什么必须是 2 的幂？hash 为什么高 16 位异或？树化阈值为什么是 8？resize 拆链表的 (e.hash & oldCap) == 0 是什么魔法？","blocks":[{"t":"h","html":"一、先记四个常量，整篇源码都围绕它们"},{"t":"code","lang":"java","title":"HashMap 关键常量与字段","code":"static final int DEFAULT_INITIAL_CAPACITY = 1 << 4;  // 默认容量 16（必须是 2 的幂）\\nstatic final int MAXIMUM_CAPACITY = 1 << 30;         // 最大 10.7 亿\\nstatic final float DEFAULT_LOAD_FACTOR = 0.75f;      // 默认负载因子\\nstatic final int TREEIFY_THRESHOLD = 8;              // 单链表长度 ≥8 且表长 ≥64 → 树化\\nstatic final int UNTREEIFY_THRESHOLD = 6;            // 扩容拆树（split）时 ≤6 退化为链表\\nstatic final int MIN_TREEIFY_CAPACITY = 64;          // 树化的表长门槛\\n\\ntransient Node<K,V>[] table;   // 哈希桶数组\\ntransient int size;            // 实际键值对数\\nint threshold;                 // 扩容阈值 = capacity × loadFactor"},{"t":"h","html":"二、put 全流程（JDK8）——背下这六步"},{"t":"code","lang":"java","title":"putVal 精简骨架","code":"public V put(K key, V value) {\\n    return putVal(hash(key), key, value, false, true);\\n}\\n\\nstatic final int hash(Object key) {\\n    int h;\\n    // ★ 扰动函数：高 16 位异或低 16 位\\n    return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);\\n}\\n\\nfinal V putVal(int hash, K key, V value, ...) {\\n    Node<K,V>[] tab; Node<K,V> p; int n, i;\\n    if ((tab = table) == null || (n = tab.length) == 0)\\n        n = (tab = resize()).length;                    // ① 表为空 → resize 初始化（懒初始化，同 ArrayList 思想）\\n    if ((p = tab[i = (n - 1) & hash]) == null)          // ② 定位桶：i = (n-1) & hash，空桶直接放\\n        tab[i] = newNode(hash, key, value, null);\\n    else {\\n        // ③ 桶非空：p 是桶头。依次判断\\n        if (p.hash == hash && (key 相等))\\n            e = p;                                       // 头节点就是目标 → 覆盖\\n        else if (p instanceof TreeNode)\\n            e = ((TreeNode)p).putTreeVal(...);           // 红黑树插入\\n        else {\\n            for (int binCount = 0; ; ++binCount) {\\n                if ((e = p.next) == null) {\\n                    p.next = newNode(...);               // ★ 尾插法（JDK7 是头插）\\n                    if (binCount >= TREEIFY_THRESHOLD - 1)\\n                        treeifyBin(tab, hash);           // 链长 ≥8 → 尝试树化\\n                    break;\\n                }\\n                if (key 相等) break;                     // 链上已有目标 → 覆盖\\n                p = e;\\n            }\\n        }\\n        if (e != null) { V old = e.value; e.value = value; return old; }  // ④ 覆盖旧值\\n    }\\n    ++modCount;\\n    if (++size > threshold) resize();                    // ⑤ size 超阈值 → 扩容 2 倍\\n    return null;                                         // ⑥ 新增成功\\n}"},{"t":"qa","q":"为什么容量必须是 2 的幂？hash 为什么要高 16 位异或？","a":"① 取模定位桶用 <code>(n-1) & hash</code>：当 n 是 2 的幂时 n-1 是「全 1 掩码」（如 16-1=1111），与运算等价于取模且<b>位运算远快于 %</b>。② hashCode 是 32 位，若容量 16 只用低 4 位——高 16 位参与不进来，碰撞概率大增。③ <code>h ^ (h >>> 16)</code> 让高 16 位「折叠」进低 16 位，一异或一次搞定，<b>代价最小地让高位也参与散列</b>。这是 Doug Lea/方腾飞们反复推敲的性价比设计。"},{"t":"h","html":"三、resize：JDK8 扩容拆链表的「神仙算法」"},{"t":"code","lang":"java","title":"resize 里的两个关键判断","code":"do {\\n    next = e.next;\\n    // ★ 核心魔法：e.hash & oldCap 只可能得 0 或 oldCap（oldCap 是 2 的幂，只有最高位是 1）\\n    if ((e.hash & oldCap) == 0)\\n        loTail.next = e;  → 保持原下标 newTab[j]\\n    else\\n        hiTail.next = e;  → 新下标 = 原下标 + oldCap（如 5 → 5+16=21）\\n} while ((e = next) != null);"},{"t":"qa","q":"(e.hash & oldCap) == 0 到底在判断什么？","a":"扩容后掩码从 n-1 变成 2n-1，比原来<b>多看 hash 的一位</b>——就是 oldCap 对应的那一位。该位是 0 → 新掩码结果不变 → 留原位；是 1 → 结果多出 oldCap → 挪到「原下标 + oldCap」。这样<b>一次遍历、按位分流</b>，不用重新计算每个元素的桶下标，也不用像 JDK7 那样倒序头插（JDK7 头插在并发 resize 会形成环形链表 → get 死循环 CPU 100%，JDK8 改尾插后解决了环，但 HashMap 依然线程不安全——会丢数据、size 不一致）。"},{"t":"h","html":"四、树化的三个阈值：为什么是 8 和 6？"},{"t":"qa","q":"链表转红黑树的阈值为什么是 8？退化为什么是 6？","a":"① 官方注释给了统计学依据：<b>理想散列下，桶内节点数服从泊松分布，λ≈0.5 时单个桶出现 8 个节点的概率仅约 0.00000006（亿分之六）</b>——树化是「散列质量已经崩了」的兜底保险，而不是常态。② 选 8 还有个巧妙契合：红黑树要求树高 ≤ 2·log₂(n+1)，链长 8 时 O(n)=8 次 vs 树 O(log8)≈3 次，同时 TreeNode 占用内存约是 Node 的 2 倍——不值得为小概率事件常驻。③ 退化阈值 6 而不是 7：留出缓冲带，防止节点在 7↔8 之间反复横跳导致链表↔红黑树来回转换抖动。"},{"t":"h","html":"五、连环追问终点站"},{"t":"qa","q":"HashMap 的 key 可以是对象吗？有什么要求？为什么 String 适合做 key？","a":"可以。要求：<b>正确重写 equals 和 hashCode</b>（成对！否则 get 找不到）。String 适合：① final 不可变 → hashCode 可缓存（String 里 hash 字段懒计算后缓存），get 时不用重算；② equals/hashCode 稳定一致；③ 内部 char[] 也是 final，防止 key 在 map 里被改。追问「为什么重写 equals 必须重写 hashCode」→ 因为 HashMap 先比 hash 再比 equals，hash 不等直接判不等，两个 equals 相等但 hash 不同的对象会存成两份，语义崩塌。"},{"t":"list","items":["懒初始化；容量 2 的幂；(n-1)&hash 定位；扰动函数折叠高 16 位","JDK8 尾插；链长 ≥8 且表长 ≥64 树化，split 时 ≤6 退链","size > capacity×0.75 扩容 2 倍；(hash & oldCap) 按位分流免重算","并发问题：JDK7 头插成环死循环；JDK8 丢数据——多线程用 ConcurrentHashMap","key 为 null 存在 0 号桶（table[0]）；value 可为 null"]}]},{"id":"top-chm","icon":"🛡️","tag":"集合源码","title":"ConcurrentHashMap 源码级剖析：JDK7 分段锁 → JDK8 CAS+synchronized","desc":"为什么弃用 Segment？size 怎么统计才线程安全？get 为什么不需要加锁？1.8 源码里的 CAS 空桶初始化、forwarding 帮助扩容，一文读透。","blocks":[{"t":"h","html":"一、两代架构对比：为什么抛弃分段锁"},{"t":"table","headers":["维度","JDK7 Segment 分段锁","JDK8 Node + CAS + synchronized"],"rows":[["锁粒度","段（默认 16 段，并发度=段数）","单个桶头节点"],["数据结构","Segment[] → HashEntry[] 链表","Node[] 链表 + 红黑树（与 HashMap 同构）"],["写并发度","最多 16 线程同时写","理论等于桶数量，冲突更少"],["寻址","两次 hash（先段后桶）","一次 hash"],["淘汰原因","并发度固定、内存翻倍、查询两次寻址","—（JDK8 方案全面更优）"]]},{"t":"h","html":"二、putVal 源码：三种情况三种锁"},{"t":"code","lang":"java","title":"JDK8 ConcurrentHashMap.putVal 关键段","code":"final V putVal(K key, V value, boolean onlyIfAbsent) {\\n    if (key == null || value == null) throw new NullPointerException(); // ★ 与 HashMap 不同：禁止 null\\n    int hash = spread(key.hashCode());          // 扰动：HIGH^ (h>>>16) 同思想\\n    int binCount = 0;\\n    for (Node<K,V>[] tab = table;;) {           // ★ 死循环 + CAS：失败重来\\n        Node<K,V> f; int n, i, fh;\\n        if (tab == null || (n = tab.length) == 0)\\n            tab = initTable();                  // ① 懒初始化（CAS sizeCtl 保证只有一个线程建表）\\n        else if ((f = tabAt(tab, i = (n - 1) & hash)) == null) {\\n            if (casTabAt(tab, i, null, new Node<>(hash, key, value)))\\n                break;                          // ② 空桶 → CAS 插入，无锁！失败则循环重试\\n        }\\n        else if ((fh = f.hash) == MOVED)\\n            tab = helpTransfer(tab, f);         // ③ 桶头是 ForwardingNode → 表在扩容，先帮忙迁移\\n        else {\\n            synchronized (f) {                  // ④ 锁住桶头节点（粒度=单桶）\\n                if (tabAt(tab, i) == f) {       //    双重检查：锁前头节点没被换掉\\n                    // 链表尾插 / 红黑树插入（逻辑同 HashMap）\\n                }\\n            }\\n            if (binCount != 0)\\n                if (binCount >= TREEIFY_THRESHOLD) treeifyBin(tab, i);\\n            break;\\n        }\\n    }\\n    addCount(1L, binCount);                     // ⑤ CAS 更新 baseCount + CounterCell 分散计数\\n    return null;\\n}"},{"t":"qa","q":"为什么 JDK8 用 synchronized 而不是 ReentrantLock？","a":"① <b>锁竞争极小</b>：只锁单个桶头，碰撞概率低，JDK6 后 synchronized 优化（偏向锁→轻量级→自适应自旋）后无竞争场景开销接近原子操作；② <b>省内存</b>：ReentrantLock 每个桶一个对象（AQS 队列+state）内存爆炸，synchronized 只用对象头 mark word；③ JVM 内建锁可持续优化（逃逸分析、锁消除）。面试还可补：空桶用 CAS 无锁化，只有真冲突才升级到 synchronized——整体是一套「CAS 乐观 → synchronized 悲观」的渐进锁策略。"},{"t":"h","html":"三、size() 怎么算的：LongAdder 思想的计数分散"},{"t":"code","lang":"java","title":"addCount 与 baseCount/CounterCell","code":"transient volatile long baseCount;             // 无竞争时的计数器\\nprivate transient volatile CounterCell[] counterCells; // 有竞争时的分散计数槽\\n\\n// 计数逻辑（等价 LongAdder）：\\nif (CAS 更新 baseCount 成功) → 完事\\nelse\\n    → 往 counterCells 随机选一个槽 CAS 累加   // ★ 把一个热点拆成 N 个槽，用空间换无争用\\n\\n// size() = sumCount() = baseCount + Σ counterCells[i].value  （非精确瞬时值！）"},{"t":"info","html":"💡 <b>为什么 size 不是精确值：</b>要精确就得全表加锁或全局原子计数——前者毁并发、后者热点瓶颈。官方取舍：把 size 定义为「并发达成过程中的估计值」，换取写入路径几乎零计数开销。这与 LongAdder 战胜 AtomicLong 是同一个思想：<b>热点分离</b>。"},{"t":"h","html":"四、get 为什么不用加锁？"},{"t":"code","lang":"java","title":"get 源码关键点","code":"public V get(Object key) {\\n    Node<K,V>[] tab; Node<K,V> e, p; int n, eh; K ek;\\n    int h = spread(key.hashCode());\\n    if ((tab = table) != null && (n = tab.length) > 0 &&\\n        (e = tabAt(tab, (n - 1) & h)) != null) {\\n        if ((eh = e.hash) == h) ...        // 直接比较\\n        else if (eh < 0)                   // ★ hash<0：ForwardingNode(MOVED) 或 TreeBin\\n            return (p = e.find(h, key)) != null ? p.val : null;\\n        while ((e = e.next) != null) { ... }  // 链表顺序找\\n    }\\n    return null;\\n}\\n// 安全的三件套：① Node.val 和 next 都被 volatile 修饰（可见性+禁止重排）\\n//              ② tabAt 用 Unsafe.getObjectVolatile 保证读到最新桶头\\n//              ③ 扩容时 ForwardingNode.find 会「转场」去新表找"},{"t":"list","items":["JDK7：Segment 分段锁（16 段）、两次寻址；JDK8：CAS 空桶 + synchronized 桶头 + volatile 读","禁止 null key/value：并发下 get 返回 null 无法区分「不存在」和「值就是 null」（二义性）","size 非精确：baseCount + CounterCell 分散计数（LongAdder 思想）","扩容：多线程 helpTransfer 协助迁移，ForwardingNode 路标","1.8 里 CHM 树化阈值同 HashMap（8/6），但树化用的是 TreeBin 包装（锁的是 TreeBin 不是根节点）"]}]},{"id":"top-lhm-tm","icon":"🎚️","tag":"集合源码","title":"LinkedHashMap 与 TreeMap 源码：一个有插入序，一个有比较序","desc":"LinkedHashMap 怎么用「双向链表串起所有 Entry」实现顺序？accessOrder 怎么变身 LRU？TreeMap 的红黑树 put 后为什么要 fixAfterInsertion？","blocks":[{"t":"h","html":"一、LinkedHashMap：HashMap + 一条贯穿的双向链表"},{"t":"code","lang":"java","title":"核心结构（继承 HashMap）","code":"public class LinkedHashMap<K,V> extends HashMap<K,V> {\\n    transient LinkedHashMap.Entry<K,V> head;  // 双向链表头（最旧）\\n    transient LinkedHashMap.Entry<K,V> tail;  // 双向链表尾（最新）\\n    final boolean accessOrder;                // false=插入序（默认） true=访问序（LRU 基础）\\n\\n    static class Entry<K,V> extends HashMap.Node<K,V> {\\n        Entry<K,V> before, after;             // ★ 每个 Entry 多挂两个指针，串成链\\n    }\\n    // HashMap 留的钩子：putVal 成功后回调\\n    void afterNodeAccess(Node<K,V> e) { ... }   // accessOrder=true 且 e 不是尾 → 移到链尾\\n    void afterNodeInsertion(boolean evict) {\\n        LinkedHashMap.Entry<K,V> first;\\n        if (evict && (first = head) != null && removeEldestEntry(first)) {\\n            removeNode(hash(first.key), ...);   // ★ LRU 淘汰点：新插入后删掉链头最旧元素\\n        }\\n    }\\n}"},{"t":"code","lang":"java","title":"经典应用：10 行写一个 LRU 缓存（LeetCode 146 同款思路）","code":"class LRUCache<K, V> extends LinkedHashMap<K, V> {\\n    private final int maxEntries;\\n    LRUCache(int cap) {\\n        super(cap, 0.75f, true);              // ★ accessOrder = true：按访问排序\\n        this.maxEntries = cap;\\n    }\\n    @Override\\n    protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {\\n        return size() > maxEntries;           // 超容量淘汰链头（最久未访问）\\n    }\\n}\\n// get/put 都会触发 afterNodeAccess 把刚访问的 Entry 挪到链尾 → 链头永远是「该杀」的"},{"t":"qa","q":"LinkedHashMap 是线程安全的吗？LinkedHashSet 和它什么关系？","a":"① 不安全，同 HashMap（1.8 前后问题一样）。② LinkedHashSet 继承 HashSet，而 HashSet 内部就是包了一个 LinkedHashMap（HashSet 源码：map = new LinkedHashMap&lt;&gt;()）——「不重复 + 插入有序」白嫖自双向链表。追问链：HashSet 里的 PRESENT 是什么 → 一个共享的静态 final Object 占位 value，因为 Set 只要 key 不要 value。"},{"t":"h","html":"二、TreeMap：红黑树落地实现，按 key 排序"},{"t":"code","lang":"java","title":"put → fixAfterInsertion（红黑树修正）","code":"public V put(K key, V value) {\\n    ...\\n    int cmp; Entry<K,V> parent;\\n    if (cpr != null) {                        // 有 Comparator\\n        do { parent = t; cmp = cpr.compare(key, t.key);\\n             if (cmp < 0) t = t.left; else if (cmp > 0) t = t.right; else return t.setValue(value);\\n        } while (t != null);                  // ★ BST 二分下潜找到插入父节点\\n    } else { /* key.compareTo 同理；null key 直接 NPE */ }\\n    Entry<K,V> e = new Entry<>(key, value, parent);\\n    if (cmp < 0) parent.left = e; else parent.right = e;\\n    fixAfterInsertion(e);                     // ★ 插入后修正：变色+旋转，恢复红黑五条性质\\n    size++; modCount++;\\n    return null;\\n}"},{"t":"p","html":"红黑树五条性质（背）：① 节点非红即黑；② 根必黑；③ 叶子（NIL）是黑；④ 红节点的两个孩子必黑（<b>红不相邻</b>）；⑤ 任意节点到其所有叶子的路径含相同数量黑节点（<b>黑高一致</b>）。由 ④⑤ 推出：<b>最长路径 ≤ 2×最短路径</b>，树高 ≤ 2·log₂(n+1)，增删查 O(log n)。fixAfterInsertion 的三种情形（叔叔红→变色上推、叔叔黑且三角形→旋转成直线、叔叔黑且直线→换色+单旋）配合图理解最牢。"},{"t":"table","headers":["能力","LinkedHashMap","TreeMap"],"rows":[["顺序语义","插入序 / 访问序","key 自然序 / Comparator 定制序"],["底层","HashMap + 双向链表","红黑树"],["get/put/containsKey","O(1)","O(log n)"],["范围操作","无","firstKey/lastKey/floorKey/ceilingKey/headMap/tailMap/subMap（全部 O(log n)）★"],["典型场景","LRU 缓存、保序去重","排行榜范围查询、时间轴区间检索、有序去重"]]},{"t":"warn","html":"<b>高频坑：</b>TreeMap 判断「相同 key」只靠 compare/compareTo 返回 0——不调用 equals！自定义 Comparator 只比较了部分字段时，会误判相等导致元素被<b>覆盖丢失</b>；key 是可变对象且 put 后修改了参与比较的字段，也会「查无此 key」。"}]},{"id":"top-coll-fw","icon":"🧩","tag":"集合源码","title":"集合框架全景与源码彩蛋：fail-fast vs fail-safe、Arrays.asList 四大坑、Collections 增强","desc":"把零散知识串成体系：Iterator 模式的骨架、modCount 彩蛋遍历、Arrays.asList 的定长陷阱、Collections.unmodifiable 的真面目、CopyOnWrite 原理。","blocks":[{"t":"h","html":"一、框架全景图（一张图记住继承树）"},{"t":"code","lang":"text","title":"集合框架继承体系","code":"                 Iterable\\n                    ↑ iterator()\\n                Collection\\n           ┌────────┴────────┐\\n          List               Set                       Map（独立体系，不继承 Collection）\\n    ┌─────┼─────┐      ┌────┼─────┐             ┌──────┼────────┐\\n ArrayList  Vector  LinkedList  HashSet  SortedSet   HashMap   SortedMap\\n              ↑          ↑        ↑   ↑        ↑          ↑\\n          Stack    (Deque接口)  LinkedHashSet  TreeMap  LinkedHashMap\\n                                    (TreeSet)\\n\\n线程安全家族：Vector/Hashtable(古董) → Collections.synchronizedXxx(全表锁)\\n           → ConcurrentHashMap/CopyOnWriteArrayList/ConcurrentLinkedQueue(JUC 现代方案)"},{"t":"h","html":"二、fail-fast vs fail-safe：两种迭代器哲学"},{"t":"table","headers":["类型","机制","代表","代价"],"rows":[["fail-fast（快速失败）","迭代时校验 modCount 快照，不一致立刻抛 ConcurrentModificationException","ArrayList/HashMap 等所有 java.util 集合","不能并发改，但错误早暴露"],["fail-safe（安全失败）","在副本上遍历（快照），或无锁并发结构上遍历","CopyOnWriteArrayList（遍历旧数组）、ConcurrentHashMap（弱一致性迭代器）","不保证读到最新数据；COW 复制内存开销大"]]},{"t":"qa","q":"modCount 不够严谨：单线程下 foreach 里 list.set(i, x) 会抛异常吗？","a":"不会。modCount 只统计<b>结构性修改</b>（size 变化的 add/remove），set 是「替换不换长」，不动 modCount。这个细节能反推出源码设计意图：fail-fast 只针对「遍历过程中结构变动导致迭代器下标失效」的风险，替换值是安全的。"},{"t":"h","html":"三、Arrays.asList 四大坑（生产事故高发区）"},{"t":"code","lang":"java","title":"坑位演示","code":"// 坑1：定长——add/remove 直接 UnsupportedOperationException\\nList<String> list = Arrays.asList(\\"a\\", \\"b\\");\\n// list.add(\\"c\\");   // 💥 UOE：底层是 Arrays 的内部 ArrayList（≠java.util.ArrayList）！\\n\\n// 坑2：改动会穿透——set 会写回原数组\\nString[] arr = {\\"a\\", \\"b\\"};\\nList<String> l = Arrays.asList(arr);\\nl.set(0, \\"X\\");            // arr[0] 也变成 \\"X\\"\\n\\n// 坑3：基本类型数组被当成一个元素\\nint[] nums = {1, 2, 3};\\nList<int[]> wrong = Arrays.asList(nums);   // size()==1 ！泛型不能是 int\\nList<Integer> ok = Arrays.stream(nums).boxed().collect(Collectors.toList());\\n\\n// 坑4：null 元素行为不明 / 与 toList() 的差异\\n// 正确姿势（JDK8+ 需要可变 List）：\\nList<String> good = new ArrayList<>(Arrays.asList(\\"a\\", \\"b\\"));\\n// JDK9+：List.of(\\"a\\",\\"b\\")  → 不可变（add 抛 UOE，且禁止 null）"},{"t":"h","html":"四、Collections 工具类与 CopyOnWrite 原理"},{"t":"qa","q":"Collections.synchronizedList 和 CopyOnWriteArrayList 怎么选？","a":"① <b>synchronizedList</b>：所有方法套 synchronized(this) 全表锁——读写全互斥，读多场景吞吐差；迭代时仍需手动加锁否则 fail-fast。② <b>CopyOnWriteArrayList</b>：写时复制整个新数组 + volatile 替换引用 + Lock 控制写写互斥——读完全无锁（读的是当前引用指向的数组），<b>读多写极少</b>（白名单、监听器列表）性能碾压；但写 O(n) 复制、内存翻倍、读到的可能是旧快照（弱一致）。③ 写多读少或读写均衡 → synchronizedList 也不行，应该考虑分段/无锁结构或换业务方案。一句话：<b>读多写少 COW，其余场景都别用「伪安全集合」硬扛</b>。"},{"t":"list","items":["Iterator 是迭代器模式的 JDK 实现；Iterable 是「可被 for-each」的标记能力","fail-fast 靠 modCount；COW/CHM 迭代器是弱一致（fail-safe）","Arrays.asList：定长、穿透修改、基本类型数组灾难；可变 List 用 new ArrayList&lt;&gt;() 包装","Collections.emptyList()/singletonList()：零开销不可变工具，返回类型注意别再 add","HashSet→LinkedHashMap、TreeSet→TreeMap、LinkedHashSet→LinkedHashMap：Set 家族全是 Map 的马甲"]}]}]');
INSERT INTO json_doc (name, data) VALUES ('topicsMySQLRedis', '[{"id":"top-btree","icon":"🌳","tag":"MySQL","title":"为什么是 B+ 树？索引底层数据结构全图解","desc":"为什么不用二叉树/红黑树/哈希/B 树？B+ 树 3 层怎么撑住 2000 万行？聚簇索引 vs 二级索引、回表与覆盖索引全讲透。","blocks":[{"t":"h","html":"一、候选结构逐个淘汰（面试标准推导链）"},{"t":"table","headers":["结构","淘汰理由"],"rows":[["有序数组","查询 O(logn) 没问题，但插入要整体挪动，O(n)，写多场景不可用"],["链表/无序结构","只能全表扫 O(n)"],["二叉搜索树(BST)","有序插入退化成链表 O(n)"],["AVL/红黑树","二叉，树高随数据量线性涨（2000万行≈23层）→ 磁盘 IO 23 次，太慢；且每节点只存 1 个键，磁盘页利用率极低"],["哈希表","等值查询 O(1) 很快，但<b>不支持范围查询和排序</b>（hash 无序），Memory 引擎可用"],["B 树","多叉矮胖已不错，但<b>非叶子节点也存数据</b>，每页装的键少 → 树更高；且范围查询要中序回溯，IO 多"],["B+ 树 ✅","非叶子只存键（一页能装 1000+ 指针）、数据全在叶子、叶子间双向链表串联 → 矮胖 + 范围查询无敌"]]},{"t":"code","lang":"text","title":"B+ 树结构（MySQL InnoDB）","code":"                    [ 30 | 60 ]            ← 非叶子：只存键+子指针\\n                  /    |     \\\\\\n          [10|20]   [40|50]   [70|80]      ← 非叶子层\\n          /  |  \\\\   ...\\n   [5|8]-[10|12]-[20|25]-[30|33]-[40|45]-...   ← 叶子：存整行数据（聚簇索引）\\n      └───── 双向链表 ─────┘   ← 范围查询顺着链表扫，不用回树上爬"},{"t":"qa","q":"为什么说 3 层 B+ 树能存约 2000 万行？","a":"InnoDB 页大小 16KB。非叶子节点只放键+指针：假设主键 bigint 8B + 指针 6B = 14B，一页可放 16KB/14B ≈ <b>1170 个指针</b>。叶子节点若每行数据约 1KB，一页放 <b>16 行</b>。则：3 层容量 = 1170 × 1170 × 16 ≈ <b>2190 万行</b>。树高 3 = 主键查询最多 3 次页 IO（根页常驻内存，实际 1~2 次）。这也是\\"为什么单表建议不超过两千万再考虑分表\\"的出处——超过后树变 4 层，IO 翻倍。"},{"t":"h","html":"二、聚簇索引、二级索引与回表"},{"t":"list","items":["<b>聚簇索引（主键索引）</b>：叶子节点存<b>整行数据</b>，表本身就是按主键组织的 B+ 树——所以\\"索引即数据，数据即索引\\"。","<b>二级索引（辅助索引）</b>：叶子节点存<b>索引列的值 + 主键值</b>，不是整行。查 name 索引拿到的是主键 id。","<b>回表</b>：二级索引查到主键后，还要去聚簇索引再查一次拿完整行——两次树查找。","<b>覆盖索引</b>：查询的字段全在二级索引里（如 SELECT id, name FROM t WHERE name=xx），不用回表——EXPLAIN 的 Extra 显示 Using index，是大厂高频优化手段。","<b>最左前缀</b>：联合索引 (a,b,c) 相当于按 a 排、a 同按 b 排……所以 where b=1 不走索引；where a=1 and c=3 只用到 a。"]},{"t":"qa","q":"为什么建议用自增主键，不用 UUID？（必考）","a":"自增主键顺序追加写入：<b>页满就开新页</b>，无分裂、无碎片，顺序 IO 快。UUID 无序：新行随机插入已有页中间 → <b>页分裂</b>（挪数据、申请新页）→ 也可能页变稀疏产生<b>碎片</b>，还连带所有二级索引跟着变。同时 UUID 占 36B vs bigint 8B，<b>所有二级索引的叶子都存主键</b>，主键越大索引越肥。分布式场景要 UUID 的话，用雪花算法这类<b>趋势递增</b>的方案折中。"},{"t":"qa","q":"什么情况索引会失效？（高频清单）","a":"① 违反最左前缀（联合索引跳过第一列）；② 索引列上做运算/函数（WHERE YEAR(dt)=2024）；③ 隐式类型转换（varchar 列用数字查）；④ 前导模糊 LIKE ''%x''；⑤ OR 两侧有非索引列；⑥ NOT IN / != / IS NOT NULL（视成本可能不走）；⑦ 优化器判断回表太多不如全表扫（如条件命中 30%+ 行）；⑧ 联表两列字符集/排序规则不一致。万能验证法：<b>EXPLAIN</b> 看 type 和 key 列。"},{"t":"tip","html":"<b>速记：</b>B+ 树赢在\\"非叶子不存数据（矮）+ 叶子链表（范围查询快）\\"；3 层 2000 万；聚簇=整行，二级=主键；回表两次查，覆盖索引免回表；自增主键防分裂。"}]},{"id":"top-mvcc","icon":"⏳","tag":"MySQL","title":"事务 ACID 怎么实现 + MVCC 多版本并发控制（图解版）","desc":"undo log/redo log/锁/MVCC 分别保障哪个字母？ReadView 判定规则、RC 和 RR 的本质区别、幻读到底解决没有？","blocks":[{"t":"h","html":"一、ACID 各自靠什么实现（很多人答不上来的框架题）"},{"t":"table","headers":["特性","含义","实现机制"],"rows":[["A 原子性","要么全成功要么全回滚","<b>undo log</b>：记录反向操作，回滚时逆着做"],["C 一致性","数据满足业务约束（总账平）","由 A+I+D 共同保障 + 应用层约束，是最终目的"],["I 隔离性","并发事务互不干扰","<b>锁 + MVCC</b>：写写用锁，读写靠版本链"],["D 持久性","提交后宕机不丢","<b>redo log</b>：WAL 先写日志再刷数据页"]]},{"t":"info","html":"<b>记忆法：</b>A 是 undo（后悔药），D 是 redo（安全垫），I 是锁+MVCC，C 是前三者的结果。"},{"t":"h","html":"二、undo / redo / binlog 三大日志分工"},{"t":"table","headers":["日志","层次","作用","写入时机"],"rows":[["undo log","InnoDB 引擎层","回滚 + MVCC 版本链","修改数据前先记旧值"],["redo log","InnoDB 引擎层","崩溃恢复（保证持久性），物理日志\\"某页某处改成了什么\\"","事务执行中顺序写，commit 时 fsync（受 innodb_flush_log_at_trx_commit 控制）"],["binlog","Server 层","主从复制 + 数据恢复/归档，逻辑日志（语句或行变更）","事务提交时写，fsync 受 sync_binlog 控制"]]},{"t":"qa","q":"redo log 和 binlog 区别？为什么有了 binlog 还要 redo log？","a":"层次不同（引擎 vs Server）、物理 vs 逻辑、循环写 vs 追加写、职责不同（崩溃恢复 vs 复制归档）。<b>为什么不能只有 binlog：</b>binlog 没有幂等的\\"进行中\\"状态且历史是追加的完整记录，用它做崩溃恢复既慢也无法区分\\"已提交未刷盘\\"的边界；redo log 是 WAL 的物理改动记录，重启时重放即可精确恢复到崩溃前已提交的状态。两阶段提交（redo log prepare → 写 binlog → redo log commit）保证两份日志一致，防止主从数据不一致。"},{"t":"qa","q":"binlog 三种格式怎么选？","a":"<b>STATEMENT</b>：记 SQL 原文，量小，但 NOW()/UUID()/limit 等在主从可能结果不同（不安全）；<b>ROW</b>（默认）：记每行的前后镜像，数据一致性强，量大（可配 binlog_row_image=MINIMAL 减量）；<b>MIXED</b>：默认 statement，遇到不安全的自动切 row。"},{"t":"h","html":"三、MVCC：读写不阻塞的核心"},{"t":"p","html":"每行记录都有隐藏列：<b>DB_TRX_ID</b>（最后修改它的事务 id）、<b>DB_ROLL_PTR</b>（指向 undo log 里的旧版本）。多次修改串成一条<b>版本链</b>，读的时候挑\\"我能看见的那个版本\\"——这就是多版本并发控制。"},{"t":"code","lang":"text","title":"版本链与 ReadView 判定","code":"最新行 (trx_id=300) → rollback_ptr → 版本(trx_id=200) → 版本(trx_id=100)\\n\\n事务开始（RC：每条查询时 / RR：第一次查询时）生成 ReadView：\\n  m_ids：生成时还活跃（未提交）的事务 id 集合\\n  min/max_water_line：活跃的最小 id、下一个将分配的 id\\n\\n拿版本的 trx_id t 判断：\\n  t < min           → 早已提交，可见 ✅\\n  t ≥ max           → 快照后才开始的，不可见，顺着链找旧版\\n  min ≤ t < max：\\n      t 在 m_ids 中   → 还没提交，不可见 → 找旧版\\n      t 不在 m_ids 中 → 已提交，可见 ✅"},{"t":"qa","q":"RC 和 RR 的本质区别？（一句话说透）","a":"<b>生成 ReadView 的时机不同。</b>RC（读已提交）<b>每条 SELECT 都重新生成</b>——别人一提交你就能看见，所以不可重复读；RR（可重复读）<b>只在第一次查询生成并复用</b>——整个事务看到的都是同一快照，所以可重复读。就这一个时机差异，代价是 RR 下 undo 版本链更长，需要清理线程及时回收。"},{"t":"qa","q":"RR 隔离级别下幻读彻底解决了吗？（陷阱题）","a":"<b>没有完全解决，是\\"很大程度上避免\\"。</b>①<b>快照读</b>（普通 SELECT）：MVCC 避免幻读（ReadView 固定）；②<b>当前读</b>（SELECT ... FOR UPDATE / UPDATE / DELETE）：靠<b>临键锁 Next-Key Lock = 行锁 + 间隙锁</b>，锁住已有行和行之间的空隙，阻止别的事务插入；③漏洞场景：事务里先快照读、再当前读（自己 UPDATE 后 SELECT 能看见别事务插入的行），会看到\\"幻影行\\"。要严格防幻读：全程用当前读加锁，或用串行化。"},{"t":"qa","q":"InnoDB 有哪些锁？间隙锁什么时候出现？","a":"粒度：表锁/意向锁/行锁（记录锁 Record、间隙锁 Gap、临键锁 Next-Key）；模式：共享 S/排他 X。RR 级别的当前读为防幻读用 Next-Key（等值命中退化为记录锁，等值未命中退化为间隙锁）；<b>RC 级别没有间隙锁</b>（所以并发好但可能幻读）。另有插入意向锁（间隙锁之间的兼容插入）、MDL 元数据锁、AUTO-INC 锁。"},{"t":"tip","html":"<b>速记：</b>A=undo、D=redo、I=锁+MVCC；两阶段提交保 redo/binlog 一致；RC 每次读建快照，RR 只建一次；幻读=快照读靠 MVCC、当前读靠 Next-Key。"}]},{"id":"top-redis-ds","icon":"🧱","tag":"Redis","title":"Redis 数据结构底座与高性能原理（图解版）","desc":"SDS 为什么比 C 字符串好？跳表 vs 红黑树？ZSet 底层怎么选？ziplist/listpack 到 hashtable 的转换时机。","blocks":[{"t":"h","html":"一、SDS：Redis 自己的字符串"},{"t":"table","headers":["能力","C 字符串","SDS"],"rows":[["获取长度","O(n) 遍历到 \\\\0","<b>O(1)</b>：头部 len 字段直接读"],["缓冲区安全","拼接可能越界","自动检查空间，不够就扩容"],["减少内存重分配","每次拼接都可能 realloc","<b>预分配</b>（<1MB 多翻倍，>1MB 每次多给 1MB）+ <b>惰性释放</b>"],["二进制安全","\\\\0 截断，不能存图片","按 len 处理，可存任意字节"]]},{"t":"h","html":"二、五大类型的底层编码（面试最爱问 ZSet）"},{"t":"table","headers":["类型","小数据编码","升级为","底层结构"],"rows":[["String","int / embstr（≤44B）","raw","SDS"],["Hash","listpack（7.0 前 ziplist）","hashtable","数组+链表（渐进式 rehash）"],["List","quicklist（7.0 后 listpack 节点）","—","双向链表套压缩列表，兼顾两端操作与内存"],["Set","intset（全整数）/ listpack","hashtable","value 全为 NULL 的字典"],["ZSet","listpack","skiplist + dict","<b>跳表</b>管排序范围查，<b>字典</b>管 O(1) 按成员查分数"]]},{"t":"code","lang":"text","title":"跳表结构","code":"L3:  head ──────────────────────────→ 50 ──────────────→ ∞\\nL2:  head ────────→ 20 ──────────────→ 50 ────────→ ∞\\nL1:  head → 5 → 20 → 25 → 38 → 50 → 70 → ∞\\n\\n查找 38：从最高层出发，一路向右走不动了就下一层\\n50→下一层→50→下一层→38 ✅  平均 O(log n)"},{"t":"qa","q":"为什么用跳表不用红黑树实现 ZSet？（必考）","a":"①<b>范围查询同样 O(log n)</b>，但跳表找到起点后沿底层链表顺序遍历即可，实现简单直接；红黑树要中序遍历回溯，代码复杂；②<b>插入删除只改前后指针</b>，无需旋转再平衡；③按排名查成员（ZRANK）只需在每个节点存一下跨度 span。作者 antirez 的理由就是：实现简单、性能相当、调试容易。"},{"t":"qa","q":"渐进式 rehash 是怎么\\"渐进\\"的？","a":"字典扩容时不是一次搬完（百万级 key 会卡住单线程 Redis），而是<b>同时持有旧、新两张哈希表</b>：之后每次增删改查<b>顺带搬一个桶</b>，后台定时任务也搬一些；查找先查旧表再查新表，新增只进新表；搬完释放旧表。整个过程分摊到每次操作里，保持单次操作 O(1)。"},{"t":"qa","q":"大 key 和热 key 分别有什么危害？怎么治理？","a":"<b>大 key</b>（value 巨大，如百万元素的 list）：读写阻塞单线程、删除卡顿（用 UNLINK 异步删/SCAN 分批删）、主从同步慢、内存倾斜。治理：拆分成多个小 key、压缩、限制集合长度。<b>热 key</b>（某 key QPS 极高）：单分片 CPU 打满、下游被打垮。治理：本地缓存（多级缓存）、key 加随机后缀拆到多分片、读写分离。<b>排查：redis-cli --bigkeys / --hotkeys。</b>"},{"t":"tip","html":"<b>速记：</b>SDS 四好=O(1)长度/防越界/预分配/二进制安全；ZSet=跳表(排序)+字典(点查)；rehash 分摊搬桶；大 key 卡单线程，热 key 打单分片。"}]},{"id":"top-cache","icon":"🛡️","tag":"Redis","title":"缓存三大问题 + 持久化 + 过期删除与内存淘汰（图解版）","desc":"穿透/击穿/雪崩的区别与完整解决方案图、RDB vs AOF 怎么选、8 种淘汰策略、主从+哨兵+集群演进。","blocks":[{"t":"h","html":"一、缓存三大问题：一张表分清"},{"t":"table","headers":["问题","定义","解决方案"],"rows":[["缓存穿透","查<b>根本不存在</b>的数据，缓存永不命中，全打到 DB（恶意攻击常见）","①缓存空值（短过期）②<b>布隆过滤器</b>前置拦截 ③接口层参数校验/限流 ④风控"],["缓存击穿","某个<b>热点 key 恰好过期</b>瞬间，海量并发同时打 DB","①热点 key 逻辑过期（物理不过期，值里带过期时间，异步刷新）②互斥锁：只放一个线程去重建缓存，其余等待 ③热点永不过期"],["缓存雪崩","<b>大量 key 同时过期</b>，或 Redis 整体宕机，DB 瞬间被打爆","①过期时间加随机抖动 ②多级缓存（本地+Redis）③限流降级熔断兜底 ④高可用：主从+哨兵/集群，故障自动切换"]]},{"t":"code","lang":"text","title":"布隆过滤器原理","code":"写入 x：用 k 个 hash 函数把位数组的 k 个位置置 1\\n查询 x：k 个位置<b>全是 1</b> → \\"可能存在\\"（有误判率，hash 冲突）\\n        有任一 0  → \\"一定不存在\\" ✅（无漏判）\\n\\n→ 用它判断\\"数据是否存在\\"，不存在的直接拒绝，DB 免受攻击\\n代价：有误判（说存在但实际没有）、标准版不支持删除（计数版可以）"},{"t":"h","html":"二、持久化：RDB vs AOF"},{"t":"table","headers":["维度","RDB（快照）","AOF（追加日志）"],"rows":[["内容","某一时刻全量二进制快照","每条写命令文本追加"],["触发","save 阻塞 / <b>bgsave fork 子进程</b> / 配置周期","每命令追加（always/everysec默认/no）"],["恢复速度","<b>快</b>（直接载入二进制）","慢（逐条重放命令）"],["数据安全","两次快照之间的数据会丢","everysec 最多丢 1 秒；always 基本不丢但慢"],["文件大小","小（紧凑）","大（含重复命令）→ AOF 重写压缩"]]},{"t":"qa","q":"bgsave 期间 Redis 还能写吗？数据会不会不一致？（Copy-On-Write）","a":"能写。bgsave 时主进程 <b>fork 出子进程</b>，子进程看到的是 fork 瞬间的内存快照（页表共享）。此后主进程修改某页数据时，内核把该页<b>复制一份</b>给主进程改（写时复制 COW），子进程读的还是旧页——快照一致性自然保证。风险：fork 瞬间页表复制有开销（大实例主线程卡顿），写入越多 COW 消耗内存越大，这就是大实例慎用 RDB 的原因。"},{"t":"qa","q":"RDB 和 AOF 怎么选？","a":"能接受分钟级丢失（纯缓存）：只用 RDB，省心高效。数据重要（当存储用）：RDB + AOF 混合持久化（4.0+）：AOF 重写时把 RDB 数据写进 AOF 文件头部，之后追加增量命令——<b>恢复快（RDB 主体）+ 丢失少（AOF 增量）</b>，生产推荐。"},{"t":"h","html":"三、过期删除与内存淘汰（两个不同的事！）"},{"t":"list","items":["<b>过期删除</b>（key 到期了怎么删）：惰性删除（访问时检查，省 CPU 但可能残留）+ <b>定期删除</b>（每 100ms 随机抽一批带过期的 key，删过期的，超 25% 再抽一轮）组合使用。","<b>内存淘汰</b>（内存满了怎么办，maxmemory 触发）：noeviction（默认，写报错）、volatile-*（只淘汰设了过期时间的：LRU/LFU/random/ttl）、allkeys-*（全库范围：LRU/LFU/random）、allkeys-lru（最常用缓存策略）。","<b>Redis 的 LRU 是近似 LRU</b>：每个 key 记最近访问时钟，淘汰时随机抽样 N 个（maxmemory-samples 默认 5）挑最久未用的——省去维护全量链表的开销。","<b>LFU（4.0+）</b>：以计数器+衰减周期记录访问频率，对付\\"偶发扫描\\"比 LRU 准。"]},{"t":"h","html":"四、高可用演进：主从 → 哨兵 → 集群"},{"t":"code","lang":"text","title":"三种架构解决的问题","code":"主从复制：   master ──异步──→ slave / slave     （读写分离，但 master 挂了要人工切）\\n哨兵：       sentinel×3 监控 master，投票判定客观下线 → 自动选新 master（HA，容量仍单机）\\nCluster：    16384 slots 平均分到多 master，\\n             key → CRC16(key) % 16384 → 定位分片（数据分片 + 自动故障转移）"},{"t":"qa","q":"主从复制是同步还是异步？会有什么问题？","a":"异步。master 写完立即回复客户端，再异步传播给 slave。<b>问题：</b>①主从延迟，读 slave 可能读到旧数据；②master 挂掉瞬间未同步的数据可能丢失。缓解：min-replicas-to-write 要求至少 N 个从库在线才可写（可用性换一致性）。"},{"t":"qa","q":"哨兵怎么判定 master 下线？为什么至少 3 个哨兵？","a":"单哨兵 ping 不通 = <b>主观下线</b>（可能只是它自己网络抖）；多数哨兵都报下线 = <b>客观下线</b>，才发起选举和故障转移。<b>至少 3 个且奇数</b>：判定需要 quorum 多数派防误判；选 leader 执行切换也需要多数投票；3 是满足容错 1 个节点故障的最小奇数（2 个时挂 1 个就无法形成多数派）。"},{"t":"tip","html":"<b>速记：</b>穿透=查不存在的（布隆），击穿=热点过期（互斥/逻辑过期），雪崩=集体过期或宕机（抖动+高可用）；RDB 快省，AOF 全，混合最优；过期删除靠惰性+定期，内存淘汰才看 maxmemory；容量瓶颈上 Cluster 分 16384 槽。"}]}]');
INSERT INTO json_doc (name, data) VALUES ('topicsNetworkOS', '[{"id":"top-tcp","icon":"🔗","tag":"计算机网络","title":"TCP 三次握手与四次挥手（图解版）","desc":"面试出现率 95%。为什么是三次不是两次？为什么挥手要四次？TIME_WAIT 为什么等 2MSL？一篇讲透。","blocks":[{"t":"h","html":"一、TCP 头部：先认识\\"信封长什么样\\""},{"t":"p","html":"TCP 报文就像寄信，头部就是信封上的信息。面试只需要记住这几个关键字段："},{"t":"code","lang":"text","title":"TCP 头部关键字段","code":"源端口(16bit) | 目的端口(16bit)   ← 找到机器上的哪个进程\\n序号 seq(32bit)                 ← 我发数据里的第几个字节，解决\\"包乱序\\"\\n确认号 ack(32bit)               ← 我期待你下次从第几个字节发，解决\\"包丢了\\"\\n标志位：\\n  SYN=1  发起连接（\\"我们建立连接吧\\"）\\n  ACK=1  确认号有效（\\"收到\\"）\\n  FIN=1  我的数据发完了（\\"我说完了\\"）\\n  RST=1  强制断开（异常）\\n窗口(16bit)                     ← 流量控制用的\\"接收能力通告\\""},{"t":"warn","html":"<b>易错点：</b>序号 seq 和确认号 ack 是 32 位，窗口是 16 位；确认号 = 收到的最后字节序号 + 1，表示\\"期望下一个收到的字节\\"。\\"ack 标志位\\"和\\"确认号 ack\\"是两回事，别混。"},{"t":"h","html":"二、三次握手全过程（带状态机）"},{"t":"code","lang":"text","title":"三次握手","code":"客户端                                服务端\\nCLOSED                               LISTEN   ← 服务端先监听\\n   │ ──── SYN=1, seq=x ────────→ │\\nSYN_SENT                            SYN_RCVD\\n   │ ←── SYN=1,ACK=1, seq=y, ack=x+1 ── │\\n   │ ──── ACK=1, seq=x+1, ack=y+1 ──→ │\\nESTABLISHED                         ESTABLISHED"},{"t":"p","html":"每次握手的通俗翻译：①客户端：\\"你好，我说话的起始序号是 x\\"→ ②服务端：\\"收到（x+1），我这边起始序号是 y\\"→ ③客户端：\\"收到（y+1），开始聊天吧\\"。"},{"t":"qa","q":"为什么必须是三次？两次不行吗？四次不更稳吗？","a":"<b>核心：三次是\\"双方都确认了自己的收发能力正常\\"的最小次数。</b><br>两次的问题：客户端发 SYN 后若因网络滞留，旧的 SYN 晚到服务端，服务端回 ACK 就当连接建立、分配资源傻等——客户端根本不理它，<b>服务端资源被空耗</b>（历史连接陷阱）。三次让客户端有机会对\\"旧 SYN 的响应\\"说 RST 拒绝。<br>四次没必要：服务端的 SYN+ACK 可以合并成一个包发，四次本质是三次的浪费版。<br>深层理论：TCP 是可靠双工协议，需要双方各自确认\\"我的发送和接收都 OK\\"，用 seq/ack 的来回验证恰好三次达成。"},{"t":"qa","q":"第三次握手丢了会怎样？","a":"服务端收不到 ACK，会<b>超时重传 SYN+ACK</b>（重试次数由 tcp_synack_retries 控制，默认 5 次，指数退避：1s、2s、4s…）。而客户端此时已进入 ESTABLISHED，若它直接发数据，数据包自带 ACK，服务端收到后也会直接进入 ESTABLISHED——连接照常建立。"},{"t":"qa","q":"什么是 SYN 洪泛攻击？怎么防？","a":"攻击者伪造大量不同源 IP 的 SYN，服务端每收一个就分配资源进入 SYN_RCVD 并等待，半连接队列被塞满，正常用户连不上。<br><b>防御：</b>① <b>syncookie</b>：不立即分配资源，把连接信息编码进 ISN 返回，收到合法 ACK 再建连接；② 调大半连接队列 backlog；③ 减少 SYN+ACK 重试次数；④ 网关层清洗。"},{"t":"h","html":"三、四次挥手全过程"},{"t":"code","lang":"text","title":"四次挥手（假设客户端主动关）","code":"客户端                                服务端\\nESTABLISHED                         ESTABLISHED\\n   │ ──── FIN=1, seq=u ────────────→ │  ①我说完了\\nFIN_WAIT_1\\n   │ ←── ACK=1, ack=u+1 ───────────  │  ②知道了（此时服务端可能还有数据要发）\\nFIN_WAIT_2                          CLOSE_WAIT\\n   │ ←── FIN=1, ACK=1, seq=w, ack=u+1 │  ③我也说完了\\n                                    LAST_ACK\\n   │ ──── ACK=1, ack=w+1 ──────────→ │  ④好的\\nTIME_WAIT (2MSL) → CLOSED           CLOSED"},{"t":"qa","q":"为什么挥手要四次，比握手多一次？","a":"因为 TCP 是<b>全双工</b>，两个方向的数据要分别关闭。握手时服务端 SYN+ACK 能合并（连接刚建立没有积压数据）；挥手时客户端 FIN 到达后，<b>服务端可能还有没发完的数据</b>，只能先 ACK\\"我知道你要关了\\"，等自己数据发完再发自己的 FIN——ACK 和 FIN 拆成两次，就成了四次。<br><b>极端情况合并成三次：</b>服务端没有数据要发且开启延迟确认合并，FIN+ACK 一起发。"},{"t":"qa","q":"TIME_WAIT 为什么要等 2MSL 才关闭？（高频！）","a":"<b>原因一：保证最后的 ACK 能被重传。</b>若第四次 ACK 丢了，服务端会重传 FIN；如果客户端直接关了，回的是 RST，服务端无法正常关闭。留在 TIME_WAIT 期间收到重传 FIN 还能再 ACK 一次。<br><b>原因二：让旧连接的报文在网络中自然消亡。</b>2MSL = 一个方向的最大存活时间(MSL) × 去和回，确保本次连接的所有报文都过期，不会污染之后复用相同四元组的新连接。<br><b>副作用：</b>高并发短连接服务器（爬虫/压测机）会有几万个 TIME_WAIT 占用端口。解决：开启 <code>tcp_tw_reuse</code>（客户端复用）、改为长连接、调大端口范围 <code>ip_local_port_range</code>。<b>注意 TIME_WAIT 出现在主动关闭方</b>——让服务端主动关还是客户端主动关要权衡。"},{"t":"tip","html":"<b>速记口诀：</b>握手\\"SYN → SYN+ACK → ACK\\"，挥手\\"FIN → ACK → FIN → ACK\\"；握手三次因为要防历史连接，挥手四次因为要等数据发完；主动关的等 2MSL（TIME_WAIT），被动关的最后关（LAST_ACK）。"},{"t":"h","html":"四、TCP 怎么保证可靠性？（总结框架）"},{"t":"list","items":["<b>校验和</b>：首部+数据的校验，检测传输差错","<b>序列号 + 确认应答</b>：数据按序编号，接收方 ack 确认，解决乱序与丢失","<b>超时重传 / 快速重传</b>：超过 RTO 未确认就重发；收到 3 个重复 ACK 立即重发（不等超时）","<b>滑动窗口</b>：流量控制，接收方通告自己还能收多少，防止打死慢接收方","<b>拥塞控制</b>：慢启动→拥塞避免→快重传→快恢复，防止网络被打垮","<b>连接管理</b>：三次握手/四次挥手确保双方状态一致"]}]},{"id":"top-http","icon":"🌐","tag":"计算机网络","title":"HTTP 1.0 → 1.1 → 2 → 3 演进 + HTTPS 握手（图解版）","desc":"HTTP 各版本解决了什么问题？HTTPS 为什么安全？TLS 握手全程 + 证书验证逻辑，一次搞清。","blocks":[{"t":"h","html":"一、四个版本的演进逻辑：每个版本都在解决前代的痛"},{"t":"table","headers":["版本","核心改进","遗留问题"],"rows":[["HTTP/1.0","每请求一个 TCP 连接","连接无法复用，三次握手开销巨大"],["HTTP/1.1","长连接（默认 keep-alive）、管线化、Host 头（虚拟主机）、Chunked 传输","队头阻塞（HOL）：前一个响应没完，后面的必须等；并发受浏览器 6~8 个连接限制"],["HTTP/2","二进制分帧、多路复用（一个连接并发多流）、头部压缩 HPACK、服务器推送","TCP 层队头阻塞：任何一个包丢了，TCP 要等重传，所有流一起卡"],["HTTP/3","换传输层为 QUIC（基于 UDP）：流级独立、0-RTT 建连、连接迁移、内置 TLS1.3","部署/中间设备兼容性，普及中"]]},{"t":"info","html":"<b>一句话记住演进：</b>1.0 每次都建连 → 1.1 复用连接但响应排队 → 2 一个连接多路并发但 TCP 丢包全卡 → 3 用 UDP 自己造可靠性，彻底告别队头阻塞。"},{"t":"h","html":"二、HTTP/1.1 你必须会的细节"},{"t":"list","items":["<b>Keep-Alive</b>：连接复用，减少握手开销；但同一时刻一个连接仍只能处理一个请求（串行）","<b>管线化（Pipelining）</b>：可以连续发多个请求不等响应——但响应必须按序返回，实践中因队头阻塞+代理兼容差几乎没人用","<b>常见方法语义</b>：GET 幂等可缓存 / POST 非幂等 / PUT 幂等替换 / DELETE 幂等 / HEAD 只要头 / OPTIONS 预检（CORS 用）","<b>关键头部</b>：Content-Type、Cache-Control（强缓存）、ETag/If-None-Match 与 Last-Modified/If-Modified-Since（协商缓存）、Cookie/Set-Cookie","<b>状态码族谱</b>：1xx 信息 / 2xx 成功(200 204 206断点续传) / 3xx 重定向(301永久 302临时 304缓存 307保留方法) / 4xx 客户端错(400 401未认证 403禁止 404 429限流) / 5xx 服务端错(500 502网关错 503不可用 504网关超时)"]},{"t":"qa","q":"301 和 302 的区别？对 SEO 有什么影响？","a":"301 永久重定向：搜索引擎会把权重转移到新地址；302 临时：权重保留在原地址。303/307 是 HTTP/1.1 补充：307 保证不把 POST 换成 GET（302 历史上浏览器常违规把 POST 转 GET）。"},{"t":"qa","q":"强缓存和协商缓存的完整流程？","a":"① 浏览器首次请求，服务端带 <code>Cache-Control: max-age=31536000</code> 和 <code>ETag: \\"abc\\"</code>；② 再次请求同 URL，先查本地缓存未过期 → <b>直接用缓存，不发请求</b>（强缓存，200 from disk/memory cache）；③ 过期了，带 <code>If-None-Match: \\"abc\\"</code> 问服务器；④ 资源没变 → 服务端回 <b>304</b>（不带 body，省流量）继续用本地；变了 → 200 + 新内容。<b>缓存决策：</b>HTML 用协商缓存，带 hash 的静态资源用一年强缓存。"},{"t":"h","html":"三、HTTPS = HTTP + TLS：到底安全在哪"},{"t":"p","html":"HTTP 三大裸奔问题：①明文可被<b>窃听</b> ②无校验可被<b>篡改</b>（运营商插广告）③不验证对方身份可被<b>冒充</b>。HTTPS 用 TLS 逐一解决：混合加密防窃听、摘要算法防篡改、数字证书防冒充。"},{"t":"code","lang":"text","title":"TLS 1.2 握手（RSA 密钥交换版）","code":"① ClientHello        → 支持的 TLS 版本、加密套件列表、客户端随机数 C\\n② ServerHello + 证书 ← 选定套件、服务端随机数 S、证书(含公钥)\\n③ 客户端验证证书：\\n     证书链逐级验签（到内置根 CA）→ 域名/有效期/吊销状态\\n     用 CA 公钥验证签名 = 确认\\"这公钥真的是该网站的\\"\\n④ 客户端生成预主密钥 Pre-Master，用服务器公钥加密发送\\n⑤ 双方用 C + S + Pre-Master 算出会话密钥（对称密钥）\\n⑥ 双方互发 Finished（用会话密钥加密的摘要）验证握手未被篡改\\n→ 之后全部用对称密钥通信（快）"},{"t":"qa","q":"为什么 HTTPS 用\\"非对称+对称\\"混合加密，不全用非对称？","a":"非对称（RSA/ECDHE）安全但<b>极慢</b>（大数运算，比对称慢几个数量级），只用来交换\\"会话密钥\\"；数据传输量巨大，用对称密钥（AES/ChaCha20）加密，性能高。各取所长：非对称保密钥交换安全，对称保传输性能。"},{"t":"qa","q":"证书是怎么防\\"中间人伪造\\"的？（理解 HTTPS 的灵魂）","a":"CA 用自己的<b>私钥</b>给网站的公钥+域名等信息<b>签名</b>；浏览器用内置的 <b>CA 公钥</b>验签——私钥签的只有对应公钥能验，而 CA 私钥绝密。中间人可以自己发一张证书，但签名验证不过（没有受信 CA 签发）；就算给真证书转发也因 TLS 握手绑定域名而失败。整条信任链：根 CA → 中间 CA → 网站证书，逐级验签到浏览器内置的根。"},{"t":"qa","q":"TLS 1.3 快在哪？","a":"握手从 2-RTT 减到 <b>1-RTT</b>：ClientHello 就带上密钥交换参数和猜测的套件；支持 <b>0-RTT</b> 会话恢复（复用老会话直接带数据，但有重放风险）。同时废弃了 RSA 密钥交换（不具备前向安全），强制 (EC)DHE——即使服务端私钥泄露，历史流量也解不开。"},{"t":"tip","html":"<b>速记：</b>HTTP 演进主线=消灭队头阻塞；HTTPS 三件套=混合加密+摘要+证书；TLS1.2 两 RTT、TLS1.3 一 RTT + 前向安全。"}]},{"id":"top-tcp-traffic","icon":"🚦","tag":"计算机网络","title":"TCP 流量控制与拥塞控制（滑动窗口全图解）","desc":"流量控制管\\"接收方\\"，拥塞控制管\\"网络\\"。慢启动/拥塞避免/快重传/快恢复四个算法 + 窗口机制，一次理顺。","blocks":[{"t":"h","html":"一、滑动窗口：一切的基础"},{"t":"p","html":"停等式发送（发一个等一个）利用率太低。滑动窗口让发送方<b>不等确认就能连发一段数据</b>（窗口内的字节），收到 ACK 后窗口向前滑动。"},{"t":"code","lang":"text","title":"发送窗口示意","code":"已发送且已确认 │ 已发送未确认 │ 可发送未发送 │ 不可发送\\n              │├──── 发送窗口 ────┤\\n                    ←──── 窗口随 ACK 到达向右滑动 ────→\\n实际发送窗口 = min(rwnd 接收窗口, cwnd 拥塞窗口)"},{"t":"h","html":"二、流量控制：别把接收方打死"},{"t":"p","html":"接收方在每个 ACK 里通告自己的<b>接收窗口 rwnd</b>（缓冲区剩余量）。发送方不得超过它。接收方缓冲区被应用读走数据后，窗口重新变大，通过后续 ACK 通告——这就是\\"流控\\"。"},{"t":"warn","html":"<b>死锁陷阱：</b>接收方缓冲区满 → 通告 rwnd=0 → 发送方停发；之后接收方腾出空间发\\"窗口更新\\"通知，但这个包<b>丢了</b> → 双方互相等待，死锁。<b>解法：</b>发送方收到零窗口后启动<b>坚持定时器</b>，定期发「零窗口探测报文」，探测对方的窗口是否恢复。"},{"t":"h","html":"三、拥塞控制四大算法（面试默写级）"},{"t":"code","lang":"text","title":"cwnd 增长曲线","code":"cwnd\\n │           拥塞避免（线性+1/RTT）\\n │        ／￣＼ssthresh降半后继续线性\\n │      ／       ×3/4 快恢复\\n │    ／  ←超时：cwnd=1 →       ____\\n │  ／慢启动（指数）      （快速重传：3个重复ACK）\\n │／\\n └─────────────────────────── 时间"},{"t":"table","headers":["算法","触发条件","动作"],"rows":[["慢启动","连接刚建立","每 RTT cwnd 翻倍（指数增长），到达 ssthresh 转拥塞避免"],["拥塞避免","cwnd ≥ ssthresh","每 RTT cwnd +1（线性增长，谨慎试探）"],["快重传","收到 3 个重复 ACK","立即重传丢失报文（不等超时），执行快恢复"],["快恢复","紧接快重传","ssthresh = cwnd/2，cwnd = ssthresh（减半继续，不回到 1）"],["（超时重传后）","RTO 超时（严重拥塞）","ssthresh = cwnd/2，cwnd 重置为 1，重新慢启动"]]},{"t":"qa","q":"流量控制和拥塞控制的区别？（必考）","a":"<b>流量控制</b>：端到端问题，防止发送方淹死<b>接收方</b>，依据接收方通告的 rwnd；<b>拥塞控制</b>：全局问题，防止发送方压垮<b>网络</b>，依据丢包/延迟推断拥塞，维护 cwnd。两者共同作用于实际窗口 = min(rwnd, cwnd)。类比：流量控制是\\"你家门口收快递的桌子小\\"，拥塞控制是\\"整条马路堵不堵\\"。"},{"t":"qa","q":"快重传为什么是 3 个重复 ACK 而不是 1 个？","a":"1 个重复 ACK 可能只是<b>乱序</b>（后面的包先到），不代表丢包。3 个重复 ACK 说明后续数据已到达 3 次，目标包大概率真丢了——既避免误判，又比超时（动辄几百 ms）反应快得多，所以触发的是温和的快恢复而不是重头慢启动。"},{"t":"tip","html":"<b>速记：</b>慢启动指数冲 → 到阈值线性爬 → 3 重复 ACK 快重传+减半（快恢复）→ 超时最严重，cwnd 归 1 从头来。"}]},{"id":"top-process","icon":"🖥️","tag":"操作系统","title":"进程、线程、协程与进程通信方式（图解版）","desc":"进程线程到底差在哪？为什么 Redis 单线程也快？虚拟地址空间、上下文切换开销、七种 IPC 对比。","blocks":[{"t":"h","html":"一、进程 vs 线程：一张图看懂"},{"t":"code","lang":"text","title":"进程与线程的资源关系","code":"┌────────── 进程 A（独立地址空间）──────────┐\\n│  代码段  数据段  堆  文件描述符表          │\\n│  ┌────────┐ ┌────────┐ ┌────────┐        │\\n│  │ 线程 1  │ │ 线程 2  │ │ 线程 3  │        │\\n│  │栈/寄存器│ │栈/寄存器│ │栈/寄存器│ ← 私有  │\\n│  └────────┘ └────────┘ └────────┘        │\\n└──────────────────────────────────────┘\\n线程共享：堆、全局变量、打开的文件、信号处理\\n线程私有：栈、寄存器、程序计数器、errno"},{"t":"table","headers":["维度","进程","线程"],"rows":[["地址空间","独立，互不干扰","共享所在进程的地址空间"],["开销","创建/切换大（页表、地址空间）","创建/切换小（只换栈和寄存器）"],["通信","需 IPC（管道/共享内存/消息队列…）","直接读写共享变量（但要加锁）"],["容错","一个崩不影响其他","一个线程段错误整个进程挂"],["比喻","不同工厂","同厂里不同工人，共享车间和原料"]]},{"t":"qa","q":"协程是什么？和线程的区别？","a":"协程是<b>用户态</b>的轻量\\"线程\\"：调度在用户代码里完成（await/yield 让出），<b>不经过内核</b>，切换只保存少量寄存器，纳秒级，单线程可开百万个。线程切换要陷入内核（1~2 微秒起）+ 可能的缓存失效。Go 的 goroutine、Kotlin 协程都是这个思路。<b>限制：</b>协程遇真正的内核阻塞（如同步 socket）会卡住整个线程，所以配非阻塞 IO/IO 多路复用（NIO+事件循环）。"},{"t":"qa","q":"进程上下文切换为什么比线程贵？","a":"进程切换要换<b>页表（虚拟地址空间）</b>→ TLB（页表缓存）大量失效 → 之后内存访问全 miss 重建，这是最大头；还要换内核栈、硬件上下文。线程共享地址空间，只换栈+寄存器，TLB 不受影响。"},{"t":"h","html":"二、进程的七种通信方式（IPC 全家桶）"},{"t":"table","headers":["方式","原理","特点/场景"],"rows":[["匿名管道","内核里的一块环形缓冲，单向","父子进程，\\"ls | grep x\\" 就是它"],["命名管道 FIFO","文件系统里有名字的管道","无亲缘关系进程也能用"],["消息队列","内核中的消息链表","有格式、可按类型取，独立于进程生命周期"],["共享内存","两个进程映射同一块物理内存","最快的 IPC，免拷贝；必须配信号量做同步"],["信号量","内核计数器 + P/V 操作","不是传数据，是做同步/互斥"],["信号","异步通知机制（kill -9 是 SIGKILL）","进程间的事件通知，如 SIGTERM 优雅退出"],["Socket","网络栈端点","跨主机通用，本机可用 Unix Domain Socket（更快）"]]},{"t":"qa","q":"最快的 IPC 是哪个？为什么还要加锁？","a":"<b>共享内存</b>：数据零拷贝，写完对方直接可见，不像管道/消息队列要经过内核两次拷贝（用户→内核→用户）。但正因为它就是同一块内存，两个进程同时读写会竞态，<b>必须配信号量或互斥锁做同步</b>——快是有代价的，同步要自己管。"},{"t":"h","html":"三、调度与死锁（面试常混的点）"},{"t":"list","items":["<b>进程状态机</b>：就绪 → 运行 → 阻塞。注意：阻塞态不能直接回运行态，必须先回就绪排队","<b>调度算法</b>：FCFS（公平但平均等待长）、SJF（平均等待最短但长任务饥饿）、时间片轮转（交互友好）、多级反馈队列（综合最优，Linux 采用 CFS 红黑树按虚拟运行时间公平调度）","<b>死锁四条件</b>：互斥、持有并等待、不可剥夺、循环等待——<b>四者同时成立</b>才死锁；破坏任意一个即可预防（如按固定顺序加锁破坏循环等待、一次性申请所有资源破坏持有并等待）","<b>避免 vs 预防</b>：预防是静态破条件；避免是运行时判断（银行家算法）；检测是允许发生再解除（杀死进程/回滚）"]},{"t":"qa","q":"生产环境怎么排查死锁/死循环？","a":"Java：jstack 看线程 dump，会直接提示 \\"Found one Java-level deadlock\\"；top -Hp 找 CPU 100% 的线程 → printf \\"%x\\" 转十六进制 → 在 dump 里定位。OS 级：ps/pstack 看各线程栈。预防层面：锁排序 + tryLock 带超时 + 减少锁粒度。"},{"t":"tip","html":"<b>速记：</b>进程=资源分配单位，线程=调度执行单位；IPC 最快共享内存（但要信号量）；死锁四条件破坏其一即可。"}]},{"id":"top-memory-io","icon":"💾","tag":"操作系统","title":"内存管理（虚拟内存/页表/缺页）与 IO 多路复用（select/poll/epoll 图解）","desc":"为什么需要虚拟内存？malloc 的内存就是物理内存吗？Redis/Nginx 高并发靠的 epoll 到底强在哪？","blocks":[{"t":"h","html":"一、虚拟内存：每个进程都以为自己独占内存"},{"t":"p","html":"CPU 访问的是<b>虚拟地址</b>，由 MMU 通过<b>页表</b>翻译成物理地址。这带来三个好处：①隔离（进程互不可见，安全）②每个进程有统一连续的地址空间（编程简单）③按需加载 + 交换，物理内存可以超卖。"},{"t":"code","lang":"text","title":"地址翻译过程","code":"虚拟地址 [ 页号 | 页内偏移 ]\\n              │\\n              ▼ 查页表（页号→物理页框号）\\n      ┌─ 页表项有效 ──→ 物理地址 = 页框号 拼接 偏移\\n      └─ 无效/不在内存 ──→ 缺页中断 → OS 从磁盘调入 → 可能淘汰页面\\n\\n加速：TLB（快表）缓存最近的翻译结果，命中率 99%+，\\n     多级页表（x86-64 四级）省页表内存"},{"t":"qa","q":"malloc 返回成功，物理内存就分配了吗？","a":"没有。malloc 只是分配<b>虚拟地址空间</b>；第一次真正写入时触发<b>缺页中断</b>，OS 才分配物理页——这叫<b>惰性分配</b>。所以 malloc 4GB 在 8GB 机器上能成功，真写满才会出问题。这也是 oom_score/overcommit 设置存在的原因。Java 的 -Xmx 也是虚拟内存预留，RSS（实际物理占用）通常小于堆设置。"},{"t":"qa","q":"页面置换算法有哪些？","a":"OPT（最优，理论基准，未来最久不用，无法实现）、FIFO（简单但有 Belady 异常：加内存缺页可能反而变多）、LRU（过去最久未用，接近 OPT 但硬件开销大，实践用时钟算法 Clock 近似）、LFU。Linux 用的类 LRU 双链表（active/inactive）。"},{"t":"h","html":"二、五种 IO 模型"},{"t":"table","headers":["模型","过程","特点"],"rows":[["阻塞 IO","recvfrom 一直等数据就绪+拷贝","最简单，一线程一连接，线程浪费"],["非阻塞 IO","没数据立刻返回 EWOULDBLOCK，轮询","不卡但 CPU 空转"],["IO 多路复用","select/poll/epoll 等多个 fd，就绪后再读写","单线程管上万连接（Nginx/Redis/Netty）"],["信号驱动 IO","SIGIO 通知就绪","实践少用"],["异步 IO（AIO）","内核完成数据拷贝后通知\\"已完成\\"","真正异步；Linux 原生 AIO 有限制，IO_uring 是新星"]]},{"t":"h","html":"三、select / poll / epoll 对比（必考三兄弟）"},{"t":"code","lang":"text","title":"epoll 的工作方式","code":"epoll_create → 内核建红黑树(存fd) + 就绪链表\\nepoll_ctl   → 增删改关心的 fd 及事件（挂到红黑树，注册回调）\\nepoll_wait  → 只看就绪链表：有就绪返回就绪列表；没有就睡眠\\n\\n数据到达网卡 → 中断 → 内核回调把该 fd 放进就绪链表 →\\n唤醒 epoll_wait → 返回\\"哪些 fd 就绪\\"，直接逐个处理"},{"t":"table","headers":["对比项","select","poll","epoll"],"rows":[["fd 上限","1024（fd_set 固定）","无（链表）","无（可达十万+）"],["fd 传递","每次调用把整个集合拷入内核","同左","ctl 注册一次，wait 不重复传"],["就绪查找","O(n) 全量遍历所有 fd","O(n)","O(1) 只返回就绪列表"],["触发模式","水平触发 LT","LT","LT + 边缘触发 ET"]]},{"t":"qa","q":"epoll 为什么快？","a":"三个原因：①<b>红黑树管理 fd</b>，注册一次反复使用，免去每次全量拷贝；②<b>事件回调</b>：数据到达由内核主动把 fd 放入就绪链表，而不是轮询检测；③<b>epoll_wait 只返回就绪 fd</b>，用户态处理量与活跃连接数成正比，与总连接数无关——10 万连接只有 100 活跃，就只处理 100 个。"},{"t":"qa","q":"LT 和 ET 的区别？Redis/Nginx 用哪个？","a":"<b>LT 水平触发</b>：只要缓冲区还有数据，每次 epoll_wait 都会通知——编程简单，一次读不完下次还提醒；<b>ET 边缘触发</b>：只在状态变化时通知一次——必须配合非阻塞 fd 一次读干（循环读到 EAGAIN），少唤醒效率高，但漏读就再也不提醒。Redis 用 LT（简单可靠）；Nginx 两种都支持，高并发常配 ET。"},{"t":"qa","q":"Redis 6 之前单线程为什么还能这么快？","a":"①<b>纯内存</b>操作；②<b>epoll + IO 多路复用</b>，单线程处理海量连接不成瓶颈；③<b>单线程无锁无切换</b>，命令天然原子；④数据结构专为内存优化（SDS/跳表/压缩列表）。瓶颈在网络 IO，所以 6.0 把网络读写改成多线程（IO Threads），命令执行仍是单线程——保住原子性的同时吃满网卡。"},{"t":"tip","html":"<b>速记：</b>虚拟内存=页表翻译+惰性分配；epoll 三招=红黑树+回调+就绪链表；LT 稳 ET 快；Redis 快=内存+epoll+单线程无锁。"}]}]');
