e"},{"id":"s01717","name":"【觉醒】卧龙·诸葛亮","category":"general","rarity":6,"icon":"👑","desc":"七星灯未熄，三分天下的棋局仍在推演。","only":"furnace"},{"id":"s01718","name":"【觉醒】冢虎·司马懿","category":"general","rarity":6,"icon":"👑","desc":"忍到最后的人，才配拿走整盘棋。","only":"furnace"},{"id":"s01719","name":"【觉醒】江东·周瑜","category":"general","rarity":6,"icon":"👑","desc":"曲有误，周郎顾；火起时，樯橹灰飞。","only":"furnace"},{"id":"s01720","name":"【觉醒】常胜·赵子龙","category":"general","rarity":6,"icon":"👑","desc":"七进七出，血染征袍，怀中阿斗仍在安睡。","only":"furnace"},{"id":"s01721","name":"【觉醒】奸雄·曹孟德","category":"general","rarity":6,"icon":"👑","desc":"宁教我负天下人，也要把乱世收拾干净。","only":"furnace"},{"id":"s01722","name":"【觉醒】枭雄·刘玄德","category":"general","rarity":6,"icon":"👑","desc":"屡败屡战，最后站上蜀中之巅。","only":"furnace"},{"id":"s01723","name":"【觉醒】碧眼·孙仲谋","category":"general","rarity":6,"icon":"👑","desc":"守得住江东，也等得起天下。","only":"furnace"},{"id":"s01724","name":"【觉醒】凤雏·庞士元","category":"general","rarity":6,"icon":"👑","desc":"落凤坡的箭，终究没能射落他的谋。","only":"furnace"},{"id":"s01725","name":"【觉醒】鬼才·郭奉孝","category":"general","rarity":6,"icon":"👑","desc":"算无遗策，只是天不假年。","only":"furnace"},{"id":"s01726","name":"【觉醒】毒士·贾文和","category":"general","rarity":6,"icon":"👑","desc":"一言乱国，一计安身。","only":"furnace"},{"id":"s01727","name":"【觉醒】无双·吕奉先","category":"general","rarity":6,"icon":"👑","desc":"辕门射戟，方天画戟下再无对手。","only":"furnace"},{"id":"s01728","name":"刘菊","category":"general","rarity":7,"icon":"🌸","desc":"菊，隐逸而傲霜。不与时人争春色，独向寒风开一枝。\\n——全池唯一一张「唯一品质」，拿到即绝版。","only":"furnace","unique":true}]}') ON DUPLICATE KEY UPDATE data = VALUES(data);
INSERT INTO json_doc (name, data) VALUES ('syllabusDetails', '{"m0-u0":{"points":[["JDK / JRE / JVM 三者关系","JDK = 开发工具 + JRE，JRE = 运行环境 + JVM。装了 JRE 只能运行不能编译（缺 javac），这是面试第一道送分/送命题。"],["环境变量 PATH 与 JAVA_HOME","PATH 让命令行找到 java.exe；JAVA_HOME 供 Maven、Tomcat、IDEA 引用。改完必须重开终端才生效。"],["IDEA 必会操作","自动导包、psvm/sout 快捷键、Debug 断点（step over/into、条件断点）、全局搜索 Ctrl+Shift+F——调试速度决定学习速度。"],["第一个 HelloWorld 与编译链路","从 javac 手动编译到 IDEA 一键运行，要讲清 .java → .class → 类加载 → JVM 执行的完整链路。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u1":{"points":[["变量与默认值","成员变量有默认值（0/null/false），局部变量必须先初始化再用——编译器强制。"],["8 大基本类型","byte/short/int/long/float/double/char/boolean 的字节数与取值范围要背；long 字面量加 L、float 加 f，char 底层是 Unicode 码。"],["运算符细节","& 与 && 的短路区别、i++ 与 ++i 的先后、整数除法丢小数（5/2=2）、取余符号跟被除数。"],["类型转换","自动提升小→大，强制转换大→小（可能精度丢失）。经典：char+int 得 int；0.1+0.2 != 0.3 的浮点误差要用 BigDecimal。"],["Scanner 与进制","nextInt 后接 nextLine 会读到残留回车——高频小坑；0b/0x 字面量认识即可。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u2":{"points":[["if / else","分支覆盖要完整，嵌套别超三层；多分支用 else if 阶梯，重复值多时换 switch。"],["switch","支持 byte/short/int/char/String/枚举；漏 break 会穿透到下一个 case（fall-through）。JDK14+ 箭头语法不穿透更安全。"],["for / while / do-while","已知次数用 for、未知用 while、至少一次用 do-while。死循环多半是循环变量忘了更新。"],["break / continue","break 跳出本层循环、continue 跳过本次；带标签的 break 能跳出多层（知道即可，别炫技）。"],["嵌套循环训练","九九乘法表、打印金字塔：外层控行数、内层控每行内容，是逻辑思维的基础体操。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u3":{"points":[["值传递本质","Java 只有值传递：基本类型拷贝值，引用类型拷贝引用——方法内改对象属性生效、给参数整体重新赋值不影响外部。这是高频辨析题。"],["重载 Overload","同名不同参（类型/个数/顺序不同即构成重载），与返回值无关；调用时优先精确匹配。"],["递归","必须有终止条件，否则 StackOverflowError。斐波那契、汉诺塔是入门；理解调用栈的压栈弹栈。"],["可变参数","int... 本质是数组，一个方法只能一个可变参数且放最后。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u4":{"points":[["初始化与默认值","静态 int[]{1,2} 与动态 new int[5] 两种写法；length 是属性不是方法。"],["遍历与基础操作","增强 for、求最值、反转、查找；下标越界 ArrayIndexOutOfBoundsException 是最常见的运行时异常。"],["二维数组","本质是数组的数组，每行长度可不同（不规则数组），内存不是连续矩形。"],["排序与 Arrays 工具类","冒泡/选择手写一遍理解思想；Arrays.sort / binarySearch / copyOf / fill / asList 日常够用。"],["引用语义陷阱","数组是对象，赋值传引用——两个变量指向同一数组时会联动修改；asList 返回的是定长视图。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u5":{"points":[["类与对象","类是模板、对象是实例；new 在堆上分配内存，栈里只存引用。"],["构造器","没写构造器才有默认无参构造器；重载多个构造器；this(...) 调用兄弟构造器必须放第一行。"],["this 关键字","区分成员变量与同名形参；this 代表当前对象引用，静态方法里不可用。"],["封装","private + getter/setter：外部不能直接改字段，内部实现可以自由重构——这是封装的真正收益。"],["继承","extends 单继承；super 调父类成员与构造器；重写遵守「两同两小一大」（方法名参数相同、返回值与异常更小、权限更大）。"],["多态","父类引用指向子类对象：编译看左边（能调什么）、运行看右边（实际执行谁）。成员变量与静态方法没有多态，必考辨析。"],["instanceof 与向下转型","向下转型前必须 instanceof 判断，否则 ClassCastException；JDK16+ 模式匹配 if (s instanceof String str) 更香。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u6":{"points":[["static","静态成员属于类不属于实例；静态方法不能访问实例成员、不能用 this。静态代码块在类加载时只执行一次。"],["final","修饰类不能被继承、方法不能被重写、变量不能重新赋值；final 引用指向的内容仍可变（final list 可 add）。"],["访问权限四级","private < 默认（包） < protected（包+子类） < public，可见范围表格要能默写。"],["代码块执行顺序","静态代码块（类加载一次）→ 构造代码块（每次 new）→ 构造器；父子类穿插执行顺序是经典面试题。"],["内部类","成员/静态/局部/匿名四种；匿名内部类是事件监听、回调的前置知识，本质是「实现了接口的没名字的类」。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u7":{"points":[["抽象类","不能实例化但可以有构造器、普通方法、成员变量；用 abstract 方法约束子类——模板方法模式的地基。"],["接口","JDK8 前只有抽象方法；8+ 增加 default / static，9+ 增加 private。成员变量默认 public static final。"],["抽象类 vs 接口","语义：「是什么」用抽象类、「能做什么」用接口；类单继承、接口多实现。对比题每年必考。"],["default 方法冲突","实现类同时继承两个含同名 default 方法的接口时必须重写来解决冲突。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u8":{"points":[["String 不可变与常量池","字符串字面量进常量池、new 出来在堆；== 比引用、equals 比内容——Java 第一面试题。"],["StringBuilder / StringBuffer","循环里拼字符串必须用 StringBuilder（每次 + 都 new 新对象）；StringBuffer 线程安全但慢，单线程用不上。"],["Object 核心方法","equals 与 hashCode 必须成对重写（否则 HashMap 出 bug）；toString 默认输出类名@哈希。"],["包装类与自动装箱","Integer 缓存 -128~127：小值 == 为 true、大值为 false，高频陷阱题；拆箱 null 报 NPE。"],["日期时间","Date/Calendar 线程不安全难用，用 java.time（LocalDate/LocalDateTime/DateTimeFormatter），格式化线程安全。"],["Math / System / Random","abs/max/round；System.currentTimeMillis 计时、arraycopy 底层复制；知道即可。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u9":{"points":[["两大体系总览","Collection（List/Set/Queue）与 Map 的继承树画一遍，脑子里有地图再学细节。"],["ArrayList vs LinkedList","底层动态数组 vs 双向链表；随机访问 O(1) vs O(n)，头插 O(n) vs O(1)；ArrayList 扩容 1.5 倍。"],["HashMap 原理","数组+链表+红黑树；put 流程（hash→寻址→冲突链表→树化阈值 8）、容量 2 的幂、负载因子 0.75、扩容 rehash。"],["HashSet 去重原理","依赖 hashCode + equals；只重写 equals 不重写 hashCode 会去重失败。"],["遍历与 fail-fast","迭代时用 iterator.remove；直接 list.remove 抛 ConcurrentModificationException（modCount 校验）。"],["对应源码专栏","展开本站「原理与源码专栏」：ArrayList / HashMap / ConcurrentHashMap 三篇逐行读，面试直接上一个档次。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u10":{"points":[["异常体系","Throwable → Error（OOM/StackOverflow，程序处理不了）与 Exception；Exception 分 Checked（必须处理）与 Runtime（可不处理）。"],["try-catch-finally","catch 从子类到父类匹配；finally 一定执行（除 System.exit / JVM 崩溃）；finally 里 return 会吞掉异常与返回值——禁止这么写。"],["throw 与 throws","throw 主动抛异常对象；throws 在方法签名声明。自定义异常一般继承 RuntimeException。"],["try-with-resources","实现 AutoCloseable 的资源自动关闭，彻底替代 finally 里关流的样板代码（JDK7+）。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u11":{"points":[["泛型类 / 接口 / 方法","类型参数化把类型错误拦在编译期；静态方法不能使用类的泛型参数，要自己声明 <T>。"],["类型擦除","泛型只在编译期存在，运行时被擦为 Object / 上界；因此不能 new T()、不能 T.class。"],["通配符与 PECS","? extends 上界只读、? super 下界只写——Producer Extends, Consumer Super，集合 API 设计的核心思想。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u12":{"points":[["流的分类","字节流/字符流、输入/输出、节点流/处理流；纯文本用字符流（省去编解码麻烦），二进制必须字节流。"],["缓冲流","BufferedReader/BufferedWriter 带内存缓冲，逐行读 readLine；不缓冲的流逐字节读文件性能差一个量级。"],["序列化","实现 Serializable；serialVersionUID 不一致会反序列化失败；transient 与 static 字段不序列化。"],["File 与递归遍历","listFiles + 递归删除/统计目录大小是经典练习，顺便练异常处理。"],["内存操作流与转换流","ByteArrayOutputStream 内存流；InputStreamReader 指定字符集解决乱码。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u13":{"points":[["线程创建三方式","继承 Thread / 实现 Runnable / Callable+FutureTask（有返回值可抛异常）；推荐 Runnable 解耦任务与线程。"],["六种线程状态","NEW→RUNNABLE→BLOCKED/WAITING/TIMED_WAITING→TERMINATED 状态图要画得出；sleep 不释放锁、wait 释放锁。"],["线程安全三要素","原子性/可见性/有序性，分别对应原子类或锁 / volatile / 禁止重排序——所有并发方案都围着这三个打转。"],["synchronized","对象锁与类锁；底层 monitor（对象头 Mark Word）；锁升级：偏向→轻量级（自旋）→重量级。"],["线程池 ThreadPoolExecutor","七大参数（核心/最大/存活/单位/队列/工厂/拒绝策略）；提交顺序核心→队列→非核心→拒绝；为什么不许用 Executors 快捷方法（无界队列 OOM）。"],["volatile","保证可见性与有序性、不保证原子性——i++ 用它照样错；底层是内存屏障。"],["Lock 与 AQS","ReentrantLock 支持可中断/公平锁/多条件队列；AQS（state + CLH 队列）是 Semaphore/CountDownLatch 的共同地基。"],["ThreadLocal","每个线程一份副本，底层是 Thread 的 ThreadLocalMap；不 remove 在线程池里会内存泄漏与脏数据。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u14":{"points":[["运行时数据区","堆/虚拟机栈/本地方法栈/程序计数器/方法区（JDK8+ 元空间）；线程私有 vs 共享要分清，OOM 常发生在堆与元空间。"],["对象创建流程","类加载检查→分配内存（指针碰撞/TLAB）→零值初始化→设置对象头→执行构造。"],["GC 基础","可达性分析（GC Roots）而非引用计数；四种引用：强/软/虚/弱及其回收时机。"],["分代收集","新生代 Eden:S0:S1 = 8:1:1，MinorGC 频繁且快；对象 15 岁晋升老年代；FullGC 触发条件与危害。"],["常见 OOM 排查","heap OOM 用 jmap dump + MAT 分析；stack OOM 查无限递归；metaspace OOM 查动态类生成（CGLib）。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u15":{"points":[["Lambda 与函数式接口","四大内置：Function/Consumer/Supplier/Predicate；@FunctionalInterface 只能有一个抽象方法。"],["Stream API","中间操作惰性求值、终端操作触发执行；map/filter/sorted/collect 三件套；并行流慎用。"],["Optional","用 ofNullable+map+orElseGet 链式防 NPE，别用裸 get()。"],["接口 default 与新日期","default 方法让接口平滑演进；java.time 全线程安全，替代 Date。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u16":{"points":[["网络三要素","IP 定主机、端口定进程、协议定语言；TCP/UDP 区别（可靠连接 vs 无连接快）在此打牢。"],["Socket 编程","TCP 用 ServerSocket accept + Socket 一问一答；UDP 用 DatagramPacket 收发——手写一个 echo 服务。"],["BIO 的瓶颈","一连接一线程，连接多线程爆；理解它才能理解 NIO 多路复用与 Netty 的价值。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u17":{"points":[["Class 对象","三种获取：类名.class / 对象.getClass() / Class.forName；反射是运行时的「照镜子」。"],["反射操作成员","getDeclaredMethod/Field + setAccessible(true) 绕过 private——框架能注入私有字段的原因。"],["注解与元注解","@Retention（SOURCE/CLASS/RUNTIME）与 @Target 决定注解存活期与位置；运行期注解靠反射读取。"],["动态代理","JDK 代理需接口、CGLib 生成子类；AOP 的实现基础——Spring 代理选型面试必考。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m0-u18":{"points":[["单例模式","饿汉/懒汉加锁/双重检查锁（volatile 防重排序）/静态内部类/枚举五种写法线程安全对比，至少会三种。"],["工厂模式","简单工厂 → 工厂方法 → 抽象工厂的演进：新增产品不动老代码（开闭原则）。"],["建造者与原型","链式 setter 构建复杂对象，Lombok @Builder 即此思想。"],["策略与模板方法","策略消灭 if-else（配合 Map 注入）；模板方法父类定骨架、子类填细节。"],["观察者与代理","事件监听/消息发布的基础；动态代理是 AOP 底层，学完回看 Spring 章节会豁然开朗。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"],["章节测验","quiz"]]},"m1-u0":{"points":[["关系模型与库/表/行/列","表=实体、行=记录、列=字段；先用 ER 图把实体关系画清再动手建表。"],["MySQL 安装与初始化","选 8.0；字符集统一 utf8mb4（能存 emoji）； Windows 服务管理、root 密码与远程授权。"],["客户端连接","命令行 mysql -uroot -p 与 Navicat/DataGrip 图形化并用；连接本质是 TCP + MySQL 协议。"],["SQL 语句四大类","DDL（结构）/ DML（数据）/ DQL（查询）/ DCL（权限），对应 CREATE、INSERT、SELECT、GRANT。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u1":{"points":[["DDL 建库建表","CREATE/ALTER/DROP；类型选择：整数按范围、金额必须 DECIMAL、时间 DATETIME、定长 CHAR 变长 VARCHAR。"],["DML 增删改","INSERT 批量多值写法；UPDATE/DELETE 必须带 WHERE——生产环境忘 WHERE 是顶级事故。"],["DQL 查询与执行顺序","书写顺序 SELECT..FROM..WHERE..ORDER..LIMIT，执行顺序 FROM→WHERE→SELECT→ORDER→LIMIT；DISTINCT 去重。"],["WHERE 条件全家桶","= <> IN BETWEEN LIKE（% 任意、_ 单个）；NULL 判断必须 IS NULL，= NULL 永远为假。"],["ORDER / LIMIT 与深分页","多字段排序、LIMIT offset,size；LIMIT 100000,10 慢是因为扫描并丢弃前 10 万行——游标/延迟关联优化。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u2":{"points":[["笛卡尔积","两表 JOIN 不写 ON 就是笛卡尔积，行数相乘——理解连接的本质是带条件的笛卡尔积。"],["内连接 INNER JOIN","取两表满足条件的交集，最常用；表起别名让 SQL 可读。"],["左/右外连接","LEFT JOIN 以左表为准、右表缺的补 NULL；「查所有用户及其订单（含没下过单的）」是标准场景。"],["子查询与 EXISTS","标量/列/表子查询；IN 大表会退化，常用 EXISTS 小表驱动大表优化。"],["UNION 与 UNION ALL","UNION 去重多一次排序开销，不需要去重用 UNION ALL。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u3":{"points":[["聚合函数","COUNT/SUM/AVG/MAX/MIN 忽略 NULL；COUNT(*) 与 COUNT(列) 的区别（列会跳过 NULL）。"],["GROUP BY","select 里的非聚合列必须出现在 GROUP BY 中（only_full_group_by 默认开启）；按部门统计是标配练习。"],["HAVING","对分组后的结果过滤；WHERE 过滤行、HAVING 过滤组，执行时机不同。"],["完整执行顺序","FROM→ON→JOIN→WHERE→GROUP BY→HAVING→SELECT→DISTINCT→ORDER BY→LIMIT，能默写才能解释各种怪现象。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u4":{"points":[["三大范式","1NF 字段原子、2NF 消除部分依赖、3NF 消除传递依赖；现实常反范式冗余换取 JOIN 性能，知道为什么违背。"],["ER 图与关系落表","一对多在多方加外键列、多对多建中间表、一对一可拆表或合并。"],["主键与约束","自增主键顺序插入友好 vs 分布式用雪花 ID；NOT NULL/DEFAULT/UNIQUE 的语义。"],["逻辑外键 vs 物理外键","互联网公司普遍不建物理外键（影响写入与扩展），一致性由应用层保证——要能说清取舍。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u5":{"points":[["B+ 树为什么赢","相比 B 树：数据全在叶子且叶子成链表（范围查询强）；相比哈希：支持排序与前缀匹配；树矮=磁盘 IO 少。"],["聚簇索引与回表","InnoDB 主键索引即数据本身；二级索引叶子存主键，查非索引列要回表——覆盖索引可免回表。"],["最左前缀原则","联合索引 (a,b,c) 支持 a / a,b / a,b+c，跳过 a 就失效；范围查询后的列失效。"],["索引失效场景","对索引列做函数/运算、隐式类型转换（字符串列传数字）、LIKE ''%x''、OR 连接非索引列——每条都能举例。"],["EXPLAIN 执行计划","重点看 type（ALL 全表扫最差→const 最优）、key、rows、Extra（Using index/filesort/temporary）。"],["索引实践","不是越多越好（写入要维护）；区分度高的列优先、长字符串用前缀索引。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u6":{"points":[["ACID 与实现","原子性靠 undo log 回滚、持久性靠 redo log、隔离性靠锁+MVCC、一致性是前三者的结果。"],["并发问题与隔离级别","脏读/不可重复读/幻读 × 读未提交/读已提交/可重复读/串行化；MySQL 默认可重复读 RR。"],["MVCC 原理","每行带隐藏版本链（roll_pointer→undo log），事务用 ReadView 判断可见性；RC 每次查询生成 ReadView、RR 首次生成——这就是两级别的本质差异。"],["锁机制","行锁（记录锁）/间隙锁/临键锁；共享锁 FOR SHARE、排他锁 FOR UPDATE；死锁用 SHOW ENGINE INNODB STATUS 看最后一段。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u7":{"points":[["慢查询定位","开启 slow_query_log 设 long_query_time，用 mysqldumpslow 或 pt-query-digest 分析 TOP SQL。"],["索引层优化","该建就建、失效就修；避免 SELECT *（回表+网络），覆盖索引优先。"],["写法层优化","深分页游标化、JOIN 小表驱动大表、批量插入合并、避免函数包在索引列上。"],["架构层优化","读写分离、缓存前置、分库分表是最后手段——先把 SQL 和索引做好。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u8":{"points":[["为什么需要连接池","TCP 建连+认证开销大，池化复用；核心参数：最小/最大连接、空闲回收、获取超时。"],["Druid vs HikariCP","Spring Boot 2+ 默认 HikariCP（更快更轻）；Druid 强在监控页面与 SQL 统计。"],["连接泄漏排查","借了不还导致池干涸接口卡死；设置 leakDetectionThreshold 打印泄漏堆栈。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m1-u9":{"points":[["MongoDB","文档型：schema 灵活、适合日志/画像/快速迭代；弱在多表事务。"],["PostgreSQL","更严格的 SQL 标准、JSONB、丰富的扩展生态；国内新一代默认库趋势。"],["Elasticsearch / HBase","搜索倒排、列存宽表——按「数据形状+查询模式」选型，而不是背名词。"]],"links":[["第 5 章 · MySQL 数据库","ch5"],["章节测验","quiz"],["易错点考场","pitfalls"]]},"m2-u0":{"points":[["文档结构与常用标签","标题/段落/列表/图片/超链接/表格；块级独占一行、行内随内容。"],["表单","input 的 text/password/radio/checkbox/file 等类型、label 关联提升可用性、required/placeholder 原生校验。"],["语义化标签","header/nav/main/article/footer：可读性、SEO、无障碍三重收益。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u1":{"points":[["选择器与优先级","标签<类<id<行内；权重 (a,b,c) 计算，!important 尽量别用。"],["盒模型","content+padding+border+margin；* { box-sizing: border-box } 是现代项目标配。"],["Flex 布局","主轴/交叉轴、justify-content/align-items、flex:1 = flex-grow:1+shrink:1+basis:0；骰子布局练到熟。"],["定位","static/relative（原位参照）/absolute（最近定位祖先）/fixed（视口）/sticky（滚动吸附）；z-index 与层叠上下文。"],["响应式入门","媒体查询 @media、rem/vw 单位、移动优先的写法顺序。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u2":{"points":[["变量与类型","var 函数作用域可重复声明（坑）vs let/const 块级；基本类型栈存值、引用类型堆存对象。"],["函数与 this","普通函数 this 看调用者、箭头函数 this 词法继承外层；call/apply/bind 手动指定。"],["闭包与作用域","函数记住定义时的词法环境；计数器/防抖节流都靠它——面试核心概念。"],["对象与数组高阶方法","解构、展开、map/filter/reduce/find；引用比较与浅拷贝（structuredClone 深拷贝）。"],["DOM 操作","querySelector 查、createElement+append 增、remove 删；批量操作用 DocumentFragment。"],["事件模型","捕获→目标→冒泡；addEventListener 第三参、e.stopPropagation；事件委托把监听挂父级，性能关键。"],["异步演进","回调地狱→Promise 链→async/await 语法糖；事件循环：宏任务（setTimeout）与微任务（Promise.then）顺序。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u3":{"points":[["let/const 与暂时性死区","块级作用域 + 先声明后使用；循环里的 let 每轮新建绑定（经典 setTimeout 问题）。"],["箭头函数与模板串","没有自己的 this/arguments，不能作构造器；`多行 ${插值}` 取代拼接。"],["解构与剩余参数","对象/数组解构带默认值；...rest 收集参数、...spread 展开。"],["class 与模块","ES6 class 是原型的语法糖；import/export 编译期静态分析，可 tree-shaking。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u4":{"points":[["fetch 与 Axios","fetch 返回 Promise 且 404 不 reject（要自己判 res.ok）；Axios 拦截器统一加 token 与错误处理。"],["同源策略与 CORS","协议+域名+端口全同才同源；简单请求与预检 OPTIONS；开发用 Vite 代理转发最省事。"],["JSON 与序列化","JSON.stringify 会丢函数与 undefined；日期变 ISO 字符串——数据过网络就是纯文本。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u5":{"points":[["组合式 API 基础","setup + ref（包装值）与 reactive（对象）；ref 在 JS 里要 .value，模板里自动解包。"],["computed 与 watch","computed 有缓存派生值；watch 监听副作用（请求/深监听 deep/immediate）。"],["组件通信","props 下行、emit 上行；v-model 是 prop+emit 的语法糖；provide/inject 跨层。"],["插槽 slot","默认/具名/作用域插槽——把「内容」当参数传给组件。"],["生命周期与请求时机","onMounted 发请求；onUnmounted 清理定时器与监听。"],["路由与状态","Vue Router：动态路由/嵌套/导航守卫；Pinia：defineStore + state/getters/actions，比 Vuex 简洁。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u6":{"points":[["Node 与 npm/pnpm","package.json、语义化版本 ^~、依赖树与 lock 文件；pnpm 硬链接省磁盘。"],["Vite vs Webpack","Vite 开发用原生 ESM 按需编译+esbuild 预构建所以快；Webpack 全量打包。"],["构建与环境变量","npm run build 产物 dist；.env.development/.env.production 与 import.meta.env。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m2-u7":{"points":[["函数组件与 JSX","JSX 编译为 createElement 调用；组件就是返回 UI 的函数。"],["Hooks 心智模型","useState 触发重渲染、useEffect 处理副作用（依赖数组决定何时跑）；与 Vue 组合式 API 思想相通，学会一个迁移很快。"],["生态速览","React Router、Redux/Zustand、React 18 并发特性——面试聊视野够用。"]],"links":[["第 4 章 · 前端开发","ch4"]]},"m3-u0":{"points":[["坐标与依赖管理","groupId:artifactId:version 唯一定位；scope 决定参与编译/打包/传递（provided/test）。"],["依赖传递与冲突仲裁","最短路径优先、同深度先声明优先；<exclusion> 排除、<dependencyManagement> 统一版本不实际引入。"],["生命周期与常用命令","clean/default/site 三套生命周期；clean compile package install deploy 的差别（install 装本地库）。"],["多模块聚合工程","父 pom 管版本、子模块各司其职——真实项目都是多模块，提前养成习惯。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u1":{"points":[["IoC 控制反转","对象的创建与依赖装配交给容器；自己用 Map 存单例手写一个迷你容器，面试讲原理立得住。"],["DI 注入三方式","构造器注入（推荐，不可变+能暴露循环依赖）、Setter、字段注入（@Autowired 直接打字段，测试难）。"],["Bean 作用域","singleton 默认全局一份——有状态字段会互相污染；prototype 每次新建。"],["Bean 生命周期","实例化→属性填充→Aware→BeanPostProcessor 前置→init→后置→销毁；扩展点决定你能在哪插一脚。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u2":{"points":[["核心术语","切面 Aspect、连接点 JoinPoint、切点 Pointcut、通知 Advice（前置/后置/环绕/返回/异常）。"],["切点表达式","execution(* com.x.service..*.*(..)) 与 @annotation(自定义注解) 两种最常用写法。"],["典型应用","接口日志与耗时统计、声明式事务（TransactionInterceptor 就是环绕通知）、权限校验。"],["代理与自调用失效","JDK 接口代理 vs CGLib 子类代理；this.method() 不走代理所以注解失效——高频事故题。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u3":{"points":[["DispatcherServlet 流程","请求→HandlerMapping 找方法→HandlerAdapter 反射调用（参数解析/消息转换）→返回 JSON 或视图。"],["常用注解与参数绑定","@RestController=@Controller+@ResponseBody；@PathVariable 取路径、@RequestParam 取查询串、@RequestBody 收 JSON。"],["Boot 自动装配","@EnableAutoConfiguration 读 AutoConfiguration.imports 清单 + @ConditionalOnXxx 条件过滤——「约定大于配置」的实现。"],["配置文件与多环境","application.yml 优先级：命令行 > 外部文件 > jar 内；profile 切 dev/test/prod。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u4":{"points":[["Filter","Servlet 规范、在 DispatcherServlet 之前：编码、CORS 等粗粒度横切。"],["Interceptor","preHandle/postHandle/afterCompletion，Spring 管理、能拿到 HandlerMethod——鉴权日志更合适。"],["执行顺序对比","Filter 前置 → DispatcherServlet → Interceptor.preHandle → Controller；三者职责边界是常见面试题。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u5":{"points":[["Mapper 代理原理","接口没有实现类，MapperProxy 动态代理按「全限定名.方法名」定位 XML 里的 SQL——与 Spring 注入无实现接口同理。"],["#{} 与 ${}","#{} 预编译占位防注入；${} 字符串拼接有注入风险，只在 order by 列名等白名单场景用。"],["动态 SQL 与批量","<if>/<where>/<foreach>；foreach 批量插入注意 max_allowed_packet。"],["MyBatis-Plus 提效","BaseMapper CRUD、LambdaQueryWrapper 类型安全查询、分页插件、代码生成器。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u6":{"points":[["资源与动词","URL 是名词复数、HTTP 方法表达动作：GET 查 POST 增 PUT 全量改 PATCH 部分改 DELETE 删。"],["状态码与统一响应","200/201/400/401/403/404/500 各归其位；业务统一 {code,msg,data} 外壳。"],["参数与版本约定","分页 page/size、排序 sort=field,desc；/api/v1 前缀做版本兼容。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u7":{"points":[["@Validated 校验","@NotNull/@NotBlank/@Size/@Min/@Pattern；嵌套对象加 @Valid 递归校验；分组校验区分新增/修改。"],["全局异常处理","@RestControllerAdvice + @ExceptionHandler 统一捕获，业务异常 BizException 带 code。"],["参数错误友好化","MethodArgumentNotValidException 提取 field+message 返回，别把堆栈甩给前端。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u8":{"points":[["Session vs JWT","Session 有状态靠 Cookie+服务器存储，分布式要粘性/共享；JWT 无状态自包含，签发后无法主动作废（要黑名单）。"],["JWT 结构与安全","Header.Payload.Signature；签名防篡改但不加密——payload 别放敏感信息；设置合理过期+刷新。"],["拦截器与 RBAC","登录拦截器校验 token；RBAC：用户-角色-权限五张表，接口用注解声明所需权限。"],["密码存储","BCrypt 自带盐的慢哈希；绝不 MD5 明文——拖库后撞库是真实事故。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u9":{"points":[["声明式事务与生效条件","@Transactional 基于 AOP：方法必须 public、必须通过代理调用、类必须是 Bean。"],["传播行为七种","REQUIRED 默认加入；REQUIRES_NEW 挂起新开（独立提交）；NESTED 保存点子事务——用场景记忆。"],["失效场景口诀","自调用、非 public、异常被 catch 吞掉（默认只回滚 RuntimeException/Error）、多线程、引擎不支持。"],["回滚规则与只读","rollbackFor=Exception.class 让受检异常也回滚；readOnly 提示驱动做优化。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u10":{"points":[["@Scheduled","cron 表达式六位（秒 分 时 日 月 周）；fixedRate 上次开始计时 vs fixedDelay 上次结束计时；分布式下会重复执行，要加分布式锁或用调度中心。"],["@Async","需 @EnableAsync；自调用失效；默认 SimpleAsyncTaskExecutor 不复用线程——必须自定义线程池。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u11":{"points":[["门面 + 实现","Slf4J 是门面、Logback 是实现（Spring Boot 默认）；门面模式让换实现不改业务代码。"],["级别与规范","error 只记影响功能的问题；占位符 log.info(\\"x={}\\", x) 而不是字符串拼接（惰性求值省性能）。"],["MDC 链路 traceId","入口生成 traceId 放 MDC，日志格式里输出，跨服务透传——排错从翻十台机器变成一次过滤。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u12":{"points":[["JUnit 5","@Test/@BeforeEach/@DisplayName/@ParameterizedTest；断言 assertThrows 验证异常路径。"],["Mockito","@Mock 隔离依赖、when().thenReturn() 打桩、verify() 验证调用；@MockBean 替换容器里的 Bean。"],["测试金字塔","单元测试多而快、集成测试少而真；Controller 用 @WebMvcTest 切片测试。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m3-u13":{"points":[["为什么拆与何时拆","拆分是为了独立部署与团队边界，不是为了时髦；业务量不大时单体+模块化更香。"],["Spring Cloud 组件分工","Nacos 注册+配置、Gateway 网关路由鉴权、OpenFeign 声明式调用、Sentinel 熔断限流、SkyWalking 链路。"],["服务治理常识","超时与重试要配幂等、负载均衡策略、配置中心动态刷新、灰度发布概念。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["章节测验","quiz"]]},"m4-u0":{"points":[["String","缓存 JSON 对象、计数器 INCR（点赞/库存预扣）、SETNX 锁基础；最大 512M。"],["Hash","对象字段级读写：购物车（userId→{skuId:count}）改一个字段不用整取整存。"],["List","lpush+lrange 做最新列表、简单消息队列 lpop；底层是快速列表 quicklist。"],["Set","无重去重、抽奖 SRANDMEMBER、共同好友 SINTER 交集——社交场景标配。"],["ZSet","score 排序：排行榜、延迟队列（score 存执行时间）；跳表实现，面试会问为什么用跳表。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u1":{"points":[["缓存穿透","查「不存在的数据」每次都打到 DB；方案：缓存空值（短过期）+ 布隆过滤器（可能误判但不漏判）。"],["缓存击穿","某个热点 key 过期瞬间万级请求压库；方案：互斥锁重建（只放一个线程去查）或逻辑过期不删除。"],["缓存雪崩","大量 key 同时过期或 Redis 整体宕机；方案：过期时间加随机打散、集群高可用、限流降级兜底。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u2":{"points":[["持久化 RDB vs AOF","RDB 快照恢复快可能丢数据；AOF 每秒 fsync 丢的少文件大；4.0+ 混合持久化（RDB 头+AOF 尾）生产推荐。"],["过期与淘汰策略","惰性删除+定期抽样删除；内存满时 8 种淘汰策略，缓存场景常用 allkeys-lru / lfu。"],["分布式锁进阶","SETNX + 唯一值 + Lua 原子「判断再删」；业务超时锁过期→Redisson 看门狗自动续期。"],["缓存与数据库一致性","Cache Aside：先更新数据库再删除缓存（不一致窗口最小）；进阶：延迟双删、订阅 binlog（canal）异步删。"],["主从与集群","主从复制读写分离、哨兵自动故障转移；Cluster 16384 槽分片，多 key 操作要 hash tag 同槽。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u3":{"points":[["三大价值配场景","异步（注册后发短信不阻塞）、解耦（订单事件多系统订阅）、削峰（秒杀请求排队消化）——每种都要能讲出场景。"],["三大 MQ 选型","RabbitMQ 吞吐中等路由灵活；Kafka 日志流超高吞吐；RocketMQ 事务消息/延迟消息功能全。"],["可靠性三段论","生产者确认、Broker 持久化+副本、消费者手动 ack——任一段都可能丢消息，逐段设防。"],["重复消费与幂等","MQ 至少一次投递必然可能重复；消费端用唯一索引/状态机/Redis 去重表兜底。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u4":{"points":[["顺序消息","全局有序性能差，通常按业务键分区局部有序（同一订单进同一队列）。"],["消息积压","原因多为消费能力不足：扩消费者、批量消费、降级非核心；严重时新开队列快速转移再补消费。"],["事务消息与本地消息表","RocketMQ 半消息+回查；本地消息表=业务与消息同库同事务+定时投递，两者思想等价。"],["延迟消息","下单 30 分钟未支付自动取消——RocketMQ 延迟级别或 Redis ZSet 实现。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u5":{"points":[["反向代理与负载均衡","upstream 定义后端池：轮询/权重/ip_hash 会话保持；正向代理代理客户端、反向代理代理服务端。"],["静态资源与优化","root/alias、gzip 压缩、expires 缓存头；动静分离让后端只管接口。"],["限流与高可用","limit_req 令牌桶限流；keepalived 主备 VIP——面试说清「一台挂了怎么切换」。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u6":{"points":[["倒排索引","分词器切词→词项→文档列表；MySQL like ''%x%'' 走全表，ES 天生为搜索而生。"],["DSL 查询","match 分词算分、term 精确不算分、filter 不算分可缓存——搜索排序 vs 过滤的分工。"],["数据同步与场景","canal 监听 binlog 同步到 ES；适用：商品搜索、日志分析（ELK）。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m4-u7":{"points":[["CAP 工程含义","网络分区是常态，P 必选，实际在 C 与 A 之间取舍：ZK 偏 CP、Eureka 偏 AP。"],["BASE 理论","基本可用、软状态、最终一致——大规模系统的现实哲学，牺牲强一致换可用与性能。"],["Raft 主线","Leader 选举（term 任期）→ 日志复制 → 安全性；面试能画出选举与复制的时序即可。"]],"links":[["第 7 章 · 中间件","ch7"],["易错点考场","pitfalls"]]},"m5-u0":{"points":[["三区工作流","工作区 →(add)→ 暂存区 →(commit)→ 本地仓库 →(push)→ 远程；status/diff 随时确认状态。"],["分支与合并","branch/switch/merge；冲突是两边改了同一行，手工取舍后 add+commit；log --graph 看分支图。"],["rebase vs merge","merge 保留分支历史、rebase 拉直历史；公共分支禁止 rebase（改写历史害队友）。"],["回退与协作流","reset 移动分支（本地）、revert 生成反向提交（安全，远程用）；feature 分支 + PR/MR 评审是团队标配。"],["ignore 与 stash",".gitignore 忽略 target/node_modules；stash 临时存改动切分支救急。"]],"links":[["第 8 章 · 工程化必备","ch8"]]},"m5-u1":{"points":[["文件与权限","cd/ls/mv/cp/rm -rf 慎用；chmod 755、chown；rwx 与数字 421 对应。"],["文本查看与检索","cat/less、tail -f 实时日志；grep -rn 关键字定位，管道组合是灵魂：grep xxx app.log | wc -l。"],["进程与端口","ps -ef / top 动态监控、kill -9 强杀（先 kill 优雅）；netstat -tunlp / lsof -i:8080 查端口占用。"],["排查组合技","端口被占、服务假死（线程满/内存满）、磁盘满（du -sh 逐层找大目录）三条标准链路要形成肌肉记忆。"]],"links":[["第 8 章 · 工程化必备","ch8"]]},"m5-u2":{"points":[["镜像与容器","镜像只读分层可复用、容器=镜像+可写层；docker pull/run/ps/logs/exec -it 进容器。"],["Dockerfile 与瘦身","FROM 选 alpine/slim、COPY 先清单后源码利用缓存层；多阶段构建把编译环境和运行时分开，镜像能小一个量级。"],["docker-compose 编排","一个 yml 定义 app+mysql+redis，networks 互通、volumes 持久化、depends_on 控制顺序——本地开发标配。"],["部署 Spring Boot 实战","jar 打进镜像、数据卷挂 MySQL 数据、环境变量注入配置；数据不挂卷，容器一删库就没了。"]],"links":[["第 8 章 · 工程化必备","ch8"]]},"m5-u3":{"points":[["流水线阶段","拉代码→构建→单测→镜像→部署；Jenkins 或 GitHub Actions 配一个感受自动化。"],["质量门禁","测试不过/扫描有高危就不允许合入——自动化挡住低级事故。"],["部署策略视野","蓝绿/滚动/灰度发布的概念与取舍。"]],"links":[["第 8 章 · 工程化必备","ch8"]]},"m5-u4":{"points":[["Postman / Apifox","环境变量切换 dev/prod、集合与脚本断言、一键生成文档——Apifox 国产一体化更顺手。"],["curl 与浏览器面板","curl -X POST -H ''Content-Type: application/json'' -d ''{}'' 快速冒烟；F12 Network 看请求响应、状态码、耗时瀑布。"]],"links":[["第 8 章 · 工程化必备","ch8"]]},"m6-u0":{"points":[["大 O 表示法","只保留最高阶、忽略常数：O(1) < O(logn) < O(n) < O(nlogn) < O(n²)；嵌套循环相乘、顺序执行取最大。"],["最好 / 最坏 / 平均","快排平均 O(nlogn) 但有序输入退化 O(n²)（可随机化 pivot 规避）——面试考「为什么会退化」。"],["递归复杂度","一层递归调一次：O(递归深度×每层开销)；二分是 O(logn)、斐波那契朴素递归是 O(2^n)，记忆化后降为 O(n)。"],["空间复杂度","额外空间：递归栈也计入；原地算法 O(1) 的价值在海量数据场景。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u1":{"points":[["两数之和","暴力双循环 O(n²) → 哈希存「值→下标」一次遍历 O(n)——优化链路本身就是标准答题范式。"],["对撞指针","先排序后首尾夹逼：三数之和（固定一个+双指针+去重）、盛水最多的容器（短板效应移动小的）。"],["快慢指针 / 原地操作","移动零（非零前移）、原地删除重复项：读写双指针，空间 O(1)。"],["前缀和","预处理 prefix[i]，任意区间和 O(1) 查询；配合哈希「和为 K 的子数组」升级玩法。"],["滑动窗口","窗口伸缩维护状态：最小覆盖子串、无重复最长子串——模板要背到能默写。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u2":{"points":[["哈希思想","用空间换时间，把「查找」从 O(n) 压到 O(1)；关键在 key 的设计（唯一、可哈希）。"],["字母异位词分组","排序后的串作 key 分桶（O(n·klogk)）或 26 位计数数组作 key（O(n·k)）——两种 key 设计都懂。"],["集合去重与交集","HashSet 判重、两个 Set 求交集/并集；元素少时数组桶更快。"],["哈希进阶映射","两数之和进阶、第一个只出现一次的字符；Java 里 HashMap 扩容与树化（回看集合章节）。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u3":{"points":[["反转链表","迭代三指针（prev/cur/next）必背；递归写法理解「先反转后面，再接回来」。"],["快慢指针找中点 / 判环","slow 一步 fast 两步：中点、环检测（相遇后头指针同速走再相遇即入口——Floyd 推导）。"],["合并有序链表","哑结点 dummy 简化头处理；归并多个链表用小顶堆 O(Nlogk)。"],["删除倒数第 N 个","快指针先走 N 步，快慢同走——一次遍历定位，注意删头结点要 dummy。"],["双向与环形链表","LinkedList 底层、约瑟夫环；手写双向链表是 LRU 缓存的组件。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u4":{"points":[["有效括号","左括号入栈、右括号匹配栈顶——栈的标志性入门题。"],["单调栈","维护单调性：下一个更大元素、每日温度；接雨水的双指针与单调栈两解法对比。"],["栈实现队列 / 队列实现栈","两栈倒腾：入队 O(1)、出队均摊 O(1)（只在出栈为空时搬一次）——均摊分析是考点。"],["优先队列（堆）","TopK、合并 K 链表；Java 的 PriorityQueue 默认小顶堆，大顶堆要传比较器。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u5":{"points":[["反转与回文","双指针首尾夹逼；回文用中心扩展（2n-1 个中心）——回文子串/最长回文都靠它。"],["无重复字符的最长子串","滑动窗口 + 哈希记录字符最后位置；窗口模板题必须一次写对。"],["串匹配视野","KMP 的 next 数组思想（了解即可，面试考概率低）；Rabin-Karp 哈希匹配思路。"],["括号生成 / 解码","与回溯、栈联动——字符串题常是多知识点的交叉。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u6":{"points":[["四种遍历","前中后序（递归 + 迭代用栈）、层序（队列）；中序=左根右，迭代写法是理解栈的最好练习。"],["递归三步曲","终止条件 → 处理当前层 → 返回信息；最大深度、对称、翻转都是套这个骨架。"],["最近公共祖先与路径和","后序回传左右子树信息向上汇总——递归「自底向上」思想的代表。"],["BST 二叉搜索树","中序遍历有序；验证 BST 用上下界（不是只比父子）；插入/删除及删除的三种情形。"],["平衡视野","AVL 旋转、红黑树近似平衡（HashMap/TreeMap 底层）——说清「为什么要自平衡」即可。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u7":{"points":[["经典五种手写","冒泡/选择/插入 O(n²)、快排/归并 O(nlogn)；稳定性：稳定（冒泡/插入/归并）vs 不稳定（选择/快排/堆）。"],["快排 partition","挖坑/交换两种分区写法；随机 pivot、三路划分应对大量重复元素。"],["非比较排序","计数/桶/基数排序用空间换时间，前提是数据范围已知——面试区分「比较排序下界 O(nlogn)」。"],["TopK 三板斧","堆 O(nlogk) 适合流式、快速选择 O(n) 平均适合静态、计数排序适合范围小——按场景选并说理由。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u8":{"points":[["标准模板与边界","while (left <= right) 配 mid±1，或 while (left < right) 配收缩——两套别混用；mid 防溢出写 left+(right-left)/2。"],["查找左右边界","「第一个 >=x」「最后一个 <=x」：用收缩式模板，靠 if 条件区分——99% 的二分 bug 是边界。"],["旋转数组","先判断哪半有序再判断 target 在不在那半——画图别硬背。"],["二分答案","把「最小化最大值」转化为「判定 x 是否可行」，对答案空间二分——题型识别是关键。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u9":{"points":[["DP 三步定义","状态定义（dp[i] 含义）→ 转移方程 → 初始化与遍历顺序；先写暴力递归，再加记忆化，最后改递推。"],["线性 DP","爬楼梯（斐波那契）、打家劫舍（偷或不偷）、最大子数组和（dp 或前缀+最小前缀）。"],["背包问题","0-1 背包每件一件：容量倒序遍历；完全背包可重复：正序——遍历顺序是理解核心。"],["子序列 / 子串 / 区间","最长递增子序列（O(nlogn) 贪心+二分）、最长公共子序列（二维表格）、编辑距离。"],["识别 DP 的信号","问「最值/方案数/可行性」且当前决策依赖之前状态——不是所有题都要 DP，先想贪心和模拟。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u10":{"points":[["回溯模板","做选择 → 递归 → 撤销选择；本质是在决策树上 DFS，画树是理解的第一步。"],["组合 / 排列 / 子集","组合用 startIndex 防重复、排列用 used 数组、子集每层都收集；三者去重策略不同，对比着练。"],["剪枝","可行性剪枝（不满足直接返回）与最优性剪枝（当前已劣于最优解）——从 O(n!) 救命的常用手段。"],["N 皇后 / 解数独 / 单词搜索","标志性难题：二维搜索 + 约束检查 + 状态恢复，写完一遍回溯就通了。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m6-u11":{"points":[["哈希分片","大文件按 hash(key)%k 拆成小文件，各小文件内统计再归并——「内存放不下」万能起手式。"],["布隆过滤器","多个哈希函数置位：说「不存在」一定不存在、说「存在」可能误判；用于缓存穿透与爬虫去重。"],["堆与 TopK","100 亿数找最大 K 个：维护 K 大小的小顶堆，内存 O(K)；比全排序快无数倍。"],["位图","int 4 字节存一个数 vs bitmap 1 bit：40 亿数判存在只要 512MB；RoaRING/Intersection 用位运算。"]],"links":[["刷题训练营（60 题）","algo"],["章节测验","quiz"]]},"m7-u0":{"points":[["选型策略","博客系统（登录/CRUD/分页/文件上传，覆盖 CRUD 全链路）+ 商城或秒杀（高并发：Redis 预扣+MQ 削峰）组合最划算。"],["吃透技术选型","每个依赖都能答「为什么用它、不用它用什么、代价是什么」——面试官一问就露馅的地方恰恰是没吃透的依赖。"],["迭代记录","v1 能跑 → v2 加缓存 → v3 优化慢 SQL 的演进过程本身就是最好的面试素材，开个 markdown 记下来。"],["部署闭环","买台云服务器用 Docker 跑起来配域名——「我能演示」比「我做过」可信十倍。"]],"links":[["第 9 章 · 全栈实战与职业路线","ch9"],["大厂分类真题","companies"],["面试八股文","baguwen"]]},"m7-u1":{"points":[["STAR 法则","背景 Situation、任务 Task、行动 Action、结果 Result；结果必须量化：QPS 从 200 到 3000、P99 从 800ms 降到 120ms。"],["用词避坑","「精通」留给教科书作者；写「熟悉/掌握」并准备好被追问到底。项目两个吃透 > 五个都浅。"],["一岗一版","对着 JD 关键词调项目描述与技能排序——简历是给筛简历的人看的，不是技术自传。"]],"links":[["第 9 章 · 全栈实战与职业路线","ch9"],["大厂分类真题","companies"],["面试八股文","baguwen"]]},"m7-u2":{"points":[["分模块滚动复习","Java/集合/并发/JVM/MySQL/Redis/Spring 按清单滚动，先理解再背诵，隔天复测（艾宾浩斯）。"],["费曼复述法","对着空气把一个概念讲 3 分钟不间断，卡壳的地方就是没懂的地方；录音回听效果拔群。"],["结合本站工具","章节测验 126 题 + 易错点 180 题 + 9 套模拟卷按模块刷——错题比新题值钱。"]],"links":[["第 9 章 · 全栈实战与职业路线","ch9"],["大厂分类真题","companies"],["面试八股文","baguwen"]]},"m7-u3":{"points":[["自问自答清单","每个模块准备 10 个高频问题，答不上立刻回炉；用本站「大厂分类真题」按公司过。"],["项目介绍两版本","3 分钟电梯版（背景/架构/亮点/结果）与 10 分钟深挖版（每个技术点能往下走两层）。"],["反问与心态","准备 2 个有质量的反问（团队技术栈/成长路径）；模拟时录音，改善语速与口头禅。"]],"links":[["第 9 章 · 全栈实战与职业路线","ch9"],["大厂分类真题","companies"],["面试八股文","baguwen"]]},"m7-u4":{"points":[["架构演进史","单体 → 垂直拆分 → SOA → 微服务 → 云原生/Service Mesh，每步的动机与代价——面试聊架构的坐标系。"],["技术趋势","云原生、AI 辅助研发、多运行时；对新东西的态度是「知道解决什么问题」而不是追名词。"],["职业路线","业务研发/中间件/基础架构/架构师的分工与技能侧重，第一份工作选「能学到东西的团队」。"]],"links":[["第 9 章 · 全栈实战与职业路线","ch9"],["大厂分类真题","companies"],["面试八股文","baguwen"]]},"m8-u0":{"points":[["主内存与工作内存","共享变量在主内存，线程操作必须先拷贝到工作内存再刷回——可见性问题的根源；JMM 是抽象规范，屏蔽硬件差异。"],["happens-before 八大规则","程序顺序、监视器锁、volatile、线程 start/join、传递性等——判断「A 的修改 B 能不能看到」全靠它，要能举例。"],["volatile 原理","写操作插 Store 屏障立即刷主存、读插 Load 屏障禁用缓存——保证可见性与有序性，不保证原子性。"],["重排序与 as-if-serial","编译器与 CPU 会重排但保证单线程语义不变；多线程下靠内存屏障约束——double-checked locking 需要 volatile 的原因。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u1":{"points":[["对象创建全流程","类加载检查 → 分配（指针碰撞/空闲列表，TLAB 加速）→ 零值 → 设置对象头 → <init>。"],["对象内存布局","对象头（Mark Word 8B + 类型指针）+ 实例数据 + 对齐填充（8B 倍数）；空对象 16 字节的由来。"],["Mark Word 与锁升级","无锁 → 偏向锁 → 轻量级锁（自旋）→ 重量级锁的状态流转都在 64bit Mark Word 里——锁优化面试的核心。"],["逃逸分析与栈上分配","JIT 证明对象不逃逸方法外时可标量替换/栈上分配/锁消除——「对象不一定在堆上」。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u2":{"points":[["评价维度","吞吐量、延迟、内存开销的不可能三角；不同业务选不同器——先讲维度再讲器。"],["CMS 四阶段","初始标记(STW)→并发标记→重新标记(STW)→并发清理；缺点：浮动垃圾、内存碎片、并发失败退化。"],["G1","Region 化堆、按停顿目标优先回收垃圾最多的 Region（Mixed GC）、Humongous 大对象区——JDK9+ 默认。"],["ZGC","染色指针 + 读屏障实现亚毫秒停顿；了解三色标记漏标的两种修复：增量更新（CMS）与原始快照（G1）。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u3":{"points":[["开启与读日志","-Xlog:gc*（JDK9+）或 PrintGCDetails；看 GC 前后各代占用、耗时、触发原因（Allocation Failure/Metaspace）。"],["可视化工具","gceasy / gcviewer 上传日志出报告：停顿分布、吞吐率、晋升速率——先看图再动参数。"],["调优闭环","定目标（延迟 or 吞吐）→ 选收集器 → 调堆/分代/晋升阈值 → 压测验证 → 观察回归；没有指标就调参是玄学。"],["常用参数","-Xms=-Xmx 防抖动、-XX:MaxGCPauseMillis、MetaspaceSize；参数不是越多越好。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u4":{"points":[["jps / jstat","jps 找进程；jstat -gcutil 1000 实时看各代占用与 GC 次数耗时——判断是频繁 YoungGC 还是 FullGC。"],["jmap + MAT","jmap -dump 转储；MAT 看支配树 + GC Roots 引用链——定位内存泄漏的引用源头（static 集合/ThreadLocal 高发）。"],["jstack 与 CPU 100% 套路","top -Hp 找最耗 CPU 线程 → printf ''%x'' 转十六进制 → jstack 里按 nid 定位栈——必背的标准流程。"],["Arthas","watch/trace 观察方法入参与耗时、jad 反编译验证部署版本、dashboard 总览——线上诊断神器，必须会用。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u5":{"points":[["加载-验证-准备-解析-初始化","准备阶段给静态变量零值（不是初始值！）、初始化才执行 <clinit>（静态块+静态赋值）——经典细节题。"],["双亲委派","App → Platform → Bootstrap 逐级委派：防核心类被篡改 + 避免重复加载；加载不到才逐级下放。"],["打破双亲委派","SPI 用线程上下文加载器（JDBC 驱动）、Tomcat 每应用隔离、热部署——说得出场景才算懂。"],["自定义类加载器","继承 ClassLoader 覆写 findClass，从加密文件/网络加载——插件化与加壳的基础。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u6":{"points":[["class 文件视野","魔数 cafebabe、常量池、字段表/方法表/属性表；用 javap -c 看方法字节码。"],["语法糖还原","字符串 + 编译成 StringBuilder.append、增强 for 是迭代器、自动装箱是 valueOf——看懂字节码就懂「性能问题的真相」。"],["JIT 分层编译","C1 快速编译、C2 深度优化；热点探测（方法计数器+回边计数器）触发编译替换解释执行。"],["JIT 优化产物","方法内联是最重要的优化（为逃逸分析铺路）、锁消除、去虚拟化——解释为什么「猜的热点」可能不准。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u7":{"points":[["cgroup 感知","JDK 8u191+/10+ 支持 UseContainerSupport，JVM 按 cgroup 限额而非物理机内存判断——容器里堆设错就 OOMKilled。"],["参数适配","MaxRAMPercentage=75 按容器内存限额设堆，别写死 -Xmx；CPU 谨慎配 ActiveProcessorCount。"],["OOMKilled vs OOM","容器被杀（exit 137）是超 cgroup 限额，不是 Java OOM——排查方向完全不同，先看 dmesg。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m8-u8":{"points":[["优化方法论","定指标（P99/QPS）→ 压测 → 定位（CPU/内存/IO/GC 哪个瓶颈）→ 优化 → 回归验证——禁止无指标优化。"],["CPU 100% 排查","top → top -Hp → printf %x → jstack 定位热点线程栈；常见根因：死循环、频繁 GC（GC 线程占满）、锁竞争自旋。"],["内存泄漏排查","jmap dump → MAT 支配树 → 引用链 → 修复；高发点：static 集合只增不减、ThreadLocal 未 remove、连接未关。"],["慢接口分层排查","先看链路追踪哪一段慢：DB（慢 SQL/索引）→ 缓存（穿透/序列化）→ 远程调用（超时重试放大）→ 日志与锁。"]],"links":[["第 3 章 · Java SE 核心","ch3"],["原理与源码专栏","topics"]]},"m9-u0":{"points":[["refresh 主线","13 个关键步骤串起容器启动：prepareEnvironment → obtainFreshBeanFactory → postProcess → finishBeanFactoryInitialization——面试画这条线。"],["BeanDefinition 装载","注解扫描（ClassPathBeanDefinitionScanner）把类变成 BeanDefinition 存进 beanDefinitionMap——先「图纸」后「实例」两阶段。"],["BeanFactoryPostProcessor","容器级扩展点：ConfigurationClassPostProcessor 解析 @Configuration/@Import、占位符替换——改定义不改实例。"],["BeanPostProcessor","Bean 级扩展点：@PostConstruct、AOP 代理都在此生成（AnnotationAwareAspectJAutoProxyCreator）——理解扩展点才看得懂框架。"],["事件机制","事件多播器 ApplicationEventMulticaster 在 refresh 中注册；ContextRefreshedEvent 等内置事件的发布时机。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u1":{"points":[["三级缓存结构","一级成品单例池、二级早期引用、三级 ObjectFactory；A 创建中把工厂放三级缓存，B 注入时提前拿到半成品。"],["为什么需要三级不是两级","若 A 被 AOP 代理，三级缓存的工厂能在被引用时才生成代理——保证「要么都拿原始、要么都拿代理」的一致性。"],["构造器循环依赖无解","提前曝光的前提是「已实例化」，构造器注入卡在实例化这一步——只能 @Lazy 或重构。"],["Boot 2.6 默认禁用的启示","循环依赖是设计坏味道：默认禁止逼你重构——框架收紧默认行为是有意为之。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u2":{"points":[["TransactionInterceptor","环绕通知：获取事务管理器 → createTransactionIfNecessary → 业务 → 按异常规则 commit/rollback。"],["传播行为的实现","挂起 = 把当前连接从 ThreadLocal 解绑并保存；REQUIRES_NEW 恢复时再绑回；NESTED 用 JDBC 保存点。"],["连接与 ThreadLocal","TransactionSynchronizationManager 把连接绑定到线程——同一事务内多个 DAO 共用连接；事务内开新线程拿不到事务的根因。"],["回滚决策链","异常类型 → rollbackOn 规则（默认 RuntimeException/Error）→ 完成时决定提交或回滚；@Transactional 自调用失效的代理解释。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u3":{"points":[["代理创建时机","Bean 初始化后由 BeanPostProcessor 判断是否需要代理（有匹配的 Advisor）——代理对象替换原始对象进容器。"],["拦截器链执行","ReflectiveMethodInvocation 责任链：前置→目标→后置/异常，环绕通知包裹全部——理解「通知顺序」的依据。"],["切面解析","@Aspect 类被解析成 Advisor 集合（切点+通知），匹配按优先级排序。"],["失效场景根因","final/private/static 方法无法被覆写、自调用不走代理、内部 new 的对象不是 Bean——每个失效都能落到原理。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u4":{"points":[["启动主线","SpringApplication.run → 创建 ApplicationContext → prepareEnvironment → refresh → 回调 Runner。"],["@EnableAutoConfiguration","AutoConfigurationImportSelector 读取 META-INF/...AutoConfiguration.imports（2.7+ 新格式），拿到候选配置类清单。"],["条件注解过滤","@ConditionalOnClass 决定类在不在、@ConditionalOnMissingBean 实现「用户配置覆盖默认」——装配顺序靠 @AutoConfigureAfter 保证。"],["starter 规范","官方 spring-boot-starter-*、第三方 xxx-spring-boot-starter；自定义三件套：配置类+条件注解+imports 注册。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u5":{"points":[["过滤器链模型","15+ Filter 责任链：SecurityContextPersistenceFilter 存取认证态、UsernamePasswordAuthenticationFilter 处理登录。"],["认证流程","AuthenticationManager 遍历 Provider → UserDetailsService 加载用户 → PasswordEncoder 比对 → 生成 Authentication。"],["授权","URL 级 authorizeRequests 与方法级 @PreAuthorize(\\"hasRole(''ADMIN'')\\")（SpEL）；RBAC：用户-角色-权限表设计。"],["JWT 无状态整合","关闭 session、自定义 OncePerRequestFilter 校验 token 并装配 SecurityContext；白名单与过滤器顺序是实战重点。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u6":{"points":[["Nacos 注册与配置","服务注册心跳续约、AP/CP 可切换（Raft）；配置中心长轮询动态刷新（30s 挂起等变更）。"],["OpenFeign","接口+注解 → 动态代理 → 编码成 HTTP 请求；超时/重试/日志级别三件必须显式配置。"],["Gateway","路由断言（Path/Method/Header）+ 过滤器链（鉴权/改写/限流）；与 Nginx 分工：Nginx 管入口流量，Gateway 管微服务路由。"],["Sentinel","流控（QPS/线程数）、熔断（慢调用/异常比例）、热点参数限流；规则可推 Nacos 持久化。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u7":{"points":[["三支柱","日志（发生了什么）/指标（多严重）/链路（慢在哪一跳）——排错时先链路定位、再日志深挖、指标告警兜底。"],["Micrometer + Prometheus","应用暴露 /actuator/prometheus，Prometheus 抓取时序数据，Grafana 出看板；Counter/Gauge/Timer 三种指标。"],["SkyWalking","javaagent 字节码增强零侵入；Trace→Span 树定位慢在哪个节点哪个方法，拓扑图看依赖。"],["告警落地","自定义业务指标（下单成功率）、慢 SQL 数、异常率阈值——告警要能行动，否则是噪音。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m9-u8":{"points":[["核心对象分工","Pod 最小调度单元、Deployment 管副本与滚动更新、Service 稳定访问入口、Ingress 七层路由。"],["镜像与配置注入","多阶段构建出小镜像；ConfigMap 挂配置、Secret 存密码——镜像不改配置，环境差异全靠注入。"],["探针与优雅停机","liveness 失败重启、readiness 失败摘流量；preStop + SIGTERM 让应用先摘流量再停——避免发布瞬时报错。"],["资源与弹性","requests/limits 与 JVM MaxRAMPercentage 联动防 OOMKilled；HPA 按 CPU/自定义指标自动扩缩容。"]],"links":[["第 6 章 · Spring 全家桶","ch6"],["原理与源码专栏","topics"]]},"m10-u0":{"points":[["CAP 的工程含义","网络分区是常态（P 必选），真实选择是 C 与 A：ZK 选举期间不可用偏 CP、Eureka 自我保护偏 AP——举得出案例才算懂。"],["BASE 与最终一致","基本可用、软状态、最终一致；「最终」靠补偿、对账、版本收敛实现——BASE 是大规模系统的落地哲学。"],["Paxos / Raft 主线","Raft：Leader 选举（随机超时+term）、日志复制（多数派提交）、安全性（只投日志最新的票）——能画时序图就够了。"],["一致性级别谱系","线性一致 > 顺序一致 > 因果一致 > 最终一致——按业务需求选级别，而不是无脑要最强。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u1":{"points":[["UUID 的问题","36 位太长且无序：InnoDB 主键无序导致页分裂、索引稀疏——「UUID 不能做主键」的原因要讲透。"],["雪花算法","64 位 = 1 符号 + 41 时间戳 + 10 机器 + 12 序列，趋势递增；核心风险是时钟回拨：小回拨等待、大回拨切换 workerId/报警。"],["号段模式","DB 批量取号段到内存双 buffer 预取（美团 Leaf）——DB 压力小、宕机可续号段；与雪花按运维能力选型。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u2":{"points":[["数据库锁","唯一索引 insert 或版本号乐观锁——正确性最高、性能最低，适合低频强一致场景。"],["Redis 锁","SET key uuid NX PX + Lua 原子「校验再删」；Redisson 看门狗解决业务超时锁过期；主从切换可能丢锁（RedLock 争议）。"],["ZooKeeper 锁","临时顺序节点 + 监听前驱：无惊群、会话断自动释放——强一致但吞吐低；效率型选 Redis、正确性关键选 ZK/DB。"],["fencing token","递增令牌 + 下游校验拒绝过期令牌——GC 停顿下唯一完备的方案，面试聊出这个就赢了。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u3":{"points":[["2PC / 3PC","协调者单点、阻塞、数据不一致风险——强一致但工程上少用；3PC 加超时缓解阻塞但没根治。"],["TCC","Try 预留资源、Confirm 确认、Cancel 释放；业务侵入大但性能好、不锁全局。三大坑：空回滚、悬挂、幂等都要防。"],["Saga 与本地消息表","Saga 长流程正向提交+逆向补偿；本地消息表=业务与消息同库同事务 + 定时投递重试——最终一致的实用主义。"],["MQ 事务消息","半消息不可见 + 本地事务 + 回查确认（RocketMQ）；与本地消息表思想等价，省了张表。"],["选型决策树","要强一致且低频 → TCC/2PC；要最终一致高吞吐 → 本地消息表/事务消息/Saga——按一致性、侵入度、吞吐三角选。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u4":{"points":[["四大限流算法","固定窗口（临界突刺）→ 滑动窗口 → 漏桶（恒定速率）→ 令牌桶（允许突发）——画出各自形状就能讲清。"],["单机 vs 集群限流","单机内存计数各自为政；集群用 Redis+Lua 保证「判断+扣减」原子——多一次网络往返的代价要提。"],["熔断器三态","Closed 正常 → 失败率/慢调用超阈值 → Open 快速失败 → 等待窗口 → Half-Open 放少量探测成功则恢复——保护自己不被下游拖死。"],["Sentinel 实战","QPS/并发/热点参数/系统自适应四种规则；fallback 与 blockHandler 的区别、规则持久化到 Nacos。"],["降级设计","核心保可用、非核心可牺牲：返回默认值/缓存旧值/关闭功能开关——提前设计降级预案而不是故障时手忙脚乱。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u5":{"points":[["取模的问题","hash % N 在节点增减时几乎全量重映射——缓存集体失效（雪崩式）。"],["哈希环","节点与 key 都映射到 2^32 环上顺时针归属；节点宕机只影响相邻区间——1/N 而不是全量。"],["虚拟节点","节点少时环分布不均导致倾斜；每个物理节点映射成百上千虚拟节点打散。"],["分库分表","垂直（按业务拆库）先于水平（按行拆表）；分片键选查询最高频维度，否则跨片 join/分页是灾难；配套：异构索引、基因法。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u6":{"points":[["秒杀架构","前端限流答题 → 网关限流 → Redis+Lua 预扣库存 → MQ 削峰异步落库 → DB 唯一索引防超卖——每一层都在挡流量。"],["库存一致性与防超卖","Redis 扣减+DB 乐观校验双保险；对账任务兜底——「不超卖、不少卖」两件事分开设计。"],["多级缓存与热点","本地缓存（Caffeine）+ Redis + 前置 CDN；热点 key 探测后本地化，避免单分片被打爆。"],["防刷组合拳","限流（IP/设备/账号维度）+ 风控名单 + 验证码/答题——安全与体验的平衡。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]},"m10-u7":{"points":[["幂等设计","唯一索引（最硬）、幂等键 Idempotency-Key（Stripe 模式：保存首次响应重试直接返回）、状态机（非法流转直接拒绝）。"],["接口兼容与版本","只加字段不删字段、枚举只增不改值；URL 版本 /v1/ 与灰度双跑——线上接口不是想改就能改。"],["开放平台安全","签名（防篡改）+ 时间戳/nonce（防重放）+ appSecret；配额与限流按 appKey 管理。"],["契约先行","OpenAPI/Swagger 文档即契约，mock 先行并行开发——前后端联调不扯皮的秘诀。"]],"links":[["第 7 章 · 中间件","ch7"],["大厂分类真题","companies"]]}}') ON DUPLICATE KEY UPDATE data = VALUES(data);
